INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52516, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勇気", "is_correct": true, "explanation": "「勇気ある行動」で、恐れずに正しいことへ踏み出す心の力を表す。文の意味に合う。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度を表す語で、「体温ある行動」とは言えない。"}, {"text": "音量", "is_correct": false, "explanation": "音の大きさを表す語で、人の行動を修飾する意味にならない。"}, {"text": "天候", "is_correct": false, "explanation": "空模様を表す語で、「天候ある行動」は意味が通らない。"}], "explanations": {"勇気": "「勇気ある行動」で、恐れずに正しいことへ踏み出す心の力を表す。文の意味に合う。", "体温": "体の温度を表す語で、「体温ある行動」とは言えない。", "音量": "音の大きさを表す語で、人の行動を修飾する意味にならない。", "天候": "空模様を表す語で、「天候ある行動」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "勇気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は勇気が据わっていて、大勢の前でも動じない。", "explanation": "据わるのは度胸で、勇気は据わるものではない。"}, {"text": "試合前、彼は勇気を入れて準備運動をした。", "explanation": "気合は入れるものだが、勇気は入れるものではない。"}, {"text": "この契約は勇気だから、来年は更新が必要だ。", "explanation": "ここは〈有期〉（期間が決まっている）の意味。期間の限りを表すのは有期で、勇気は期間を示さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52516, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は危険な崖の前で、勇気の出して一歩を踏み出した。", "corrected_sentence": "彼は危険な崖の前で、勇気を出して一歩を踏み出した。", "error_description": "「勇気を出す」の「勇気」に付く助詞は「を」。「の」は誤りで、正しくは「勇気を出して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52516, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は、くじけそうな心に勇気を奮い立てて、一歩を踏み出した。", "corrected_sentence": "彼女は、くじけそうな心に勇気を奮い立たせて、一歩を踏み出した。", "error_description": "「奮い立たせる」は他動詞で、「奮い立たせて」が正しい形。「奮い立てて」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52517, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「歩みを止める」の目的語を示す「を」。文の意味に合う。"}, {"text": "に", "is_correct": false, "explanation": "「止める」の対象は「を」で示すので、「歩みに止めた」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「歩みで止めた」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すが、「歩みと止めた」とは言えない。"}], "correct_answer": "を", "explanations": {"を": "「歩みを止める」の目的語を示す「を」。文の意味に合う。", "に": "「止める」の対象は「を」で示すので、「歩みに止めた」は成り立たない。", "で": "「で」は手段や場所を示すが、「歩みで止めた」は意味が通らない。", "と": "「と」は相手や並列を示すが、「歩みと止めた」とは言えない。"}, "error_tags": {"に": "帰着", "で": "手段", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
