INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52517, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "足を前へ運ぶ動きや、その歩きぶり・歩調。", "primary_collocate": null, "pronunciation": "あゆみ", "ipa": "ajɯmi", "syllable_count": 3, "sentences": [{"text": "疲れた老人は、ゆっくりした歩みで坂をのぼった。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "疲[つか]れた老人[ろうじん]は、ゆっくりした歩[あゆ]みで坂[さか]をのぼった。", "sentence_source": "generated"}, {"text": "彼女は犬の足音に気づいて、歩みを止めた。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は犬[いぬ]の足音[あしおと]に気[き]づいて、歩[あゆ]みを止[と]めた。", "sentence_source": "generated"}, {"text": "山道が急になり、登山者たちの歩みは重くなった。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "山道[やまみち]が急[きゅう]になり、登山者[とざんしゃ]たちの歩[あゆ]みは重[おも]くなった。", "sentence_source": "generated"}, {"text": "兵士たちは同じ歩みで、広場をまっすぐ進んだ。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "兵士[へいし]たちは同[おな]じ歩[あゆ]みで、広場[ひろば]をまっすぐ進[すす]んだ。", "sentence_source": "generated"}, {"text": "夜道で後ろに人がいるのを感じ、歩みを速めた。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "夜道[よみち]で後[うし]ろに人[ひと]がいるのを感[かん]じ、歩[あゆ]みを速[はや]めた。", "sentence_source": "generated"}, {"text": "赤ちゃんは、よちよちとした小さな歩みで母親に近づいた。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは、よちよちとした小[ちい]さな歩[あゆ]みで母親[ははおや]に近[ちか]づいた。", "sentence_source": "generated"}, {"text": "雪が深くて、歩みがとても遅くなった。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "雪[ゆき]が深[ふか]くて、歩[あゆ]みがとても遅[おそ]くなった。", "sentence_source": "generated"}, {"text": "彼は声をかけられて、思わず歩みをゆるめた。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "彼[かれ]は声[こえ]をかけられて、思[おも]わず歩[あゆ]みをゆるめた。", "sentence_source": "generated"}, {"text": "先生は規則正しい歩みで廊下を進み、教室の前で止まった。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "先生[せんせい]は規則正[きそくただ]しい歩[あゆ]みで廊下[ろうか]を進[すす]み、教室[きょうしつ]の前[まえ]で止[と]まった。", "sentence_source": "generated"}, {"text": "橋の手前で、彼の歩みがぴたりと止まった。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "橋[はし]の手前[てまえ]で、彼[かれ]の歩[あゆ]みがぴたりと止[と]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "歩み", "label": "基本形"}, {"form": "歩みを", "label": "目的語形"}], "register": "neutral", "sense_fingerprint": "歩み: 足を前に運ぶ動きや歩きぶり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: 速め (Zipf 2.43)','sentence 9 above tier T2: contains vocabulary far above tier T2: ぴたり (Zipf 2.14)']::text[], '8cdf0ab4-1330-4fca-9cea-5488818a8241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52517, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歩み", "is_correct": true, "explanation": "「ゆっくりした歩みで」で、足を運ぶ動きや歩きぶりを表す。文の意味に合う。"}, {"text": "眠り", "is_correct": false, "explanation": "寝ている状態を表す語で、「ゆっくりした眠りで坂をのぼった」は意味が通らない。"}, {"text": "手紙", "is_correct": false, "explanation": "文字で伝える書き物を表す語で、坂をのぼる動きを修飾しない。"}, {"text": "食事", "is_correct": false, "explanation": "食べることを表す語で、「ゆっくりした食事で坂をのぼった」は意味が通らない。"}], "explanations": {"歩み": "「ゆっくりした歩みで」で、足を運ぶ動きや歩きぶりを表す。文の意味に合う。", "眠り": "寝ている状態を表す語で、「ゆっくりした眠りで坂をのぼった」は意味が通らない。", "手紙": "文字で伝える書き物を表す語で、坂をのぼる動きを修飾しない。", "食事": "食べることを表す語で、「ゆっくりした食事で坂をのぼった」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "歩み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "歩みを担いで、息を切らした。", "explanation": "肩にかつぐのは荷物で、歩みは担げるものではない。"}, {"text": "朝、歩みを読むのが日課だ。", "explanation": "読むのは新聞などで、歩みは読めるものではない。"}, {"text": "窓の歩みをかける。", "explanation": "かけるのは鍵で、歩みはかけるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52517, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歩み", "is_correct": true, "explanation": "「歩みがとても遅くなった」で、足を運ぶ速さを表す。文の意味に合う。"}, {"text": "眠気", "is_correct": false, "explanation": "眠たい感じを表す語で、進む速さを表すことはない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語で、「天気がとても遅くなった」は意味が通らない。"}, {"text": "楽器", "is_correct": false, "explanation": "音を出す道具を表す語で、速さを表す文脈に合わない。"}], "explanations": {"歩み": "「歩みがとても遅くなった」で、足を運ぶ速さを表す。文の意味に合う。", "眠気": "眠たい感じを表す語で、進む速さを表すことはない。", "天気": "空模様を表す語で、「天気がとても遅くなった」は意味が通らない。", "楽器": "音を出す道具を表す語で、速さを表す文脈に合わない。"}, "sentence_index": 6, "correct_answer": "歩み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "悲しくて、歩みがこぼれた。", "explanation": "こぼれるのは涙で、歩みはこぼれるものではない。"}, {"text": "ろうそくの歩みを消して、寝た。", "explanation": "消すものは火などで、歩みは消せるものではない。"}, {"text": "答案に歩みを書いた。", "explanation": "書くのは名前などで、歩みは書くものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52517, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は坂の途中で歩みが止めたが、息は整わなかった。", "corrected_sentence": "彼は坂の途中で歩みを止めたが、息は整わなかった。", "error_description": "「止める」の対象は「を」で示す。「が」は誤りで、正しくは「歩みを止めた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52517, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は坂道で、歩みをゆるみた。", "corrected_sentence": "彼は坂道で、歩みをゆるめた。", "error_description": "「ゆるむ」は自動詞、「ゆるめる」は他動詞。「歩みを」に続くので「ゆるめた」が正しい。「ゆるみた」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
