INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52518, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が少しずつ進んでいくことや、それを始める最初の行動。", "primary_collocate": null, "pronunciation": "あゆみ", "ipa": "ajɯmi", "syllable_count": 3, "sentences": [{"text": "親である私にできるのは、その勇気ある最初の歩みを、ただ静かに、そして確かな祈りを込めて見守ることだけだ。", "target_word": "歩み", "complexity_tier": "T4", "furigana": "親[おや]である私[わたし]にできるのは、その勇気[ゆうき]ある最初[さいしょ]の歩[あゆ]みを、ただ静[しず]かに、そして確[たし]かな祈[いの]りを込[こ]めて見守[みまも]ることだけだ。", "sentence_source": "generated"}, {"text": "彼は迷いながらも、新しい仕事への歩みを始めた。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "彼[かれ]は迷[まよ]いながらも、新[あたら]しい仕事[しごと]への歩[あゆ]みを始[はじ]めた。", "sentence_source": "generated"}, {"text": "彼女は新しい店を開く最初の歩みとして、まず場所を探した。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は新[あたら]しい店[みせ]を開[ひら]く最初[さいしょ]の歩[あゆ]みとして、まず場所[ばしょ]を探[さが]した。", "sentence_source": "generated"}, {"text": "長い入院を経て、彼女は再び自分らしい歩みを取り戻していった。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "長[なが]い入院[にゅういん]を経[へ]て、彼女[かのじょ]は再[ふたた]び自分[じぶん]らしい歩[あゆ]みを取[と]り戻[もど]していった。", "sentence_source": "generated"}, {"text": "迷ったが、まず近所の図書館へ行くという歩みを踏み出した。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "迷[まよ]ったが、まず近所[きんじょ]の図書館[としょかん]へ行[い]くという歩[あゆ]みを踏[ふ]み出[だ]した。", "sentence_source": "generated"}, {"text": "仲間との歩みを大切にして、チームは少しずつ前に進んだ。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "仲間[なかま]との歩[あゆ]みを大切[たいせつ]にして、チームは少[すこ]しずつ前[まえ]に進[すす]んだ。", "sentence_source": "generated"}, {"text": "二人はたがいの歩みを認め合い、同じ目標に向かって進んでいった。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "二人[ふたり]はたがいの歩[あゆ]みを認[みと]め合[あ]い、同[おな]じ目標[もくひょう]に向[む]かって進[すす]んでいった。", "sentence_source": "generated"}, {"text": "失敗を恐れず、まず最初の歩みを踏み出してみよう。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "失敗[しっぱい]を恐[おそ]れず、まず最初[さいしょ]の歩[あゆ]みを踏[ふ]み出[だ]してみよう。", "sentence_source": "generated"}, {"text": "彼は起業に向けた最初の歩みとして、まず資金を集め始めた。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "彼[かれ]は起業[きぎょう]に向[む]けた最初[さいしょ]の歩[あゆ]みとして、まず資金[しきん]を集[あつ]め始[はじ]めた。", "sentence_source": "generated"}, {"text": "彼の歩みは遅いが、足取りは確かだった。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "彼[かれ]の歩[あゆ]みは遅[おそ]いが、足取[あしど]りは確[たし]かだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "歩み", "label": "基本形"}, {"form": "歩みを", "label": "目的語形"}], "register": "neutral", "sense_fingerprint": "歩み: 進んでいく歩調や、物事の歩み出し・経過", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cdf0ab4-1330-4fca-9cea-5488818a8241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52518, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歩み", "is_correct": true, "explanation": "「最初の歩み」で、物事を始めて進んでいく一歩を表す。文の意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語で、「勇気ある最初の天気」は文の意味に合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠たい感じを表す語で、「勇気ある最初の眠気」は意味が通らない。"}, {"text": "色", "is_correct": false, "explanation": "目で見える色合いを表す語で、「勇気ある最初の色」は文の意味に合わない。"}], "explanations": {"歩み": "「最初の歩み」で、物事を始めて進んでいく一歩を表す。文の意味に合う。", "天気": "空模様を表す語で、「勇気ある最初の天気」は文の意味に合わない。", "眠気": "眠たい感じを表す語で、「勇気ある最初の眠気」は意味が通らない。", "色": "目で見える色合いを表す語で、「勇気ある最初の色」は文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "歩み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "胸の歩みが速くなり、手のひらに汗がにじんだ。", "explanation": "胸の動きを表すのは鼓動で、歩みは足を運ぶことや物事の進み具合を指すので、胸には使わない。"}, {"text": "窓から歩みが差し込んで、部屋が明るくなった。", "explanation": "差し込むのは光で、歩みは差し込むものではない。"}, {"text": "列車は歩みを上げて、トンネルに入った。", "explanation": "歩みは上げるものではなく、「歩みを上げる」とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52518, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歩み", "is_correct": true, "explanation": "「たがいの歩み」で、互いに進んできた道のりや努力を表す。文の意味に合う。"}, {"text": "雨音", "is_correct": false, "explanation": "雨の降る音を表す語で、「たがいの雨音」は文の意味に合わない。"}, {"text": "油", "is_correct": false, "explanation": "食用や機械に使う液体で、「たがいの油」は意味が通らない。"}, {"text": "楽器", "is_correct": false, "explanation": "音を出す道具を表す語で、「たがいの楽器」は文の意味に合わない。"}], "explanations": {"歩み": "「たがいの歩み」で、互いに進んできた道のりや努力を表す。文の意味に合う。", "雨音": "雨の降る音を表す語で、「たがいの雨音」は文の意味に合わない。", "油": "食用や機械に使う液体で、「たがいの油」は意味が通らない。", "楽器": "音を出す道具を表す語で、「たがいの楽器」は文の意味に合わない。"}, "sentence_index": 6, "correct_answer": "歩み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "玄関の歩みをかけ忘れて、家を出てしまった。", "explanation": "かけるのは鍵で、歩みはかけるものではない。"}, {"text": "夜の廊下に、歩みを立てないよう気をつけた。", "explanation": "足音を立てるもので、歩みは音を立てるものではない。"}, {"text": "毎晩、歩みを読んでから眠る。", "explanation": "読むのは本で、歩みは読めるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52518, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は迷わず歩みを進また。", "corrected_sentence": "彼は迷わず歩みを進めた。", "error_description": "「歩みを進める」の「進める」は他動詞。「進また」は誤った形で、正しくは「進めた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52518, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は思い切って、最初の歩みで踏み出した。", "corrected_sentence": "彼女は思い切って、最初の歩みを踏み出した。", "error_description": "「踏み出す」の対象は「を」で示す。「で」は誤りで、正しくは「歩みを踏み出した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
