INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52519, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「回転を止める」の目的語を示す「を」。止められる対象の回転を表す。"}, {"text": "が", "is_correct": false, "explanation": "「止める」は他動詞なので目的語の「を」が必要。「回転が止める」は主語だけでは成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「回転へ止めてから」は止める対象として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「回転から止めてから」では意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「回転を止める」の目的語を示す「を」。止められる対象の回転を表す。", "が": "「止める」は他動詞なので目的語の「を」が必要。「回転が止める」は主語だけでは成り立たない。", "へ": "「へ」は方向を示すが、「回転へ止めてから」は止める対象として成り立たない。", "から": "「から」は起点を示すが、「回転から止めてから」では意味が通らない。"}, "error_tags": {"が": "主語", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52519, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものが、くるくるまわること。", "primary_collocate": null, "pronunciation": "かいてん", "ipa": "kaiteɴ", "syllable_count": 4, "sentences": [{"text": "洗濯機のドラムが勢いよく回転している。", "target_word": "回転", "complexity_tier": "T3", "furigana": "洗濯機[せんたくき]のドラムが勢[いきお]いよく回転[かいてん]している。", "sentence_source": "generated"}, {"text": "地球は一日に一回、自分の軸を中心に回転する。", "target_word": "回転", "complexity_tier": "T3", "furigana": "地球[ちきゅう]は一日[いちにち]に一回[いっかい]、自分[じぶん]の軸[じく]を中心[ちゅうしん]に回転[かいてん]する。", "sentence_source": "generated"}, {"text": "扇風機の羽根が回転して、涼しい風が来た。", "target_word": "回転", "complexity_tier": "T3", "furigana": "扇風機[せんぷうき]の羽根[はね]が回転[かいてん]して、涼[すず]しい風[かぜ]が来[き]た。", "sentence_source": "generated"}, {"text": "コマは回転が弱くなると、ふらふらと倒れた。", "target_word": "回転", "complexity_tier": "T3", "furigana": "コマは回転[かいてん]が弱[よわ]くなると、ふらふらと倒[たお]れた。", "sentence_source": "generated"}, {"text": "車のタイヤが回転しなくなり、車は動かなかった。", "target_word": "回転", "complexity_tier": "T3", "furigana": "車[くるま]のタイヤが回転[かいてん]しなくなり、車[くるま]は動[うご]かなかった。", "sentence_source": "generated"}, {"text": "観覧車はゆっくり回転しながら、夜の街を照らした。", "target_word": "回転", "complexity_tier": "T3", "furigana": "観覧車[かんらんしゃ]はゆっくり回転[かいてん]しながら、夜[よる]の街[まち]を照[て]らした。", "sentence_source": "generated"}, {"text": "氷の上で、選手は体を三回回転させて着地した。", "target_word": "回転", "complexity_tier": "T3", "furigana": "氷[こおり]の上[うえ]で、選手[せんしゅ]は体[からだ]を三回[さんかい]回転[かいてん]させて着地[ちゃくち]した。", "sentence_source": "generated"}, {"text": "モーターの回転を止めてから、部品の掃除をした。", "target_word": "回転", "complexity_tier": "T3", "furigana": "モーターの回転[かいてん]を止[と]めてから、部品[ぶひん]の掃除[そうじ]をした。", "sentence_source": "generated"}, {"text": "レコードが回転するにつれ、音楽が流れ出した。", "target_word": "回転", "complexity_tier": "T3", "furigana": "レコードが回転[かいてん]するにつれ、音楽[おんがく]が流[なが]れ出[だ]した。", "sentence_source": "generated"}, {"text": "風車は強い風を受けて、速く回転した。", "target_word": "回転", "complexity_tier": "T3", "furigana": "風車[かざぐるま]は強[つよ]い風[かぜ]を受[う]けて、速[はや]く回転[かいてん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "回転", "label": "基本形"}, {"form": "回転する", "label": "動詞形"}, {"form": "回転させる", "label": "使役形"}], "register": "neutral", "sense_fingerprint": "回転: 物が軸を中心にくるくる回る動き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cdf0ab4-1330-4fca-9cea-5488818a8241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52519, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回転", "is_correct": true, "explanation": "「回転している」で、ドラムがくるくる回る動きを表す。洗濯機の動きとして自然。"}, {"text": "注文", "is_correct": false, "explanation": "「注文」は品物を頼むこと。「ドラムが勢いよく注文している」は文が成り立たない。"}, {"text": "感染", "is_correct": false, "explanation": "「感染」は病原体がうつること。ドラムの動きには使えず、この空所には入らない。"}, {"text": "解凍", "is_correct": false, "explanation": "「解凍」は凍ったものを溶かすこと。ドラムには当てはまらず、文の意味が通らない。"}], "explanations": {"回転": "「回転している」で、ドラムがくるくる回る動きを表す。洗濯機の動きとして自然。", "注文": "「注文」は品物を頼むこと。「ドラムが勢いよく注文している」は文が成り立たない。", "感染": "「感染」は病原体がうつること。ドラムの動きには使えず、この空所には入らない。", "解凍": "「解凍」は凍ったものを溶かすこと。ドラムには当てはまらず、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "回転"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工事は予定どおり回転している。", "explanation": "ここは〈物事が順に進むこと〉の意味。〈進行〉と混同しやすいが、回転は物がくるくるまわる動きなので、工事の進み具合には使えない。"}, {"text": "バスは一時間かけて、郊外へ回転した。", "explanation": "ここは〈場所を移ること〉の意味。〈移動〉と混同しやすいが、回転はその場で軸を中心にまわる動きなので、別の場所へ移る意味では使えない。"}, {"text": "電車は駅を回転して、速度を落とさなかった。", "explanation": "ここは〈駅を通り抜けること〉の意味。〈通過〉と混同しやすいが、回転は軸を中心にまわる動きなので、場所を通り過ぎる意味には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52519, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回転", "is_correct": true, "explanation": "「体を三回回転させて」の「回転」。体をくるくる回す動きを表し、この文脈に合う。"}, {"text": "分類", "is_correct": false, "explanation": "「分類」は種類ごとに分けること。「体を三回分類させて」は不自然で、この空所には入らない。"}, {"text": "採点", "is_correct": false, "explanation": "「採点」は点数をつけること。「体を三回採点させて」は成り立たない。"}, {"text": "点灯", "is_correct": false, "explanation": "「点灯」は明かりをつけること。体の動きには使えず、この空所には合わない。"}], "explanations": {"回転": "「体を三回回転させて」の「回転」。体をくるくる回す動きを表し、この文脈に合う。", "分類": "「分類」は種類ごとに分けること。「体を三回分類させて」は不自然で、この空所には入らない。", "採点": "「採点」は点数をつけること。「体を三回採点させて」は成り立たない。", "点灯": "「点灯」は明かりをつけること。体の動きには使えず、この空所には合わない。"}, "sentence_index": 6, "correct_answer": "回転"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合は後半に一気に回転した。", "explanation": "ここは〈勝ち負けが入れ替わること〉の意味。〈逆転〉と混同しやすいが、回転は物がまわる動きなので、結果の入れ替わりは表せない。"}, {"text": "夜になって、天気が急に回転した。", "explanation": "ここは〈状態が変わること〉の意味。〈変化〉と混同しやすいが、回転は物がまわる動きなので、天気の変化には使えない。"}, {"text": "気温が一気に回転した。", "explanation": "ここは〈数値が上がること〉の意味。〈上昇〉と混同しやすいが、回転は物がまわる動きなので、気温の上がり方には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52519, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "コマの回転を止まると、倒れてしまう。", "corrected_sentence": "コマの回転が止まると、倒れてしまう。", "error_description": "誤りは「回転」に付く格助詞。「止まる」は自動詞なので主語として「回転が」が必要で、「回転を止まる」は成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52519, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "風車の羽根は回転させ、風の音が大きくなる。", "corrected_sentence": "風車の羽根は回転し、風の音が大きくなる。", "error_description": "誤りは「回転」に続く動詞の形。羽根は自分で回る自動詞の主語なので「回転し」が正しい。「回転させ」は誰かが回す使役で、主語の羽根と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52520, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「回転が鈍い」の主語を示す「が」。頭の回転という状態の主体を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「鈍い」は目的語を取らないので「回転を鈍くて」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や結果を示すが、「回転に鈍くて」では状態を述べる文として意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「回転で鈍くて」と状態を述べる文型にはならない。"}], "correct_answer": "が", "explanations": {"が": "「回転が鈍い」の主語を示す「が」。頭の回転という状態の主体を表す。", "を": "「を」は目的語を示すが、「鈍い」は目的語を取らないので「回転を鈍くて」は成り立たない。", "に": "「に」は相手や結果を示すが、「回転に鈍くて」では状態を述べる文として意味が通らない。", "で": "「で」は手段や場所を示すが、「回転で鈍くて」と状態を述べる文型にはならない。"}, "error_tags": {"を": "目的語", "に": "相手・結果", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52520, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「回転が鈍らない」の主語を示す「が」。頭の回転が鈍らないようにという文の主体。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示すが、「回転と鈍らないように」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「回転へ鈍らない」は状態の主語として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「回転から鈍らないように」では意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「回転が鈍らない」の主語を示す「が」。頭の回転が鈍らないようにという文の主体。", "と": "「と」は並列や引用を示すが、「回転と鈍らないように」では文が成り立たない。", "へ": "「へ」は方向を示すが、「回転へ鈍らない」は状態の主語として成り立たない。", "から": "「から」は起点を示すが、「回転から鈍らないように」では意味が通らない。"}, "error_tags": {"と": "並列・引用", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52520, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "頭をしっかり働かせること。頭の働きの速さをたとえて言う。", "primary_collocate": null, "pronunciation": "かいてん", "ipa": "kaiteɴ", "syllable_count": 4, "sentences": [{"text": "教師の指示のもと、静寂を保ちつつも頭脳をフル回転させる学習の時間。", "target_word": "回転", "complexity_tier": "T4", "furigana": "教師[きょうし]の指示[しじ]のもと、静寂[せいじゃく]を保[たも]ちつつも頭脳[ずのう]をフル回転[かいてん]させる学習[がくしゅう]の時間[じかん]。", "sentence_source": "mined"}, {"text": "試験の前日は、頭の回転が鈍くて何も覚えられなかった。", "target_word": "回転", "complexity_tier": "T3", "furigana": "試験[しけん]の前日[ぜんじつ]は、頭[あたま]の回転[かいてん]が鈍[にぶ]くて何[なに]も覚[おぼ]えられなかった。", "sentence_source": "generated"}, {"text": "朝は頭の回転が遅いので、大事な話は午後にしたい。", "target_word": "回転", "complexity_tier": "T3", "furigana": "朝[あさ]は頭[あたま]の回転[かいてん]が遅[おそ]いので、大事[だいじ]な話[はなし]は午後[ごご]にしたい。", "sentence_source": "generated"}, {"text": "彼女は頭の回転がよく、冗談への返しも早い。", "target_word": "回転", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は頭[あたま]の回転[かいてん]がよく、冗談[じょうだん]への返[かえ]しも早[はや]い。", "sentence_source": "generated"}, {"text": "寝不足だと頭がうまく回転せず、簡単な計算も間違える。", "target_word": "回転", "complexity_tier": "T3", "furigana": "寝不足[ねぶそく]だと頭[あたま]がうまく回転[かいてん]せず、簡単[かんたん]な計算[けいさん]も間違[まちが]える。", "sentence_source": "generated"}, {"text": "将棋の名人は、頭を高速で回転させて何十手も先を読む。", "target_word": "回転", "complexity_tier": "T3", "furigana": "将棋[しょうぎ]の名人[めいじん]は、頭[あたま]を高速[こうそく]で回転[かいてん]させて何十手[なんじゅってん]も先[さき]を読[よ]む。", "sentence_source": "generated"}, {"text": "難しいクイズ番組では、頭の回転の速さが勝負を分ける。", "target_word": "回転", "complexity_tier": "T3", "furigana": "難[むずか]しいクイズ番組[ばんぐみ]では、頭[あたま]の回転[かいてん]の速[はや]さが勝負[しょうぶ]を分[わ]ける。", "sentence_source": "generated"}, {"text": "疲れているときは、頭の回転が鈍らないように甘いものを食べる。", "target_word": "回転", "complexity_tier": "T3", "furigana": "疲[つか]れているときは、頭[あたま]の回転[かいてん]が鈍[にぶ]らないように甘[あま]いものを食[た]べる。", "sentence_source": "generated"}, {"text": "新人の彼は、頭の回転が速いと先輩にほめられた。", "target_word": "回転", "complexity_tier": "T3", "furigana": "新人[しんじん]の彼[かれ]は、頭[あたま]の回転[かいてん]が速[はや]いと先輩[せんぱい]にほめられた。", "sentence_source": "generated"}, {"text": "冷たい水で顔を洗うと、頭が回転し始める気がする。", "target_word": "回転", "complexity_tier": "T3", "furigana": "冷[つめ]たい水[みず]で顔[かお]を洗[あら]うと、頭[あたま]が回転[かいてん]し始[はじ]める気[き]がする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "回転", "label": "基本形"}, {"form": "回転する", "label": "動詞形"}, {"form": "回転させる", "label": "使役形"}], "register": "neutral", "sense_fingerprint": "回転: 頭の働きの速さ・よく働くことのたとえ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cdf0ab4-1330-4fca-9cea-5488818a8241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52520, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回転", "is_correct": true, "explanation": "「フル回転させる」で、頭脳を最大限に働かせる意味の「回転」。頭の働きの速さを表すので自然に入る。"}, {"text": "点滅", "is_correct": false, "explanation": "「点滅」は明かりがついたり消えたりすること。「頭脳をフル点滅させる」は意味をなさず、この空所には入らない。"}, {"text": "分解", "is_correct": false, "explanation": "「分解」は物をばらすこと。「頭脳をフル分解させる」は頭の働きの意味にならず、文が成り立たない。"}, {"text": "解凍", "is_correct": false, "explanation": "「解凍」は凍った物を溶かすこと。頭脳を「フル解凍させる」とは言えず、この空所には合わない。"}], "explanations": {"回転": "「フル回転させる」で、頭脳を最大限に働かせる意味の「回転」。頭の働きの速さを表すので自然に入る。", "点滅": "「点滅」は明かりがついたり消えたりすること。「頭脳をフル点滅させる」は意味をなさず、この空所には入らない。", "分解": "「分解」は物をばらすこと。「頭脳をフル分解させる」は頭の働きの意味にならず、文が成り立たない。", "解凍": "「解凍」は凍った物を溶かすこと。頭脳を「フル解凍させる」とは言えず、この空所には合わない。"}, "sentence_index": 0, "correct_answer": "回転"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は回転を利かせて、トラブルを一言で収めた。", "explanation": "ここは〈機転〉の意味。〈機転〉と混同しやすいが、回転は頭の働きの速さを指すので、とっさの工夫を利かせる使い方はできない。"}, {"text": "祖母は長年の回転で、季節の変わり目の体調管理を教えてくれた。", "explanation": "ここは〈長年の経験から得た知恵〉の意味。〈知恵〉と混同しやすいが、回転は頭の働きの速さを指すので、経験の積み重ねは表せない。"}, {"text": "彼女は回転に任せて答えを選び、理由は後から考えた。", "explanation": "ここは〈直感〉の意味。〈直感〉と混同しやすいが、回転は頭が速く働くことを指すので、直感的に即決する様子とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52520, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回転", "is_correct": true, "explanation": "「頭の回転の速さ」の「回転」。頭の働きの速さを表し、勝負を分ける要素として自然。"}, {"text": "配送", "is_correct": false, "explanation": "「配送」は荷物を届けること。「頭の配送の速さ」は意味をなさず、この空所には入らない。"}, {"text": "採点", "is_correct": false, "explanation": "「採点」は答案に点数をつけること。「頭の採点の速さ」とは言えず、文が成り立たない。"}, {"text": "点灯", "is_correct": false, "explanation": "「点灯」は明かりをつけること。「頭の点灯の速さ」は不自然で、この文には合わない。"}], "explanations": {"回転": "「頭の回転の速さ」の「回転」。頭の働きの速さを表し、勝負を分ける要素として自然。", "配送": "「配送」は荷物を届けること。「頭の配送の速さ」は意味をなさず、この空所には入らない。", "採点": "「採点」は答案に点数をつけること。「頭の採点の速さ」とは言えず、文が成り立たない。", "点灯": "「点灯」は明かりをつけること。「頭の点灯の速さ」は不自然で、この文には合わない。"}, "sentence_index": 6, "correct_answer": "回転"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の後半は、部屋の換気扇の回転が止まらなかった。", "explanation": "ここは〈物がくるくる回ること〉の意味。頭の働きの速さとは関係なく、物理的な回転を指すので、ここでは使えない。"}, {"text": "彼は回転を重ねて、やっと試験に合格した。", "explanation": "ここは〈努力を積み重ねること〉の意味。〈努力〉と混同しやすいが、回転は頭の働きの速さを指すので、積み重ねの努力とは結びつかない。"}, {"text": "祖母は昔の出来事を、回転で細かく覚えている。", "explanation": "ここは〈記憶が確かなこと〉の意味。〈記憶〉と混同しやすいが、回転は頭の働きの速さを指すので、記憶の保持には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52520, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "頭の回転を速い人は、会議でも話の流れを素早くつかむ。", "corrected_sentence": "頭の回転が速い人は、会議でも話の流れを素早くつかむ。", "error_description": "誤りは「回転」に付く格助詞。主語を示す「が」が正しく、「を」は目的語の助詞なので「回転を速い」は成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52520, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "将棋の棋士は、対局中に頭を回転して候補を絞る。", "corrected_sentence": "将棋の棋士は、対局中に頭を回転させて候補を絞る。", "error_description": "誤りは「回転」に続く動詞の形。「頭を回転させる」は誰かが頭を回す使役の形が必要なのに、「回転して」は自動詞の形になっている。正しくは「回転させて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52521, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「親に電話をする」の「に」。電話をかける相手を示す。"}, {"text": "を", "is_correct": false, "explanation": "「親を電話」は目的語が重なり、電話の相手にならない。"}, {"text": "で", "is_correct": false, "explanation": "「親で電話」は手段や場所になり、相手を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「親の電話」は所有を表す名詞句になり、「電話をして」と続かない。"}], "correct_answer": "に", "explanations": {"に": "「親に電話をする」の「に」。電話をかける相手を示す。", "を": "「親を電話」は目的語が重なり、電話の相手にならない。", "で": "「親で電話」は手段や場所になり、相手を示せない。", "の": "「親の電話」は所有を表す名詞句になり、「電話をして」と続かない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52521, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「親から新しい自転車をもらった」の「から」。もらう相手の起点を示す。"}, {"text": "と", "is_correct": false, "explanation": "「親と」は並列や共同を示し、「もらった」の相手にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「親へ」は方向を示し、もらう相手の意味にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「親より」は比較を示し、「もらった」の相手にはならない。"}], "correct_answer": "から", "explanations": {"から": "「親から新しい自転車をもらった」の「から」。もらう相手の起点を示す。", "と": "「親と」は並列や共同を示し、「もらった」の相手にはならない。", "へ": "「親へ」は方向を示し、もらう相手の意味にはならない。", "より": "「親より」は比較を示し、「もらった」の相手にはならない。"}, "error_tags": {"と": "共同", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52521, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "おとうさんやおかあさんのこと。", "primary_collocate": null, "pronunciation": "おや", "ipa": "oja", "syllable_count": 2, "sentences": [{"text": "私の親は、毎朝六時に起きて弁当を作ってくれる。", "target_word": "親", "complexity_tier": "T3", "furigana": "私[わたし]の親[おや]は、毎朝[まいあさ]六時[ろくじ]に起[お]きて弁当[べんとう]を作[つく]ってくれる。", "sentence_source": "generated"}, {"text": "親に電話をして、元気だと伝えた。", "target_word": "親", "complexity_tier": "T3", "furigana": "親[おや]に電話[でんわ]をして、元気[げんき]だと伝[つた]えた。", "sentence_source": "generated"}, {"text": "彼は親と一緒に、夏休みに海へ行った。", "target_word": "親", "complexity_tier": "T3", "furigana": "彼[かれ]は親[おや]と一緒[いっしょ]に、夏休[なつやす]みに海[うみ]へ行[い]った。", "sentence_source": "generated"}, {"text": "友だちの親が、車で駅まで送ってくれた。", "target_word": "親", "complexity_tier": "T3", "furigana": "友[とも]だちの親[おや]が、車[くるま]で駅[えき]まで送[おく]ってくれた。", "sentence_source": "generated"}, {"text": "親に叱られたので、今日はゲームをしない。", "target_word": "親", "complexity_tier": "T3", "furigana": "親[おや]に叱[しか]られたので、今日[きょう]はゲームをしない。", "sentence_source": "generated"}, {"text": "親が仕事で遅いから、夕食は弟と二人で食べる。", "target_word": "親", "complexity_tier": "T3", "furigana": "親[おや]が仕事[しごと]で遅[おそ]いから、夕食[ゆうしょく]は弟[おとうと]と二人[ふたり]で食[た]べる。", "sentence_source": "generated"}, {"text": "兄は親に似て、背がとても高い。", "target_word": "親", "complexity_tier": "T3", "furigana": "兄[あに]は親[おや]に似[に]て、背[せ]がとても高[たか]い。", "sentence_source": "generated"}, {"text": "誕生日に、親から新しい自転車をもらった。", "target_word": "親", "complexity_tier": "T3", "furigana": "誕生日[たんじょうび]に、親[おや]から新[あたら]しい自転車[じてんしゃ]をもらった。", "sentence_source": "generated"}, {"text": "親の誕生日には、毎年花を送っている。", "target_word": "親", "complexity_tier": "T3", "furigana": "親[おや]の誕生日[たんじょうび]には、毎年[まいとし]花[はな]を送[おく]っている。", "sentence_source": "generated"}, {"text": "小さいころ、親と手をつないで公園へ行った。", "target_word": "親", "complexity_tier": "T3", "furigana": "小[ちい]さいころ、親[おや]と手[て]をつないで公園[こうえん]へ行[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "親", "label": "基本形"}, {"form": "親たち", "label": "複数形"}], "register": "neutral", "sense_fingerprint": "親: 自分や友だちのお父さん・お母さん", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cdf0ab4-1330-4fca-9cea-5488818a8241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52521, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "親", "is_correct": true, "explanation": "おとうさん・おかあさんを指す「親」。毎朝六時に起きて弁当を作る人として自然に入る。"}, {"text": "犬", "is_correct": false, "explanation": "「犬」は弁当を作れないので、「私の犬は毎朝六時に起きて弁当を作ってくれる」は意味が通らない。"}, {"text": "窓", "is_correct": false, "explanation": "「窓」は弁当を作らない。「私の窓は」と続けると文として成り立たない。"}, {"text": "空", "is_correct": false, "explanation": "「空」は弁当を作らない。「私の空は」と続けても意味が通らない。"}], "explanations": {"親": "おとうさん・おかあさんを指す「親」。毎朝六時に起きて弁当を作る人として自然に入る。", "犬": "「犬」は弁当を作れないので、「私の犬は毎朝六時に起きて弁当を作ってくれる」は意味が通らない。", "窓": "「窓」は弁当を作らない。「私の窓は」と続けると文として成り立たない。", "空": "「空」は弁当を作らない。「私の空は」と続けても意味が通らない。"}, "sentence_index": 0, "correct_answer": "親"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "親は小学校に入学したばかりで、毎朝ランドセルを背負って登校する。", "explanation": "ここは〈小学生〉の意味。〈小学生〉と混同しやすいが、親は子を育てる父母のことなので、学校に通う子どもには使えない。"}, {"text": "親は幼稚園に通っていて、お遊戯の時間が楽しみだ。", "explanation": "ここは〈幼稚園児〉の意味。〈幼稚園児〉と混同しやすいが、親は子どもを持つ父母のことなので、園に通う子どもには使えない。"}, {"text": "親は夜泣きがひどくて、一晩中泣いていた。", "explanation": "ここは〈赤ちゃん〉の意味。〈赤ちゃん〉と混同しやすいが、親は子を育てる父母のことなので、夜泣きをする乳児には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52521, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "親", "is_correct": true, "explanation": "おとうさん・おかあさんを指す「親」。兄が背格好を似せる相手として文に合う。"}, {"text": "雨", "is_correct": false, "explanation": "「雨」は天気の一つで、人の背格好を比べる相手にはならず、「兄は雨に似て」は不自然。"}, {"text": "紙", "is_correct": false, "explanation": "「紙」は薄い物で、兄の背の高さとの比較には使えず、文脈に合わない。"}, {"text": "砂", "is_correct": false, "explanation": "「砂」は粒の集まりで、人の背の高さの比較には使えず、「兄は砂に似て」は意味が通らない。"}], "explanations": {"親": "おとうさん・おかあさんを指す「親」。兄が背格好を似せる相手として文に合う。", "雨": "「雨」は天気の一つで、人の背格好を比べる相手にはならず、「兄は雨に似て」は不自然。", "紙": "「紙」は薄い物で、兄の背の高さとの比較には使えず、文脈に合わない。", "砂": "「砂」は粒の集まりで、人の背の高さの比較には使えず、「兄は砂に似て」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "親"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校の親が、体育館の鍵を閉めた。", "explanation": "ここは〈先生〉の意味。〈先生〉と混同しやすいが、学校の教職員を親とは言わないので、父母の意味では合わない。"}, {"text": "商店街の親が、子どもたちにお菓子をくれた。", "explanation": "ここは〈店主〉の意味。〈店主〉と混同しやすいが、店を営む人を親とは言わないので、この項目の父母の意味には合わない。"}, {"text": "親は要人の横に立って、周囲に目を光らせていた。", "explanation": "ここは〈ボディーガード〉の意味。〈ボディーガード〉と混同しやすいが、親は子を育てる父母のことなので、警護の役目には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52521, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母の家に行く前に、親を相談して予定を決めた。", "corrected_sentence": "祖母の家に行く前に、親と相談して予定を決めた。", "error_description": "誤りは「親」に付く助詞。相談する相手を示す「と」が正しく、「親を相談」は目的語の「を」になり、相談の相手にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52521, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "親に叱らせて、今日は早く寝た。", "corrected_sentence": "親に叱られて、今日は早く寝た。", "error_description": "誤りは「親に」に続く動詞の形。親から叱られる受け身の「叱られて」が正しく、「叱らせて」は使役で、自分が親に叱らせる意味になり文の意味が変わる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde8e4-19f7-4600-b559-a905ef1260cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52523, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「祈りの時間」で、祈りを時間の内容として結ぶ「の」。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表す。「祈りで時間がある」とは続かない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す。時間の存在を述べる文には入らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す。「祈りから時間がある」は文として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "正解。「祈りの時間」で、祈りを時間の内容として結ぶ「の」。", "で": "場所や手段を表す。「祈りで時間がある」とは続かない。", "へ": "方向を表す。時間の存在を述べる文には入らない。", "から": "起点を表す。「祈りから時間がある」は文として成り立たない。"}, "error_tags": {"で": "場所・手段", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52523, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「祈りをする」の対象を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「祈りがするのが」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。「祈りよりするのが」は文として通らない。"}, {"text": "の", "is_correct": false, "explanation": "連体や所有を示す。「祈りのするのが」は文法的に続かない。"}], "correct_answer": "を", "explanations": {"を": "正解。「祈りをする」の対象を示す「を」。", "が": "主語を示す。「祈りがするのが」は成り立たない。", "より": "比較を示す。「祈りよりするのが」は文として通らない。", "の": "連体や所有を示す。「祈りのするのが」は文法的に続かない。"}, "error_tags": {"が": "主語", "より": "比較", "の": "連体・所有"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52523, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "神様にお願いすること。", "primary_collocate": null, "pronunciation": "いのり", "ipa": "inoɾi", "syllable_count": 3, "sentences": [{"text": "村の人々は、雨が降るように祈りを捧げた。", "target_word": "祈り", "complexity_tier": "T3", "furigana": "村[むら]の人々[ひとびと]は、雨[あめ]が降[ふ]るように祈[いの]りを捧[ささ]げた。", "sentence_source": "generated"}, {"text": "教会では、毎朝静かな祈りの時間がある。", "target_word": "祈り", "complexity_tier": "T3", "furigana": "教会[きょうかい]では、毎朝[まいあさ]静[しず]かな祈[いの]りの時間[じかん]がある。", "sentence_source": "generated"}, {"text": "母は、息子の無事を願って祈りを込めたお守りを渡した。", "target_word": "祈り", "complexity_tier": "T3", "furigana": "母[はは]は、息子[むすこ]の無事[ぶじ]を願[ねが]って祈[いの]りを込[こ]めたお守[まも]りを渡[わた]した。", "sentence_source": "generated"}, {"text": "彼の祈りが神様に届いたのか、病気はすっかり治った。", "target_word": "祈り", "complexity_tier": "T3", "furigana": "彼[かれ]の祈[いの]りが神様[かみさま]に届[とど]いたのか、病気[びょうき]はすっかり治[なお]った。", "sentence_source": "generated"}, {"text": "遭難した船の家族は、無事の帰還を神に願う祈りを毎日続けた。", "target_word": "祈り", "complexity_tier": "T3", "furigana": "遭難[そうなん]した船[ふね]の家族[かぞく]は、無事[ぶじ]の帰還[きかん]を神[かみ]に願[ねが]う祈[いの]りを毎日[まいにち]続[つづ]けた。", "sentence_source": "generated"}, {"text": "神社で手を合わせ、短い祈りのあとに深く頭を下げた。", "target_word": "祈り", "complexity_tier": "T3", "furigana": "神社[じんじゃ]で手[て]を合[あ]わせ、短[みじか]い祈[いの]りのあとに深[ふか]く頭[あたま]を下[さ]げた。", "sentence_source": "generated"}, {"text": "地震のあと、町中が犠牲者への祈りに包まれた。", "target_word": "祈り", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、町中[まちじゅう]が犠牲者[ぎせいしゃ]への祈[いの]りに包[つつ]まれた。", "sentence_source": "generated"}, {"text": "食事の前に祈りをするのが、この家の習慣だ。", "target_word": "祈り", "complexity_tier": "T3", "furigana": "食事[しょくじ]の前[まえ]に祈[いの]りをするのが、この家[いえ]の習慣[しゅうかん]だ。", "sentence_source": "generated"}, {"text": "祖母は毎晩、仏壇の前で長い祈りを続けている。", "target_word": "祈り", "complexity_tier": "T3", "furigana": "祖母[そぼ]は毎晩[まいばん]、仏壇[ぶつだん]の前[まえ]で長[なが]い祈[いの]りを続[つづ]けている。", "sentence_source": "generated"}, {"text": "出発の前、巡礼者たちは山の神への祈りを唱え、旅の安全を願った。", "target_word": "祈り", "complexity_tier": "T3", "furigana": "出発[しゅっぱつ]の前[まえ]、巡礼者[じゅんれいしゃ]たちは山[やま]の神[かみ]への祈[いの]りを唱[とな]え、旅[たび]の安全[あんぜん]を願[ねが]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "祈り", "label": "基本形"}, {"form": "祈りを", "label": "格助詞つき"}], "register": "中立（普通体）", "sense_fingerprint": "神や仏に願いを捧げる行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19296fb3-942a-43e0-bd14-652689089628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52523, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "祈り", "is_correct": true, "explanation": "正解。神に願いを捧げる行為を表し、「捧げた」の対象になる。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は文章を送るもの。神に捧げる対象にはならない。"}, {"text": "洗濯物", "is_correct": false, "explanation": "洗濯物は洗った衣類などのこと。雨を願う捧げ物としては合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は学習用の本。雨を願う捧げ物としては合わない。"}], "explanations": {"祈り": "正解。神に願いを捧げる行為を表し、「捧げた」の対象になる。", "手紙": "手紙は文章を送るもの。神に捧げる対象にはならない。", "洗濯物": "洗濯物は洗った衣類などのこと。雨を願う捧げ物としては合わない。", "教科書": "教科書は学習用の本。雨を願う捧げ物としては合わない。"}, "sentence_index": 0, "correct_answer": "祈り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝、近所の人と祈りを交わした。", "explanation": "ここは〈挨拶〉の意味。朝の挨拶は交わすが、祈りを人と交わすとは言わない。"}, {"text": "二人は結婚の祈りを立てて、長い付き合いを約束した。", "explanation": "ここは〈誓い〉の意味。誓いは立てるものだが、祈りを立てるとは言わない。"}, {"text": "二人の祈りを解いた。", "explanation": "ここは〈誤解〉の意味。誤解は解くものだが、祈りを解くとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52523, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "祈り", "is_correct": true, "explanation": "正解。犠牲者を悼む願いの気持ちを表し、「〜への祈りに包まれた」と続く。"}, {"text": "合図", "is_correct": false, "explanation": "合図は知らせるための信号。「〜への合図に包まれた」とは続かない。"}, {"text": "料理", "is_correct": false, "explanation": "料理は食べ物を作ること。犠牲者への対象にはならない。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題は学校の課題。「犠牲者への宿題」は文として成り立たない。"}], "explanations": {"祈り": "正解。犠牲者を悼む願いの気持ちを表し、「〜への祈りに包まれた」と続く。", "合図": "合図は知らせるための信号。「〜への合図に包まれた」とは続かない。", "料理": "料理は食べ物を作ること。犠牲者への対象にはならない。", "宿題": "宿題は学校の課題。「犠牲者への宿題」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "祈り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は素晴らしい祈りを弾いて、会場を感動させた。", "explanation": "ここは〈演奏〉（曲）の意味。曲は弾くものだが、祈りは弾くものではない。"}, {"text": "彼は大きな祈りをついて、周りをだました。", "explanation": "ここは〈嘘〉の意味。嘘はつくものだが、祈りをつくとは言わない。"}, {"text": "二人は長い別れの祈りを告げて、駅を出た。", "explanation": "ここは〈別れ〉の意味。別れは告げるものだが、祈りを告げるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52523, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "お守りには、家族の幸せを願う祈りが張られている。", "corrected_sentence": "お守りには、家族の幸せを願う祈りが込められている。", "error_description": "誤りは祈りに続く動詞。「祈りを込める」が正しい。「張る」は祈りには使わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52523, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は、神様での祈りを毎晩欠かさない。", "corrected_sentence": "彼女は、神様への祈りを毎晩欠かさない。", "error_description": "誤りは助詞。祈りの相手や向かう先は「への」で示す。「での」は場所を示すので、祈りの対象には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
