INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52525, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ずっと見ていること。だいじに思って、目をはなさないこと。", "primary_collocate": null, "pronunciation": "みまもる", "ipa": "mimamoɾɯ", "syllable_count": 4, "sentences": [{"text": "母は、初めて自転車に乗る娘を後ろから見守った。", "target_word": "見守った", "complexity_tier": "T3", "furigana": "母[はは]は、初[はじ]めて自転車[じてんしゃ]に乗[の]る娘[むすめ]を後[うし]ろから見守[みまも]った。", "sentence_source": "generated"}, {"text": "先生は、生徒たちが自分で答えを見つけるのを見守っている。", "target_word": "見守って", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒[せいと]たちが自分[じぶん]で答[こた]えを見[み]つけるのを見守[みまも]っている。", "sentence_source": "generated"}, {"text": "家族は手術室の前で、手術が終わるまで静かに見守った。", "target_word": "見守った", "complexity_tier": "T3", "furigana": "家族[かぞく]は手術室[しゅじゅつしつ]の前[まえ]で、手術[しゅじゅつ]が終[お]わるまで静[しず]かに見守[みまも]った。", "sentence_source": "generated"}, {"text": "口を出さずに見守るのも、親の大切な役目だ。", "target_word": "見守る", "complexity_tier": "T3", "furigana": "口[くち]を出[だ]さずに見守[みまも]るのも、親[おや]の大切[たいせつ]な役目[やくめ]だ。", "sentence_source": "generated"}, {"text": "町の人々は、新しい橋ができていくようすを毎日見守った。", "target_word": "見守った", "complexity_tier": "T3", "furigana": "町[まち]の人々[ひとびと]は、新[あたら]しい橋[はし]ができていくようすを毎日[まいにち]見守[みまも]った。", "sentence_source": "generated"}, {"text": "天国から私たちを見守ってくれている祖父に、感謝したい。", "target_word": "見守って", "complexity_tier": "T3", "furigana": "天国[てんごく]から私[わたし]たちを見守[みまも]ってくれている祖父[そふ]に、感謝[かんしゃ]したい。", "sentence_source": "generated"}, {"text": "犬は、赤ちゃんが眠っている間、ずっとそばで見守っていた。", "target_word": "見守って", "complexity_tier": "T3", "furigana": "犬[いぬ]は、赤[あか]ちゃんが眠[ねむ]っている間[あいだ]、ずっとそばで見守[みまも]っていた。", "sentence_source": "generated"}, {"text": "観客は、選手の最後のジャンプを息をのんで見守った。", "target_word": "見守った", "complexity_tier": "T3", "furigana": "観客[かんきゃく]は、選手[せんしゅ]の最後[さいご]のジャンプを息[いき]をのんで見守[みまも]った。", "sentence_source": "generated"}, {"text": "心配だが、今は手を出さず、彼の成長を見守ろうと思う。", "target_word": "見守ろう", "complexity_tier": "T3", "furigana": "心配[しんぱい]だが、今[いま]は手[て]を出[だ]さず、彼[かれ]の成長[せいちょう]を見守[みまも]ろうと思[おも]う。", "sentence_source": "generated"}, {"text": "隣の人が、留守の間も家を見守ってくれるので安心だ。", "target_word": "見守って", "complexity_tier": "T3", "furigana": "隣[となり]の人[ひと]が、留守[るす]の間[あいだ]も家[いえ]を見守[みまも]ってくれるので安心[あんしん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "見守る", "label": "終止形"}, {"form": "見守った", "label": "過去形"}, {"form": "見守って", "label": "て形"}, {"form": "見守ろう", "label": "意向形"}], "register": "中立（普通体）", "sense_fingerprint": "大切に思い、目を離さず見続ける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19296fb3-942a-43e0-bd14-652689089628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52525, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "見守った", "is_correct": true, "explanation": "「後ろから見守った」は、初めての自転車を支える母の姿に合う。"}, {"text": "見捨てた", "is_correct": false, "explanation": "「見捨てた」は助けずに放り出す意味で、後ろから支える場面と逆になる。"}, {"text": "断った", "is_correct": false, "explanation": "「断った」は申し出を断る意味で、娘を後ろから見る文には合わない。"}, {"text": "忘れた", "is_correct": false, "explanation": "「忘れた」は記憶から消える意味で、後ろから娘に付き添う場面と合わない。"}], "explanations": {"見守った": "「後ろから見守った」は、初めての自転車を支える母の姿に合う。", "見捨てた": "「見捨てた」は助けずに放り出す意味で、後ろから支える場面と逆になる。", "断った": "「断った」は申し出を断る意味で、娘を後ろから見る文には合わない。", "忘れた": "「忘れた」は記憶から消える意味で、後ろから娘に付き添う場面と合わない。"}, "sentence_index": 0, "correct_answer": "見守った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察は、容疑者の動きを一週間ずっと見守った。", "explanation": "ここは〈監視〉の意味。見守るは相手を大切に思って目を離さない見方で、取り締まりの監視には合わない。"}, {"text": "門の前で、不審な車を見守った。", "explanation": "ここは〈見張る〉の意味。見守るは相手を大切に思う見方で、警戒して不審者を見張る場面には合わない。"}, {"text": "彼は、契約書の細かい字を見守った。", "explanation": "ここは〈細かく読んで確かめる〉の意味。見守るは相手を大切に思って目を離さないことで、文字を読んで確認する場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52525, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "見守って", "is_correct": true, "explanation": "「見守っていた」で、そばで寝ている赤ちゃんを見守り続けた意味になる。"}, {"text": "諦めて", "is_correct": false, "explanation": "「諦めていた」は見限る意味で、寝ている赤ちゃんを守る場面と逆になる。"}, {"text": "投げ出して", "is_correct": false, "explanation": "「投げ出していた」は途中でやめる意味で、そばで見続ける場面に合わない。"}, {"text": "逃げて", "is_correct": false, "explanation": "「逃げていた」は場を離れる意味で、そばにいた文脈と合わない。"}], "explanations": {"見守って": "「見守っていた」で、そばで寝ている赤ちゃんを見守り続けた意味になる。", "諦めて": "「諦めていた」は見限る意味で、寝ている赤ちゃんを守る場面と逆になる。", "投げ出して": "「投げ出していた」は途中でやめる意味で、そばで見続ける場面に合わない。", "逃げて": "「逃げていた」は場を離れる意味で、そばにいた文脈と合わない。"}, "sentence_index": 6, "correct_answer": "見守って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は、散らかった部屋を一晩中見守った。", "explanation": "ここは〈放置する〉の意味。見守るは大切に思って目を離さないことで、散らかったまま放っておく場面には合わない。"}, {"text": "彼は隣の答案を見守った。", "explanation": "ここは〈盗み見る〉の意味。見守るは相手を大切に思って見ることで、こっそり見る場面には合わない。"}, {"text": "先生の注意を見守って、彼はゲームを続けた。", "explanation": "ここは〈無視する〉の意味。見守るは気にかけて見ることで、注意を聞き流す場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52525, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は孫が遠くから見守った。", "corrected_sentence": "祖父は孫を遠くから見守った。", "error_description": "「見守る」の対象は「を」で示す。「孫が」だと孫が見守る主語になり、祖父が見守る意味にならない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "見守って", "is_correct": true, "explanation": "「見守っている」を作る「て形」。"}, {"text": "見守る", "is_correct": false, "explanation": "終止形では「見守るいる」になり、「ている」を作れない。"}, {"text": "見守った", "is_correct": false, "explanation": "過去形では「見守ったいる」になり、進行の「ている」にならない。"}, {"text": "見守ろう", "is_correct": false, "explanation": "意向形では「見守ろういる」となり、成り立たない。"}], "correct_form": "見守って", "base_form": "見守る", "form_label": "て形", "sentence_index": 1, "explanations": {"見守って": "「見守っている」を作る「て形」。", "見守る": "終止形では「見守るいる」になり、「ている」を作れない。", "見守った": "過去形では「見守ったいる」になり、進行の「ている」にならない。", "見守ろう": "意向形では「見守ろういる」となり、成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52525, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は、遠足の子どもたちを一晩中見守た。", "corrected_sentence": "先生は、遠足の子どもたちを一晩中見守った。", "error_description": "「見守る」は五段活用なので過去形は「見守った」。「見守た」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "見守った", "is_correct": true, "explanation": "過去の出来事を表す過去形。"}, {"text": "見守り", "is_correct": false, "explanation": "連用形。文末に置くと言い切れず、過去の描写として文が成り立たない。"}, {"text": "見守れば", "is_correct": false, "explanation": "仮定形。「ば」で続く形で、文を終えられない。"}, {"text": "見守って", "is_correct": false, "explanation": "「て形」では文を終えられず、過去の描写にならない。"}], "correct_form": "見守った", "base_form": "見守る", "form_label": "過去形", "sentence_index": 7, "explanations": {"見守った": "過去の出来事を表す過去形。", "見守り": "連用形。文末に置くと言い切れず、過去の描写として文が成り立たない。", "見守れば": "仮定形。「ば」で続く形で、文を終えられない。", "見守って": "「て形」では文を終えられず、過去の描写にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52527, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有機", "is_correct": true, "explanation": "生きているもの・有機物を指す語で、生きていないもの（無機）の対義語として辞書に載る。"}, {"text": "石", "is_correct": false, "explanation": "無機の具体例であり、対義語ではない。"}, {"text": "砂", "is_correct": false, "explanation": "無機の具体例であり、対義語ではない。"}, {"text": "機械", "is_correct": false, "explanation": "人工物で、生きていないものとしての無機と対になる語ではない。"}], "correct_answer": "有機", "explanations": {"有機": "生きているもの・有機物を指す語で、生きていないもの（無機）の対義語として辞書に載る。", "石": "無機の具体例であり、対義語ではない。", "砂": "無機の具体例であり、対義語ではない。", "機械": "人工物で、生きていないものとしての無機と対になる語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52527, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有機", "is_correct": true, "explanation": "生きているもの・有機物を指す語で、生きていないもの（無機）の対義語として辞書に載る。"}, {"text": "鉄", "is_correct": false, "explanation": "無機の具体例であり、対義語ではない。"}, {"text": "ガラス", "is_correct": false, "explanation": "無機の具体例であり、対義語ではない。"}, {"text": "鉱物", "is_correct": false, "explanation": "無機物に含まれる天然の物質で、対義語ではない。"}], "correct_answer": "有機", "explanations": {"有機": "生きているもの・有機物を指す語で、生きていないもの（無機）の対義語として辞書に載る。", "鉄": "無機の具体例であり、対義語ではない。", "ガラス": "無機の具体例であり、対義語ではない。", "鉱物": "無機物に含まれる天然の物質で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52527, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "「無機」は、生きていないものや、自然ではないもののことです。", "primary_collocate": null, "pronunciation": "むき", "ipa": "mɯki", "syllable_count": 2, "sentences": [{"text": "石や鉄は生きていないので、無機の仲間に入る。", "target_word": "無機", "complexity_tier": "T3", "furigana": "石[いし]や鉄[てつ]は生[い]きていないので、無機[むき]の仲間[なかま]に入[はい]る。", "sentence_source": "generated"}, {"text": "無機のものには、命がない。", "target_word": "無機", "complexity_tier": "T3", "furigana": "無機[むき]のものには、命[いのち]がない。", "sentence_source": "generated"}, {"text": "この公園の人工的な景色は、どこか無機で、自然の山とは違う。", "target_word": "無機", "complexity_tier": "T3", "furigana": "この公園[こうえん]の人工的[じんこうてき]な景色[けしき]は、どこか無機[むき]で、自然[しぜん]の山[やま]とは違[ちが]う。", "sentence_source": "generated"}, {"text": "先生は、動物や植物を有機、石や水を無機と呼ぶと教えてくれた。", "target_word": "無機", "complexity_tier": "T3", "furigana": "先生[せんせい]は、動物[どうぶつ]や植物[しょくぶつ]を有機[ゆうき]、石[いし]や水[みず]を無機[むき]と呼[よ]ぶと教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "ガラスと鉄でできた建物が並ぶ町は、無機な感じがする。", "target_word": "無機", "complexity_tier": "T3", "furigana": "ガラスと鉄[てつ]でできた建物[たてもの]が並[なら]ぶ町[まち]は、無機[むき]な感[かん]じがする。", "sentence_source": "generated"}, {"text": "砂は無機で、種をまいても芽が出ることはない。", "target_word": "無機", "complexity_tier": "T3", "furigana": "砂[すな]は無機[むき]で、種[たね]をまいても芽[め]が出[で]ることはない。", "sentence_source": "generated"}, {"text": "机の上の無機な部品を見ながら、ロボットが動き出す日を想像した。", "target_word": "無機", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]の無機[むき]な部品[ぶひん]を見[み]ながら、ロボットが動[うご]き出[だ]す日[ひ]を想像[そうぞう]した。", "sentence_source": "generated"}, {"text": "無機と有機の違いは、生きているかどうかで考えると分かりやすい。", "target_word": "無機", "complexity_tier": "T3", "furigana": "無機[むき]と有機[ゆうき]の違[ちが]いは、生[い]きているかどうかで考[かんが]えると分[わ]かりやすい。", "sentence_source": "generated"}, {"text": "白い壁だけの部屋は無機で、少しさびしい。", "target_word": "無機", "complexity_tier": "T3", "furigana": "白[しろ]い壁[かべ]だけの部屋[へや]は無機[むき]で、少[すこ]しさびしい。", "sentence_source": "generated"}, {"text": "雨にぬれても、無機の石は何も感じない。", "target_word": "無機", "complexity_tier": "T3", "furigana": "雨[あめ]にぬれても、無機[むき]の石[いし]は何[なに]も感[かん]じない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "無機", "label": "名詞の基本形"}, {"form": "無機な", "label": "連体形（な）"}, {"form": "無機の", "label": "連体形（の）"}], "register": "標準（やさしい話し言葉）", "sense_fingerprint": "生きていないもの、自然ではないもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edb8103a-cdfa-4994-b1e8-bcd75eb2303e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52527, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "無機", "is_correct": true, "explanation": "「生きていないので」という前提に合い、仲間として成立する。"}, {"text": "植物", "is_correct": false, "explanation": "生きているものを指すので、「生きていないので」という前提と合わない。"}, {"text": "動物", "is_correct": false, "explanation": "生きているものを指すので、「生きていないので」という前提と合わない。"}, {"text": "微生物", "is_correct": false, "explanation": "生きているものを指すので、「生きていないので」という前提と合わない。"}], "explanations": {"無機": "「生きていないので」という前提に合い、仲間として成立する。", "植物": "生きているものを指すので、「生きていないので」という前提と合わない。", "動物": "生きているものを指すので、「生きていないので」という前提と合わない。", "微生物": "生きているものを指すので、「生きていないので」という前提と合わない。"}, "sentence_index": 0, "correct_answer": "無機"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ペットとして無機を飼うには、責任が伴う。", "explanation": "ここは〈生物〉の意味。無機は生きていないものを指すので、飼うペットにはならない。"}, {"text": "その森には、珍しい無機がたくさんいる。", "explanation": "ここは〈動物〉の意味。無機は生命のないものを指すので、「いる」と言う対象にならない。"}, {"text": "庭の無機は、毎朝水をやる必要がある。", "explanation": "ここは〈植物〉の意味。無機は生命のないものを指すので、水やりの対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52527, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "無機", "is_correct": true, "explanation": "「無機な部品」として、ロボットを連想させる無生物の文脈に合う。"}, {"text": "温暖", "is_correct": false, "explanation": "気候を表す語で、「温暖な部品」は意味が通らない。"}, {"text": "湿潤", "is_correct": false, "explanation": "湿り気を表す語で、「湿潤な部品」は意味が通らない。"}, {"text": "腐敗", "is_correct": false, "explanation": "物が傷むことを表す語で、「腐敗な部品」は文脈に合わない。"}], "explanations": {"無機": "「無機な部品」として、ロボットを連想させる無生物の文脈に合う。", "温暖": "気候を表す語で、「温暖な部品」は意味が通らない。", "湿潤": "湿り気を表す語で、「湿潤な部品」は意味が通らない。", "腐敗": "物が傷むことを表す語で、「腐敗な部品」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "無機"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この無機は、春になると一斉に咲く。", "explanation": "ここは〈花〉の意味。無機は生命のないものを指すので、咲く植物には当てはまらない。"}, {"text": "川には、たくさんの無機が泳いでいる。", "explanation": "ここは〈魚〉の意味。無機は生きていないものを指すので、泳ぐ生き物とは合わない。"}, {"text": "無機は、考えたり感じたりする生き物だ。", "explanation": "ここは〈人間〉の意味。無機は生きていないものを指すので、考える生き物の説明には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52527, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "石や土は無機をものとして、理科の授業で習う。", "corrected_sentence": "石や土は無機のものとして、理科の授業で習う。", "error_description": "「無機のもの」の「の」を「を」にしている。名詞を修飾する「の」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52527, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "棚の上の無機だ部品を見ながら、ロボットが動き出す日を思い描いた。", "corrected_sentence": "棚の上の無機な部品を見ながら、ロボットが動き出す日を思い描いた。", "error_description": "名詞の前では「な」を使う。「だ」は誤りで、正しくは「な」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52528, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有機", "is_correct": true, "explanation": "無機（生命や有機物を含まない物質）の対義語として辞書に載る語。"}, {"text": "金属", "is_correct": false, "explanation": "無機物に含まれる物質で、対義語ではない。"}, {"text": "鉱物", "is_correct": false, "explanation": "無機物に含まれる天然の物質で、対義語ではない。"}, {"text": "機械", "is_correct": false, "explanation": "人工物で、無機と対になる語ではない。"}], "correct_answer": "有機", "explanations": {"有機": "無機（生命や有機物を含まない物質）の対義語として辞書に載る語。", "金属": "無機物に含まれる物質で、対義語ではない。", "鉱物": "無機物に含まれる天然の物質で、対義語ではない。", "機械": "人工物で、無機と対になる語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52528, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52528, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "「無機」は、生命がなく、有機物を含まない物質や、感情や個性が感じられない様子を指します。", "primary_collocate": null, "pronunciation": "むき", "ipa": "mɯki", "syllable_count": 2, "sentences": [{"text": "その家具は無機な素材でできていて、温かみがない。", "target_word": "無機", "complexity_tier": "T4", "furigana": "その家具[かぐ]は無機[むき]な素材[そざい]でできていて、温[あたた]かみがない。", "sentence_source": "generated"}, {"text": "水や塩のような、生命を持たない物質は無機に分類される。", "target_word": "無機", "complexity_tier": "T3", "furigana": "水[みず]や塩[しお]のような、生命[せいめい]を持[も]たない物質[ぶっしつ]は無機[むき]に分類[ぶんるい]される。", "sentence_source": "generated"}, {"text": "理科の授業で、有機と無機の違いを表にまとめた。", "target_word": "無機", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、有機[ゆうき]と無機[むき]の違[ちが]いを表[ひょう]にまとめた。", "sentence_source": "generated"}, {"text": "岩や金属は無機の物質なので、植物のように成長することはない。", "target_word": "無機", "complexity_tier": "T3", "furigana": "岩[いわ]や金属[きんぞく]は無機[むき]の物質[ぶっしつ]なので、植物[しょくぶつ]のように成長[せいちょう]することはない。", "sentence_source": "generated"}, {"text": "彼は感情のない無機な声で、決まった文章を読み上げた。", "target_word": "無機", "complexity_tier": "T4", "furigana": "彼[かれ]は感情[かんじょう]のない無機[むき]な声[こえ]で、決[き]まった文章[ぶんしょう]を読[よ]み上[あ]げた。", "sentence_source": "generated"}, {"text": "無機な表情のロボットを前にして、客は少し不安になった。", "target_word": "無機", "complexity_tier": "T4", "furigana": "無機[むき]な表情[ひょうじょう]のロボットを前[まえ]にして、客[きゃく]は少[すこ]し不安[ふあん]になった。", "sentence_source": "generated"}, {"text": "駅の無機な案内音声は、いつ聞いても同じ調子で、温かみがまったく感じられない。", "target_word": "無機", "complexity_tier": "T4", "furigana": "駅[えき]の無機[むき]な案内[あんない]音声[おんせい]は、いつ聞[き]いても同[おな]じ調子[ちょうし]で、温[あたた]かみがまったく感[かん]じられない。", "sentence_source": "generated"}, {"text": "土の中の無機の成分は、植物が育つための栄養にもなる。", "target_word": "無機", "complexity_tier": "T4", "furigana": "土[つち]の中[なか]の無機[むき]の成分[せいぶん]は、植物[しょくぶつ]が育[そだ]つための栄養[えいよう]にもなる。", "sentence_source": "generated"}, {"text": "コンクリートの壁が続く団地は、どこか無機で冷たい印象を与える。", "target_word": "無機", "complexity_tier": "T4", "furigana": "コンクリートの壁[かべ]が続[つづ]く団地[だんち]は、どこか無機[むき]で冷[つめ]たい印象[いんしょう]を与[あた]える。", "sentence_source": "generated"}, {"text": "感情を込めずに話すと、聞き手には無機な印象を与えてしまう。", "target_word": "無機", "complexity_tier": "T3", "furigana": "感情[かんじょう]を込[こ]めずに話[はな]すと、聞[き]き手[て]には無機[むき]な印象[いんしょう]を与[あた]えてしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "無機", "label": "名詞の基本形"}, {"form": "無機な", "label": "連体形（な）"}, {"form": "無機の", "label": "連体形（の）"}], "register": "標準（書き言葉）", "sense_fingerprint": "生命や有機物を含まない物質、または感情や個性が感じられない様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edb8103a-cdfa-4994-b1e8-bcd75eb2303e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52528, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "無機", "is_correct": true, "explanation": "「無機な素材」の形で素材を修飾し、温かみがないという文脈に合う。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気な素材」は意味が通らず、素材の性質を示せない。"}, {"text": "豪快", "is_correct": false, "explanation": "「豪快な素材」は意味が通らず、素材の性質を示せない。"}, {"text": "俊敏", "is_correct": false, "explanation": "「俊敏な素材」は意味が通らず、素材の性質を示せない。"}], "explanations": {"無機": "「無機な素材」の形で素材を修飾し、温かみがないという文脈に合う。", "陽気": "「陽気な素材」は意味が通らず、素材の性質を示せない。", "豪快": "「豪快な素材」は意味が通らず、素材の性質を示せない。", "俊敏": "「俊敏な素材」は意味が通らず、素材の性質を示せない。"}, "sentence_index": 0, "correct_answer": "無機"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この料理は無機で、とても香ばしい。", "explanation": "ここは〈味〉の意味。無機は物質の性質や感情のなさを表すので、料理の香ばしさを表すことはできない。"}, {"text": "彼女は歌に無機をこめた。", "explanation": "ここは〈感情〉の意味。無機は感情がないことを表すので、「こめる」の目的語にはならない。"}, {"text": "この畑の無機は、毎年よく育つ。", "explanation": "ここは〈作物〉の意味。無機は生命のない物質を指すので、育つ作物には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52528, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "無機", "is_correct": true, "explanation": "「無機な」は冷たい印象の案内音声を修飾し、温かみがないという文脈に合う。"}, {"text": "陽気", "is_correct": false, "explanation": "陽気な印象は温かみがないという文脈と逆になり、合わない。"}, {"text": "腐敗", "is_correct": false, "explanation": "物が傷むことを表す語で、「腐敗な案内音声」は意味が通らない。"}, {"text": "華麗", "is_correct": false, "explanation": "華やかな印象の語で、冷たさを表す文脈に合わない。"}], "explanations": {"無機": "「無機な」は冷たい印象の案内音声を修飾し、温かみがないという文脈に合う。", "陽気": "陽気な印象は温かみがないという文脈と逆になり、合わない。", "腐敗": "物が傷むことを表す語で、「腐敗な案内音声」は意味が通らない。", "華麗": "華やかな印象の語で、冷たさを表す文脈に合わない。"}, "sentence_index": 6, "correct_answer": "無機"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は無機をもって、新しい企画を説明した。", "explanation": "ここは〈熱意〉の意味。無機は感情がないことを表すので、熱意をもって説明する表現とは合わない。"}, {"text": "無機は、飼い主の声を聞くとしっぽを振って喜ぶ。", "explanation": "ここは〈犬〉の意味。無機は生命のないものを指すので、喜ぶ生き物には使えない。"}, {"text": "無機は、友人の話を聞いて温かい気持ちになる。", "explanation": "ここは〈人間〉の感情の意味。無機は感情がないことを表すので、温かい気持ちを感じる主語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52528, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ガラスは無機を物質として、工場で使われる。", "corrected_sentence": "ガラスは無機の物質として、工場で使われる。", "error_description": "「無機の物質」の「の」を「を」にしている。名詞を修飾する「の」が正しく、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52528, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の無機で話し方は、聞く人を冷たく感じさせる。", "corrected_sentence": "彼の無機な話し方は、聞く人を冷たく感じさせる。", "error_description": "名詞を修飾するには「な」が必要。「で」は誤りで、正しくは「な」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52529, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "他律", "is_correct": true, "explanation": "他者によって律せられること。〈自律〉の対義語として辞典に載る。"}, {"text": "暗記", "is_correct": false, "explanation": "覚えること。〈自律〉の対義語ではない。"}, {"text": "慎重", "is_correct": false, "explanation": "注意深く行うこと。〈自律〉の対義語ではない。"}, {"text": "規律", "is_correct": false, "explanation": "決まりや秩序のこと。〈自律〉と関係はあるが対義語ではない。"}], "correct_answer": "他律", "explanations": {"他律": "他者によって律せられること。〈自律〉の対義語として辞典に載る。", "暗記": "覚えること。〈自律〉の対義語ではない。", "慎重": "注意深く行うこと。〈自律〉の対義語ではない。", "規律": "決まりや秩序のこと。〈自律〉と関係はあるが対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52529, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "他律", "is_correct": true, "explanation": "他者によって律せられること。〈自律〉の対義語として辞典に載る。"}, {"text": "雑談", "is_correct": false, "explanation": "気楽に話をすること。〈自律〉の対義語ではない。"}, {"text": "熟慮", "is_correct": false, "explanation": "よく考えること。〈自律〉の対義語ではない。"}, {"text": "規範", "is_correct": false, "explanation": "従うべき基準のこと。〈自律〉と対になる概念ではない。"}], "correct_answer": "他律", "explanations": {"他律": "他者によって律せられること。〈自律〉の対義語として辞典に載る。", "雑談": "気楽に話をすること。〈自律〉の対義語ではない。", "熟慮": "よく考えること。〈自律〉の対義語ではない。", "規範": "従うべき基準のこと。〈自律〉と対になる概念ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52529, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分で考えて、自分で行動すること。", "primary_collocate": null, "pronunciation": "じりつ", "ipa": "dʑiɾitsɯ", "syllable_count": 3, "sentences": [{"text": "兄は自律していて、朝は自分で起きて、自分で準備をする。", "target_word": "自律", "complexity_tier": "T3", "furigana": "兄[あに]は自律[じりつ]していて、朝[あさ]は自分[じぶん]で起[お]きて、自分[じぶん]で準備[じゅんび]をする。", "sentence_source": "generated"}, {"text": "自律とは、自分で考えて、自分で動くことだ。", "target_word": "自律", "complexity_tier": "T3", "furigana": "自律[じりつ]とは、自分[じぶん]で考[かんが]えて、自分[じぶん]で動[うご]くことだ。", "sentence_source": "generated"}, {"text": "先生は、生徒の自律を大切にして、すぐに答えを教えない。", "target_word": "自律", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒[せいと]の自律[じりつ]を大切[たいせつ]にして、すぐに答[こた]えを教[おし]えない。", "sentence_source": "generated"}, {"text": "自律して勉強する子は、親に言われなくても宿題をする。", "target_word": "自律", "complexity_tier": "T3", "furigana": "自律[じりつ]して勉強[べんきょう]する子[こ]は、親[おや]に言[い]われなくても宿題[しゅくだい]をする。", "sentence_source": "generated"}, {"text": "一人で旅行に行ったことが、私の自律につながった。", "target_word": "自律", "complexity_tier": "T3", "furigana": "一人[ひとり]で旅行[りょこう]に行[い]ったことが、私[わたし]の自律[じりつ]につながった。", "sentence_source": "generated"}, {"text": "毎朝自分で時間を決めて起きることで、妹の自律が少しずつ育った。", "target_word": "自律", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]自分[じぶん]で時間[じかん]を決[き]めて起[お]きることで、妹[いもうと]の自律[じりつ]が少[すこ]しずつ育[そだ]った。", "sentence_source": "generated"}, {"text": "この会社は、社員の自律を信じて、細かいルールを作らない。", "target_word": "自律", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、社員[しゃいん]の自律[じりつ]を信[しん]じて、細[こま]かいルールを作[つく]らない。", "sentence_source": "generated"}, {"text": "自律した人は、困ったときも、まず自分で考える。", "target_word": "自律", "complexity_tier": "T3", "furigana": "自律[じりつ]した人[ひと]は、困[こま]ったときも、まず自分[じぶん]で考[かんが]える。", "sentence_source": "generated"}, {"text": "部活で自律を学んだので、大学でも計画を立てて行動できる。", "target_word": "自律", "complexity_tier": "T3", "furigana": "部活[ぶかつ]で自律[じりつ]を学[まな]んだので、大学[だいがく]でも計画[けいかく]を立[た]てて行動[こうどう]できる。", "sentence_source": "generated"}, {"text": "自律が足りないと、休みの日は一日中ゲームをしてしまう。", "target_word": "自律", "complexity_tier": "T3", "furigana": "自律[じりつ]が足[た]りないと、休[やす]みの日[ひ]は一日中[いちにちじゅう]ゲームをしてしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自律", "label": "名詞の基本形"}, {"form": "自律する", "label": "サ変動詞の基本形"}, {"form": "自律した", "label": "サ変動詞の過去・連体形"}], "register": "標準（やさしい話し言葉）", "sense_fingerprint": "自分で考えて自分で行動すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edb8103a-cdfa-4994-b1e8-bcd75eb2303e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52529, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自律", "is_correct": true, "explanation": "「自律していて」のサ変動詞。自分で起きて準備する兄の様子に合う。"}, {"text": "海苔", "is_correct": false, "explanation": "「海苔していて」は成り立たず、サ変動詞にならない名詞。"}, {"text": "窓", "is_correct": false, "explanation": "「窓していて」は成り立たず、文が崩れる。"}, {"text": "電車", "is_correct": false, "explanation": "「電車していて」は成り立たず、文が崩れる。"}], "explanations": {"自律": "「自律していて」のサ変動詞。自分で起きて準備する兄の様子に合う。", "海苔": "「海苔していて」は成り立たず、サ変動詞にならない名詞。", "窓": "「窓していて」は成り立たず、文が崩れる。", "電車": "「電車していて」は成り立たず、文が崩れる。"}, "sentence_index": 0, "correct_answer": "自律"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は自律で小さな店を営んでいる。", "explanation": "ここは〈自営〉の意味。個人で店を経営する場面で、〈自律〉（自分で考えて行動する）は使わない。"}, {"text": "この椅子は、父が休日に自律で組み立てた。", "explanation": "ここは〈自作〉の意味。家具や道具を自分で作る場面で、〈自律〉は物の製作を表さない。"}, {"text": "合宿の機材は、部員が自律で用意した。", "explanation": "ここは〈自前〉の意味。自分たちで用意する場面で、〈自律〉は道具の出所を表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52529, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自律", "is_correct": true, "explanation": "「社員の自律を信じて」の目的語。社員が自分で動けることを信じる文脈に合う。"}, {"text": "年齢", "is_correct": false, "explanation": "「社員の年齢を信じて」は意味が通らない。"}, {"text": "人数", "is_correct": false, "explanation": "「社員の人数を信じて」は意味が通らない。"}, {"text": "給料", "is_correct": false, "explanation": "「社員の給料を信じて」は意味が通らない。"}], "explanations": {"自律": "「社員の自律を信じて」の目的語。社員が自分で動けることを信じる文脈に合う。", "年齢": "「社員の年齢を信じて」は意味が通らない。", "人数": "「社員の人数を信じて」は意味が通らない。", "給料": "「社員の給料を信じて」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "自律"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒い日は自律が乱れて、手足がずっと冷たい。", "explanation": "ここは〈自律神経〉の意味。〈自律〉だけでは体の働きを指せず、「自律神経が乱れる」の形が必要。"}, {"text": "雪景色の自律の美しさに、しばらく見とれた。", "explanation": "ここは〈自然〉の意味。「自然の美しさ」の形で、〈自律〉は当てはまらない。"}, {"text": "夏休みの自律研究で、近所の虫を観察した。", "explanation": "ここは〈自由研究〉の意味。夏休みの課題を指す語で、〈自律〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52529, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は自律が子で、朝は一人で起きられる。", "corrected_sentence": "妹は自律した子で、朝は一人で起きられる。", "error_description": "「自律」の後に「が」を置くと文が崩れる。サ変動詞の連体形「自律した」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52529, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店長は、アルバイトの自律に信じて、シフトの細かい指示を出さない。", "corrected_sentence": "店長は、アルバイトの自律を信じて、シフトの細かい指示を出さない。", "error_description": "「信じる」の目的語を示すのは「を」。「自律に」は誤りで、「自律を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52530, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「育てる」の目的語「子どもの自律」を示す「を」で、文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「育てる」は目的語を要する他動詞なので、「が」では文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「育てる」の目的語にならない「と」で、意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「育てる」の目的語にならず、文が崩れる。"}], "correct_answer": "を", "explanations": {"を": "「育てる」の目的語「子どもの自律」を示す「を」で、文が成り立つ。", "が": "「育てる」は目的語を要する他動詞なので、「が」では文が成り立たない。", "と": "「育てる」の目的語にならない「と」で、意味が通らない。", "より": "比較の「より」は「育てる」の目的語にならず、文が崩れる。"}, "error_tags": {"が": "主語の「が」", "と": "並列・引用の「と」", "より": "比較の「より」"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "他律", "is_correct": true, "explanation": "他者によって律せられること。〈自律〉の対義語として辞典に載る。"}, {"text": "暗記", "is_correct": false, "explanation": "覚えること。〈自律〉の対義語ではない。"}, {"text": "熟慮", "is_correct": false, "explanation": "よく考えること。〈自律〉の対義語ではない。"}, {"text": "規律", "is_correct": false, "explanation": "決まりや秩序のこと。〈自律〉と関係はあるが対義語ではない。"}], "correct_answer": "他律", "explanations": {"他律": "他者によって律せられること。〈自律〉の対義語として辞典に載る。", "暗記": "覚えること。〈自律〉の対義語ではない。", "熟慮": "よく考えること。〈自律〉の対義語ではない。", "規律": "決まりや秩序のこと。〈自律〉と関係はあるが対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52530, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "他律", "is_correct": true, "explanation": "他者によって律せられること。〈自律〉の対義語として辞典に載る。"}, {"text": "雑談", "is_correct": false, "explanation": "気楽に話をすること。〈自律〉の対義語ではない。"}, {"text": "慎重", "is_correct": false, "explanation": "注意深く行うこと。〈自律〉の対義語ではない。"}, {"text": "規範", "is_correct": false, "explanation": "従うべき基準のこと。〈自律〉と対になる概念ではない。"}], "correct_answer": "他律", "explanations": {"他律": "他者によって律せられること。〈自律〉の対義語として辞典に載る。", "雑談": "気楽に話をすること。〈自律〉の対義語ではない。", "慎重": "注意深く行うこと。〈自律〉の対義語ではない。", "規範": "従うべき基準のこと。〈自律〉と対になる概念ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52530, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "他のものに頼らず、自分の力で判断し、行動すること。", "primary_collocate": null, "pronunciation": "じりつ", "ipa": "dʑiɾitsɯ", "syllable_count": 3, "sentences": [{"text": "無機質な素材が自律的実体へと昇華する奇跡を、自らの双手で紡ぎ出す営み。", "target_word": "自律", "complexity_tier": "T4", "furigana": "無機質[むきしつ]な素材[そざい]が自律的[じりつてき]実体[じったい]へと昇華[しょうか]する奇跡[きせき]を、自[みずか]らの双手[そうしゅ]で紡[つむ]ぎ出[だ]す営[いとな]み。", "sentence_source": "mined"}, {"text": "子どもの自律を育てるには、親が先回りして手を出しすぎないことが大切だ。", "target_word": "自律", "complexity_tier": "T4", "furigana": "子[こ]どもの自律[じりつ]を育[そだ]てるには、親[おや]が先回[さきまわ]りして手[て]を出[だ]しすぎないことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "在宅勤務では、上司の指示を待たず、自律して仕事を進める力が求められる。", "target_word": "自律", "complexity_tier": "T4", "furigana": "在宅[ざいたく]勤務[きんむ]では、上司[じょうし]の指示[しじ]を待[ま]たず、自律[じりつ]して仕事[しごと]を進[すす]める力[ちから]が求[もと]められる。", "sentence_source": "generated"}, {"text": "彼女は誰にも頼らず、自律した態度で進路を決めた。", "target_word": "自律", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は誰[だれ]にも頼[たよ]らず、自律[じりつ]した態度[たいど]で進路[しんろ]を決[き]めた。", "sentence_source": "generated"}, {"text": "この学校は、生徒の自律を重んじ、校則をほとんど設けていない。", "target_word": "自律", "complexity_tier": "T4", "furigana": "この学校[がっこう]は、生徒[せいと]の自律[じりつ]を重[おも]んじ、校則[こうそく]をほとんど設[もう]けていない。", "sentence_source": "generated"}, {"text": "自律とは、自分で決めたことに自分で責任を持つことでもある。", "target_word": "自律", "complexity_tier": "T3", "furigana": "自律[じりつ]とは、自分[じぶん]で決[き]めたことに自分[じぶん]で責任[せきにん]を持[も]つことでもある。", "sentence_source": "generated"}, {"text": "先輩は自律した人で、監督がいなくても毎日練習を欠かさない。", "target_word": "自律", "complexity_tier": "T3", "furigana": "先輩[せんぱい]は自律[じりつ]した人[ひと]で、監督[かんとく]がいなくても毎日[まいにち]練習[れんしゅう]を欠[か]かさない。", "sentence_source": "generated"}, {"text": "上から命令されるだけの職場では、社員の自律は育ちにくい。", "target_word": "自律", "complexity_tier": "T4", "furigana": "上[うえ]から命令[めいれい]されるだけの職場[しょくば]では、社員[しゃいん]の自律[じりつ]は育[そだ]ちにくい。", "sentence_source": "generated"}, {"text": "自律を身につけたおかげで、一人暮らしでも生活のリズムを崩さずにすんだ。", "target_word": "自律", "complexity_tier": "T4", "furigana": "自律[じりつ]を身[み]につけたおかげで、一人暮[ひとりぐ]らしでも生活[せいかつ]のリズムを崩[くず]さずにすんだ。", "sentence_source": "generated"}, {"text": "組織が成長するためには、一人一人が自律して動くことが必要だ。", "target_word": "自律", "complexity_tier": "T4", "furigana": "組織[そしき]が成長[せいちょう]するためには、一人一人[ひとりひとり]が自律[じりつ]して動[うご]くことが必要[ひつよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自律", "label": "名詞の基本形"}, {"form": "自律する", "label": "サ変動詞の基本形"}, {"form": "自律した", "label": "サ変動詞の過去・連体形"}], "register": "標準（書き言葉）", "sense_fingerprint": "他に頼らず自分の判断で行動すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 無機質 (Zipf 2.84), 昇華 (Zipf 3.35), 紡ぎ (Zipf 2.82), 営み (Zipf 3.27)']::text[], 'edb8103a-cdfa-4994-b1e8-bcd75eb2303e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52530, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自律", "is_correct": true, "explanation": "「自律的実体」の「自律」。素材が自ら律する存在へ変わるという文脈に合う。"}, {"text": "食料", "is_correct": false, "explanation": "「食料的実体」は成り立たず、昇華する素材の説明にならない。"}, {"text": "液体", "is_correct": false, "explanation": "「液体的実体」は文脈に合わず、素材の変化を表せない。"}, {"text": "紙幣", "is_correct": false, "explanation": "「紙幣的実体」は昇華する素材の説明として意味が通らない。"}], "explanations": {"自律": "「自律的実体」の「自律」。素材が自ら律する存在へ変わるという文脈に合う。", "食料": "「食料的実体」は成り立たず、昇華する素材の説明にならない。", "液体": "「液体的実体」は文脈に合わず、素材の変化を表せない。", "紙幣": "「紙幣的実体」は昇華する素材の説明として意味が通らない。"}, "sentence_index": 0, "correct_answer": "自律"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は毎日、夕食を自律で作っている。", "explanation": "ここは〈自炊〉の意味。食事を自分で作る場面で、〈自律〉（判断や行動の独立）は使わない。"}, {"text": "彼は新車を自律して、友人に見せびらかした。", "explanation": "ここは〈自慢〉の意味。誇って見せる場面で、〈自律〉（判断や行動の独立）は合わない。"}, {"text": "この店の看板は、祖父が自律で書いた。", "explanation": "ここは〈自作〉の意味。自分で書いた作品を表す場面で、〈自律〉は当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52530, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自律", "is_correct": true, "explanation": "「自律した人」の「自律」。監督がいなくても練習する人物像に合う。"}, {"text": "砂利", "is_correct": false, "explanation": "「砂利した人」は成り立たず、「した」を続けられない名詞。"}, {"text": "石炭", "is_correct": false, "explanation": "「石炭した人」は成り立たず、「した」を続けられない名詞。"}, {"text": "黒板", "is_correct": false, "explanation": "「黒板した人」は成り立たず、「した」を続けられない名詞。"}], "explanations": {"自律": "「自律した人」の「自律」。監督がいなくても練習する人物像に合う。", "砂利": "「砂利した人」は成り立たず、「した」を続けられない名詞。", "石炭": "「石炭した人」は成り立たず、「した」を続けられない名詞。", "黒板": "「黒板した人」は成り立たず、「した」を続けられない名詞。"}, "sentence_index": 6, "correct_answer": "自律"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ストレスで自律が乱れ、夜になってもなかなか眠れない。", "explanation": "ここは〈自律神経〉の意味。「自律神経が乱れる」とは言うが、〈自律〉だけでは体の働きを指せない。"}, {"text": "山の自律の恵みで、この町の水は今も豊かだ。", "explanation": "ここは〈自然〉の意味。「自然の恵み」の形で、〈自律〉は自然界を指さない。"}, {"text": "ニューヨークで、自律の女神像を見上げた。", "explanation": "ここは〈自由〉の意味。「自由の女神」という固有名詞で、〈自律〉は当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52530, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は自律な判断で、新しい企画を進めた。", "corrected_sentence": "彼は自律的な判断で、新しい企画を進めた。", "error_description": "「自律」は名詞（サ変）なので、直接「な」は続けられない。「自律的な」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52530, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は自律に学習を続け、資格を取った。", "corrected_sentence": "彼女は自律して学習を続け、資格を取った。", "error_description": "「自律」を「に」で修飾することはできない。サ変動詞の連用形「自律して」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
