INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52531, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "とてもすごいこと。ふつうではありえないこと。", "primary_collocate": null, "pronunciation": "きせき", "ipa": "kiseki", "syllable_count": 3, "sentences": [{"text": "三階から落ちた子どもが無事だったのは奇跡だ。", "target_word": "奇跡", "complexity_tier": "T3", "furigana": "三階(さんがい)から落(お)ちた子(こ)どもが無事(ぶじ)だったのは奇跡(きせき)だ。", "sentence_source": "generated"}, {"text": "試合の終わりに逆転できたのは、まるで奇跡のようだった。", "target_word": "奇跡", "complexity_tier": "T3", "furigana": "試合(しあい)の終(お)わりに逆転(ぎゃくてん)できたのは、まるで奇跡(きせき)のようだった。", "sentence_source": "generated"}, {"text": "奇跡は簡単には起こらないので、努力が必要だ。", "target_word": "奇跡", "complexity_tier": "T3", "furigana": "奇跡(きせき)は簡単(かんたん)には起(お)こらないので、努力(どりょく)が必要(ひつよう)だ。", "sentence_source": "generated"}, {"text": "一年前には歩けなかった祖父が走るなんて、奇跡だと思う。", "target_word": "奇跡", "complexity_tier": "T3", "furigana": "一年前(いちねんまえ)には歩(ある)けなかった祖父(そふ)が走(はし)るなんて、奇跡(きせき)だと思(おも)う。", "sentence_source": "generated"}, {"text": "雪の日に桜が咲くという奇跡を、みんなが写真に撮った。", "target_word": "奇跡", "complexity_tier": "T3", "furigana": "雪(ゆき)の日(ひ)に桜(さくら)が咲(さ)くという奇跡(きせき)を、みんなが写真(しゃしん)に撮(と)った。", "sentence_source": "generated"}, {"text": "宝くじが二回続けて当たるなんて、奇跡でもなければありえない。", "target_word": "奇跡", "complexity_tier": "T3", "furigana": "宝(たから)くじが二回(にかい)続(つづ)けて当(あ)たるなんて、奇跡(きせき)でもなければありえない。", "sentence_source": "generated"}, {"text": "彼女は奇跡を信じて、毎日神社に祈りに行った。", "target_word": "奇跡", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は奇跡(きせき)を信(しん)じて、毎日(まいにち)神社(じんじゃ)に祈(いの)りに行(い)った。", "sentence_source": "generated"}, {"text": "地震の後、一人も怪我をしなかったのは奇跡だった。", "target_word": "奇跡", "complexity_tier": "T3", "furigana": "地震(じしん)の後(あと)、一人(ひとり)も怪我(けが)をしなかったのは奇跡(きせき)だった。", "sentence_source": "generated"}, {"text": "小さなチームが優勝するという奇跡が、本当に起こった。", "target_word": "奇跡", "complexity_tier": "T3", "furigana": "小(ちい)さなチームが優勝(ゆうしょう)するという奇跡(きせき)が、本当(ほんとう)に起(お)こった。", "sentence_source": "generated"}, {"text": "事故の中で車だけが壊れて、人が無傷だったのは奇跡に近い。", "target_word": "奇跡", "complexity_tier": "T3", "furigana": "事故(じこ)の中(なか)で車(くるま)だけが壊(こわ)れて、人(ひと)が無傷(むきず)だったのは奇跡(きせき)に近(ちか)い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "奇跡", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ふつうはありえないほどすごいこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edb8103a-cdfa-4994-b1e8-bcd75eb2303e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52531, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奇跡", "is_correct": true, "explanation": "「無事だったのは奇跡だ」の述語。ありえない幸運な結果を表す文脈に合う。"}, {"text": "家具", "is_correct": false, "explanation": "「無事だったのは家具だ」は意味が通らない。"}, {"text": "雑草", "is_correct": false, "explanation": "「無事だったのは雑草だ」は意味が通らない。"}, {"text": "窓枠", "is_correct": false, "explanation": "「無事だったのは窓枠だ」は意味が通らない。"}], "explanations": {"奇跡": "「無事だったのは奇跡だ」の述語。ありえない幸運な結果を表す文脈に合う。", "家具": "「無事だったのは家具だ」は意味が通らない。", "雑草": "「無事だったのは雑草だ」は意味が通らない。", "窓枠": "「無事だったのは窓枠だ」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "奇跡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この選手の奇跡は、今も後輩たちに語り継がれている。", "explanation": "ここは〈軌跡〉の意味。人の歩みや足跡を表す語で、〈奇跡〉（驚くべき出来事）とは別の語。"}, {"text": "川原で拾ったこの奇跡は、夕日を受けて黒く光っていた。", "explanation": "ここは〈輝石〉の意味。鉱物の名で、〈奇跡〉（驚くべき出来事）は石の名にならない。"}, {"text": "大叔父は冬に、奇跡に入った。", "explanation": "ここは〈鬼籍〉の意味。死者の名を記す帳のことで、「鬼籍に入る」は〈奇跡〉では言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52531, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奇跡", "is_correct": true, "explanation": "「奇跡を信じて」の目的語。結果が起きることを信じる文脈に合う。"}, {"text": "掃除機", "is_correct": false, "explanation": "「掃除機を信じて」は文脈に合わず不自然。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「冷蔵庫を信じて」は文脈に合わず不自然。"}, {"text": "雑誌", "is_correct": false, "explanation": "「雑誌を信じて」は文脈に合わず不自然。"}], "explanations": {"奇跡": "「奇跡を信じて」の目的語。結果が起きることを信じる文脈に合う。", "掃除機": "「掃除機を信じて」は文脈に合わず不自然。", "冷蔵庫": "「冷蔵庫を信じて」は文脈に合わず不自然。", "雑誌": "「雑誌を信じて」は文脈に合わず不自然。"}, "sentence_index": 6, "correct_answer": "奇跡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事故現場には、車が描いた奇跡が残っていた。", "explanation": "ここは〈軌跡〉の意味。跡や道筋を表す語で、〈奇跡〉とは別の語。"}, {"text": "この岩は奇跡を含んで、夕日の中できらめいていた。", "explanation": "ここは〈輝石〉の意味。鉱物の名で、〈奇跡〉は岩の成分にはならない。"}, {"text": "祖父は先月、奇跡に入った。", "explanation": "ここは〈鬼籍〉の意味。死者の名を記す帳のことで、「鬼籍に入る」は〈奇跡〉では言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52531, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の逆転は、まるで奇跡な勝利だった。", "corrected_sentence": "彼女の逆転は、まるで奇跡のような勝利だった。", "error_description": "「奇跡」に直接「な」は続けられない。比喩の「奇跡のような」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52531, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は奇跡の信じて、毎日母の手術を祈った。", "corrected_sentence": "彼女は奇跡を信じて、毎日母の手術を祈った。", "error_description": "「信じる」の目的語を示すのは「を」。「の」は誤りで、「奇跡を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52532, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52532, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「奇跡のような」の「の」。名詞を連体修飾する形で、文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「奇跡がような」は成り立たず、文が崩れる。"}, {"text": "を", "is_correct": false, "explanation": "「奇跡をような」は成り立たず、文が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "「奇跡にような」は文法的に成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「奇跡のような」の「の」。名詞を連体修飾する形で、文が成り立つ。", "が": "「奇跡がような」は成り立たず、文が崩れる。", "を": "「奇跡をような」は成り立たず、文が崩れる。", "に": "「奇跡にような」は文法的に成り立たない。"}, "error_tags": {"が": "主格（主語）", "を": "対象（目的語）", "に": "位置・状態"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52532, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "普通では考えられないような、驚くべき出来事や現象。", "primary_collocate": null, "pronunciation": "きせき", "ipa": "kiseki", "syllable_count": 3, "sentences": [{"text": "無機質な素材が自律的実体へと昇華する奇跡を、自らの双手で紡ぎ出す営み。", "target_word": "奇跡", "complexity_tier": "T5", "furigana": "無機質(むきしつ)な素材(そざい)が自律的(じりつてき)実体(じったい)へと昇華(しょうか)する奇跡(きせき)を、自(みずか)らの双手(そうしゅ)で紡(つむ)ぎ出(だ)す営(いとな)み。", "sentence_source": "mined"}, {"text": "医者も諦めた病気が治ったのは、まさに奇跡だった。", "target_word": "奇跡", "complexity_tier": "T3", "furigana": "医者(いしゃ)も諦(あきら)めた病気(びょうき)が治(なお)ったのは、まさに奇跡(きせき)だった。", "sentence_source": "generated"}, {"text": "乗客が全員無事だったのは奇跡としか言いようがない。", "target_word": "奇跡", "complexity_tier": "T3", "furigana": "乗客(じょうきゃく)が全員(ぜんいん)無事(ぶじ)だったのは奇跡(きせき)としか言(い)いようがない。", "sentence_source": "generated"}, {"text": "奇跡が起こるのを信じて、最後まで試合を戦った。", "target_word": "奇跡", "complexity_tier": "T3", "furigana": "奇跡(きせき)が起(お)こるのを信(しん)じて、最後(さいご)まで試合(しあい)を戦(たたか)った。", "sentence_source": "generated"}, {"text": "崖から落ちて、かすり傷だけで済んだのは奇跡だ。", "target_word": "奇跡", "complexity_tier": "T3", "furigana": "崖(がけ)から落(お)ちて、かすり傷(きず)だけで済(す)んだのは奇跡(きせき)だ。", "sentence_source": "generated"}, {"text": "彼の復帰は、誰も予想しなかった奇跡の物語として語り継がれている。", "target_word": "奇跡", "complexity_tier": "T3", "furigana": "彼(かれ)の復帰(ふっき)は、誰(だれ)も予想(よそう)しなかった奇跡(きせき)の物語(ものがたり)として語(かた)り継(つ)がれている。", "sentence_source": "generated"}, {"text": "奇跡を待つだけでなく、毎日練習を重ねることが大切だ。", "target_word": "奇跡", "complexity_tier": "T3", "furigana": "奇跡(きせき)を待(ま)つだけでなく、毎日(まいにち)練習(れんしゅう)を重(かさ)ねることが大切(たいせつ)だ。", "sentence_source": "generated"}, {"text": "偶然が何度も重なって、奇跡のような一日になった。", "target_word": "奇跡", "complexity_tier": "T3", "furigana": "偶然(ぐうぜん)が何度(なんど)も重(かさ)なって、奇跡(きせき)のような一日(いちにち)になった。", "sentence_source": "generated"}, {"text": "砂漠の真ん中で水を見つけたのは、奇跡に近い幸運だった。", "target_word": "奇跡", "complexity_tier": "T3", "furigana": "砂漠(さばく)の真(ま)ん中(なか)で水(みず)を見(み)つけたのは、奇跡(きせき)に近(ちか)い幸運(こううん)だった。", "sentence_source": "generated"}, {"text": "閉じ込められた作業員が皆生還し、町は奇跡だと喜んだ。", "target_word": "奇跡", "complexity_tier": "T3", "furigana": "閉(と)じ込(こ)められた作業員(さぎょういん)が皆(みな)生還(せいかん)し、町(まち)は奇跡(きせき)だと喜(よろこ)んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "奇跡", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "常識では説明できない驚くべき出来事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 5 words above tier T2 (max 3): 無機質 (Zipf 2.84), 自律 (Zipf 3.67), 昇華 (Zipf 3.35), 紡ぎ (Zipf 2.82), 営み (Zipf 3.27)']::text[], 'edb8103a-cdfa-4994-b1e8-bcd75eb2303e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52532, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奇跡", "is_correct": true, "explanation": "「奇跡を紡ぎ出す」の目的語。昇華という比喩的な出来事を表す。"}, {"text": "手続き", "is_correct": false, "explanation": "「昇華する手続きを紡ぎ出す」は意味が通らない。"}, {"text": "運搬", "is_correct": false, "explanation": "「昇華する運搬を紡ぎ出す」は意味が通らない。"}, {"text": "天井", "is_correct": false, "explanation": "「昇華する天井を紡ぎ出す」は意味が通らない。"}], "explanations": {"奇跡": "「奇跡を紡ぎ出す」の目的語。昇華という比喩的な出来事を表す。", "手続き": "「昇華する手続きを紡ぎ出す」は意味が通らない。", "運搬": "「昇華する運搬を紡ぎ出す」は意味が通らない。", "天井": "「昇華する天井を紡ぎ出す」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "奇跡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は奇跡を持っていて、どんな勝負にも勝ってしまう。", "explanation": "ここは〈幸運〉の意味。「幸運を持つ」とは言うが、起きた出来事の〈奇跡〉は持つものではない。"}, {"text": "この岩の奇跡は、夕日を受けて黒くきらめいていた。", "explanation": "ここは〈輝石〉の意味。鉱物の名で、〈奇跡〉（驚くべき出来事）は石の名にならない。"}, {"text": "叔父は去年の冬、奇跡に入った。", "explanation": "ここは〈鬼籍〉の意味。死者の名を記す帳のことで、〈奇跡〉（驚くべき出来事）では言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52532, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奇跡", "is_correct": true, "explanation": "「奇跡を待つ」の目的語。偶然の幸運を待つ文脈に合う。"}, {"text": "努力", "is_correct": false, "explanation": "「努力を待つ」は不自然で、待つ対象にならない。"}, {"text": "電卓", "is_correct": false, "explanation": "「電卓を待つ」は不自然で、待つ対象にならない。"}, {"text": "信頼", "is_correct": false, "explanation": "「信頼を待つ」は不自然で、待つ対象にならない。"}], "explanations": {"奇跡": "「奇跡を待つ」の目的語。偶然の幸運を待つ文脈に合う。", "努力": "「努力を待つ」は不自然で、待つ対象にならない。", "電卓": "「電卓を待つ」は不自然で、待つ対象にならない。", "信頼": "「信頼を待つ」は不自然で、待つ対象にならない。"}, "sentence_index": 6, "correct_answer": "奇跡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "飛行機雲が空に描いた奇跡が、夕方まできれいに残っていた。", "explanation": "ここは〈軌跡〉の意味。描いた跡を指す語で、〈奇跡〉（驚くべき出来事）とは別の語。"}, {"text": "その山の岩には奇跡が含まれていて、夕日を受けて光る。", "explanation": "ここは〈輝石〉の意味。鉱物の名前で、〈奇跡〉は岩の成分を表さない。"}, {"text": "父の友人が、奇跡に入ったと知らせが来た。", "explanation": "ここは〈鬼籍〉の意味。死者の名を記す帳のことで、〈奇跡〉（驚くべき出来事）とは別の語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52532, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "それは奇跡な出来事だった。", "corrected_sentence": "それは奇跡的な出来事だった。", "error_description": "「奇跡」は名詞なので、直接「な」は続けられない。「奇跡的な」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
