INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52533, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "両方の手。", "primary_collocate": null, "pronunciation": "そうしゅ", "ipa": "soːɕɯ", "syllable_count": 3, "sentences": [{"text": "双手を上げて、彼は降参の意思を示した。", "target_word": "双手", "complexity_tier": "T3", "furigana": "双手[そうしゅ]を上げて、彼は降参の意思を示した。", "sentence_source": "generated"}, {"text": "寒い朝、彼女は双手をポケットに入れて歩いた。", "target_word": "双手", "complexity_tier": "T3", "furigana": "寒い朝、彼女は双手[そうしゅ]をポケットに入れて歩いた。", "sentence_source": "generated"}, {"text": "赤ん坊が双手でボールをつかもうとしている。", "target_word": "双手", "complexity_tier": "T3", "furigana": "赤ん坊が双手[そうしゅ]でボールをつかもうとしている。", "sentence_source": "generated"}, {"text": "双手を洗ってから、料理を始めた。", "target_word": "双手", "complexity_tier": "T3", "furigana": "双手[そうしゅ]を洗ってから、料理を始めた。", "sentence_source": "generated"}, {"text": "双手に花束を抱えた男が、店の前に立っていた。", "target_word": "双手", "complexity_tier": "T3", "furigana": "双手[そうしゅ]に花束を抱えた男が、店の前に立っていた。", "sentence_source": "generated"}, {"text": "彼は双手を握りしめ、怒りをこらえた。", "target_word": "双手", "complexity_tier": "T3", "furigana": "彼は双手[そうしゅ]を握りしめ、怒りをこらえた。", "sentence_source": "generated"}, {"text": "双手が震えるほど緊張して、舞台に立った。", "target_word": "双手", "complexity_tier": "T3", "furigana": "双手[そうしゅ]が震えるほど緊張して、舞台に立った。", "sentence_source": "generated"}, {"text": "剣道では、竹刀を双手でしっかり握る。", "target_word": "双手", "complexity_tier": "T3", "furigana": "剣道では、竹刀を双手[そうしゅ]でしっかり握る。", "sentence_source": "generated"}, {"text": "彼女はカップを双手で包み、ゆっくりお茶を飲んだ。", "target_word": "双手", "complexity_tier": "T3", "furigana": "彼女はカップを双手[そうしゅ]で包み、ゆっくりお茶を飲んだ。", "sentence_source": "generated"}, {"text": "双手を大きく振って、遠くの友人に合図を送った。", "target_word": "双手", "complexity_tier": "T3", "furigana": "双手[そうしゅ]を大きく振って、遠くの友人に合図を送った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "双手", "label": "基本形"}], "register": "literary", "sense_fingerprint": "左右両方の手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edb8103a-cdfa-4994-b1e8-bcd75eb2303e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52533, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "双手", "is_correct": true, "explanation": "両方の手を上げる降参の動作として正しく、文の意味に合う。"}, {"text": "双肩", "is_correct": false, "explanation": "肩を上げる動作は降参の意思を示す動作として不自然で、部位も変わる。"}, {"text": "双眸", "is_correct": false, "explanation": "目を上げる動作では降参の意思にならず、文が通らない。"}, {"text": "双耳", "is_correct": false, "explanation": "耳を上げる動作は降参の意思を示さず、文の意味が合わない。"}], "explanations": {"双手": "両方の手を上げる降参の動作として正しく、文の意味に合う。", "双肩": "肩を上げる動作は降参の意思を示す動作として不自然で、部位も変わる。", "双眸": "目を上げる動作では降参の意思にならず、文が通らない。", "双耳": "耳を上げる動作は降参の意思を示さず、文の意味が合わない。"}, "sentence_index": 0, "correct_answer": "双手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "両国の双手が合意に達した。", "explanation": "双手は両手を指すので、両国や両者という意味にはならない。"}, {"text": "父は双手の靴を一足そろえて、玄関に置いた。", "explanation": "双手は手を指すので、靴を数えたり修飾したりする語にはならない。"}, {"text": "彼女の双手が涙で光っていた。", "explanation": "双手は手を指すので、涙をためる目の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52533, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "双手", "is_correct": true, "explanation": "「双手が震える」の主語として正しく、緊張で震える手の意味に合う。"}, {"text": "双極", "is_correct": false, "explanation": "両極を指す語で、緊張で震える主語としては文が成り立たない。"}, {"text": "双璧", "is_correct": false, "explanation": "並び立つ二つの優れたものを指す語で、手の震えの主語にはならない。"}, {"text": "双翼", "is_correct": false, "explanation": "鳥などの翼を指す語で、人の手の震えの主語にはならない。"}], "explanations": {"双手": "「双手が震える」の主語として正しく、緊張で震える手の意味に合う。", "双極": "両極を指す語で、緊張で震える主語としては文が成り立たない。", "双璧": "並び立つ二つの優れたものを指す語で、手の震えの主語にはならない。", "双翼": "鳥などの翼を指す語で、人の手の震えの主語にはならない。"}, "sentence_index": 6, "correct_answer": "双手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鳥が双手を大きく振って、遠くへ飛び去った。", "explanation": "双手は手を指すので、翼の意味にはならない。"}, {"text": "彼女は双手で地面を蹴り、高く跳んだ。", "explanation": "双手は手を指すので、足の意味にはならない。"}, {"text": "彼女は双手の耳で、遠くの鐘の音を聞き分けた。", "explanation": "双手は手を指すので、耳の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52533, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は双手を荷物を抱えた。", "corrected_sentence": "彼は双手で荷物を抱えた。", "error_description": "抱える手段は「で」で示す。「双手を」と「荷物を」で目的語が二つになり、「双手」に付く「を」が誤り。正しくは「双手で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
