INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52534, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "両手。自分の手。", "primary_collocate": null, "pronunciation": "そうしゅ", "ipa": "soːɕɯ", "syllable_count": 3, "sentences": [{"text": "無機質な素材が自律的実体へと昇華する奇跡を、自らの双手で紡ぎ出す営み。", "target_word": "双手", "complexity_tier": "T5", "furigana": "無機質(むきしつ)な素材(そざい)が自律的(じりつてき)実体(じったい)へと昇華(しょうか)する奇跡(きせき)を、自(みずか)らの双手(そうしゅ)で紡(つむ)ぎ出(だ)す営(いとな)み。", "sentence_source": "mined"}, {"text": "彼は重い荷物を双手でしっかりと抱えた。", "target_word": "双手", "complexity_tier": "T3", "furigana": "彼は重い荷物を双手[そうしゅ]でしっかりと抱えた。", "sentence_source": "generated"}, {"text": "母は双手を合わせて、静かに祈った。", "target_word": "双手", "complexity_tier": "T3", "furigana": "母は双手[そうしゅ]を合わせて、静かに祈った。", "sentence_source": "generated"}, {"text": "少女は双手を大きく広げて、風を受けた。", "target_word": "双手", "complexity_tier": "T3", "furigana": "少女は双手[そうしゅ]を大きく広げて、風を受けた。", "sentence_source": "generated"}, {"text": "職人は自分の双手で、一つずつ器を作り上げる。", "target_word": "双手", "complexity_tier": "T3", "furigana": "職人は自分の双手[そうしゅ]で、一つずつ器を作り上げる。", "sentence_source": "generated"}, {"text": "双手に息を吹きかけて、冷えた指を温めた。", "target_word": "双手", "complexity_tier": "T3", "furigana": "双手[そうしゅ]に息を吹きかけて、冷えた指を温めた。", "sentence_source": "generated"}, {"text": "双手が泥だらけになるまで、畑を耕した。", "target_word": "双手", "complexity_tier": "T3", "furigana": "双手[そうしゅ]が泥だらけになるまで、畑を耕した。", "sentence_source": "generated"}, {"text": "彼は双手で顔をおおい、しばらく動かなかった。", "target_word": "双手", "complexity_tier": "T3", "furigana": "彼は双手[そうしゅ]で顔をおおい、しばらく動かなかった。", "sentence_source": "generated"}, {"text": "賞状を双手で受け取り、深く頭を下げた。", "target_word": "双手", "complexity_tier": "T3", "furigana": "賞状を双手[そうしゅ]で受け取り、深く頭を下げた。", "sentence_source": "generated"}, {"text": "片手では持てないので、双手で支えるしかない。", "target_word": "双手", "complexity_tier": "T3", "furigana": "片手では持てないので、双手[そうしゅ]で支えるしかない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "双手", "label": "基本形"}], "register": "literary", "sense_fingerprint": "自分の両方の手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 無機質 (Zipf 2.84), 昇華 (Zipf 3.35), 紡ぎ (Zipf 2.82), 営み (Zipf 3.27)']::text[], 'edb8103a-cdfa-4994-b1e8-bcd75eb2303e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52534, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "双手", "is_correct": true, "explanation": "「自らの双手で紡ぎ出す」と、両方の手で手仕事をする文脈に合う。"}, {"text": "双肩", "is_correct": false, "explanation": "肩は紡ぐ動作の道具にならず、手仕事の文脈に合わない。"}, {"text": "双眸", "is_correct": false, "explanation": "目で紡ぎ出す動作は成り立たず、文の意味が通らない。"}, {"text": "双脚", "is_correct": false, "explanation": "足で紡ぎ出すことは不自然で、手仕事の文脈に合わない。"}], "explanations": {"双手": "「自らの双手で紡ぎ出す」と、両方の手で手仕事をする文脈に合う。", "双肩": "肩は紡ぐ動作の道具にならず、手仕事の文脈に合わない。", "双眸": "目で紡ぎ出す動作は成り立たず、文の意味が通らない。", "双脚": "足で紡ぎ出すことは不自然で、手仕事の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "双手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "両国の双手が歩み寄り、合意に至った。", "explanation": "双手は手を指すので、国や立場を指す〈双方〉の意味にはならない。"}, {"text": "彼女には双手の妹がいる。", "explanation": "双手は手を指す語で、人の関係を表す〈双子〉の意味にはならない。"}, {"text": "彼女の双手に、涙がにじんでいた。", "explanation": "双手は手を指すので、涙をためる目の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52534, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "双手", "is_correct": true, "explanation": "泥だらけになるのは畑仕事で働く両手の意味で、文脈に合う。"}, {"text": "双眸", "is_correct": false, "explanation": "目を指す語で、畑仕事で泥だらけになる主語としては不自然。"}, {"text": "双翼", "is_correct": false, "explanation": "鳥の翼を指す語で、人が泥だらけになる主語にはならない。"}, {"text": "双耳", "is_correct": false, "explanation": "耳が泥だらけになる文脈は不自然で、主語として成り立たない。"}], "explanations": {"双手": "泥だらけになるのは畑仕事で働く両手の意味で、文脈に合う。", "双眸": "目を指す語で、畑仕事で泥だらけになる主語としては不自然。", "双翼": "鳥の翼を指す語で、人が泥だらけになる主語にはならない。", "双耳": "耳が泥だらけになる文脈は不自然で、主語として成り立たない。"}, "sentence_index": 6, "correct_answer": "双手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は双手で、遠くの鐘の音を聞き分けた。", "explanation": "双手は手を指すので、音を聞く耳の意味にはならない。"}, {"text": "彼は双手で地面をしっかり踏みしめた。", "explanation": "双手は手を指すので、地面を踏みしめる足の意味にはならない。"}, {"text": "鳥が双手を広げて飛び立った。", "explanation": "双手は手を指すので、翼の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52534, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は茶碗を双手をくるんで差し出した。", "corrected_sentence": "祖父は茶碗を双手でくるんで差し出した。", "error_description": "「茶碗を」と「双手を」で目的語が二つになり誤り。手段は「で」で示すので、正しくは「双手でくるんで」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52534, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は小鳥を双手が包み込んだ。", "corrected_sentence": "彼女は小鳥を双手で包み込んだ。", "error_description": "小鳥を包み込むのは彼女なので、手段の双手には「で」を使う。「が」は主語の表示で誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52535, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "料理を作る場所を示すので、「自宅で料理を作った」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」は着点や存在を示す。「自宅に料理を作った」は場所として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列・共同を示す。「自宅と料理を作った」では意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「自宅より料理を作った」では文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "料理を作る場所を示すので、「自宅で料理を作った」が正しい。", "に": "「に」は着点や存在を示す。「自宅に料理を作った」は場所として不自然。", "と": "「と」は並列・共同を示す。「自宅と料理を作った」では意味が通らない。", "より": "「より」は比較を示す。「自宅より料理を作った」では文が成り立たない。"}, "error_tags": {"に": "着点・存在", "と": "並列・共同", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52535, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "戻る先の方向を示すので、「自宅へ戻った」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「戻る」は目的語を取らないので、「自宅を戻った」は合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「自宅が戻った」は主語として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を示す。「駅から自宅の戻った」は文が成り立たない。"}], "correct_answer": "へ", "explanations": {"へ": "戻る先の方向を示すので、「自宅へ戻った」が正しい。", "を": "「戻る」は目的語を取らないので、「自宅を戻った」は合わない。", "が": "「が」は主語を示す。「自宅が戻った」は主語として成り立たない。", "の": "「の」は所属や修飾を示す。「駅から自宅の戻った」は文が成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "の": "所属・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52535, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分の家のこと。", "primary_collocate": null, "pronunciation": "じたく", "ipa": "dʑitakɯ", "syllable_count": 3, "sentences": [{"text": "友達を自宅に招いて、夕食をごちそうした。", "target_word": "自宅", "complexity_tier": "T3", "furigana": "友達[ともだち]を自宅[じたく]に招[まね]いて、夕食[ゆうしょく]をごちそうした。", "sentence_source": "generated"}, {"text": "仕事が早く終わったので、自宅で料理を作った。", "target_word": "自宅", "complexity_tier": "T3", "furigana": "仕事[しごと]が早[はや]く終[お]わったので、自宅[じたく]で料理[りょうり]を作[つく]った。", "sentence_source": "generated"}, {"text": "自宅の近くに大きな公園がある。", "target_word": "自宅", "complexity_tier": "T3", "furigana": "自宅[じたく]の近[ちか]くに大[おお]きな公園[こうえん]がある。", "sentence_source": "generated"}, {"text": "先生は自宅で、近所の子どもに英語を教えている。", "target_word": "自宅", "complexity_tier": "T3", "furigana": "先生[せんせい]は自宅[じたく]で、近所[きんじょ]の子[こ]どもに英語[えいご]を教[おし]えている。", "sentence_source": "generated"}, {"text": "自宅にいる時間が増えて、本を読むようになった。", "target_word": "自宅", "complexity_tier": "T3", "furigana": "自宅[じたく]にいる時間[じかん]が増[ふ]えて、本[ほん]を読[よ]むようになった。", "sentence_source": "generated"}, {"text": "駅から自宅まで歩くと、十五分ぐらいかかる。", "target_word": "自宅", "complexity_tier": "T3", "furigana": "駅[えき]から自宅[じたく]まで歩[ある]くと、十五分[じゅうごふん]ぐらいかかる。", "sentence_source": "generated"}, {"text": "母は自宅の掃除を毎朝している。", "target_word": "自宅", "complexity_tier": "T3", "furigana": "母[はは]は自宅[じたく]の掃除[そうじ]を毎朝[まいあさ]している。", "sentence_source": "generated"}, {"text": "忘れ物に気づいて、駅からいったん自宅へ戻った。", "target_word": "自宅", "complexity_tier": "T3", "furigana": "忘[わす]れ物[もの]に気[き]づいて、駅[えき]からいったん自宅[じたく]へ戻[もど]った。", "sentence_source": "generated"}, {"text": "自宅で勉強するより、図書館のほうが集中できる。", "target_word": "自宅", "complexity_tier": "T3", "furigana": "自宅[じたく]で勉強[べんきょう]するより、図書館[としょかん]のほうが集中[しゅうちゅう]できる。", "sentence_source": "generated"}, {"text": "彼の自宅には、大きな犬が二匹いる。", "target_word": "自宅", "complexity_tier": "T3", "furigana": "彼[かれ]の自宅[じたく]には、大[おお]きな犬[いぬ]が二匹[にひき]いる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自宅", "label": "基本形"}], "register": "ふつう", "sense_fingerprint": "自分の家。学校や職場、他人の家に対して、自分が暮らす家を指す言い方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21d2050e-73d4-41bb-b305-1aad375477d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52535, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自宅", "is_correct": true, "explanation": "自分の家に招くという文に合うので、ここに入る。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題は招く相手にならないので、「友達を宿題に招く」は意味が通らない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は招く先にならないので、「友達を天井に招く」は意味が通らない。"}, {"text": "電話", "is_correct": false, "explanation": "電話は招く先にならないので、「友達を電話に招く」は意味が通らない。"}], "explanations": {"自宅": "自分の家に招くという文に合うので、ここに入る。", "宿題": "宿題は招く相手にならないので、「友達を宿題に招く」は意味が通らない。", "天井": "天井は招く先にならないので、「友達を天井に招く」は意味が通らない。", "電話": "電話は招く先にならないので、「友達を電話に招く」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "自宅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は次男なので、自宅の跡取りにはなれない。", "explanation": "ここは〈家〉（家系・家督）の意味。自宅は自分が住む家を指し、家系を継ぐ意味では使わない。"}, {"text": "旅の自宅を予約した。", "explanation": "ここは〈宿〉（泊まる施設）の意味。自宅は自分が住む家なので、泊まる先の予約には使わない。"}, {"text": "自宅の製造ラインで働く人が増えた。", "explanation": "ここは〈工場〉の意味（製造ラインがある場所）。自宅は住まいを指すので、製造ラインのある場所には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52535, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自宅", "is_correct": true, "explanation": "母が毎朝掃除する場所にあたるので、ここに入る。"}, {"text": "誕生日", "is_correct": false, "explanation": "誕生日は掃除の対象にならないので、「誕生日の掃除」は意味が通らない。"}, {"text": "会議", "is_correct": false, "explanation": "会議は掃除の対象にならないので、「会議の掃除」は意味が通らない。"}, {"text": "夏休み", "is_correct": false, "explanation": "夏休みは掃除の対象にならないので、「夏休みの掃除」は意味が通らない。"}], "explanations": {"自宅": "母が毎朝掃除する場所にあたるので、ここに入る。", "誕生日": "誕生日は掃除の対象にならないので、「誕生日の掃除」は意味が通らない。", "会議": "会議は掃除の対象にならないので、「会議の掃除」は意味が通らない。", "夏休み": "夏休みは掃除の対象にならないので、「夏休みの掃除」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "自宅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "年末に帰省して、自宅に泊まった。", "explanation": "ここは〈実家〉（親が住む家）の意味。帰省先の親の家は自宅とは言わない。自宅は自分が住む家を指すので、帰省先には使わない。"}, {"text": "会社は新入社員に、自宅を用意した。", "explanation": "ここは〈社宅〉（会社が用意する住まい）の意味。自宅は自分が住んでいる家を指すので、会社が用意するものには使わない。"}, {"text": "留学中、毎日自宅の選挙の結果をニュースで確かめた。", "explanation": "ここは〈自国〉（自分の国）の意味。自宅は自分が住む家で、国の出来事には使わない。国の選挙は「自国の選挙」と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52535, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は自宅が英語を教えている。", "corrected_sentence": "先生は自宅で英語を教えている。", "error_description": "「教える」の場所は「で」で示す。「が」は主語を表すので、「自宅が教えている」は誤り。正しくは「自宅で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52535, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕方、友達が自宅に来るた。", "corrected_sentence": "夕方、友達が自宅に来た。", "error_description": "「来る」の過去形は「来た」。「来るた」は活用の誤り。正しくは「来た」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52536, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "映画を見る場所を示すので、「自宅で映画を見る」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「自宅が映画を見る」は主語として不自然で、意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「自宅を映画を見る」と目的語が二つ並び、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列・共同を示す。「自宅と映画を見る」では意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "映画を見る場所を示すので、「自宅で映画を見る」が正しい。", "が": "「が」は主語を示す。「自宅が映画を見る」は主語として不自然で、意味が通らない。", "を": "「を」は目的語を示す。「自宅を映画を見る」と目的語が二つ並び、文が成り立たない。", "と": "「と」は並列・共同を示す。「自宅と映画を見る」では意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "と": "並列・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52536, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「自宅の住所」と続けて所属や修飾を表すので、「の」が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「自宅へ住所と電話番号を書く」では意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「自宅を住所と電話番号を書く」と目的語が二つ並び、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「自宅より住所と電話番号を書く」では文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「自宅の住所」と続けて所属や修飾を表すので、「の」が正しい。", "へ": "「へ」は方向を示す。「自宅へ住所と電話番号を書く」では意味が通らない。", "を": "「を」は目的語を示す。「自宅を住所と電話番号を書く」と目的語が二つ並び、文が成り立たない。", "より": "「より」は比較を示す。「自宅より住所と電話番号を書く」では文が成り立たない。"}, "error_tags": {"へ": "方向", "を": "目的語の重複", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52536, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分が住んでいる家。", "primary_collocate": null, "pronunciation": "じたく", "ipa": "dʑitakɯ", "syllable_count": 3, "sentences": [{"text": "それこそが、静謐な自宅の工房において初学者が向き合う、ロボット製作の本質である。", "target_word": "自宅", "complexity_tier": "T3", "furigana": "それこそが、静謐[せいひつ]な自宅[じたく]の工房[こうぼう]において初学者[しょがくしゃ]が向[む]き合[あ]う、ロボット製作[せいさく]の本質[ほんしつ]である。", "sentence_source": "mined"}, {"text": "今日は雨なので、自宅で映画を見ることにした。", "target_word": "自宅", "complexity_tier": "T3", "furigana": "今日[きょう]は雨[あめ]なので、自宅[じたく]で映画[えいが]を見[み]ることにした。", "sentence_source": "generated"}, {"text": "会議のあと、どこにも寄らずにまっすぐ自宅に帰った。", "target_word": "自宅", "complexity_tier": "T3", "furigana": "会議[かいぎ]のあと、どこにも寄[よ]らずにまっすぐ自宅[じたく]に帰[かえ]った。", "sentence_source": "generated"}, {"text": "自宅から会社まで、電車で四十分かかる。", "target_word": "自宅", "complexity_tier": "T3", "furigana": "自宅[じたく]から会社[かいしゃ]まで、電車[でんしゃ]で四十分[よんじゅっぷん]かかる。", "sentence_source": "generated"}, {"text": "荷物は自宅に届くので、受け取りの時間を決めておいてください。", "target_word": "自宅", "complexity_tier": "T3", "furigana": "荷物[にもつ]は自宅[じたく]に届[とど]くので、受[う]け取[と]りの時間[じかん]を決[き]めておいてください。", "sentence_source": "generated"}, {"text": "彼は自宅の庭で野菜を育てている。", "target_word": "自宅", "complexity_tier": "T3", "furigana": "彼[かれ]は自宅[じたく]の庭[にわ]で野菜[やさい]を育[そだ]てている。", "sentence_source": "generated"}, {"text": "台風が近づいているため、今日は自宅で待機してください。", "target_word": "自宅", "complexity_tier": "T3", "furigana": "台風[たいふう]が近[ちか]づいているため、今日[きょう]は自宅[じたく]で待機[たいき]してください。", "sentence_source": "generated"}, {"text": "申込書には、自宅の住所と電話番号を書いてください。", "target_word": "自宅", "complexity_tier": "T3", "furigana": "申込書[もうしこみしょ]には、自宅[じたく]の住所[じゅうしょ]と電話番号[でんわばんごう]を書[か]いてください。", "sentence_source": "generated"}, {"text": "入院していた祖母は、退院して自宅で過ごしている。", "target_word": "自宅", "complexity_tier": "T3", "furigana": "入院[にゅういん]していた祖母[そぼ]は、退院[たいいん]して自宅[じたく]で過[す]ごしている。", "sentence_source": "generated"}, {"text": "自宅の鍵をなくしてしまい、夜まで家に入れなかった。", "target_word": "自宅", "complexity_tier": "T3", "furigana": "自宅[じたく]の鍵[かぎ]をなくしてしまい、夜[よる]まで家[いえ]に入[はい]れなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自宅", "label": "基本形"}], "register": "ふつう", "sense_fingerprint": "自分が実際に住んでいる家。外出先や職場に対して、帰る場所としての家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21d2050e-73d4-41bb-b305-1aad375477d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52536, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自宅", "is_correct": true, "explanation": "静かで落ち着いた住まいの中に工房があるという文に合い、ここに入る。"}, {"text": "工場", "is_correct": false, "explanation": "大きな機械の音がする場所で、「静謐な」工房とは合わない。"}, {"text": "駅", "is_correct": false, "explanation": "人の往来が多く騒がしい場所で、「静謐な」工房を構える場所としては合わない。"}, {"text": "空港", "is_correct": false, "explanation": "人の往来が激しく騒がしい場所で、「静謐な」工房を構える場所としては合わない。"}], "explanations": {"自宅": "静かで落ち着いた住まいの中に工房があるという文に合い、ここに入る。", "工場": "大きな機械の音がする場所で、「静謐な」工房とは合わない。", "駅": "人の往来が多く騒がしい場所で、「静謐な」工房を構える場所としては合わない。", "空港": "人の往来が激しく騒がしい場所で、「静謐な」工房を構える場所としては合わない。"}, "sentence_index": 0, "correct_answer": "自宅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は自宅を継ぐため、大学を辞めた。", "explanation": "ここは〈家〉（家業・家系）の意味。自宅は住んでいる建物を指し、家業を継ぐ意味では使わない。"}, {"text": "祖母は、転んで骨を折り、自宅に入院した。", "explanation": "ここは〈病院〉（入院する施設）の意味。自宅は住んでいる家なので、入院先には使わない。"}, {"text": "今シーズン、チームは自宅で六連勝した。", "explanation": "ここは〈本拠地〉（チームの拠点）の意味。自宅は個人の住まいを指すので、チームの拠点には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52536, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自宅", "is_correct": true, "explanation": "今いる家で待機するという文に合い、ここに入る。"}, {"text": "雷", "is_correct": false, "explanation": "天候を指す語で、待機する場所にはならないので文が通らない。"}, {"text": "豪雨", "is_correct": false, "explanation": "天候を指す語で、待機する場所にはならないので文が通らない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "空の様子を指す語で、待機する場所にはならないので文が通らない。"}], "explanations": {"自宅": "今いる家で待機するという文に合い、ここに入る。", "雷": "天候を指す語で、待機する場所にはならないので文が通らない。", "豪雨": "天候を指す語で、待機する場所にはならないので文が通らない。", "夕焼け": "空の様子を指す語で、待機する場所にはならないので文が通らない。"}, "sentence_index": 6, "correct_answer": "自宅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "娘は毎朝、電車で一時間かけて自宅に通い、英語を習っている。", "explanation": "ここは〈教室〉の意味（習いに通う場所）。自宅は住んでいる家なので、通って習う場所には使わない。"}, {"text": "会議は、各部署の自宅で行われた。", "explanation": "ここは〈会議室〉の意味（会議をする部屋）。自宅は住む家を指すので、会議の場所には使わない。"}, {"text": "この地域には三百の自宅が住んでいる。", "explanation": "ここは〈世帯〉（住む人の単位）の意味。自宅は家（建物）を指すので、人の数を数える語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52536, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "仕事を終えて、まっすぐ自宅で帰った。", "corrected_sentence": "仕事を終えて、まっすぐ自宅に帰った。", "error_description": "「帰る」は移動の着点に「に」を取る。「で」は場所を表すので誤り。正しくは「自宅に帰った」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52536, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "台風が近づいたので、早く自宅へ戻りた。", "corrected_sentence": "台風が近づいたので、早く自宅へ戻った。", "error_description": "「戻る」は五段活用の動詞で、過去形は「戻った」。「戻りた」は活用の誤り。正しくは「戻った」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
