INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52537, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "糸をよって、布などをつくること。", "primary_collocate": null, "pronunciation": "つむぎだす", "ipa": "tsɯmɯɡidasɯ", "syllable_count": 5, "sentences": [{"text": "祖母は糸車を回して、羊毛から細い糸を紡ぎ出した。", "target_word": "紡ぎ出した", "complexity_tier": "T3", "furigana": "祖母[そぼ]は糸車[いとぐるま]を回[まわ]して、羊毛[ようもう]から細[ほそ]い糸[いと]を紡[つむ]ぎ出[だ]した。", "sentence_source": "generated"}, {"text": "蚕は、口から細くて白い糸を紡ぎ出して繭を作る。", "target_word": "紡ぎ出して", "complexity_tier": "T3", "furigana": "蚕[かいこ]は、口[くち]から細[ほそ]くて白[しろ]い糸[いと]を紡[つむ]ぎ出[だ]して繭[まゆ]を作[つく]る。", "sentence_source": "generated"}, {"text": "職人は、綿を手でよりながら、長い糸を紡ぎ出していく。", "target_word": "紡ぎ出して", "complexity_tier": "T3", "furigana": "職人[しょくにん]は、綿[わた]を手[て]でよりながら、長[なが]い糸[いと]を紡[つむ]ぎ出[だ]していく。", "sentence_source": "generated"}, {"text": "この機械は、一日で何百メートルもの糸を紡ぎ出す。", "target_word": "紡ぎ出す", "complexity_tier": "T3", "furigana": "この機械[きかい]は、一日[いちにち]で何百[なんびゃく]メートルもの糸[いと]を紡[つむ]ぎ出[だ]す。", "sentence_source": "generated"}, {"text": "昔の人は、冬の間に家で糸を紡ぎ出し、春に布を織った。", "target_word": "紡ぎ出し", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]は、冬[ふゆ]の間[あいだ]に家[いえ]で糸[いと]を紡[つむ]ぎ出[だ]し、春[はる]に布[ぬの]を織[お]った。", "sentence_source": "generated"}, {"text": "体験教室では、参加者が羊の毛から自分の糸を紡ぎ出した。", "target_word": "紡ぎ出した", "complexity_tier": "T3", "furigana": "体験教室[たいけんきょうしつ]では、参加者[さんかしゃ]が羊[ひつじ]の毛[け]から自分[じぶん]の糸[いと]を紡[つむ]ぎ出[だ]した。", "sentence_source": "generated"}, {"text": "手で糸を紡ぎ出すのは時間がかかるが、布は温かく丈夫になる。", "target_word": "紡ぎ出す", "complexity_tier": "T3", "furigana": "手[て]で糸[いと]を紡[つむ]ぎ出[だ]すのは時間[じかん]がかかるが、布[ぬの]は温[あたた]かく丈夫[じょうぶ]になる。", "sentence_source": "generated"}, {"text": "山の村の女たちは、麻から糸を紡ぎ出して着物を作っていた。", "target_word": "紡ぎ出して", "complexity_tier": "T3", "furigana": "山[やま]の村[むら]の女[おんな]たちは、麻[あさ]から糸[いと]を紡[つむ]ぎ出[だ]して着物[きもの]を作[つく]っていた。", "sentence_source": "generated"}, {"text": "彼女は毎日、庭で飼っている羊の毛を紡ぎ出して、マフラーを編んだ。", "target_word": "紡ぎ出して", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は毎日[まいにち]、庭[にわ]で飼[か]っている羊[ひつじ]の毛[け]を紡[つむ]ぎ出[だ]して、マフラーを編[あ]んだ。", "sentence_source": "generated"}, {"text": "紡ぎ出した糸が太すぎて、細かい布は織れなかった。", "target_word": "紡ぎ出した", "complexity_tier": "T3", "furigana": "紡[つむ]ぎ出[だ]した糸[いと]が太[ふと]すぎて、細[こま]かい布[ぬの]は織[お]れなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "紡ぎ出す", "label": "終止形"}, {"form": "紡ぎ出した", "label": "過去形"}, {"form": "紡ぎ出して", "label": "て形"}, {"form": "紡ぎ出し", "label": "連用形"}], "register": "中立（普通体）", "sense_fingerprint": "繊維をよって糸にする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19296fb3-942a-43e0-bd14-652689089628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52537, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "紡ぎ出した", "is_correct": true, "explanation": "羊毛から糸を生み出す「紡ぎ出した」は、糸車の作業の文脈に合う。"}, {"text": "切った", "is_correct": false, "explanation": "「切った」では糸を作る作業の説明にならず、羊毛から糸を作る文脈に合わない。"}, {"text": "洗った", "is_correct": false, "explanation": "「洗った」では細い糸が生まれる流れにならず、文脈に合わない。"}, {"text": "焼いた", "is_correct": false, "explanation": "「焼いた」では糸を作る作業にならず、この文脈に合わない。"}], "explanations": {"紡ぎ出した": "羊毛から糸を生み出す「紡ぎ出した」は、糸車の作業の文脈に合う。", "切った": "「切った」では糸を作る作業の説明にならず、羊毛から糸を作る文脈に合わない。", "洗った": "「洗った」では細い糸が生まれる流れにならず、文脈に合わない。", "焼いた": "「焼いた」では糸を作る作業にならず、この文脈に合わない。"}, "sentence_index": 0, "correct_answer": "紡ぎ出した"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝、チューブから歯磨き粉を紡ぎ出して、歯を磨いた。", "explanation": "ここは絞り出す（押して外に出す）の意味。紡ぎ出すは繊維をよって糸にすることなので、歯磨き粉には使えない。"}, {"text": "将軍は、新しい部隊を次々と紡ぎ出した。", "explanation": "ここは繰り出す（次々と送り出す）の意味。紡ぎ出すは糸を作ることなので、部隊には使わない。"}, {"text": "宝物を、土の中から紡ぎ出した。", "explanation": "ここは掘り出す（地中から取り出す）の意味。紡ぎ出すは糸をよることなので、土の中の物には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52537, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "紡ぎ出す", "is_correct": true, "explanation": "糸をよって作る「紡ぎ出す」は、手作業の糸作りの文脈に合う。"}, {"text": "踏む", "is_correct": false, "explanation": "「手で糸を踏む」では糸を作る作業にならず、文脈に合わない。"}, {"text": "投げる", "is_correct": false, "explanation": "「手で糸を投げる」では糸を作る作業にならず、文脈に合わない。"}, {"text": "蹴る", "is_correct": false, "explanation": "「手で糸を蹴る」では作業として成り立たず、文脈に合わない。"}], "explanations": {"紡ぎ出す": "糸をよって作る「紡ぎ出す」は、手作業の糸作りの文脈に合う。", "踏む": "「手で糸を踏む」では糸を作る作業にならず、文脈に合わない。", "投げる": "「手で糸を投げる」では糸を作る作業にならず、文脈に合わない。", "蹴る": "「手で糸を蹴る」では作業として成り立たず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "紡ぎ出す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "やかんの口から、蒸気を紡ぎ出した。", "explanation": "ここは吹き出す（勢いよく外へ出す）の意味。紡ぎ出すは糸をよることなので、蒸気には使えない。"}, {"text": "雑草を、根から紡ぎ出した。", "explanation": "ここは引き抜く（根ごと抜く）の意味。紡ぎ出すは糸を作ることなので、植物を抜く動作には使えない。"}, {"text": "この鉱山からは、金が年間に紡ぎ出されている。", "explanation": "ここは産出（地中から産み出す）の意味。紡ぎ出すは糸や布を作ることなので、鉱物には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52537, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は、羊毛から糸が紡ぎ出して、マフラーを編んだ。", "corrected_sentence": "祖母は、羊毛から糸を紡ぎ出して、マフラーを編んだ。", "error_description": "正しくは「糸を紡ぎ出して」。「紡ぎ出す」は他動詞なので目的語「糸」に「を」が必要で、「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "紡ぎ出して", "is_correct": true, "explanation": "て形で、「繭を作る」へ続けるための形。文脈に合う。"}, {"text": "紡ぎ出そう", "is_correct": false, "explanation": "意志形。「繭を作る」の前には続かず、文が成り立たない。"}, {"text": "紡ぎ出せ", "is_correct": false, "explanation": "命令形。名詞「繭」の前に続かず、文が成り立たない。"}, {"text": "紡ぎ出し", "is_correct": false, "explanation": "連用形だが、「繭を作る」へ続けるには接続の「て」が必要で、この形では文が成り立たない。"}], "correct_form": "紡ぎ出して", "base_form": "紡ぎ出す", "form_label": "て形", "sentence_index": 1, "explanations": {"紡ぎ出して": "て形で、「繭を作る」へ続けるための形。文脈に合う。", "紡ぎ出そう": "意志形。「繭を作る」の前には続かず、文が成り立たない。", "紡ぎ出せ": "命令形。名詞「繭」の前に続かず、文が成り立たない。", "紡ぎ出し": "連用形だが、「繭を作る」へ続けるには接続の「て」が必要で、この形では文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52537, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は紡ぎ出して糸で、マフラーを編んだ。", "corrected_sentence": "祖母は紡ぎ出した糸で、マフラーを編んだ。", "error_description": "正しくは「紡ぎ出した糸」。名詞「糸」を修飾する連体形には過去の「た」が必要で、「て」は接続の形なので誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "紡ぎ出して", "is_correct": true, "explanation": "て形で、「着物を作っていた」へ続く形。文脈に合う。"}, {"text": "紡ぎ出せば", "is_correct": false, "explanation": "仮定形。「着物を作っていた」へ続けると条件文になり、文が成り立たない。"}, {"text": "紡ぎ出させ", "is_correct": false, "explanation": "使役形の途中の形。そのまま「着物を作っていた」へは続かず、文が成り立たない。"}, {"text": "紡ぎ出さ", "is_correct": false, "explanation": "未然形だけでは文が成り立たず、「着物」へ続けられない。"}], "correct_form": "紡ぎ出して", "base_form": "紡ぎ出す", "form_label": "て形", "sentence_index": 7, "explanations": {"紡ぎ出して": "て形で、「着物を作っていた」へ続く形。文脈に合う。", "紡ぎ出せば": "仮定形。「着物を作っていた」へ続けると条件文になり、文が成り立たない。", "紡ぎ出させ": "使役形の途中の形。そのまま「着物を作っていた」へは続かず、文が成り立たない。", "紡ぎ出さ": "未然形だけでは文が成り立たず、「着物」へ続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52539, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「初学の科目」。名詞を修飾する「の」で、初めて学ぶ科目を指す。"}, {"text": "が", "is_correct": false, "explanation": "「初学が科目」は主語の形で、科目を修飾できない。"}, {"text": "を", "is_correct": false, "explanation": "「初学を科目」は対象の形で、科目を修飾できない。"}, {"text": "に", "is_correct": false, "explanation": "「初学に科目」は位置を示す形で、科目を修飾しない。"}], "correct_answer": "の", "explanations": {"の": "「初学の科目」。名詞を修飾する「の」で、初めて学ぶ科目を指す。", "が": "「初学が科目」は主語の形で、科目を修飾できない。", "を": "「初学を科目」は対象の形で、科目を修飾できない。", "に": "「初学に科目」は位置を示す形で、科目を修飾しない。"}, "error_tags": {"が": "主語の誤り", "を": "対象の誤り", "に": "位置の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52539, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52539, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "はじめてべんきょうすること。", "primary_collocate": null, "pronunciation": "しょがく", "ipa": "ɕoɡakɯ", "syllable_count": 3, "sentences": [{"text": "用語の意味を一つずつ確かめながら読めば、初学の段階でもこの分野は理解しやすい。", "target_word": "初学", "complexity_tier": "T3", "furigana": "用語[ようご]の意味[いみ]を一[ひと]つずつ確[たし]かめながら読[よ]めば、初学[しょがく]の段階[だんかい]でもこの分野[ぶんや]は理解[りかい]しやすい。", "sentence_source": "generated"}, {"text": "数学は初学の科目なので、先生の説明をノートに丁寧に書き写した。", "target_word": "初学", "complexity_tier": "T3", "furigana": "数学[すうがく]は初学[しょがく]の科目[かもく]なので、先生[せんせい]の説明[せつめい]をノートに丁寧[ていねい]に書[か]き写[うつ]した。", "sentence_source": "generated"}, {"text": "初学のときに使った教科書を、今でも大切に持っている。", "target_word": "初学", "complexity_tier": "T3", "furigana": "初学[しょがく]のときに使[つか]った教科書[きょうかしょ]を、今[いま]でも大切[たいせつ]に持[も]っている。", "sentence_source": "generated"}, {"text": "初学の内容が難しすぎて、最初の一週間はほとんど理解できなかった。", "target_word": "初学", "complexity_tier": "T3", "furigana": "初学[しょがく]の内容[ないよう]が難[むずか]しすぎて、最初[さいしょ]の一週間[いっしゅうかん]はほとんど理解[りかい]できなかった。", "sentence_source": "generated"}, {"text": "初学の人にもわかるように、図を多く入れた資料を作った。", "target_word": "初学", "complexity_tier": "T3", "furigana": "初学[しょがく]の人[ひと]にもわかるように、図[ず]を多[おお]く入[い]れた資料[しりょう]を作[つく]った。", "sentence_source": "generated"}, {"text": "中国語は初学なので、ゆっくり話してもらえると助かります。", "target_word": "初学", "complexity_tier": "T3", "furigana": "中国語[ちゅうごくご]は初学[しょがく]なので、ゆっくり話[はな]してもらえると助[たす]かります。", "sentence_source": "generated"}, {"text": "初学の時期は、毎日少しずつ続けることが上達の近道だ。", "target_word": "初学", "complexity_tier": "T3", "furigana": "初学[しょがく]の時期[じき]は、毎日[まいにち]少[すこ]しずつ続[つづ]けることが上達[じょうたつ]の近道[ちかみち]だ。", "sentence_source": "generated"}, {"text": "料理は初学だったが、三か月で家族に出せるほど上達した。", "target_word": "初学", "complexity_tier": "T3", "furigana": "料理[りょうり]は初学[しょがく]だったが、三[さん]か月[げつ]で家族[かぞく]に出[だ]せるほど上達[じょうたつ]した。", "sentence_source": "generated"}, {"text": "初学のとき、先輩に教わったやり方が今も役に立っている。", "target_word": "初学", "complexity_tier": "T3", "furigana": "初学[しょがく]のとき、先輩[せんぱい]に教[おそ]わったやり方[かた]が今[いま]も役[やく]に立[た]っている。", "sentence_source": "generated"}, {"text": "初学の者にとって、専門用語の多い論文は読むのが大変だ。", "target_word": "初学", "complexity_tier": "T3", "furigana": "初学[しょがく]の者[もの]にとって、専門[せんもん]用語[ようご]の多[おお]い論文[ろんぶん]は読[よ]むのが大変[たいへん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "初学", "label": "基本形"}], "register": "書き言葉・やや硬い", "sense_fingerprint": "その科目や分野を初めて勉強すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21d2050e-73d4-41bb-b305-1aad375477d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52539, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "初学", "is_correct": true, "explanation": "「初学の段階」として、初めて学ぶ段階を指し、文の意味に合う。"}, {"text": "試験", "is_correct": false, "explanation": "「試験の段階」とは言わず、理解のしやすさの話に合わない。"}, {"text": "採点", "is_correct": false, "explanation": "「採点の段階」とは言わず、分野の理解には合わない。"}, {"text": "合格", "is_correct": false, "explanation": "「合格の段階」とは言わず、文の内容に合わない。"}], "explanations": {"初学": "「初学の段階」として、初めて学ぶ段階を指し、文の意味に合う。", "試験": "「試験の段階」とは言わず、理解のしやすさの話に合わない。", "採点": "「採点の段階」とは言わず、分野の理解には合わない。", "合格": "「合格の段階」とは言わず、文の内容に合わない。"}, "sentence_index": 0, "correct_answer": "初学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "初学の相手は、同じクラスの子だった。", "explanation": "ここは〈初恋〉の意味。初学は学び始めることで、恋愛の経験には使わない。"}, {"text": "将棋の初学で角を動かした。", "explanation": "ここは〈初手〉の意味。初学は学習のことで、指し手には使わない。"}, {"text": "新キャラが初学した。", "explanation": "ここは〈初登場〉の意味。初学は学び始める意味で、作品への登場には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52539, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初学", "is_correct": true, "explanation": "「初学の時期」として、初めて学ぶ時期を指し、文の意味に合う。"}, {"text": "結果", "is_correct": false, "explanation": "「結果の時期」とは言わず、上達の話には合わない。"}, {"text": "結論", "is_correct": false, "explanation": "「結論の時期」とは言わず、文の意味に合わない。"}, {"text": "報告", "is_correct": false, "explanation": "「報告の時期」とは言わず、上達の近道の話には合わない。"}], "explanations": {"初学": "「初学の時期」として、初めて学ぶ時期を指し、文の意味に合う。", "結果": "「結果の時期」とは言わず、上達の話には合わない。", "結論": "「結論の時期」とは言わず、文の意味に合わない。", "報告": "「報告の時期」とは言わず、上達の近道の話には合わない。"}, "sentence_index": 6, "correct_answer": "初学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は初学なので、罰金は軽く済んだ。", "explanation": "ここは〈初犯〉の意味。初学は学び始めることで、法律上の罪の区分には使わない。"}, {"text": "この本は初学が売り切れた。", "explanation": "ここは〈初版〉の意味。初学は学び始めることで、本の刷りの種類には使わない。"}, {"text": "彼女は初学で主役を演じた。", "explanation": "ここは〈初舞台〉の意味。初学は学習の段階で、舞台に立つ経験には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52539, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "初学をつまずくと、その後の理解にも響く。", "corrected_sentence": "初学でつまずくと、その後の理解にも響く。", "error_description": "「つまずく」は自動詞なので「を」は使えない。場面は「で」で示し、正しくは「初学でつまずく」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52539, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "初学をうちは、毎日少しずつ続けることが上達の近道だ。", "corrected_sentence": "初学のうちは、毎日少しずつ続けることが上達の近道だ。", "error_description": "「〜のうち」は「の」で続ける。「を」は誤りで、正しくは「初学のうち」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52540, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「初学の段階」。名詞を修飾する「の」で、学び始めの段階を指す。"}, {"text": "が", "is_correct": false, "explanation": "「初学が段階では」は主語の形で、段階を修飾できない。"}, {"text": "を", "is_correct": false, "explanation": "「初学を段階では」は対象の形で、段階を修飾できない。"}, {"text": "に", "is_correct": false, "explanation": "「初学に段階では」は位置を示す形で、段階を修飾しない。"}], "correct_answer": "の", "explanations": {"の": "「初学の段階」。名詞を修飾する「の」で、学び始めの段階を指す。", "が": "「初学が段階では」は主語の形で、段階を修飾できない。", "を": "「初学を段階では」は対象の形で、段階を修飾できない。", "に": "「初学に段階では」は位置を示す形で、段階を修飾しない。"}, "error_tags": {"が": "主語の誤り", "を": "対象の誤り", "に": "位置の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52540, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「初学で挫折する」。挫折が起きる場面・段階を「で」で示す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列・共同を示す。「初学と挫折する人が多い」では意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「初学を挫折する」は、挫折が対象を取る動詞ではないため誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「初学へ挫折する」は方向を示す形で、挫折する場面にならない。"}], "correct_answer": "で", "explanations": {"で": "「初学で挫折する」。挫折が起きる場面・段階を「で」で示す。", "と": "「と」は並列・共同を示す。「初学と挫折する人が多い」では意味が通らない。", "を": "「初学を挫折する」は、挫折が対象を取る動詞ではないため誤り。", "へ": "「初学へ挫折する」は方向を示す形で、挫折する場面にならない。"}, "error_tags": {"と": "並列・共同", "を": "対象の誤り", "へ": "方向の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52540, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "学び始めること。初めて学ぶこと。", "primary_collocate": null, "pronunciation": "しょがく", "ipa": "ɕoɡakɯ", "syllable_count": 3, "sentences": [{"text": "初学の時期に、先生の話を毎回ノートに書き留めた。", "target_word": "初学", "complexity_tier": "T4", "furigana": "初学[しょがく]の時期[じき]に、先生[せんせい]の話[はなし]を毎回[まいかい]ノートに書[か]き留[と]めた。", "sentence_source": "generated"}, {"text": "初学の段階では、基本を繰り返し練習することが何より大切だ。", "target_word": "初学", "complexity_tier": "T3", "furigana": "初学[しょがく]の段階[だんかい]では、基本[きほん]を繰[く]り返[かえ]し練習[れんしゅう]することが何[なに]より大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "初学のころに身につけた習慣は、その後も長く役に立つ。", "target_word": "初学", "complexity_tier": "T3", "furigana": "初学[しょがく]のころに身[み]につけた習慣[しゅうかん]は、その後[ご]も長[なが]く役[やく]に立[た]つ。", "sentence_source": "generated"}, {"text": "彼は初学の身でありながら、先生にも鋭い質問をした。", "target_word": "初学", "complexity_tier": "T3", "furigana": "彼[かれ]は初学[しょがく]の身[み]でありながら、先生[せんせい]にも鋭[するど]い質問[しつもん]をした。", "sentence_source": "generated"}, {"text": "初学のうちは、難しい本よりも入門書を読むほうがよい。", "target_word": "初学", "complexity_tier": "T3", "furigana": "初学[しょがく]のうちは、難[むずか]しい本[ほん]よりも入門書[にゅうもんしょ]を読[よ]むほうがよい。", "sentence_source": "generated"}, {"text": "英語の初学に時間をかけたおかげで、今は自信を持って話せる。", "target_word": "初学", "complexity_tier": "T3", "furigana": "英語[えいご]の初学[しょがく]に時間[じかん]をかけたおかげで、今[いま]は自信[じしん]を持[も]って話[はな]せる。", "sentence_source": "generated"}, {"text": "初学の時期に正しい発音を覚えないと、後で直すのが大変だ。", "target_word": "初学", "complexity_tier": "T3", "furigana": "初学[しょがく]の時期[じき]に正[ただ]しい発音[はつおん]を覚[おぼ]えないと、後[あと]で直[なお]すのが大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "初学で挫折する人が多いので、教室では丁寧に説明している。", "target_word": "初学", "complexity_tier": "T3", "furigana": "初学[しょがく]で挫折[ざせつ]する人[ひと]が多[おお]いので、教室[きょうしつ]では丁寧[ていねい]に説明[せつめい]している。", "sentence_source": "generated"}, {"text": "初学の苦労を思い出すと、新入生の気持ちがよくわかる。", "target_word": "初学", "complexity_tier": "T3", "furigana": "初学[しょがく]の苦労[くろう]を思[おも]い出[だ]すと、新入生[しんにゅうせい]の気持[きも]ちがよくわかる。", "sentence_source": "generated"}, {"text": "ピアノの初学では、まず正しい姿勢を身につけるべきだ。", "target_word": "初学", "complexity_tier": "T3", "furigana": "ピアノの初学[しょがく]では、まず正[ただ]しい姿勢[しせい]を身[み]につけるべきだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "初学", "label": "基本形"}], "register": "書き言葉・やや硬い", "sense_fingerprint": "ある分野を学び始めたばかりの段階や時期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21d2050e-73d4-41bb-b305-1aad375477d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52540, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "初学", "is_correct": true, "explanation": "「初学の時期」として、学び始めの時期を指し、文の意味に合う。"}, {"text": "天井", "is_correct": false, "explanation": "「天井の時期」とは言わず、文の意味に合わない。"}, {"text": "電話", "is_correct": false, "explanation": "「電話の時期」とは言わず、文の意味に合わない。"}, {"text": "台所", "is_correct": false, "explanation": "「台所の時期」とは言わず、文の意味に合わない。"}], "explanations": {"初学": "「初学の時期」として、学び始めの時期を指し、文の意味に合う。", "天井": "「天井の時期」とは言わず、文の意味に合わない。", "電話": "「電話の時期」とは言わず、文の意味に合わない。", "台所": "「台所の時期」とは言わず、文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "初学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この病気は初学に見つければ、治りやすい。", "explanation": "ここは〈初期〉の意味。初学は学び始める時期で、病気の段階には使わない。"}, {"text": "彼は初学なので、執行猶予がついた。", "explanation": "ここは〈初犯〉の意味。初学は学び始めることで、法律上の罪の区分には使わない。"}, {"text": "初学にかえって、もう一度ゼロから考え直す。", "explanation": "ここは〈初心〉の意味。初学は学び始めの段階で、気持ちに立ち返るという意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52540, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初学", "is_correct": true, "explanation": "「初学の時期」として、学び始めの時期を指す。"}, {"text": "語彙", "is_correct": false, "explanation": "「語彙の時期」とは言わず、発音を覚える時期の話には合わない。"}, {"text": "文法", "is_correct": false, "explanation": "「文法の時期」とは言わず、発音の習得には合わない。"}, {"text": "単語", "is_correct": false, "explanation": "「単語の時期」とは言わず、文の意味に合わない。"}], "explanations": {"初学": "「初学の時期」として、学び始めの時期を指す。", "語彙": "「語彙の時期」とは言わず、発音を覚える時期の話には合わない。", "文法": "「文法の時期」とは言わず、発音の習得には合わない。", "単語": "「単語の時期」とは言わず、文の意味に合わない。"}, "sentence_index": 6, "correct_answer": "初学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この曲は昨年、東京で初学された。", "explanation": "ここは〈初演〉の意味。初学は学び始めることで、作品の初めての披露には使わない。"}, {"text": "囲碁の初学を誤って、序盤から不利になった。", "explanation": "ここは〈初手〉の意味。初学は学習のことで、一手目の着手には使わない。"}, {"text": "初学で受付を済ませ、問診票を書いた。", "explanation": "ここは〈初診〉の意味。初学は学習の段階で、病院の初めての受診には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52540, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "初学な私には、この本は少し難しかった。", "corrected_sentence": "初学の私には、この本は少し難しかった。", "error_description": "「初学」は名詞なので、名詞に続けるのは「の」。「な」は誤りで、正しくは「初学の私」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52540, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "初学を挫折しやすいので、教室では丁寧に説明している。", "corrected_sentence": "初学で挫折しやすいので、教室では丁寧に説明している。", "error_description": "「挫折する」は場面を「で」で示す。「を」は誤りで、正しくは「初学で挫折」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52541, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「看護師を志しています」で、目指す対象を示す格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「看護師に志す」は目標の対象を示せず不自然。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す「で」では、目標を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では、目指す対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「看護師を志しています」で、目指す対象を示す格助詞。", "に": "「看護師に志す」は目標の対象を示せず不自然。", "で": "場所や手段を示す「で」では、目標を表せない。", "へ": "方向を示す「へ」では、目指す対象にならない。"}, "error_tags": {"に": "対象", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52541, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「消防士を志した」で、目指す対象を示す格助詞。"}, {"text": "と", "is_correct": false, "explanation": "「消防士と志した」では並列になり、目標を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」では、目指す対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」では、目標の対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「消防士を志した」で、目指す対象を示す格助詞。", "と": "「消防士と志した」では並列になり、目標を示せない。", "から": "起点を示す「から」では、目指す対象にならない。", "より": "比較を示す「より」では、目標の対象を表せない。"}, "error_tags": {"と": "並列", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52541, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを目指して、がんばる。", "primary_collocate": null, "pronunciation": "こころざす", "ipa": "kokoɾozasɯ", "syllable_count": 5, "sentences": [{"text": "弟はサッカー選手を志して、毎朝早く走っている。", "target_word": "志して", "complexity_tier": "T3", "furigana": "弟[おとうと]はサッカー選手[せんしゅ]を志[こころざ]して、毎朝[まいあさ]早[はや]く走[はし]っている。", "sentence_source": "generated"}, {"text": "私は将来、看護師を志しています。", "target_word": "志し", "complexity_tier": "T3", "furigana": "私[わたし]は将来[しょうらい]、看護師[かんごし]を志[こころざ]しています。", "sentence_source": "generated"}, {"text": "留学を志した彼女は、アルバイトでお金をためた。", "target_word": "志した", "complexity_tier": "T3", "furigana": "留学[りゅうがく]を志[こころざ]した彼女[かのじょ]は、アルバイトでお金[かね]をためた。", "sentence_source": "generated"}, {"text": "画家を志す友人が、小さな個展を開くことになった。", "target_word": "志す", "complexity_tier": "T3", "furigana": "画家[がか]を志[こころざ]す友人[ゆうじん]が、小[ちい]さな個展[こてん]を開[ひら]くことになった。", "sentence_source": "generated"}, {"text": "料理人を志すなら、まず基本の包丁さばきを覚えなさい。", "target_word": "志す", "complexity_tier": "T3", "furigana": "料理人[りょうりにん]を志[こころざ]すなら、まず基本[きほん]の包丁[ほうちょう]さばきを覚[おぼ]えなさい。", "sentence_source": "generated"}, {"text": "宇宙飛行士を志して、数学と英語の勉強に力を入れている。", "target_word": "志して", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]飛行士[ひこうし]を志[こころざ]して、数学[すうがく]と英語[えいご]の勉強[べんきょう]に力[ちから]を入[い]れている。", "sentence_source": "generated"}, {"text": "彼は若いころ弁護士を志したが、試験に何度も落ちた。", "target_word": "志した", "complexity_tier": "T3", "furigana": "彼[かれ]は若[わか]いころ弁護士[べんごし]を志[こころざ]したが、試験[しけん]に何度[なんど]も落[お]ちた。", "sentence_source": "generated"}, {"text": "兄が消防士を志したきっかけは、子どものころの火事だった。", "target_word": "志した", "complexity_tier": "T3", "furigana": "兄[あに]が消防士[しょうぼうし]を志[こころざ]したきっかけは、子[こ]どものころの火事[かじ]だった。", "sentence_source": "generated"}, {"text": "平和な社会の実現を志して、彼は市民団体に加わった。", "target_word": "志して", "complexity_tier": "T3", "furigana": "平和[へいわ]な社会[しゃかい]の実現[じつげん]を志[こころざ]して、彼[かれ]は市民[しみん]団体[だんたい]に加[くわ]わった。", "sentence_source": "generated"}, {"text": "歌手を志す少女が、駅前で毎週歌っている。", "target_word": "志す", "complexity_tier": "T3", "furigana": "歌手[かしゅ]を志[こころざ]す少女[しょうじょ]が、駅前[えきまえ]で毎週[まいしゅう]歌[うた]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "志す", "label": "終止形"}, {"form": "志し", "label": "連用形"}, {"form": "志さ", "label": "未然形"}, {"form": "志せ", "label": "仮定形"}, {"form": "志そう", "label": "意向形"}, {"form": "志した", "label": "た形"}, {"form": "志して", "label": "て形"}], "register": "標準・やや硬い", "sense_fingerprint": "なりたい職業や進みたい道を目指してがんばる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21d2050e-73d4-41bb-b305-1aad375477d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52541, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "志して", "is_correct": true, "explanation": "「サッカー選手を志して」で、目指して努力するという文意に合う。"}, {"text": "煮込んで", "is_correct": false, "explanation": "料理を煮る意味で、サッカー選手とは組み合わない。"}, {"text": "脱いで", "is_correct": false, "explanation": "服を脱ぐ動作で、目指す意味にならない。"}, {"text": "叩いて", "is_correct": false, "explanation": "打つという意味で、目標に向かう文脈に合わない。"}], "explanations": {"志して": "「サッカー選手を志して」で、目指して努力するという文意に合う。", "煮込んで": "料理を煮る意味で、サッカー選手とは組み合わない。", "脱いで": "服を脱ぐ動作で、目指す意味にならない。", "叩いて": "打つという意味で、目標に向かう文脈に合わない。"}, "sentence_index": 0, "correct_answer": "志して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お母さんは、家族のためにケーキを志そうと朝から材料を並べた。", "explanation": "ここは〈作る〉の意味。志すは目標や職業に向かう努力で、食べ物を作る動作には使わない。"}, {"text": "彼女は友人に手紙を志そうと、郵便局へ向かった。", "explanation": "ここは〈届ける〉の意味。志すは目指して努力する意味で、物を届ける行為は表せない。"}, {"text": "父は電車を志そうと、駅へ走った。", "explanation": "ここは〈乗る〉の意味。志すは目標に向かう努力で、乗り物に乗る動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52541, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "志した", "is_correct": true, "explanation": "「弁護士を志したが」で、目指したという過去の動作を表し、文意に合う。"}, {"text": "割った", "is_correct": false, "explanation": "割るは壊す意味で、目指す意味にならない。"}, {"text": "干した", "is_correct": false, "explanation": "乾かす意味で、目標に向かう文脈に合わない。"}, {"text": "焦がした", "is_correct": false, "explanation": "焼いて色をつける意味で、ここでは文が成り立たない。"}], "explanations": {"志した": "「弁護士を志したが」で、目指したという過去の動作を表し、文意に合う。", "割った": "割るは壊す意味で、目指す意味にならない。", "干した": "乾かす意味で、目標に向かう文脈に合わない。", "焦がした": "焼いて色をつける意味で、ここでは文が成り立たない。"}, "sentence_index": 6, "correct_answer": "志した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は車を志そうと、ホースを取り出した。", "explanation": "ここは〈洗う〉の意味。志すは目指して努力する意味で、車を洗う行為には使えない。"}, {"text": "薬を志そうと、コップに水を汲んだ。", "explanation": "ここは〈飲む〉の意味。志すは目標に向かう努力で、薬を飲む動作は表せない。"}, {"text": "本を志すために、図書館で席を探した。", "explanation": "ここは〈読む〉の意味。志すは目標や理想に向かう努力で、本を読む動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52541, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は消防士に志して、毎日体を鍛えている。", "corrected_sentence": "兄は消防士を志して、毎日体を鍛えている。", "error_description": "誤: 消防士に志して（「志す」は目標を「を」で示す）。正: 消防士を志して。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "志し", "is_correct": true, "explanation": "連用形で、「ています」に続けて進行の形を作れる。"}, {"text": "志さ", "is_correct": false, "explanation": "未然形なので、「ています」には続かない。"}, {"text": "志せ", "is_correct": false, "explanation": "仮定形・命令形で、「ています」には続かない。"}, {"text": "志す", "is_correct": false, "explanation": "終止形のままでは「ています」に直接続かない。"}], "correct_form": "志し", "base_form": "志す", "form_label": "連用形", "sentence_index": 1, "explanations": {"志し": "連用形で、「ています」に続けて進行の形を作れる。", "志さ": "未然形なので、「ています」には続かない。", "志せ": "仮定形・命令形で、「ています」には続かない。", "志す": "終止形のままでは「ています」に直接続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52541, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は若いころ大工を志ていたが、家族に止められた。", "corrected_sentence": "祖父は若いころ大工を志していたが、家族に止められた。", "error_description": "誤: 志て（「志している」の「し」が抜けている）。正: 志していた。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "志した", "is_correct": true, "explanation": "た形で名詞「きっかけ」を修飾する形。文法的に正しい。"}, {"text": "志し", "is_correct": false, "explanation": "連用形は名詞を直接修飾できず、ここでは成り立たない。"}, {"text": "志して", "is_correct": false, "explanation": "て形は名詞を直接修飾できず、「志してきっかけは」は不自然。"}, {"text": "志さ", "is_correct": false, "explanation": "未然形は名詞を修飾できず、ここでは文が成り立たない。"}], "correct_form": "志した", "base_form": "志す", "form_label": "た形（連体修飾）", "sentence_index": 7, "explanations": {"志した": "た形で名詞「きっかけ」を修飾する形。文法的に正しい。", "志し": "連用形は名詞を直接修飾できず、ここでは成り立たない。", "志して": "て形は名詞を直接修飾できず、「志してきっかけは」は不自然。", "志さ": "未然形は名詞を修飾できず、ここでは文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52543, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「この工房で教室が開かれる」のように、行事が行われる場所を示す。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を示すため、「この工房を」では場所の意味にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すため、「開かれる」場所を表すには合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すため、「この工房から教室が開かれる」は場所の意味として不自然になる。"}], "correct_answer": "で", "explanations": {"で": "「この工房で教室が開かれる」のように、行事が行われる場所を示す。", "を": "動作の対象を示すため、「この工房を」では場所の意味にならない。", "へ": "方向を示すため、「開かれる」場所を表すには合わない。", "から": "起点を示すため、「この工房から教室が開かれる」は場所の意味として不自然になる。"}, "error_tags": {"を": "対象", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52543, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「工房が狭い」の主語を示す。主題を示す「は」とは違い、ここでは主語を標示する。"}, {"text": "に", "is_correct": false, "explanation": "到着点や存在の場所を示すため、「工房に狭い」では主語にならない。"}, {"text": "で", "is_correct": false, "explanation": "場所を示すため、「工房で狭い」では形容詞の主語として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "共同を示すため、「工房と狭い」では文の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「工房が狭い」の主語を示す。主題を示す「は」とは違い、ここでは主語を標示する。", "に": "到着点や存在の場所を示すため、「工房に狭い」では主語にならない。", "で": "場所を示すため、「工房で狭い」では形容詞の主語として成り立たない。", "と": "共同を示すため、「工房と狭い」では文の主語にならない。"}, "error_tags": {"に": "到着点", "で": "場所", "と": "共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52543, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものをつくるへや", "primary_collocate": null, "pronunciation": "こうぼう", "ipa": "koːboː", "syllable_count": 4, "sentences": [{"text": "父は庭の工房で、木の椅子を作っている。", "target_word": "工房", "complexity_tier": "T3", "furigana": "父[ちち]は庭[にわ]の工房[こうぼう]で、木[き]の椅子[いす]を作[つく]っている。", "sentence_source": "generated"}, {"text": "この工房では、毎週土曜日に陶芸教室が開かれる。", "target_word": "工房", "complexity_tier": "T3", "furigana": "この工房[こうぼう]では、毎週[まいしゅう]土曜日[どようび]に陶芸[とうげい]教室[きょうしつ]が開[ひら]かれる。", "sentence_source": "generated"}, {"text": "工房の中は、木くずのにおいでいっぱいだった。", "target_word": "工房", "complexity_tier": "T3", "furigana": "工房[こうぼう]の中[なか]は、木[き]くずのにおいでいっぱいだった。", "sentence_source": "generated"}, {"text": "私は自分の工房がほしくて、小さな家を探している。", "target_word": "工房", "complexity_tier": "T3", "furigana": "私[わたし]は自分[じぶん]の工房[こうぼう]がほしくて、小[ちい]さな家[いえ]を探[さが]している。", "sentence_source": "generated"}, {"text": "工房に入る前に、必ず手を洗ってください。", "target_word": "工房", "complexity_tier": "T3", "furigana": "工房[こうぼう]に入[はい]る前[まえ]に、必[かなら]ず手[て]を洗[あら]ってください。", "sentence_source": "generated"}, {"text": "雨の日は外に出られないので、一日じゅう工房にいた。", "target_word": "工房", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は外[そと]に出[で]られないので、一日[いちにち]じゅう工房[こうぼう]にいた。", "sentence_source": "generated"}, {"text": "彼の工房には、手作りの時計が百個以上ある。", "target_word": "工房", "complexity_tier": "T3", "furigana": "彼[かれ]の工房[こうぼう]には、手作[てづく]りの時計[とけい]が百個[ひゃっこ]以上[いじょう]ある。", "sentence_source": "generated"}, {"text": "工房が狭いので、大きな作品は作れない。", "target_word": "工房", "complexity_tier": "T3", "furigana": "工房[こうぼう]が狭[せま]いので、大[おお]きな作品[さくひん]は作[つく]れない。", "sentence_source": "generated"}, {"text": "友達の工房を訪ねて、革のかばんの作り方を教わった。", "target_word": "工房", "complexity_tier": "T3", "furigana": "友達[ともだち]の工房[こうぼう]を訪[たず]ねて、革[かわ]のかばんの作[つく]り方[かた]を教[おそ]わった。", "sentence_source": "generated"}, {"text": "工房の壁には、使い込んだ道具が掛けてある。", "target_word": "工房", "complexity_tier": "T3", "furigana": "工房[こうぼう]の壁[かべ]には、使[つか]い込[こ]んだ道具[どうぐ]が掛[か]けてある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "工房", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ものを作る部屋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfd20d42-23ee-4ee7-8eb0-26fc22ef5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52543, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工房", "is_correct": true, "explanation": "ものを作るための部屋で、庭で木の椅子を作る場所として合う。"}, {"text": "水族館", "is_correct": false, "explanation": "魚を展示する施設で、椅子を作る場所ではない。"}, {"text": "牢獄", "is_correct": false, "explanation": "収容施設で、木の椅子を作る場所にはならない。"}, {"text": "神殿", "is_correct": false, "explanation": "信仰のための施設で、木の椅子を作る場所としては合わない。"}], "explanations": {"工房": "ものを作るための部屋で、庭で木の椅子を作る場所として合う。", "水族館": "魚を展示する施設で、椅子を作る場所ではない。", "牢獄": "収容施設で、木の椅子を作る場所にはならない。", "神殿": "信仰のための施設で、木の椅子を作る場所としては合わない。"}, "sentence_index": 0, "correct_answer": "工房"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この工房では、一日に千個のねじを機械で作っている。", "explanation": "ここは〈工場〉の意味。工房は少人数で作る小さな作業場で、機械による大量生産には使わない。"}, {"text": "この工房では、毎晩チラシを大量に刷っている。", "explanation": "ここは〈印刷所〉の意味。工房は手で物を作る場所で、大量の印刷物を刷る施設には使わない。"}, {"text": "この工房では、毎朝全校生徒が校歌を歌う。", "explanation": "ここは〈学校〉の意味。工房はものを作るへやで、全校生徒が校歌を歌う場所ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52543, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工房", "is_correct": true, "explanation": "手作りの時計を作る作業場として、「彼の〜には、手作りの時計が百個以上ある」に合う。"}, {"text": "戦場", "is_correct": false, "explanation": "戦いの場で、手作りの時計が百個以上あるという文に合わない。"}, {"text": "砂漠", "is_correct": false, "explanation": "乾燥した地域で、手作りの時計が並んでいる場所としては合わない。"}, {"text": "火山", "is_correct": false, "explanation": "噴火する山で、手作りの時計が並ぶ場所とは合わない。"}], "explanations": {"工房": "手作りの時計を作る作業場として、「彼の〜には、手作りの時計が百個以上ある」に合う。", "戦場": "戦いの場で、手作りの時計が百個以上あるという文に合わない。", "砂漠": "乾燥した地域で、手作りの時計が並んでいる場所としては合わない。", "火山": "噴火する山で、手作りの時計が並ぶ場所とは合わない。"}, "sentence_index": 6, "correct_answer": "工房"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅前の工房に、若い警察官が立っている。", "explanation": "ここは〈交番〉の意味。工房は作業場で、警察官が詰めている施設ではない。"}, {"text": "暑さをしのぐ工房を、いくつも考えた。", "explanation": "ここは〈工夫〉（方法や知恵）の意味。工房は場所で、考え出す方法を指すことはない。"}, {"text": "この橋は工房のため、来月まで通行止めになる。", "explanation": "ここは〈工事〉の意味。工房は作業場で、橋の工事そのものを指すことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52543, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は家の裏の工房に、革のベルトを作っている。", "corrected_sentence": "兄は家の裏の工房で、革のベルトを作っている。", "error_description": "誤り：工房に。正しい：工房で。「作る」の動作の場所は「で」で示す。「に」は到着点を示すため、ここでは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52543, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は朝から工房にこもる、古い人形を直した。", "corrected_sentence": "祖母は朝から工房にこもり、古い人形を直した。", "error_description": "誤り：こもる。正しい：こもり。「こもり、〜」と動作を続けるには連用形が必要で、終止形のままでは文が続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52544, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「工房で陶器を作る」のように、動作が行われる場所を示す。"}, {"text": "に", "is_correct": false, "explanation": "到着点や存在の場所を示すため、作る動作の場所を表すには合わない。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を示すため、場所を対象のように扱ってしまい不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すため、その場で行う作る動作の場所には合わない。"}], "correct_answer": "で", "explanations": {"で": "「工房で陶器を作る」のように、動作が行われる場所を示す。", "に": "到着点や存在の場所を示すため、作る動作の場所を表すには合わない。", "を": "動作の対象を示すため、場所を対象のように扱ってしまい不自然になる。", "へ": "方向を示すため、その場で行う作る動作の場所には合わない。"}, "error_tags": {"に": "到着点", "を": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52544, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「工房で染めた」のように、染める動作が行われる場所を示す。"}, {"text": "と", "is_correct": false, "explanation": "共同を示すため、「工房と染めた布」では場所の関係が成立しない。"}, {"text": "を", "is_correct": false, "explanation": "対象を示すため、「工房を染めた」では工房自体が染められる意味になり、場所として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "到着点を示すため、「工房に染めた布」では布を染める場所を表せず不自然になる。"}], "correct_answer": "で", "explanations": {"で": "「工房で染めた」のように、染める動作が行われる場所を示す。", "と": "共同を示すため、「工房と染めた布」では場所の関係が成立しない。", "を": "対象を示すため、「工房を染めた」では工房自体が染められる意味になり、場所として成り立たない。", "に": "到着点を示すため、「工房に染めた布」では布を染める場所を表せず不自然になる。"}, "error_tags": {"と": "共同", "を": "対象", "に": "到着点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52544, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "作品や製品を作るための作業場。特に、芸術家や職人が使う小さな工場や仕事部屋。", "primary_collocate": null, "pronunciation": "こうぼう", "ipa": "koːboː", "syllable_count": 4, "sentences": [{"text": "それこそが、静謐な自宅の工房において初学者が向き合う、ロボット製作の本質である。", "target_word": "工房", "complexity_tier": "T3", "furigana": "それこそが、静謐[せいひつ]な自宅[じたく]の工房[こうぼう]において初学者[しょがくしゃ]が向[む]き合[あ]う、ロボット製作[せいさく]の本質[ほんしつ]である。", "sentence_source": "mined"}, {"text": "彼は山の中の工房で、毎日陶器を作っている。", "target_word": "工房", "complexity_tier": "T3", "furigana": "彼[かれ]は山[やま]の中[なか]の工房[こうぼう]で、毎日[まいにち]陶器[とうき]を作[つく]っている。", "sentence_source": "generated"}, {"text": "工房の見学は予約が必要なので、先に電話をした。", "target_word": "工房", "complexity_tier": "T3", "furigana": "工房[こうぼう]の見学[けんがく]は予約[よやく]が必要[ひつよう]なので、先[さき]に電話[でんわ]をした。", "sentence_source": "generated"}, {"text": "祖父の工房には、古い道具がたくさん並んでいる。", "target_word": "工房", "complexity_tier": "T3", "furigana": "祖父[そふ]の工房[こうぼう]には、古[ふる]い道具[どうぐ]がたくさん並[なら]んでいる。", "sentence_source": "generated"}, {"text": "工房が火事になり、完成間近の作品がすべて燃えてしまった。", "target_word": "工房", "complexity_tier": "T3", "furigana": "工房[こうぼう]が火事[かじ]になり、完成[かんせい]間近[まぢか]の作品[さくひん]がすべて燃[も]えてしまった。", "sentence_source": "generated"}, {"text": "小さな工房だが、腕のいい職人が集まって評判になった。", "target_word": "工房", "complexity_tier": "T3", "furigana": "小[ちい]さな工房[こうぼう]だが、腕[うで]のいい職人[しょくにん]が集[あつ]まって評判[ひょうばん]になった。", "sentence_source": "generated"}, {"text": "新しい工房を借りたので、来月から作品づくりに専念できる。", "target_word": "工房", "complexity_tier": "T3", "furigana": "新[あたら]しい工房[こうぼう]を借[か]りたので、来月[らいげつ]から作品[さくひん]づくりに専念[せんねん]できる。", "sentence_source": "generated"}, {"text": "彼女は工房で染めた布を使って、かばんを作る。", "target_word": "工房", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は工房[こうぼう]で染[そ]めた布[ぬの]を使[つか]って、かばんを作[つく]る。", "sentence_source": "generated"}, {"text": "工房の窓を開けると、木のいい香りが外まで広がった。", "target_word": "工房", "complexity_tier": "T3", "furigana": "工房[こうぼう]の窓[まど]を開[あ]けると、木[き]のいい香[かお]りが外[そと]まで広[ひろ]がった。", "sentence_source": "generated"}, {"text": "弟子たちは朝早く工房に入り、師匠の指示を待った。", "target_word": "工房", "complexity_tier": "T3", "furigana": "弟子[でし]たちは朝早[あさはや]く工房[こうぼう]に入[はい]り、師匠[ししょう]の指示[しじ]を待[ま]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "工房", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "芸術家や職人が作品を作る作業場", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfd20d42-23ee-4ee7-8eb0-26fc22ef5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52544, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工房", "is_correct": true, "explanation": "作品や製品を作る小さな作業場で、「静謐な自宅の」に続く場所として合う。"}, {"text": "砂漠", "is_correct": false, "explanation": "乾燥した広い地域のことで、静謐な自宅の作業場としては合わない。"}, {"text": "戦場", "is_correct": false, "explanation": "戦いが行われる場所で、ロボット製作の作業場としては文脈に合わない。"}, {"text": "病院", "is_correct": false, "explanation": "診療の施設で、ロボット製作を初学者が行う場所としては合わない。"}], "explanations": {"工房": "作品や製品を作る小さな作業場で、「静謐な自宅の」に続く場所として合う。", "砂漠": "乾燥した広い地域のことで、静謐な自宅の作業場としては合わない。", "戦場": "戦いが行われる場所で、ロボット製作の作業場としては文脈に合わない。", "病院": "診療の施設で、ロボット製作を初学者が行う場所としては合わない。"}, "sentence_index": 0, "correct_answer": "工房"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この工房では、毎日千台の車が流れ作業で組み立てられている。", "explanation": "ここは〈工場〉の意味。工房は少人数で作品を作る小さな作業場で、流れ作業による大量生産には使わない。"}, {"text": "この工房では、何年も新薬の効果を試している。", "explanation": "ここは〈研究所〉の意味。工房は物を作る場所で、薬の効果を検証する研究施設には使わない。"}, {"text": "この工房では、毎晩百万部の雑誌を刷っている。", "explanation": "ここは〈印刷所〉の意味。工房は職人や芸術家が使う作業場で、大部数の印刷物を刷る施設には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52544, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工房", "is_correct": true, "explanation": "作品づくりのための作業場として借りるものなので、「新しい」「借りた」に自然に合う。"}, {"text": "墓地", "is_correct": false, "explanation": "埋葬のための場所で、借りて作品づくりをする場所ではない。"}, {"text": "神殿", "is_correct": false, "explanation": "信仰のための施設で、借りて作品づくりをする場所としては合わない。"}, {"text": "牢獄", "is_correct": false, "explanation": "収容施設で、作品づくりの場所として借りることはない。"}], "explanations": {"工房": "作品づくりのための作業場として借りるものなので、「新しい」「借りた」に自然に合う。", "墓地": "埋葬のための場所で、借りて作品づくりをする場所ではない。", "神殿": "信仰のための施設で、借りて作品づくりをする場所としては合わない。", "牢獄": "収容施設で、作品づくりの場所として借りることはない。"}, "sentence_index": 6, "correct_answer": "工房"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市は毎週、市の工房を発行している。", "explanation": "ここは〈公報〉（行政が出す告知の刊行物）の意味。工房は作業場で、発行される印刷物を指すことはない。"}, {"text": "この道路は工房のため、来月まで通行止めになる。", "explanation": "ここは〈工事〉の意味。工房は作業場であって、道路の工事そのものを指すことはない。"}, {"text": "暑さをしのぐための工房を、家族で話し合った。", "explanation": "ここは〈工夫〉（方法や知恵）の意味。工房は場所で、考え出す方法を指すことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52544, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は裏庭の工房に、毎朝木のおもちゃを作っている。", "corrected_sentence": "祖父は裏庭の工房で、毎朝木のおもちゃを作っている。", "error_description": "誤り：工房に。正しい：工房で。「作る」の動作が行われる場所は「で」で示す。「に」は到着点や存在の場所を示すため、ここでは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52544, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟子たちは朝早く工房に入る、道具を磨いた。", "corrected_sentence": "弟子たちは朝早く工房に入り、道具を磨いた。", "error_description": "誤り：入る。正しい：入り。「入り、〜」と動作を続けるには連用形が必要で、終止形のままでは文が続かない。", "correct_sentence_indices": [6, 7, 8]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52545, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「ロープを垂らす」先の到着点を示し、「深淵にロープを垂らす」となる。"}, {"text": "を", "is_correct": false, "explanation": "対象を示すため、「深淵をロープを垂らす」は場所の関係が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐ働きで、動詞「垂らす」の到着点を示せない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すため、「深淵がロープを垂らす」では意味が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「ロープを垂らす」先の到着点を示し、「深淵にロープを垂らす」となる。", "を": "対象を示すため、「深淵をロープを垂らす」は場所の関係が成り立たない。", "の": "名詞をつなぐ働きで、動詞「垂らす」の到着点を示せない。", "が": "主語を示すため、「深淵がロープを垂らす」では意味が成り立たない。"}, "error_tags": {"を": "対象", "の": "連体", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52545, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「深淵には光が届かない」のように、届く先の場所を示す。"}, {"text": "と", "is_correct": false, "explanation": "共同を示すため、「深淵と光が届かない」では場所の関係が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すため、「深淵から光が届かない」は届く先を表せない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すため、「深淵より光が届かない」では意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「深淵には光が届かない」のように、届く先の場所を示す。", "と": "共同を示すため、「深淵と光が届かない」では場所の関係が成り立たない。", "から": "起点を示すため、「深淵から光が届かない」は届く先を表せない。", "より": "比較を示すため、「深淵より光が届かない」では意味が通らない。"}, "error_tags": {"と": "共同", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52545, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "とても深い穴のこと。", "primary_collocate": null, "pronunciation": "しんえん", "ipa": "ɕiɴeɴ", "syllable_count": 4, "sentences": [{"text": "崖の下には底の見えない深淵が広がっていた。", "target_word": "深淵", "complexity_tier": "T3", "furigana": "崖[がけ]の下[した]には底[そこ]の見[み]えない深淵[しんえん]が広[ひろ]がっていた。", "sentence_source": "generated"}, {"text": "探検家は暗い深淵にロープを垂らして、深さを測った。", "target_word": "深淵", "complexity_tier": "T3", "furigana": "探検家[たんけんか]は暗[くら]い深淵[しんえん]にロープを垂[た]らして、深[ふか]さを測[はか]った。", "sentence_source": "generated"}, {"text": "深淵をのぞき込むと、冷たい風が吹き上がってきた。", "target_word": "深淵", "complexity_tier": "T3", "furigana": "深淵[しんえん]をのぞき込[こ]むと、冷[つめ]たい風[かぜ]が吹[ふ]き上[あ]がってきた。", "sentence_source": "generated"}, {"text": "地震のあと、地面に深淵のような裂け目ができた。", "target_word": "深淵", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、地面[じめん]に深淵[しんえん]のような裂[さ]け目[め]ができた。", "sentence_source": "generated"}, {"text": "彼は足を滑らせ、深淵へ落ちそうになって悲鳴を上げた。", "target_word": "深淵", "complexity_tier": "T3", "furigana": "彼[かれ]は足[あし]を滑[すべ]らせ、深淵[しんえん]へ落[お]ちそうになって悲鳴[ひめい]を上[あ]げた。", "sentence_source": "generated"}, {"text": "洞窟の奥の深淵は、石を落としても音が返ってこない。", "target_word": "深淵", "complexity_tier": "T3", "furigana": "洞窟[どうくつ]の奥[おく]の深淵[しんえん]は、石[いし]を落[お]としても音[おと]が返[かえ]ってこない。", "sentence_source": "generated"}, {"text": "橋の下の深淵を見て、足がすくんでしまった。", "target_word": "深淵", "complexity_tier": "T3", "furigana": "橋[はし]の下[した]の深淵[しんえん]を見[み]て、足[あし]がすくんでしまった。", "sentence_source": "generated"}, {"text": "海の底の深淵には、光がまったく届かない。", "target_word": "深淵", "complexity_tier": "T3", "furigana": "海[うみ]の底[そこ]の深淵[しんえん]には、光[ひかり]がまったく届[とど]かない。", "sentence_source": "generated"}, {"text": "深淵の縁に立つと、めまいがして動けなくなった。", "target_word": "深淵", "complexity_tier": "T3", "furigana": "深淵[しんえん]の縁[ふち]に立[た]つと、めまいがして動[うご]けなくなった。", "sentence_source": "generated"}, {"text": "山道の脇に深淵があるので、子どもの手を離さないでください。", "target_word": "深淵", "complexity_tier": "T3", "furigana": "山道[やまみち]の脇[わき]に深淵[しんえん]があるので、子[こ]どもの手[て]を離[はな]さないでください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "深淵", "label": "基本形"}], "register": "formal", "sense_fingerprint": "底の見えないとても深い穴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfd20d42-23ee-4ee7-8eb0-26fc22ef5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52545, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深淵", "is_correct": true, "explanation": "底の見えないほど深い穴を指し、崖の下に広がっているという文脈に合う。"}, {"text": "草原", "is_correct": false, "explanation": "広い平原のことで、底の見えない穴ではない。"}, {"text": "歌声", "is_correct": false, "explanation": "声の響きのことで、崖の下に広がる場所ではない。"}, {"text": "行列", "is_correct": false, "explanation": "人や物が並んだ列のことで、底の見えない穴が広がるという文に合わない。"}], "explanations": {"深淵": "底の見えないほど深い穴を指し、崖の下に広がっているという文脈に合う。", "草原": "広い平原のことで、底の見えない穴ではない。", "歌声": "声の響きのことで、崖の下に広がる場所ではない。", "行列": "人や物が並んだ列のことで、底の見えない穴が広がるという文に合わない。"}, "sentence_index": 0, "correct_answer": "深淵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓ガラスに深淵が並んでいた。", "explanation": "ここは〈雨粒〉の意味。深淵はとても深い穴のことで、ガラスに付く小さな水滴には使わない。"}, {"text": "夕方、塀の深淵が長く伸びた。", "explanation": "ここは〈影〉の意味。深淵は深い穴を指し、光が遮られてできる影には使わない。"}, {"text": "風呂場に深淵が立ちこめた。", "explanation": "ここは〈湯気〉の意味。深淵は穴を指し、立ちこめる蒸気には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52545, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深淵", "is_correct": true, "explanation": "底の見えない深い穴を指し、橋の下を見て足がすくむという文脈に合う。"}, {"text": "夕立", "is_correct": false, "explanation": "夕方の強い雨のことで、見て足がすくむ対象ではない。"}, {"text": "子守歌", "is_correct": false, "explanation": "子どもを寝かせる歌のことで、橋の下にあるものではない。"}, {"text": "昼寝", "is_correct": false, "explanation": "休息のことで、橋の下を見て足がすくむ対象ではない。"}], "explanations": {"深淵": "底の見えない深い穴を指し、橋の下を見て足がすくむという文脈に合う。", "夕立": "夕方の強い雨のことで、見て足がすくむ対象ではない。", "子守歌": "子どもを寝かせる歌のことで、橋の下にあるものではない。", "昼寝": "休息のことで、橋の下を見て足がすくむ対象ではない。"}, "sentence_index": 6, "correct_answer": "深淵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "壁に小さな深淵が開いている。", "explanation": "ここは〈穴〉の意味。深淵は底の見えないほど深い穴を指し、小さく浅い穴には使わない。"}, {"text": "このかばんの深淵は、一万円ほどだ。", "explanation": "ここは〈値段〉の意味。深淵はとても深い穴のことで、金額を表すことはない。"}, {"text": "校庭の深淵で、子どもたちが毎朝体操をしている。", "explanation": "ここは〈広場〉の意味。深淵はとても深い穴で、人が集まって体操する平らな場所ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52545, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "探検隊は、地図にない深淵にのぞき込んだ。", "corrected_sentence": "探検隊は、地図にない深淵をのぞき込んだ。", "error_description": "誤り：深淵に。正しい：深淵を。「のぞき込む」は対象を「を」で示すので、「に」は合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52545, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は深淵をのぞき込む、そっと後ずさった。", "corrected_sentence": "彼は深淵をのぞき込み、そっと後ずさった。", "error_description": "誤り：のぞき込む。正しい：のぞき込み。「のぞき込み、〜」と続けるには連用形が必要で、終止形のままでは文が続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52546, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「のぞく」の対象を示し、「深淵をのぞく」となる。"}, {"text": "に", "is_correct": false, "explanation": "到着点を示すため、「のぞく」の対象を表すには合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すため、「深淵でのぞく」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すため、「のぞく」の対象を表すには不自然になる。"}], "correct_answer": "を", "explanations": {"を": "「のぞく」の対象を示し、「深淵をのぞく」となる。", "に": "到着点を示すため、「のぞく」の対象を表すには合わない。", "で": "場所や手段を示すため、「深淵でのぞく」は成り立たない。", "へ": "方向を示すため、「のぞく」の対象を表すには不自然になる。"}, "error_tags": {"に": "到着点", "で": "場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52546, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「知る」の対象を示し、「古典文学の深淵を知る」となる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すため、「深淵が知る」では文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "共同を示すため、「深淵と知る」では対象にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すため、「深淵から知る」では対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「知る」の対象を示し、「古典文学の深淵を知る」となる。", "が": "主語を示すため、「深淵が知る」では文が成り立たない。", "と": "共同を示すため、「深淵と知る」では対象にならない。", "から": "起点を示すため、「深淵から知る」では対象を表せない。"}, "error_tags": {"が": "主語", "と": "共同", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52546, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "学問や技術などで、非常に奥深い領域。", "primary_collocate": null, "pronunciation": "しんえん", "ipa": "ɕiɴeɴ", "syllable_count": 4, "sentences": [{"text": "ロボット工学の深淵を志す者がまず体現すべきは、DIYの精神に根ざした泥臭い試行錯誤のプロセスに他ならない。", "target_word": "深淵", "complexity_tier": "T3", "furigana": "ロボット工学[こうがく]の深淵[しんえん]を志[こころざ]す者[もの]がまず体現[たいげん]すべきは、DIYの精神[せいしん]に根[ね]ざした泥臭[どろくさ]い試行錯誤[しこうさくご]のプロセスに他[ほか]ならない。", "sentence_source": "mined"}, {"text": "哲学の深淵をのぞくうちに、簡単な答えなどないと分かった。", "target_word": "深淵", "complexity_tier": "T3", "furigana": "哲学[てつがく]の深淵[しんえん]をのぞくうちに、簡単[かんたん]な答[こた]えなどないと分[わ]かった。", "sentence_source": "generated"}, {"text": "彼は研究を続け、量子論の深淵にたどり着いた。", "target_word": "深淵", "complexity_tier": "T3", "furigana": "彼[かれ]は研究[けんきゅう]を続[つづ]け、量子論[りょうしろん]の深淵[しんえん]にたどり着[つ]いた。", "sentence_source": "generated"}, {"text": "数学の深淵は広く、一生かけても学び尽くせない。", "target_word": "深淵", "complexity_tier": "T3", "furigana": "数学[すうがく]の深淵[しんえん]は広[ひろ]く、一生[いっしょう]かけても学[まな]び尽[つ]くせない。", "sentence_source": "generated"}, {"text": "職人の技術の深淵に触れ、自分の未熟さを思い知った。", "target_word": "深淵", "complexity_tier": "T3", "furigana": "職人[しょくにん]の技術[ぎじゅつ]の深淵[しんえん]に触[ふ]れ、自分[じぶん]の未熟[みじゅく]さを思[おも]い知[し]った。", "sentence_source": "generated"}, {"text": "人間の心理の深淵は、どんな学者にも完全には解明できない。", "target_word": "深淵", "complexity_tier": "T3", "furigana": "人間[にんげん]の心理[しんり]の深淵[しんえん]は、どんな学者[がくしゃ]にも完全[かんぜん]には解明[かいめい]できない。", "sentence_source": "generated"}, {"text": "彼女は言語学の深淵に魅せられ、大学院に進んだ。", "target_word": "深淵", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は言語学[げんごがく]の深淵[しんえん]に魅[み]せられ、大学院[だいがくいん]に進[すす]んだ。", "sentence_source": "generated"}, {"text": "古典文学の深淵を知るには、まず原文を読むしかない。", "target_word": "深淵", "complexity_tier": "T3", "furigana": "古典[こてん]文学[ぶんがく]の深淵[しんえん]を知[し]るには、まず原文[げんぶん]を読[よ]むしかない。", "sentence_source": "generated"}, {"text": "入門書だけでは、この分野の深淵は理解できない。", "target_word": "深淵", "complexity_tier": "T3", "furigana": "入門書[にゅうもんしょ]だけでは、この分野[ぶんや]の深淵[しんえん]は理解[りかい]できない。", "sentence_source": "generated"}, {"text": "師匠は何十年も修行を重ねても、茶道の深淵には届かないと語った。", "target_word": "深淵", "complexity_tier": "T3", "furigana": "師匠[ししょう]は何十年[なんじゅうねん]も修行[しゅぎょう]を重[かさ]ねても、茶道[さどう]の深淵[しんえん]には届[とど]かないと語[かた]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "深淵", "label": "基本形"}], "register": "formal", "sense_fingerprint": "学問や技術の非常に奥深い領域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfd20d42-23ee-4ee7-8eb0-26fc22ef5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52546, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深淵", "is_correct": true, "explanation": "学問の非常に奥深い領域を指し、「ロボット工学の〜を志す」に合う。"}, {"text": "雑談", "is_correct": false, "explanation": "気軽な会話のことで、志す対象となる学問の領域ではない。"}, {"text": "寝坊", "is_correct": false, "explanation": "朝遅く起きることで、志す対象にはならない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "空に見える現象で、学問の領域を志すという文に合わない。"}], "explanations": {"深淵": "学問の非常に奥深い領域を指し、「ロボット工学の〜を志す」に合う。", "雑談": "気軽な会話のことで、志す対象となる学問の領域ではない。", "寝坊": "朝遅く起きることで、志す対象にはならない。", "夕焼け": "空に見える現象で、学問の領域を志すという文に合わない。"}, "sentence_index": 0, "correct_answer": "深淵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この論文の深淵は、結論が飛躍していることだ。", "explanation": "ここは〈問題点〉の意味。深淵は奥深い領域を指し、欠点や問題点の意味では使わない。"}, {"text": "来期の深淵は、社員の給料を倍にすることだ。", "explanation": "ここは〈目標〉の意味。深淵は奥深い領域を指し、目指す目標の意味では使わない。"}, {"text": "提出の深淵は、来週の金曜日だ。", "explanation": "ここは〈期限〉の意味。深淵は期限を表さず、締め切りの日付には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52546, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深淵", "is_correct": true, "explanation": "学問の奥深い領域を指し、言語学に魅せられるという文脈に合う。"}, {"text": "洗濯", "is_correct": false, "explanation": "衣類を洗う家事のことで、魅せられる対象にはならない。"}, {"text": "昼寝", "is_correct": false, "explanation": "休息のことで、言語学に魅せられる対象にはならない。"}, {"text": "雨宿り", "is_correct": false, "explanation": "雨をしのぐ行為で、学問の対象にはならない。"}], "explanations": {"深淵": "学問の奥深い領域を指し、言語学に魅せられるという文脈に合う。", "洗濯": "衣類を洗う家事のことで、魅せられる対象にはならない。", "昼寝": "休息のことで、言語学に魅せられる対象にはならない。", "雨宿り": "雨をしのぐ行為で、学問の対象にはならない。"}, "sentence_index": 6, "correct_answer": "深淵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市の深淵は、今年も二億円を超えた。", "explanation": "ここは〈予算〉の意味。深淵は奥深い領域を指し、金額を表すことはない。"}, {"text": "明日の深淵は、ところにより雨になるでしょう。", "explanation": "ここは〈天気〉の意味。深淵は奥深い領域を指し、天気の予報には使わない。"}, {"text": "この店で一番人気の深淵は、焼きたてのメロンパンだ。", "explanation": "ここは〈商品〉の意味。深淵は奥深い領域を指し、店で売る品物を表すことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52546, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は量子論の深淵にのぞこうと、毎晩遅くまで本を読んでいる。", "corrected_sentence": "彼は量子論の深淵をのぞこうと、毎晩遅くまで本を読んでいる。", "error_description": "誤り：深淵に。正しい：深淵を。「のぞく」は対象を「を」で示す動詞なので、「に」は合わない。", "correct_sentence_indices": [0, 1, 3]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52546, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は哲学の深淵に魅せられる、三年かけて論文を書いた。", "corrected_sentence": "彼女は哲学の深淵に魅せられ、三年かけて論文を書いた。", "error_description": "誤り：魅せられる。正しい：魅せられ。「魅せられ、〜」と続けるには連用形が必要で、終止形のままでは文が続かない。", "correct_sentence_indices": [7, 8, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52547, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「十回の試行のすえ」の「の」。試行を重ねた後の結果へ続く形で、試行に後続する語句をつなぐ。"}, {"text": "が", "is_correct": false, "explanation": "「試行がすえ」は主語にならず、名詞「すえ」にもつながらない。"}, {"text": "へ", "is_correct": false, "explanation": "「試行へすえ」は方向を示す形で、「すえ」と結びつかず意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「試行とすえ」は並列の形になり、結果を示す意味にならない。"}], "correct_answer": "の", "explanations": {"の": "「十回の試行のすえ」の「の」。試行を重ねた後の結果へ続く形で、試行に後続する語句をつなぐ。", "が": "「試行がすえ」は主語にならず、名詞「すえ」にもつながらない。", "へ": "「試行へすえ」は方向を示す形で、「すえ」と結びつかず意味が通らない。", "と": "「試行とすえ」は並列の形になり、結果を示す意味にならない。"}, "error_tags": {"が": "主格", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52547, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52547, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何度もやってみること。", "primary_collocate": null, "pronunciation": "しこう", "ipa": "ɕikoː", "syllable_count": 3, "sentences": [{"text": "何度も試行を繰り返して、ようやく正しい配合を見つけた。", "target_word": "試行", "complexity_tier": "T3", "furigana": "何度[なんど]も試行[しこう]を繰[く]り返[かえ]して、ようやく正[ただ]しい配合[はいごう]を見[み]つけた。", "sentence_source": "generated"}, {"text": "彼女は十回の試行のすえ、ついに合格点を取った。", "target_word": "試行", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は十回[じゅっかい]の試行[しこう]のすえ、ついに合格点[ごうかくてん]を取[と]った。", "sentence_source": "generated"}, {"text": "試行の回数が増えるほど、手の動きは速くなる。", "target_word": "試行", "complexity_tier": "T3", "furigana": "試行[しこう]の回数[かいすう]が増[ふ]えるほど、手[て]の動[うご]きは速[はや]くなる。", "sentence_source": "generated"}, {"text": "実験では、同じ条件で百回試行して平均を出した。", "target_word": "試行", "complexity_tier": "T3", "furigana": "実験[じっけん]では、同[おな]じ条件[じょうけん]で百回[ひゃっかい]試行[しこう]して平均[へいきん]を出[だ]した。", "sentence_source": "generated"}, {"text": "彼は条件を変えながら試行を続け、ようやく安定した結果を得た。", "target_word": "試行", "complexity_tier": "T3", "furigana": "彼[かれ]は条件[じょうけん]を変[か]えながら試行[しこう]を続[つづ]け、ようやく安定[あんてい]した結果[けっか]を得[え]た。", "sentence_source": "generated"}, {"text": "試行が少なすぎて、結果を信用することはできない。", "target_word": "試行", "complexity_tier": "T3", "furigana": "試行[しこう]が少[すく]なすぎて、結果[けっか]を信用[しんよう]することはできない。", "sentence_source": "generated"}, {"text": "何度試行しても、同じところで機械が止まってしまう。", "target_word": "試行", "complexity_tier": "T3", "furigana": "何度[なんど]試行[しこう]しても、同[おな]じところで機械[きかい]が止[と]まってしまう。", "sentence_source": "generated"}, {"text": "サイコロを千回振る試行で、各目の出る割合を調べた。", "target_word": "試行", "complexity_tier": "T3", "furigana": "サイコロを千回[せんかい]振[ふ]る試行[しこう]で、各目[かくめ]の出[で]る割合[わりあい]を調[しら]べた。", "sentence_source": "generated"}, {"text": "試行を重ねた分だけ、料理の味は確実によくなった。", "target_word": "試行", "complexity_tier": "T3", "furigana": "試行[しこう]を重[かさ]ねた分[ぶん]だけ、料理[りょうり]の味[あじ]は確実[かくじつ]によくなった。", "sentence_source": "generated"}, {"text": "最初の試行では失敗したが、二回目で形になった。", "target_word": "試行", "complexity_tier": "T3", "furigana": "最初[さいしょ]の試行[しこう]では失敗[しっぱい]したが、二回目[にかいめ]で形[かたち]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "試行", "label": "基本形"}, {"form": "試行する", "label": "サ変動詞"}], "register": "formal", "sense_fingerprint": "何度も繰り返してやってみること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfd20d42-23ee-4ee7-8eb0-26fc22ef5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52547, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "試行", "is_correct": true, "explanation": "「何度も試行を繰り返して」の「試行」。同じことを何度も試みる意味で、文の中心となる語。"}, {"text": "誕生", "is_correct": false, "explanation": "「何度も誕生を繰り返して」は誕生が一度きりの出来事なので、繰り返す文として成り立たない。"}, {"text": "完成", "is_correct": false, "explanation": "「何度も完成を繰り返して」は完成が一度きりの結果を指すため、文の意味が合わない。"}, {"text": "合格", "is_correct": false, "explanation": "「何度も合格を繰り返して」は合格が結果の一点で、繰り返す動作ではないので合わない。"}], "explanations": {"試行": "「何度も試行を繰り返して」の「試行」。同じことを何度も試みる意味で、文の中心となる語。", "誕生": "「何度も誕生を繰り返して」は誕生が一度きりの出来事なので、繰り返す文として成り立たない。", "完成": "「何度も完成を繰り返して」は完成が一度きりの結果を指すため、文の意味が合わない。", "合格": "「何度も合格を繰り返して」は合格が結果の一点で、繰り返す動作ではないので合わない。"}, "sentence_index": 0, "correct_answer": "試行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい車の試行を三台分組み立て、それぞれ走らせた。", "explanation": "ここは〈試作〉の意味。試行は同じことを何度もためすことで、物を組み立てて作る試作の意味では使わないので合わない。"}, {"text": "店で新しいアルバムの試行を繰り返し、感想をまとめた。", "explanation": "ここは〈試聴〉の意味。試行は方法を何度もためすことで、曲を聴いて確かめる試聴の意味では使わないので合わない。"}, {"text": "店は新しいパンの試行を無料で配り、感想を集めた。", "explanation": "ここは〈試食〉の意味。試行は繰り返してためすことで、食べ物を味見させる試食の意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52547, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "試行", "is_correct": true, "explanation": "「何度試行しても」の「試行」。同じ方法を繰り返しためす意味で、文の主語の行為を表す。"}, {"text": "解散", "is_correct": false, "explanation": "「何度解散しても」は解散が一度きりの出来事なので、繰り返す文として成り立たない。"}, {"text": "卒業", "is_correct": false, "explanation": "「何度卒業しても」は卒業が一度きりの節目なので、文の意味が合わない。"}, {"text": "開店", "is_correct": false, "explanation": "「何度開店しても」は開店が一度きりの出来事なので、文脈に合わない。"}], "explanations": {"試行": "「何度試行しても」の「試行」。同じ方法を繰り返しためす意味で、文の主語の行為を表す。", "解散": "「何度解散しても」は解散が一度きりの出来事なので、繰り返す文として成り立たない。", "卒業": "「何度卒業しても」は卒業が一度きりの節目なので、文の意味が合わない。", "開店": "「何度開店しても」は開店が一度きりの出来事なので、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "試行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "次の試行に勝って、決勝に進んだ。", "explanation": "ここは〈試合〉の意味。試行は同じ方法を繰り返して結果を探すことで、勝ち負けを競う試合とは合わないので誤り。"}, {"text": "彼は服を何度も試行してから、一着に決めた。", "explanation": "ここは〈試着〉の意味。試行は方法を繰り返しためすことで、衣服を身につけて確かめる試着とは別物なので合わない。"}, {"text": "その大会は選手たちにとって大きな試行だった。", "explanation": "ここは〈試練〉の意味。試行は繰り返しためすことで、苦難や困難を指す試練の意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52547, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小さな試行の何度も重ねて、結果を確かめた。", "corrected_sentence": "小さな試行を何度も重ねて、結果を確かめた。", "error_description": "正しくは「試行を何度も重ねて」。重ねる対象は「を」で示す。「の」は名詞どうしをつなぐ助詞で、動詞の目的語には使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52547, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同じ手順で試行を重ねるて、まずまずの数字を出した。", "corrected_sentence": "同じ手順で試行を重ねて、まずまずの数字を出した。", "error_description": "正しくは「重ねて」。動詞「重ねる」を「て」で続けるときは連用形の「重ねて」を使い、「重ねるて」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52548, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「規模で試行」の「で」。試行を行う場や方法の範囲を示す。"}, {"text": "が", "is_correct": false, "explanation": "「規模が試行」は主語にも動作の対象にもならず、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「規模へ試行」は方向を示す形で、試行の範囲を表す文脈に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「規模に試行」では場所や範囲の関係が不自然で、試行の場を示せない。"}], "correct_answer": "で", "explanations": {"で": "「規模で試行」の「で」。試行を行う場や方法の範囲を示す。", "が": "「規模が試行」は主語にも動作の対象にもならず、文として成り立たない。", "へ": "「規模へ試行」は方向を示す形で、試行の範囲を表す文脈に合わない。", "に": "「規模に試行」では場所や範囲の関係が不自然で、試行の場を示せない。"}, "error_tags": {"が": "主格", "へ": "方向", "に": "帰着"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52548, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「試行として」の「と」。「〜として」の形で、試行という資格や立場を示す。"}, {"text": "が", "is_correct": false, "explanation": "「試行がして」は主語にも対象にもならず、「して」と結びつかない。"}, {"text": "へ", "is_correct": false, "explanation": "「試行へして」は方向を示す形で、「して」と続く文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「試行でして」は手段を示せても、「して」の形と結びつかず不自然。"}], "correct_answer": "と", "explanations": {"と": "「試行として」の「と」。「〜として」の形で、試行という資格や立場を示す。", "が": "「試行がして」は主語にも対象にもならず、「して」と結びつかない。", "へ": "「試行へして」は方向を示す形で、「して」と続く文として成り立たない。", "で": "「試行でして」は手段を示せても、「して」の形と結びつかず不自然。"}, "error_tags": {"が": "主格", "へ": "方向", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52548, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ためしに何かをやってみること。うまくいくかどうかわからないが、やってみること。", "primary_collocate": null, "pronunciation": "しこう", "ipa": "ɕikoː", "syllable_count": 3, "sentences": [{"text": "全店に広げる前に、まず一店で試行を行うことになった。", "target_word": "試行", "complexity_tier": "T3", "furigana": "全店[ぜんてん]に広[ひろ]げる前[まえ]に、まず一店[いってん]で試行[しこう]を行[おこな]うことになった。", "sentence_source": "generated"}, {"text": "新しい方法をまず小さな規模で試行してみることにした。", "target_word": "試行", "complexity_tier": "T3", "furigana": "新[あたら]しい方法[ほうほう]をまず小[ちい]さな規模[きぼ]で試行[しこう]してみることにした。", "sentence_source": "generated"}, {"text": "試行の結果が良ければ、来年から全店で導入する。", "target_word": "試行", "complexity_tier": "T3", "furigana": "試行[しこう]の結果[けっか]が良[よ]ければ、来年[らいねん]から全店[ぜんてん]で導入[どうにゅう]する。", "sentence_source": "generated"}, {"text": "この制度は来月から半年間、試行される予定だ。", "target_word": "試行", "complexity_tier": "T3", "furigana": "この制度[せいど]は来月[らいげつ]から半年間[はんとしかん]、試行[しこう]される予定[よてい]だ。", "sentence_source": "generated"}, {"text": "うまくいくか分からないが、とにかく試行してから考えよう。", "target_word": "試行", "complexity_tier": "T3", "furigana": "うまくいくか分[わ]からないが、とにかく試行[しこう]してから考[かんが]えよう。", "sentence_source": "generated"}, {"text": "新しい時間割を試行したが、生徒の反応はよくなかった。", "target_word": "試行", "complexity_tier": "T3", "furigana": "新[あたら]しい時間割[じかんわり]を試行[しこう]したが、生徒[せいと]の反応[はんのう]はよくなかった。", "sentence_source": "generated"}, {"text": "市は無料バスの試行を始め、利用者の数を調べている。", "target_word": "試行", "complexity_tier": "T3", "furigana": "市[し]は無料[むりょう]バスの試行[しこう]を始[はじ]め、利用者[りようしゃ]の数[かず]を調[しら]べている。", "sentence_source": "generated"}, {"text": "この機能は試行として公開しているので、予告なく変更されることがある。", "target_word": "試行", "complexity_tier": "T3", "furigana": "この機能[きのう]は試行[しこう]として公開[こうかい]しているので、予告[よこく]なく変更[へんこう]されることがある。", "sentence_source": "generated"}, {"text": "失敗してもいいから、まず試行してみることが大切だ。", "target_word": "試行", "complexity_tier": "T3", "furigana": "失敗[しっぱい]してもいいから、まず試行[しこう]してみることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "会社は在宅勤務を三か月だけ試行することに決めた。", "target_word": "試行", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は在宅[ざいたく]勤務[きんむ]を三[さん]か月[げつ]だけ試行[しこう]することに決[き]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "試行", "label": "基本形"}, {"form": "試行する", "label": "サ変動詞"}], "register": "formal", "sense_fingerprint": "うまくいくか分からないままためしにやってみること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfd20d42-23ee-4ee7-8eb0-26fc22ef5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52548, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "試行", "is_correct": true, "explanation": "「一店で試行を行う」の「試行」。うまくいくか分からないままためしに実施する意味で、文の中心となる語。"}, {"text": "解散", "is_correct": false, "explanation": "「一店で解散を行う」は解散が組織を終わらせる出来事で、ためしに実施する意味に合わない。"}, {"text": "卒業", "is_correct": false, "explanation": "「一店で卒業を行う」は卒業が課程を終える節目で、ためしに実施する意味に合わない。"}, {"text": "誕生", "is_correct": false, "explanation": "「一店で誕生を行う」は誕生が自然に起こる出来事で、行う対象として意味が成り立たない。"}], "explanations": {"試行": "「一店で試行を行う」の「試行」。うまくいくか分からないままためしに実施する意味で、文の中心となる語。", "解散": "「一店で解散を行う」は解散が組織を終わらせる出来事で、ためしに実施する意味に合わない。", "卒業": "「一店で卒業を行う」は卒業が課程を終える節目で、ためしに実施する意味に合わない。", "誕生": "「一店で誕生を行う」は誕生が自然に起こる出来事で、行う対象として意味が成り立たない。"}, "sentence_index": 0, "correct_answer": "試行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新型車の試行を三台作り、それぞれ耐久性を確かめた。", "explanation": "ここは〈試作〉の意味。試行は方法や制度をためしに実施することで、部品や車体を作ることは指さないので合わない。"}, {"text": "大会は選手にとって大きな試行となった。", "explanation": "ここは〈試練〉の意味。試行は実際にやってみることで、苦しみや困難を指す試練とは違うので合わない。"}, {"text": "学生たちは来週、期末の試行を受ける。", "explanation": "ここは〈試験〉の意味。試行は新しい方法を実際にためすことで、学力を測る試験とは別物なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52548, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "試行", "is_correct": true, "explanation": "「無料バスの試行を始め」の「試行」。ためしに実施することを指し、文の中心となる語。"}, {"text": "乗客", "is_correct": false, "explanation": "「無料バスの乗客を始め」は、乗客を始めるという動作の対象にならず意味が通らない。"}, {"text": "停留所", "is_correct": false, "explanation": "「停留所を始め」は始められる動作の対象にならず、文が成り立たない。"}, {"text": "料金", "is_correct": false, "explanation": "「料金を始め」は意味が通らず、無料バスの文脈とも合わない。"}], "explanations": {"試行": "「無料バスの試行を始め」の「試行」。ためしに実施することを指し、文の中心となる語。", "乗客": "「無料バスの乗客を始め」は、乗客を始めるという動作の対象にならず意味が通らない。", "停留所": "「停留所を始め」は始められる動作の対象にならず、文が成り立たない。", "料金": "「料金を始め」は意味が通らず、無料バスの文脈とも合わない。"}, "sentence_index": 6, "correct_answer": "試行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店は新商品の試行を配って、お客の感想を集めた。", "explanation": "ここは〈試食〉の意味。試行は制度や方法をためしに実施することで、食べ物を味見させる試食とは別物なので合わない。"}, {"text": "次の試行に勝って、決勝に進むことができた。", "explanation": "ここは〈試合〉の意味。試行は実施して結果を見ることで、勝ち負けを競う試合の意味では使わないので合わない。"}, {"text": "この服を試行してから買うか決めた。", "explanation": "ここは〈試着〉の意味。試行は方法をためすことで、衣服を身につけて合うか確かめる試着の意味にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52548, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい料金体系を一部の店で試行するにした。", "corrected_sentence": "新しい料金体系を一部の店で試行することにした。", "error_description": "正しくは「試行することにした」。動詞を名詞化する「こと」が抜けて「するにした」になっている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52548, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は新しいバスの運行を来月から試行した予定だ。", "corrected_sentence": "市は新しいバスの運行を来月から試行する予定だ。", "error_description": "正しくは「試行する予定だ」。未来の予定を表すので辞書形を使う。「試行した」は過去形で、予定の文に合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
