INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52549, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "きれいじゃないけど、がんばっていること。", "primary_collocate": null, "pronunciation": "どろくさい", "ipa": "doɾokɯsai", "syllable_count": 5, "sentences": [{"text": "かっこよくなくても、泥臭く走る彼を私は応援したい。", "target_word": "泥臭く", "complexity_tier": "T3", "furigana": "かっこよくなくても、泥臭[どろくさ]く走[はし]る彼[かれ]を私[わたし]は応援[おうえん]したい。", "sentence_source": "generated"}, {"text": "姉は泥臭い勉強を続けて、試験に合格した。", "target_word": "泥臭い", "complexity_tier": "T3", "furigana": "姉[あね]は泥臭[どろくさ]い勉強[べんきょう]を続[つづ]けて、試験[しけん]に合格[ごうかく]した。", "sentence_source": "generated"}, {"text": "サッカーでは、きれいなシュートより泥臭いゴールのほうが大切なときもある。", "target_word": "泥臭い", "complexity_tier": "T3", "furigana": "サッカーでは、きれいなシュートより泥臭[どろくさ]いゴールのほうが大切[たいせつ]なときもある。", "sentence_source": "generated"}, {"text": "泥臭い練習ばかりで疲れたが、その分うまくなった。", "target_word": "泥臭い", "complexity_tier": "T3", "furigana": "泥臭[どろくさ]い練習[れんしゅう]ばかりで疲[つか]れたが、その分[ぶん]うまくなった。", "sentence_source": "generated"}, {"text": "父の仕事は地味で泥臭いが、家族のために毎日働いている。", "target_word": "泥臭い", "complexity_tier": "T3", "furigana": "父[ちち]の仕事[しごと]は地味[じみ]で泥臭[どろくさ]いが、家族[かぞく]のために毎日[まいにち]働[はたら]いている。", "sentence_source": "generated"}, {"text": "先生は「泥臭くてもいいから、最後までやってみなさい」と言った。", "target_word": "泥臭くても", "complexity_tier": "T3", "furigana": "先生[せんせい]は「泥臭[どろくさ]くてもいいから、最後[さいご]までやってみなさい」と言[い]った。", "sentence_source": "generated"}, {"text": "弟は泥臭い方法で、難しい漢字を何度も書いて覚えた。", "target_word": "泥臭い", "complexity_tier": "T3", "furigana": "弟[おとうと]は泥臭[どろくさ]い方法[ほうほう]で、難[むずか]しい漢字[かんじ]を何度[なんど]も書[か]いて覚[おぼ]えた。", "sentence_source": "generated"}, {"text": "このチームは強くないが、泥臭い試合をして最後まであきらめない。", "target_word": "泥臭い", "complexity_tier": "T3", "furigana": "このチームは強[つよ]くないが、泥臭[どろくさ]い試合[しあい]をして最後[さいご]まであきらめない。", "sentence_source": "generated"}, {"text": "社長は泥臭い人で、朝早くから現場に立って社員と一緒に働く。", "target_word": "泥臭い", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は泥臭[どろくさ]い人[ひと]で、朝早[あさはや]くから現場[げんば]に立[た]って社員[しゃいん]と一緒[いっしょ]に働[はたら]く。", "sentence_source": "generated"}, {"text": "彼は話し方が上手ではないが、泥臭い誠実さで客の心をつかんだ。", "target_word": "泥臭い", "complexity_tier": "T3", "furigana": "彼[かれ]は話[はな]し方[かた]が上手[じょうず]ではないが、泥臭[どろくさ]い誠実[せいじつ]さで客[きゃく]の心[こころ]をつかんだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "泥臭い", "label": "終止形・連体形"}, {"form": "泥臭く", "label": "連用形"}, {"form": "泥臭かった", "label": "過去形"}, {"form": "泥臭くない", "label": "否定形"}, {"form": "泥臭ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "かっこよくはないが一生懸命がんばる様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfd20d42-23ee-4ee7-8eb0-26fc22ef5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52549, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "泥臭く", "is_correct": true, "explanation": "「泥臭く走る彼」の「泥臭く」。連用形で動詞「走る」を修飾する形になる。"}, {"text": "泥臭い", "is_correct": false, "explanation": "連体形の「泥臭い」は動詞「走る」を修飾できず、「泥臭い走る彼」は文として成り立たない。"}, {"text": "泥臭くない", "is_correct": false, "explanation": "否定形の「泥臭くない」は「走る」を修飾する形として不自然で、文脈の意味も逆になる。"}, {"text": "泥臭かった", "is_correct": false, "explanation": "過去形の「泥臭かった」は動詞「走る」を修飾できず、現在の動作の文に合わない。"}], "explanations": {"泥臭く": "「泥臭く走る彼」の「泥臭く」。連用形で動詞「走る」を修飾する形になる。", "泥臭い": "連体形の「泥臭い」は動詞「走る」を修飾できず、「泥臭い走る彼」は文として成り立たない。", "泥臭くない": "否定形の「泥臭くない」は「走る」を修飾する形として不自然で、文脈の意味も逆になる。", "泥臭かった": "過去形の「泥臭かった」は動詞「走る」を修飾できず、現在の動作の文に合わない。"}, "sentence_index": 0, "correct_answer": "泥臭く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は洗練された泥臭い手つきで、客を驚かせた。", "explanation": "ここは〈洗練〉の意味で置き換えた形。泥臭いは洗練されていない様子を表すので、洗練を表す語と並ぶと矛盾するので誤り。"}, {"text": "彼女は泥臭い優雅さで、舞台を盛り上げた。", "explanation": "ここは〈優雅〉の意味で置き換えた形。泥臭いは洗練されていない様子で、優雅さとは矛盾するので誤り。"}, {"text": "彼は泥臭い華麗さで、観客を一瞬で黙らせた。", "explanation": "ここは〈華麗〉の意味で置き換えた形。泥臭いは華やかさとは逆の様子で、華麗な印象とは両立しないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52549, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "泥臭い", "is_correct": true, "explanation": "「弟は泥臭い方法で」の連体形。後ろの名詞「方法」を修飾している。"}, {"text": "泥臭く", "is_correct": false, "explanation": "連用形の「泥臭く」は名詞を直接修飾できず、「弟は泥臭く方法で」は成り立たない。"}, {"text": "泥臭くて", "is_correct": false, "explanation": "て形の「泥臭くて」は名詞を修飾できず、「方法で」にはつながらない。"}, {"text": "泥臭くても", "is_correct": false, "explanation": "逆接の「泥臭くても」は名詞を修飾できず、「方法で」にはつながらない。"}], "explanations": {"泥臭い": "「弟は泥臭い方法で」の連体形。後ろの名詞「方法」を修飾している。", "泥臭く": "連用形の「泥臭く」は名詞を直接修飾できず、「弟は泥臭く方法で」は成り立たない。", "泥臭くて": "て形の「泥臭くて」は名詞を修飾できず、「方法で」にはつながらない。", "泥臭くても": "逆接の「泥臭くても」は名詞を修飾できず、「方法で」にはつながらない。"}, "sentence_index": 6, "correct_answer": "泥臭い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は軽快な泥臭い話し方で、場を盛り上げた。", "explanation": "ここは〈軽快〉の意味で置き換えた形。泥臭いは洗練されていない様子で、軽快な印象とは噛み合わないので誤り。"}, {"text": "彼は端正な泥臭い表情で、客の心をつかんだ。", "explanation": "ここは〈端正〉の意味で置き換えた形。泥臭いは洗練されていない様子で、整って清らかな端正さとは意味が合わないので誤り。"}, {"text": "繊細な泥臭い手つきで、客の信頼を得た。", "explanation": "ここは〈繊細〉の意味で置き換えた形。泥臭いは荒削りな様子で、細やかさを表す繊細とは矛盾するので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52549, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は泥臭いで働いて、家族を支えている。", "corrected_sentence": "父は泥臭く働いて、家族を支えている。", "error_description": "正しくは「泥臭く働いて」。形容詞「泥臭い」を動詞「働く」にかけるときは連用形「泥臭く」を使い、「泥臭いで」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "泥臭い", "is_correct": true, "explanation": "「泥臭い勉強を続けて」の連体形。後ろの名詞「勉強」を修飾している。"}, {"text": "泥臭く", "is_correct": false, "explanation": "連用形の「泥臭く」は名詞を直接修飾できず、「勉強」にはつながらない。"}, {"text": "泥臭くて", "is_correct": false, "explanation": "て形の「泥臭くて」は名詞を直接修飾できず、「勉強」にはつながらない。"}, {"text": "泥臭ければ", "is_correct": false, "explanation": "仮定形の「泥臭ければ」は条件節になり、「勉強」を修飾する形として成り立たない。"}], "correct_form": "泥臭い", "base_form": "泥臭い", "form_label": "連体形", "sentence_index": 1, "explanations": {"泥臭い": "「泥臭い勉強を続けて」の連体形。後ろの名詞「勉強」を修飾している。", "泥臭く": "連用形の「泥臭く」は名詞を直接修飾できず、「勉強」にはつながらない。", "泥臭くて": "て形の「泥臭くて」は名詞を直接修飾できず、「勉強」にはつながらない。", "泥臭ければ": "仮定形の「泥臭ければ」は条件節になり、「勉強」を修飾する形として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52549, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "泥臭いな練習を続けるのは大変だ。", "corrected_sentence": "泥臭い練習を続けるのは大変だ。", "error_description": "正しくは「泥臭い練習」。い形容詞が名詞を直接修飾するときは「い」の形を使い、「泥臭いな」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "泥臭い", "is_correct": true, "explanation": "「泥臭い試合をして」の連体形。後ろの名詞「試合」を修飾している。"}, {"text": "泥臭くても", "is_correct": false, "explanation": "逆接の「泥臭くても」は名詞を修飾できず、「試合」にはつながらない。"}, {"text": "泥臭くて", "is_correct": false, "explanation": "て形の「泥臭くて」は名詞を直接修飾できず、「試合」にはつながらない。"}, {"text": "泥臭いで", "is_correct": false, "explanation": "「泥臭いで試合」は形が合わず、名詞を修飾する形として成り立たない。"}], "correct_form": "泥臭い", "base_form": "泥臭い", "form_label": "連体形", "sentence_index": 7, "explanations": {"泥臭い": "「泥臭い試合をして」の連体形。後ろの名詞「試合」を修飾している。", "泥臭くても": "逆接の「泥臭くても」は名詞を修飾できず、「試合」にはつながらない。", "泥臭くて": "て形の「泥臭くて」は名詞を直接修飾できず、「試合」にはつながらない。", "泥臭いで": "「泥臭いで試合」は形が合わず、名詞を修飾する形として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
