INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52550, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52550, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "見た目ややり方が洗練されていないが、努力や実直さが感じられる様子。", "primary_collocate": null, "pronunciation": "どろくさい", "ipa": "doɾokɯsai", "syllable_count": 5, "sentences": [{"text": "ロボット工学の深淵を志す者がまず体現すべきは、DIYの精神に根ざした泥臭い試行錯誤のプロセスに他ならない。", "target_word": "泥臭い", "complexity_tier": "T4", "furigana": "ロボット工学[こうがく]の深淵[しんえん]を志[こころざ]す者[もの]がまず体現[たいげん]すべきは、DIYの精神[せいしん]に根[ね]ざした泥臭[どろくさ]い試行錯誤[しこうさくご]のプロセスに他[ほか]ならない。", "sentence_source": "mined"}, {"text": "彼はスマートな方法を探さず、泥臭いやり方で毎日練習を続けた。", "target_word": "泥臭い", "complexity_tier": "T3", "furigana": "彼[かれ]はスマートな方法[ほうほう]を探[さが]さず、泥臭[どろくさ]いやり方[かた]で毎日[まいにち]練習[れんしゅう]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "見た目は格好悪いが、泥臭い営業が結局いちばん信頼を得た。", "target_word": "泥臭い", "complexity_tier": "T3", "furigana": "見[み]た目[め]は格好悪[かっこうわる]いが、泥臭[どろくさ]い営業[えいぎょう]が結局[けっきょく]いちばん信頼[しんらい]を得[え]た。", "sentence_source": "generated"}, {"text": "あの選手のプレーは華やかさこそないが、泥臭い守備でチームを支えている。", "target_word": "泥臭い", "complexity_tier": "T3", "furigana": "あの選手[せんしゅ]のプレーは華[はな]やかさこそないが、泥臭[どろくさ]い守備[しゅび]でチームを支[ささ]えている。", "sentence_source": "generated"}, {"text": "新製品の開発は、派手な発表の裏で泥臭い作業を重ねた結果だった。", "target_word": "泥臭い", "complexity_tier": "T3", "furigana": "新製品[しんせいひん]の開発[かいはつ]は、派手[はで]な発表[はっぴょう]の裏[うら]で泥臭[どろくさ]い作業[さぎょう]を重[かさ]ねた結果[けっか]だった。", "sentence_source": "generated"}, {"text": "理論だけでは解決しないので、現場で泥臭く資料を集めて回った。", "target_word": "泥臭く", "complexity_tier": "T3", "furigana": "理論[りろん]だけでは解決[かいけつ]しないので、現場[げんば]で泥臭[どろくさ]く資料[しりょう]を集[あつ]めて回[まわ]った。", "sentence_source": "generated"}, {"text": "洗練された新人より、泥臭くても粘り強く働く人のほうが育つと私は思う。", "target_word": "泥臭くても", "complexity_tier": "T3", "furigana": "洗練[せんれん]された新人[しんじん]より、泥臭[どろくさ]くても粘[ねば]り強[づよ]く働[はたら]く人[ひと]のほうが育[そだ]つと私[わたし]は思[おも]う。", "sentence_source": "generated"}, {"text": "泥臭い努力を笑う人もいるが、彼は気にせず走り続けた。", "target_word": "泥臭い", "complexity_tier": "T3", "furigana": "泥臭[どろくさ]い努力[どりょく]を笑[わら]う人[ひと]もいるが、彼[かれ]は気[き]にせず走[はし]り続[つづ]けた。", "sentence_source": "generated"}, {"text": "この町工場の泥臭い仕事ぶりが、世界中の企業から高く評価されている。", "target_word": "泥臭い", "complexity_tier": "T3", "furigana": "この町工場[まちこうば]の泥臭[どろくさ]い仕事[しごと]ぶりが、世界中[せかいじゅう]の企業[きぎょう]から高[たか]く評価[ひょうか]されている。", "sentence_source": "generated"}, {"text": "泥臭い方法ですが、結局は一軒ずつ頭を下げて回るしかありません。", "target_word": "泥臭い", "complexity_tier": "T3", "furigana": "泥臭[どろくさ]い方法[ほうほう]ですが、結局[けっきょく]は一軒[いっけん]ずつ頭[あたま]を下[さ]げて回[まわ]るしかありません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "泥臭い", "label": "終止形・連体形"}, {"form": "泥臭く", "label": "連用形"}, {"form": "泥臭かった", "label": "過去形"}, {"form": "泥臭くない", "label": "否定形"}, {"form": "泥臭ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "洗練されていないが努力や実直さを感じさせる様子(肯定的評価を含む)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfd20d42-23ee-4ee7-8eb0-26fc22ef5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52550, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "泥臭い", "is_correct": true, "explanation": "「根ざした泥臭い試行錯誤」の「泥臭い」。洗練されていないが実直な努力を表し、後ろの名詞を修飾する。"}, {"text": "眩しい", "is_correct": false, "explanation": "「根ざした眩しい試行錯誤」は意味が成り立たず、光の強さを表す語は努力の様子に合わない。"}, {"text": "寒い", "is_correct": false, "explanation": "「根ざした寒い試行錯誤」は意味が通らず、温度を表す語は文脈に合わない。"}, {"text": "冷たい", "is_correct": false, "explanation": "「根ざした冷たい試行錯誤」は意味が成り立たず、努力の実直さを表す語とも合わない。"}], "explanations": {"泥臭い": "「根ざした泥臭い試行錯誤」の「泥臭い」。洗練されていないが実直な努力を表し、後ろの名詞を修飾する。", "眩しい": "「根ざした眩しい試行錯誤」は意味が成り立たず、光の強さを表す語は努力の様子に合わない。", "寒い": "「根ざした寒い試行錯誤」は意味が通らず、温度を表す語は文脈に合わない。", "冷たい": "「根ざした冷たい試行錯誤」は意味が成り立たず、努力の実直さを表す語とも合わない。"}, "sentence_index": 0, "correct_answer": "泥臭い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その店は、泥臭い高級感で客を集めている。", "explanation": "ここは〈高級感〉の意味で置き換えた形。泥臭いは洗練されていない様子を表すので、高級感とは両立せず矛盾するので誤り。"}, {"text": "その店は、泥臭い上品さで客を魅了している。", "explanation": "ここは〈上品〉の意味で言い換えた形。泥臭いは洗練されていない様子で、上品さとは両立せず矛盾するので誤り。"}, {"text": "彼女は泥臭い華やかさで、舞台の主役を務めた。", "explanation": "ここは〈華やか〉の意味で言い換えた形。泥臭いは華やかさとは逆の様子を表すので、この文脈では誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52550, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "泥臭くても", "is_correct": true, "explanation": "「泥臭くても粘り強く働く人」の「泥臭くても」。逆接の条件を表し、文の論旨に合う。"}, {"text": "泥臭いで", "is_correct": false, "explanation": "「泥臭いで粘り強く」は形が合わず、後ろの動詞句とつながらない。"}, {"text": "泥臭いと", "is_correct": false, "explanation": "「泥臭いと粘り強く」は条件の形が続かず、文として成り立たない。"}, {"text": "泥臭いに", "is_correct": false, "explanation": "「泥臭いに粘り強く」は形容詞の語尾として不自然で、修飾関係が成り立たない。"}], "explanations": {"泥臭くても": "「泥臭くても粘り強く働く人」の「泥臭くても」。逆接の条件を表し、文の論旨に合う。", "泥臭いで": "「泥臭いで粘り強く」は形が合わず、後ろの動詞句とつながらない。", "泥臭いと": "「泥臭いと粘り強く」は条件の形が続かず、文として成り立たない。", "泥臭いに": "「泥臭いに粘り強く」は形容詞の語尾として不自然で、修飾関係が成り立たない。"}, "sentence_index": 6, "correct_answer": "泥臭くても"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は洗練された泥臭い所作で、取引先の信頼を得た。", "explanation": "ここは〈洗練〉の意味で置き換えた形。泥臭いは洗練されていない様子を表すので、洗練を表す語と並ぶと矛盾する。"}, {"text": "優雅な泥臭い所作で、一軒ずつ頭を下げて回った。", "explanation": "ここは〈優雅〉の意味で置き換えた形。泥臭いは洗練されていない様子で、優雅さとは両立しないので誤り。"}, {"text": "瀟洒な泥臭い内装のカフェで、常連客が増えた。", "explanation": "ここは〈瀟洒〉の意味で置き換えた形。泥臭いは洗練されていない様子を表すので、しゃれて垢抜けた瀟洒とは両立せず矛盾するので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52550, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は近道を探さず、泥臭いで練習を続けた。", "corrected_sentence": "彼は近道を探さず、泥臭く練習を続けた。", "error_description": "正しくは「泥臭く」。形容詞「泥臭い」を動詞「練習を続けた」にかけるときは連用形「泥臭く」を使い、「泥臭いで」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "泥臭い", "is_correct": true, "explanation": "「泥臭いやり方で」の連体形。後ろの名詞「やり方」を修飾している。"}, {"text": "泥臭く", "is_correct": false, "explanation": "連用形の「泥臭く」は名詞を直接修飾できず、「やり方」にはつながらない。"}, {"text": "泥臭くて", "is_correct": false, "explanation": "て形の「泥臭くて」は名詞を直接修飾できず、「やり方」にはつながらない。"}, {"text": "泥臭ければ", "is_correct": false, "explanation": "仮定形の「泥臭ければ」は条件節になり、「やり方」を修飾する形として成り立たない。"}], "correct_form": "泥臭い", "base_form": "泥臭い", "form_label": "連体形", "sentence_index": 1, "explanations": {"泥臭い": "「泥臭いやり方で」の連体形。後ろの名詞「やり方」を修飾している。", "泥臭く": "連用形の「泥臭く」は名詞を直接修飾できず、「やり方」にはつながらない。", "泥臭くて": "て形の「泥臭くて」は名詞を直接修飾できず、「やり方」にはつながらない。", "泥臭ければ": "仮定形の「泥臭ければ」は条件節になり、「やり方」を修飾する形として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52550, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "泥臭くでも、最後までやり抜くことが大切だ。", "corrected_sentence": "泥臭くても、最後までやり抜くことが大切だ。", "error_description": "正しくは「泥臭くても」。逆接の「ても」が正しく、「でも」では連なりが不自然で誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "泥臭い", "is_correct": true, "explanation": "「泥臭い努力を笑う」の連体形。後ろの名詞「努力」を修飾している。"}, {"text": "泥臭くても", "is_correct": false, "explanation": "逆接の「泥臭くても」は名詞を修飾できず、「努力」にはつながらない。"}, {"text": "泥臭くて", "is_correct": false, "explanation": "て形の「泥臭くて」は名詞を直接修飾できず、「努力」にはつながらない。"}, {"text": "泥臭いで", "is_correct": false, "explanation": "「泥臭いで努力」は形が合わず、名詞を修飾する形として成り立たない。"}], "correct_form": "泥臭い", "base_form": "泥臭い", "form_label": "連体形", "sentence_index": 7, "explanations": {"泥臭い": "「泥臭い努力を笑う」の連体形。後ろの名詞「努力」を修飾している。", "泥臭くても": "逆接の「泥臭くても」は名詞を修飾できず、「努力」にはつながらない。", "泥臭くて": "て形の「泥臭くて」は名詞を直接修飾できず、「努力」にはつながらない。", "泥臭いで": "「泥臭いで努力」は形が合わず、名詞を修飾する形として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52551, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52551, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「錯誤を防ぐ」で、防ぐ対象を示す正しい助詞。"}, {"text": "で", "is_correct": false, "explanation": "「錯誤で防ぐ」は手段の意味になり、防ぐ対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「錯誤と防ぐ」は相手を表すため、防ぐ対象としては不自然。"}, {"text": "より", "is_correct": false, "explanation": "「錯誤より防ぐ」は比較の助詞で、防ぐ対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「錯誤を防ぐ」で、防ぐ対象を示す正しい助詞。", "で": "「錯誤で防ぐ」は手段の意味になり、防ぐ対象を示せない。", "と": "「錯誤と防ぐ」は相手を表すため、防ぐ対象としては不自然。", "より": "「錯誤より防ぐ」は比較の助詞で、防ぐ対象を示せない。"}, "error_tags": {"で": "手段", "と": "相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52551, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "まちがいのこと", "primary_collocate": null, "pronunciation": "さくご", "ipa": "sakɯɡo", "syllable_count": 3, "sentences": [{"text": "地図の見方に錯誤があり、私たちは違う駅で降りてしまった。", "target_word": "錯誤", "complexity_tier": "T3", "furigana": "地図[ちず]の見方[みかた]に錯誤[さくご]があり、私[わたし]たちは違[ちが]う駅[えき]で降[お]りてしまった。", "sentence_source": "generated"}, {"text": "先生は答案を見直して、採点の錯誤を正した。", "target_word": "錯誤", "complexity_tier": "T3", "furigana": "先生[せんせい]は答案[とうあん]を見直[みなお]して、採点[さいてん]の錯誤[さくご]を正[ただ]した。", "sentence_source": "generated"}, {"text": "値段の錯誤に気づいた店員が、すぐにお客さんに謝った。", "target_word": "錯誤", "complexity_tier": "T3", "furigana": "値段[ねだん]の錯誤[さくご]に気[き]づいた店員[てんいん]が、すぐにお客[きゃく]さんに謝[あやま]った。", "sentence_source": "generated"}, {"text": "私は数字を写し間違えたが、その錯誤はすぐに見つかった。", "target_word": "錯誤", "complexity_tier": "T3", "furigana": "私[わたし]は数字[すうじ]を写[うつ]し間違[まちが]えたが、その錯誤[さくご]はすぐに見[み]つかった。", "sentence_source": "generated"}, {"text": "時刻表に錯誤があり、私は約束の一時間前に着いてしまった。", "target_word": "錯誤", "complexity_tier": "T3", "furigana": "時刻表[じこくひょう]に錯誤[さくご]があり、私[わたし]は約束[やくそく]の一時間前[いちじかんまえ]に着[つ]いてしまった。", "sentence_source": "generated"}, {"text": "自分は正しいと思っていたが、それは大きな錯誤だった。", "target_word": "錯誤", "complexity_tier": "T3", "furigana": "自分[じぶん]は正[ただ]しいと思[おも]っていたが、それは大[おお]きな錯誤[さくご]だった。", "sentence_source": "generated"}, {"text": "連絡の錯誤があって、二人は別の場所で待っていた。", "target_word": "錯誤", "complexity_tier": "T3", "furigana": "連絡[れんらく]の錯誤[さくご]があって、二人[ふたり]は別[べつ]の場所[ばしょ]で待[ま]っていた。", "sentence_source": "generated"}, {"text": "注文の錯誤を防ぐために、店では必ず内容を読み上げる。", "target_word": "錯誤", "complexity_tier": "T3", "furigana": "注文[ちゅうもん]の錯誤[さくご]を防[ふせ]ぐために、店[みせ]では必[かなら]ず内容[ないよう]を読[よ]み上[あ]げる。", "sentence_source": "generated"}, {"text": "錯誤に気づいた彼は、すぐに最初からやり直した。", "target_word": "錯誤", "complexity_tier": "T3", "furigana": "錯誤[さくご]に気[き]づいた彼[かれ]は、すぐに最初[さいしょ]からやり直[なお]した。", "sentence_source": "generated"}, {"text": "説明書の錯誤のせいで、組み立てがうまくいかなかった。", "target_word": "錯誤", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]の錯誤[さくご]のせいで、組[く]み立[た]てがうまくいかなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "錯誤", "label": "基本形"}, {"form": "錯誤の", "label": "連体(の)形"}], "register": "formal", "sense_fingerprint": "見まちがい・やりまちがいなどの間違い(やや硬い語)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfd20d42-23ee-4ee7-8eb0-26fc22ef5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52551, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "錯誤", "is_correct": true, "explanation": "「地図の見方に錯誤」で、見方の誤りが原因だと示せる。"}, {"text": "勝利", "is_correct": false, "explanation": "「地図の見方に勝利」は意味が通らず、原因を表せない。"}, {"text": "比率", "is_correct": false, "explanation": "「地図の見方に比率」は文脈に合わず、駅で降りた原因にならない。"}, {"text": "熱意", "is_correct": false, "explanation": "「地図の見方に熱意」は原因として不自然で、文脈に合わない。"}], "explanations": {"錯誤": "「地図の見方に錯誤」で、見方の誤りが原因だと示せる。", "勝利": "「地図の見方に勝利」は意味が通らず、原因を表せない。", "比率": "「地図の見方に比率」は文脈に合わず、駅で降りた原因にならない。", "熱意": "「地図の見方に熱意」は原因として不自然で、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "錯誤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕暮れの道で、ゆらぐ草が人影に見えたのは、目の錯誤だった。", "explanation": "ここは〈錯覚〉の意味。錯誤は判断や事実の思い違いを指し、見え方の錯覚には使わないので合わない。"}, {"text": "寝不足で錯誤を起こし、会議で突然大声を出した。", "explanation": "ここは〈錯乱〉の意味。錯誤は思い違いで、精神の混乱状態には使わないので合わない。"}, {"text": "古いパソコンの錯誤のせいで、画面が真っ暗になった。", "explanation": "ここは〈故障〉の意味。錯誤は判断や事実の思い違いで、機械の不具合には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52551, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "錯誤", "is_correct": true, "explanation": "「連絡の錯誤」で、伝達の食い違いが原因だと示せる。"}, {"text": "余韻", "is_correct": false, "explanation": "「連絡の余韻」は意味が通らず、待ち合わせの原因を表せない。"}, {"text": "感謝", "is_correct": false, "explanation": "「連絡の感謝」は文脈に合わず、待っていた原因にならない。"}, {"text": "誇り", "is_correct": false, "explanation": "「連絡の誇り」は不自然で、別の場所で待った原因を表せない。"}], "explanations": {"錯誤": "「連絡の錯誤」で、伝達の食い違いが原因だと示せる。", "余韻": "「連絡の余韻」は意味が通らず、待ち合わせの原因を表せない。", "感謝": "「連絡の感謝」は文脈に合わず、待っていた原因にならない。", "誇り": "「連絡の誇り」は不自然で、別の場所で待った原因を表せない。"}, "sentence_index": 6, "correct_answer": "錯誤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このスープは、錯誤が控えめで体にやさしい。", "explanation": "ここは〈味〉の意味。錯誤は間違いを指し、料理の味の強さには使わないので合わない。"}, {"text": "明日の錯誤は雨になりそうだ。", "explanation": "ここは〈天気〉の意味。錯誤は間違いを指し、空模様には使わないので合わない。"}, {"text": "夕焼けの空は、一面の錯誤に染まっていた。", "explanation": "ここは〈色〉の意味。錯誤は間違いを指し、空の色合いには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52551, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "見積もりの錯誤を気づいて、すぐに直した。", "corrected_sentence": "見積もりの錯誤に気づいて、すぐに直した。", "error_description": "「気づく」は「に」で対象を示すため、「錯誤を」は誤り。正しくは「錯誤に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52551, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "連絡の錯誤が生じるして、二人は別の場所で待っていた。", "corrected_sentence": "連絡の錯誤が生じて、二人は別の場所で待っていた。", "error_description": "「生じる」のテ形は「生じて」。「生じるして」は活用形が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52552, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「錯誤に気づく」で、気づく対象を示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「気づく」は「に」で対象を示すため、「錯誤を気づかず」は不自然で合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すため、気づく対象の「錯誤」には使えない。"}, {"text": "の", "is_correct": false, "explanation": "「錯誤の気づかず」では名詞を修飾する形になり、文の述語とつながらない。"}], "correct_answer": "に", "explanations": {"に": "「錯誤に気づく」で、気づく対象を示す正しい助詞。", "を": "「気づく」は「に」で対象を示すため、「錯誤を気づかず」は不自然で合わない。", "へ": "「へ」は方向を表すため、気づく対象の「錯誤」には使えない。", "の": "「錯誤の気づかず」では名詞を修飾する形になり、文の述語とつながらない。"}, "error_tags": {"を": "対象の助詞の誤り", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52552, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「錯誤があった」で、存在を表す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「錯誤をあった」は目的語を示すが、存在を表す「あった」とは結びつかず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「錯誤と」は並列や引用を表し、存在の文には合わない。"}, {"text": "より", "is_correct": false, "explanation": "「錯誤より」は比較の助詞で、存在を示す文には合わない。"}], "correct_answer": "が", "explanations": {"が": "「錯誤があった」で、存在を表す正しい助詞。", "を": "「錯誤をあった」は目的語を示すが、存在を表す「あった」とは結びつかず不自然。", "と": "「錯誤と」は並列や引用を表し、存在の文には合わない。", "より": "「錯誤より」は比較の助詞で、存在を示す文には合わない。"}, "error_tags": {"を": "目的語の誤り", "と": "並列・引用", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52552, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "間違い。正しくないこと。", "primary_collocate": null, "pronunciation": "さくご", "ipa": "sakɯɡo", "syllable_count": 3, "sentences": [{"text": "彼は原因を突き止めるため、思いつく方法を一つずつ試し、その過程で生じた錯誤から多くを学んだ。", "target_word": "錯誤", "complexity_tier": "T4", "furigana": "彼[かれ]は原因[げんいん]を突[つ]き止[と]めるため、思[おも]いつく方法[ほうほう]を一[ひと]つずつ試[ため]し、その過程[かてい]で生[しょう]じた錯誤[さくご]から多[おお]くを学[まな]んだ。", "sentence_source": "generated"}, {"text": "計算の錯誤に気づかず、報告書をそのまま提出してしまった。", "target_word": "錯誤", "complexity_tier": "T3", "furigana": "計算[けいさん]の錯誤[さくご]に気[き]づかず、報告書[ほうこくしょ]をそのまま提出[ていしゅつ]してしまった。", "sentence_source": "generated"}, {"text": "彼は自分の判断が錯誤だったと認め、全員に頭を下げた。", "target_word": "錯誤", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の判断[はんだん]が錯誤[さくご]だったと認[みと]め、全員[ぜんいん]に頭[あたま]を下[さ]げた。", "sentence_source": "generated"}, {"text": "事実の錯誤が原因で、契約が取り消されることもある。", "target_word": "錯誤", "complexity_tier": "T3", "furigana": "事実[じじつ]の錯誤[さくご]が原因[げんいん]で、契約[けいやく]が取[と]り消[け]されることもある。", "sentence_source": "generated"}, {"text": "操作の錯誤で、大切なデータが消えてしまった。", "target_word": "錯誤", "complexity_tier": "T3", "furigana": "操作[そうさ]の錯誤[さくご]で、大切[たいせつ]なデータが消[き]えてしまった。", "sentence_source": "generated"}, {"text": "記憶の錯誤かもしれないので、写真で日付を確かめよう。", "target_word": "錯誤", "complexity_tier": "T3", "furigana": "記憶[きおく]の錯誤[さくご]かもしれないので、写真[しゃしん]で日付[ひづけ]を確[たし]かめよう。", "sentence_source": "generated"}, {"text": "双方の錯誤から、会議の時間が食い違ってしまった。", "target_word": "錯誤", "complexity_tier": "T3", "furigana": "双方[そうほう]の錯誤[さくご]から、会議[かいぎ]の時間[じかん]が食[く]い違[ちが]ってしまった。", "sentence_source": "generated"}, {"text": "新聞は、事実関係に錯誤があった記事について謝罪し、翌日の紙面で訂正した。", "target_word": "錯誤", "complexity_tier": "T3", "furigana": "新聞[しんぶん]は、事実関係[じじつかんけい]に錯誤[さくご]があった記事[きじ]について謝罪[しゃざい]し、翌日[よくじつ]の紙面[しめん]で訂正[ていせい]した。", "sentence_source": "generated"}, {"text": "その理論は一見正しそうだが、根本に大きな錯誤がある。", "target_word": "錯誤", "complexity_tier": "T3", "furigana": "その理論[りろん]は一見[いっけん]正[ただ]しそうだが、根本[こんぽん]に大[おお]きな錯誤[さくご]がある。", "sentence_source": "generated"}, {"text": "小さな錯誤が重なって、工事の完成が三か月も遅れた。", "target_word": "錯誤", "complexity_tier": "T3", "furigana": "小[ちい]さな錯誤[さくご]が重[かさ]なって、工事[こうじ]の完成[かんせい]が三[さん]か月[げつ]も遅[おく]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "錯誤", "label": "基本形"}, {"form": "錯誤の", "label": "連体(の)形"}], "register": "formal", "sense_fingerprint": "事実や判断などの誤り・思い違い(やや硬い語)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfd20d42-23ee-4ee7-8eb0-26fc22ef5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52552, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "錯誤", "is_correct": true, "explanation": "「過程で生じた錯誤」で、思い違いや間違いを表す語として文脈に合う。"}, {"text": "郵便", "is_correct": false, "explanation": "「過程で生じた郵便」は意味をなさず、学びの原因を表せない。"}, {"text": "切手", "is_correct": false, "explanation": "「過程で生じた切手」は不自然で、学びの原因にならない。"}, {"text": "比率", "is_correct": false, "explanation": "「過程で生じた比率」は文脈に合わず、学びの原因を表さない。"}], "explanations": {"錯誤": "「過程で生じた錯誤」で、思い違いや間違いを表す語として文脈に合う。", "郵便": "「過程で生じた郵便」は意味をなさず、学びの原因を表せない。", "切手": "「過程で生じた切手」は不自然で、学びの原因にならない。", "比率": "「過程で生じた比率」は文脈に合わず、学びの原因を表さない。"}, "sentence_index": 0, "correct_answer": "錯誤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "暗い道で木が人に見えたのは、目の錯誤だった。", "explanation": "ここは〈錯覚〉の意味。錯誤は判断や事実の思い違いを指し、目に映る見え方の錯覚には使わないので合わない。"}, {"text": "事故のショックで錯誤を起こし、大声で叫んだ。", "explanation": "ここは〈錯乱〉の意味。錯誤は思い違いを指し、精神の混乱状態には使わないので合わない。"}, {"text": "古い冷蔵庫の錯誤のせいで、食品が傷んでしまった。", "explanation": "ここは〈故障〉の意味。錯誤は判断や事実の思い違いで、機械の不具合には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52552, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "錯誤", "is_correct": true, "explanation": "「双方の錯誤から」で、お互いの思い違いが原因だと示せる。"}, {"text": "継続", "is_correct": false, "explanation": "「双方の継続から」では原因として意味が通らない。"}, {"text": "成果", "is_correct": false, "explanation": "「双方の成果から食い違った」は文脈に合わず、原因を表せない。"}, {"text": "誠意", "is_correct": false, "explanation": "「双方の誠意から食い違った」は原因として不自然で、文脈に合わない。"}], "explanations": {"錯誤": "「双方の錯誤から」で、お互いの思い違いが原因だと示せる。", "継続": "「双方の継続から」では原因として意味が通らない。", "成果": "「双方の成果から食い違った」は文脈に合わず、原因を表せない。", "誠意": "「双方の誠意から食い違った」は原因として不自然で、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "錯誤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今日は体の錯誤が続いていて、思うように走れなかった。", "explanation": "ここは〈不調〉の意味。錯誤は判断や事実の思い違いを指し、体調の悪さには使わないので合わない。"}, {"text": "彼の試みは結局錯誤に終わった。", "explanation": "ここは〈失敗〉の意味。錯誤は思い違いを指し、試みがうまくいかなかったことには使わないので合わない。"}, {"text": "この紅茶は、ほのかな錯誤が特徴だ。", "explanation": "ここは〈香り〉の意味。錯誤は間違いを指し、飲み物の香りには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52552, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は前日の計算で錯誤を気づき、すぐに修正した。", "corrected_sentence": "彼は前日の計算で錯誤に気づき、すぐに修正した。", "error_description": "「気づく」は「に」で対象を示すため、「錯誤を」は誤り。正しくは「錯誤に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52552, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "報告書の錯誤が見つかれて、修正に三日かかった。", "corrected_sentence": "報告書の錯誤が見つかって、修正に三日かかった。", "error_description": "「見つかる」のテ形は「見つかって」。「見つかれて」は活用形が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
