INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52553, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「器官といわれている」で、引用の「と」として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「器官を言われている」では、対象の関係が成立せず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「器官に言われている」は相手を表すが、言われる内容の表現としては合わない。"}, {"text": "が", "is_correct": false, "explanation": "「器官が言われている」では器官が主語になり、文の意味が通らない。"}], "correct_answer": "と", "explanations": {"と": "「器官といわれている」で、引用の「と」として正しい。", "を": "「器官を言われている」では、対象の関係が成立せず不自然。", "に": "「器官に言われている」は相手を表すが、言われる内容の表現としては合わない。", "が": "「器官が言われている」では器官が主語になり、文の意味が通らない。"}, "error_tags": {"を": "目的語", "に": "相手", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52553, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "体の中で、食べ物を消化したり、血液を動かしたりする、特別なはたらきをする部分のことです。", "primary_collocate": null, "pronunciation": "きかん", "ipa": "kikaɴ", "syllable_count": 3, "sentences": [{"text": "肝臓は体の中で毒を分解する器官だ。", "target_word": "器官", "complexity_tier": "T3", "furigana": "肝臓[かんぞう]は体[からだ]の中[なか]で毒[どく]を分解[ぶんかい]する器官[きかん]だ。", "sentence_source": "generated"}, {"text": "先生は、目と耳がどんな器官なのかを図で説明した。", "target_word": "器官", "complexity_tier": "T3", "furigana": "先生[せんせい]は、目[め]と耳[みみ]がどんな器官[きかん]なのかを図[ず]で説明[せつめい]した。", "sentence_source": "generated"}, {"text": "腸は栄養を取り入れる大事な器官です。", "target_word": "器官", "complexity_tier": "T3", "furigana": "腸[ちょう]は栄養[えいよう]を取[と]り入[い]れる大事[だいじ]な器官[きかん]です。", "sentence_source": "generated"}, {"text": "心臓という器官が止まると、血液が体を回らなくなる。", "target_word": "器官", "complexity_tier": "T3", "furigana": "心臓[しんぞう]という器官[きかん]が止[と]まると、血液[けつえき]が体[からだ]を回[まわ]らなくなる。", "sentence_source": "generated"}, {"text": "たばこは、肺などの器官に悪い影響を与える。", "target_word": "器官", "complexity_tier": "T3", "furigana": "たばこは、肺[はい]などの器官[きかん]に悪[わる]い影響[えいきょう]を与[あた]える。", "sentence_source": "generated"}, {"text": "生き物の体では、どの器官も助け合って働いている。", "target_word": "器官", "complexity_tier": "T3", "furigana": "生[い]き物[もの]の体[からだ]では、どの器官[きかん]も助[たす]け合[あ]って働[はたら]いている。", "sentence_source": "generated"}, {"text": "病院で検査を受けて、体のどの器官にも問題がないとわかった。", "target_word": "器官", "complexity_tier": "T3", "furigana": "病院[びょういん]で検査[けんさ]を受[う]けて、体[からだ]のどの器官[きかん]にも問題[もんだい]がないとわかった。", "sentence_source": "generated"}, {"text": "皮膚は、体を守る一番大きな器官といわれている。", "target_word": "器官", "complexity_tier": "T3", "furigana": "皮膚[ひふ]は、体[からだ]を守[まも]る一番[いちばん]大[おお]きな器官[きかん]といわれている。", "sentence_source": "generated"}, {"text": "魚はえらという器官を使って、水の中で息をする。", "target_word": "器官", "complexity_tier": "T3", "furigana": "魚[さかな]はえらという器官[きかん]を使[つか]って、水[みず]の中[なか]で息[いき]をする。", "sentence_source": "generated"}, {"text": "弟は理科の宿題で、人の器官の名前を全部覚えた。", "target_word": "器官", "complexity_tier": "T3", "furigana": "弟[おとうと]は理科[りか]の宿題[しゅくだい]で、人[ひと]の器官[きかん]の名前[なまえ]を全部[ぜんぶ]覚[おぼ]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "器官", "label": "基本形"}, {"form": "器官の", "label": "連体(の)形"}], "register": "neutral", "sense_fingerprint": "体の中で消化や血液の循環など特別な働きをする部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfd20d42-23ee-4ee7-8eb0-26fc22ef5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52553, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "器官", "is_correct": true, "explanation": "「毒を分解する器官」で、体の働きを担う部分を示す。"}, {"text": "窓", "is_correct": false, "explanation": "「毒を分解する窓」は文脈に合わず、体の働きを表せない。"}, {"text": "切手", "is_correct": false, "explanation": "「毒を分解する切手」は意味をなさず、肝臓の説明にならない。"}, {"text": "郵便", "is_correct": false, "explanation": "「毒を分解する郵便」は文脈に合わず、不自然。"}], "explanations": {"器官": "「毒を分解する器官」で、体の働きを担う部分を示す。", "窓": "「毒を分解する窓」は文脈に合わず、体の働きを表せない。", "切手": "「毒を分解する切手」は意味をなさず、肝臓の説明にならない。", "郵便": "「毒を分解する郵便」は文脈に合わず、不自然。"}, "sentence_index": 0, "correct_answer": "器官"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この工場には、金属を磨く器官が三十台ある。", "explanation": "ここは〈装置〉の意味。器官は生き物の体の部分で、工場の機械には使わないので合わない。"}, {"text": "あの器官は、世界中に支店を持つ大企業だ。", "explanation": "ここは〈企業〉の意味。器官は生き物の体の部分で、会社には使わないので合わない。"}, {"text": "この町の器官には、図書館と体育館がそろっている。", "explanation": "ここは〈施設〉の意味。器官は体の部分で、公共施設には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52553, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "器官", "is_correct": true, "explanation": "「どの器官にも」で、体の部位を指す語として文脈に合う。"}, {"text": "食器", "is_correct": false, "explanation": "「どの食器にも問題がない」は体の検査の文脈に合わない。"}, {"text": "時計", "is_correct": false, "explanation": "「どの時計にも問題がない」は体の検査には合わず、不自然。"}, {"text": "切符", "is_correct": false, "explanation": "「どの切符にも」は体の検査の文脈に合わない。"}], "explanations": {"器官": "「どの器官にも」で、体の部位を指す語として文脈に合う。", "食器": "「どの食器にも問題がない」は体の検査の文脈に合わない。", "時計": "「どの時計にも問題がない」は体の検査には合わず、不自然。", "切符": "「どの切符にも」は体の検査の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "器官"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "料理人は、切れ味の良い器官を選んで包丁を研いだ。", "explanation": "ここは〈道具〉の意味。器官は体の部分で、包丁など道具には使わないので合わない。"}, {"text": "美術館には、有名な画家の器官がたくさん並んでいる。", "explanation": "ここは〈作品〉の意味。器官は体の部分で、絵画には使わないので合わない。"}, {"text": "春の器官が、ようやく訪れた。", "explanation": "ここは〈季節〉の意味。器官は生き物の体の部分で、時の流れには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52553, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "そのクラゲは、触手という器官を獲物を捕まえる。", "corrected_sentence": "そのクラゲは、触手という器官で獲物を捕まえる。", "error_description": "「捕まえる」の手段を表す「で」を使う。「器官を」は誤り。正しくは「器官で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52553, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "腎臓は血液をろ過する器官を、体にとって欠かせない。", "corrected_sentence": "腎臓は血液をろ過する器官で、体にとって欠かせない。", "error_description": "「器官」に続く断定は「で」。「器官を」は誤り。正しくは「器官で」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
