INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52554, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生物の体の中で、特定の機能を持つ部分。たとえば、心臓や胃など。", "primary_collocate": null, "pronunciation": "きかん", "ipa": "kikaɴ", "syllable_count": 3, "sentences": [{"text": "耳は音を聞き取る器官で、頭の左右にある。", "target_word": "器官", "complexity_tier": "T3", "furigana": "耳[みみ]は音[おと]を聞[き]き取[と]る器官[きかん]で、頭[あたま]の左右[さゆう]にある。", "sentence_source": "generated"}, {"text": "心臓は血液を全身に送る、大切な器官である。", "target_word": "器官", "complexity_tier": "T3", "furigana": "心臓[しんぞう]は血液[けつえき]を全身[ぜんしん]に送[おく]る、大切[たいせつ]な器官[きかん]である。", "sentence_source": "generated"}, {"text": "肺は呼吸をするための器官で、胸の中にある。", "target_word": "器官", "complexity_tier": "T3", "furigana": "肺[はい]は呼吸[こきゅう]をするための器官[きかん]で、胸[むね]の中[なか]にある。", "sentence_source": "generated"}, {"text": "胃は食べ物を消化する器官なので、食べすぎると疲れてしまう。", "target_word": "器官", "complexity_tier": "T3", "furigana": "胃[い]は食[た]べ物[もの]を消化[しょうか]する器官[きかん]なので、食[た]べすぎると疲[つか]れてしまう。", "sentence_source": "generated"}, {"text": "医者は、手術で病気になった器官の一部を取り除いた。", "target_word": "器官", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、手術[しゅじゅつ]で病気[びょうき]になった器官[きかん]の一部[いちぶ]を取[と]り除[のぞ]いた。", "sentence_source": "generated"}, {"text": "人間の体には、それぞれ違う働きをする器官がたくさんある。", "target_word": "器官", "complexity_tier": "T3", "furigana": "人間[にんげん]の体[からだ]には、それぞれ違[ちが]う働[はたら]きをする器官[きかん]がたくさんある。", "sentence_source": "generated"}, {"text": "腎臓は血液をきれいにする器官として、毎日休まず働いている。", "target_word": "器官", "complexity_tier": "T3", "furigana": "腎臓[じんぞう]は血液[けつえき]をきれいにする器官[きかん]として、毎日[まいにち]休[やす]まず働[はたら]いている。", "sentence_source": "generated"}, {"text": "この動物は、暗い海の中でも光を感じられる特別な器官を持っている。", "target_word": "器官", "complexity_tier": "T3", "furigana": "この動物[どうぶつ]は、暗[くら]い海[うみ]の中[なか]でも光[ひかり]を感[かん]じられる特別[とくべつ]な器官[きかん]を持[も]っている。", "sentence_source": "generated"}, {"text": "授業で、植物にも根や葉といった器官があることを学んだ。", "target_word": "器官", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]で、植物[しょくぶつ]にも根[ね]や葉[は]といった器官[きかん]があることを学[まな]んだ。", "sentence_source": "generated"}, {"text": "生まれたばかりの赤ちゃんは、まだ発達していない器官が多い。", "target_word": "器官", "complexity_tier": "T3", "furigana": "生[う]まれたばかりの赤[あか]ちゃんは、まだ発達[はったつ]していない器官[きかん]が多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "器官", "label": "基本形"}, {"form": "器官の", "label": "連体(の)形"}], "register": "neutral", "sense_fingerprint": "生物の体で特定の働きをする部分(心臓・胃・肺など)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfd20d42-23ee-4ee7-8eb0-26fc22ef5ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52554, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "器官", "is_correct": true, "explanation": "「音を聞き取る器官」で、感覚を担う体の部分を示す。"}, {"text": "植物", "is_correct": false, "explanation": "「音を聞き取る植物」は意味をなさず、感覚を担う部分を表せない。"}, {"text": "郵便", "is_correct": false, "explanation": "「音を聞き取る郵便」は意味をなさず、文脈に合わない。"}, {"text": "切手", "is_correct": false, "explanation": "「音を聞き取る切手」は不自然で、体の部分を表せない。"}], "explanations": {"器官": "「音を聞き取る器官」で、感覚を担う体の部分を示す。", "植物": "「音を聞き取る植物」は意味をなさず、感覚を担う部分を表せない。", "郵便": "「音を聞き取る郵便」は意味をなさず、文脈に合わない。", "切手": "「音を聞き取る切手」は不自然で、体の部分を表せない。"}, "sentence_index": 0, "correct_answer": "器官"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "料理に使う器官を洗って、棚にしまった。", "explanation": "ここは〈器具〉の意味。器官は生き物の体の部分を指すので、料理道具には使わないので合わない。"}, {"text": "彼女は毎日、バイオリンという器官を練習している。", "explanation": "ここは〈楽器〉の意味。器官は生き物の体の部分を指すので、練習する楽器には使わないので合わない。"}, {"text": "壊れた器官を直すため、店で部品を買った。", "explanation": "ここは〈部品〉の意味。器官は生き物の体の部分で、機械の部品には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52554, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "器官", "is_correct": true, "explanation": "「器官として」で、役割を持つ体の部分を示せる。"}, {"text": "時計", "is_correct": false, "explanation": "「時計として」は血液をきれいにする役割に合わず、文脈に合わない。"}, {"text": "食器", "is_correct": false, "explanation": "「食器として」は文脈に合わず、体の働きを表さない。"}, {"text": "窓", "is_correct": false, "explanation": "「窓として」は血液をきれいにする働きに合わない。"}], "explanations": {"器官": "「器官として」で、役割を持つ体の部分を示せる。", "時計": "「時計として」は血液をきれいにする役割に合わず、文脈に合わない。", "食器": "「食器として」は文脈に合わず、体の働きを表さない。", "窓": "「窓として」は血液をきれいにする働きに合わない。"}, "sentence_index": 6, "correct_answer": "器官"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この器官では、毎日多くの患者が治療を受けている。", "explanation": "ここは〈病院〉の意味。器官は生物の体の部分で、患者が通う建物には使わないので合わない。"}, {"text": "この山からは、貴重な器官が採れる。", "explanation": "ここは〈鉱物〉の意味。器官は生き物の体の部分を指すので、山から採れる石や金属には使わないので合わない。"}, {"text": "この大学には、最新の器官がそろっている。", "explanation": "ここは〈施設〉の意味。器官は体の部分で、大学の設備には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52554, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は肺という器官を呼吸して、山の空気を楽しんだ。", "corrected_sentence": "彼は肺という器官で呼吸して、山の空気を楽しんだ。", "error_description": "「呼吸する」は手段の「で」を取るため、「器官を」は誤り。正しくは「器官で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52554, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究者は、この動物が持つ器官に詳しく調べた。", "corrected_sentence": "研究者は、この動物が持つ器官を詳しく調べた。", "error_description": "「調べる」は「を」で対象を取る。「器官に」は誤り。正しくは「器官を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecbed082-3bf2-470f-897f-d315965e7422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52555, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「小さなアクチュエーターが必要だ」の主語を示す「が」。正解。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では「アクチュエーターへ必要だ」が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」では「アクチュエーターと必要だ」が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では「アクチュエーターから必要だ」は文が通らない。"}], "correct_answer": "が", "explanations": {"が": "「小さなアクチュエーターが必要だ」の主語を示す「が」。正解。", "へ": "方向の「へ」では「アクチュエーターへ必要だ」が成り立たない。", "と": "並列の「と」では「アクチュエーターと必要だ」が成り立たない。", "から": "起点の「から」では「アクチュエーターから必要だ」は文が通らない。"}, "error_tags": {"へ": "方向の助詞", "と": "並列の助詞", "から": "起点の助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52555, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「アクチュエーターを取り替えた」の目的語を示す「を」。正解。"}, {"text": "に", "is_correct": false, "explanation": "「新しい部品に」で既に「に」が使われており、「アクチュエーターに」は二重になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では「アクチュエーターへ取り替えた」となり、取り替える対象を表せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では「アクチュエーターより取り替えた」となり、目的語の役割を果たさない。"}], "correct_answer": "を", "explanations": {"を": "「アクチュエーターを取り替えた」の目的語を示す「を」。正解。", "に": "「新しい部品に」で既に「に」が使われており、「アクチュエーターに」は二重になる。", "へ": "方向の「へ」では「アクチュエーターへ取り替えた」となり、取り替える対象を表せない。", "より": "比較の「より」では「アクチュエーターより取り替えた」となり、目的語の役割を果たさない。"}, "error_tags": {"に": "帰着・対象の助詞", "へ": "方向の助詞", "より": "比較の助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52555, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "機械の体の一部を動かすための部品です。", "primary_collocate": null, "pronunciation": "あくちゅえーたー", "ipa": "akɯt͡ɕɯeːtaː", "syllable_count": 7, "sentences": [{"text": "ロボットの腕を動かすアクチュエーターは、肘の中に入っている。", "target_word": "アクチュエーター", "complexity_tier": "T3", "furigana": "ロボットの腕[うで]を動[うご]かすアクチュエーターは、肘[ひじ]の中[なか]に入[はい]っている。", "sentence_source": "generated"}, {"text": "指を曲げるには、小さなアクチュエーターが必要だ。", "target_word": "アクチュエーター", "complexity_tier": "T3", "furigana": "指[ゆび]を曲[ま]げるには、小[ちい]さなアクチュエーターが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "アクチュエーターが壊れたので、ロボットは足を上げられなくなった。", "target_word": "アクチュエーター", "complexity_tier": "T3", "furigana": "アクチュエーターが壊[こわ]れたので、ロボットは足[あし]を上[あ]げられなくなった。", "sentence_source": "generated"}, {"text": "人の筋肉のように動くアクチュエーターを研究している。", "target_word": "アクチュエーター", "complexity_tier": "T3", "furigana": "人[ひと]の筋肉[きんにく]のように動[うご]くアクチュエーターを研究[けんきゅう]している。", "sentence_source": "generated"}, {"text": "義手の指は、アクチュエーターのおかげでなめらかに動く。", "target_word": "アクチュエーター", "complexity_tier": "T3", "furigana": "義手[ぎしゅ]の指[ゆび]は、アクチュエーターのおかげでなめらかに動[うご]く。", "sentence_source": "generated"}, {"text": "このロボットは、首に二つのアクチュエーターを使って頭を回す。", "target_word": "アクチュエーター", "complexity_tier": "T3", "furigana": "このロボットは、首[くび]に二[ふた]つのアクチュエーターを使[つか]って頭[あたま]を回[まわ]す。", "sentence_source": "generated"}, {"text": "軽いアクチュエーターを使うと、ロボットの体は軽くなる。", "target_word": "アクチュエーター", "complexity_tier": "T3", "furigana": "軽[かる]いアクチュエーターを使[つか]うと、ロボットの体[からだ]は軽[かる]くなる。", "sentence_source": "generated"}, {"text": "技術者は、ロボットの足のアクチュエーターを新しい部品に取り替えた。", "target_word": "アクチュエーター", "complexity_tier": "T3", "furigana": "技術者[ぎじゅつしゃ]は、ロボットの足[あし]のアクチュエーターを新[あたら]しい部品[ぶひん]に取[と]り替[か]えた。", "sentence_source": "generated"}, {"text": "アクチュエーターの音が静かなので、ロボットは夜でも使いやすい。", "target_word": "アクチュエーター", "complexity_tier": "T3", "furigana": "アクチュエーターの音[おと]が静[しず]かなので、ロボットは夜[よる]でも使[つか]いやすい。", "sentence_source": "generated"}, {"text": "子どもたちは、ロボットの模型でアクチュエーターの働きを学んだ。", "target_word": "アクチュエーター", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、ロボットの模型[もけい]でアクチュエーターの働[はたら]きを学[まな]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アクチュエーター", "label": "基本形"}, {"form": "アクチュエーターの", "label": "連体(の)"}, {"form": "アクチュエーターが", "label": "主格(が)"}], "register": "technical", "sense_fingerprint": "ロボットの腕・指・足など体の一部を動かす部品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b6f44e-98bc-47ea-8709-e20223619fec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52555, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アクチュエーター", "is_correct": true, "explanation": "ロボットの腕を動かす部品を表し、「腕を動かすアクチュエーター」で文が通る。"}, {"text": "画面", "is_correct": false, "explanation": "情報を表示する板で、腕を動かす部品ではない。"}, {"text": "スピーカー", "is_correct": false, "explanation": "音を出す部品で、腕を動かす役割はない。"}, {"text": "カメラ", "is_correct": false, "explanation": "映像を撮る部品で、腕を動かすことはできない。"}], "explanations": {"アクチュエーター": "ロボットの腕を動かす部品を表し、「腕を動かすアクチュエーター」で文が通る。", "画面": "情報を表示する板で、腕を動かす部品ではない。", "スピーカー": "音を出す部品で、腕を動かす役割はない。", "カメラ": "映像を撮る部品で、腕を動かすことはできない。"}, "sentence_index": 0, "correct_answer": "アクチュエーター"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "アクチュエーターが人の体温を感じ取って、ロボットに知らせる。", "explanation": "ここは〈センサー〉の意味。感じ取って知らせるのはセンサーで、アクチュエーターは体を動かす部品。"}, {"text": "信号が青になったので、アクチュエーターを強く踏んだ。", "explanation": "ここは〈アクセル〉の意味。踏むのはアクセルで、アクチュエーターは動かす部品。"}, {"text": "アクチュエーターは、指令を出してロボットの計算を担当する。", "explanation": "ここは〈制御装置〉の意味。計算と判断は制御装置の役割で、アクチュエーターは動かす部品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52555, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アクチュエーター", "is_correct": true, "explanation": "ロボットを動かす部品を表し、「軽いアクチュエーターを使うと体が軽くなる」で文が通る。"}, {"text": "信号", "is_correct": false, "explanation": "情報を伝えるもので、体を軽くする部品ではない。"}, {"text": "指令", "is_correct": false, "explanation": "命令の内容で、物として使って体を軽くするものではない。"}, {"text": "電波", "is_correct": false, "explanation": "電磁波で、体を軽くする部品にはならない。"}], "explanations": {"アクチュエーター": "ロボットを動かす部品を表し、「軽いアクチュエーターを使うと体が軽くなる」で文が通る。", "信号": "情報を伝えるもので、体を軽くする部品ではない。", "指令": "命令の内容で、物として使って体を軽くするものではない。", "電波": "電磁波で、体を軽くする部品にはならない。"}, "sentence_index": 6, "correct_answer": "アクチュエーター"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "アクチュエーターで写真を撮った。", "explanation": "ここは〈スマートフォン〉の意味。写真を撮るのは機器で、アクチュエーターは動かす部品。"}, {"text": "アクチュエーターを充電すると、ロボットは長く動く。", "explanation": "ここは〈電池〉の意味。充電して電気を蓄えるのは電池で、アクチュエーターは動かす部品。"}, {"text": "アクチュエーターで野菜を冷やした。", "explanation": "ここは〈冷蔵庫〉の意味。野菜を冷やすのは冷蔵庫で、アクチュエーターは動かす部品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52555, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このロボットの指を動かすアクチュエーターを、手のひらに入っている。", "corrected_sentence": "このロボットの指を動かすアクチュエーターは、手のひらに入っている。", "error_description": "「アクチュエーター」に続く助詞の誤り。主題の「は」が正しい。「を」は目的語を示すが、「入っている」とは続かず文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52555, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ロボットの肘をアクチュエーターは、新しく取り替えられた。", "corrected_sentence": "ロボットの肘のアクチュエーターは、新しく取り替えられた。", "error_description": "「アクチュエーター」の直前の助詞の誤り。「肘の」と名詞を続ける「の」が正しい。「を」は目的語を示すため、「肘を」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52556, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す「が」。「アクチュエーターが電気の信号を動きに変える」で正解。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」では「電気の信号を」と二重になり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では「アクチュエーターへ変える」と文が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では「アクチュエーターより電気の信号を」となり、文の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す「が」。「アクチュエーターが電気の信号を動きに変える」で正解。", "を": "目的語の「を」では「電気の信号を」と二重になり、文が成り立たない。", "へ": "方向の「へ」では「アクチュエーターへ変える」と文が通らない。", "より": "比較の「より」では「アクチュエーターより電気の信号を」となり、文の主語にならない。"}, "error_tags": {"を": "目的格の助詞", "へ": "方向の助詞", "より": "比較の助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52556, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す「が」。「アクチュエーターが使われている」で正解。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では「アクチュエーターから使われている」と文が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では「使われている」の主語にならず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「アクチュエーターの使われている」では名詞が続かず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す「が」。「アクチュエーターが使われている」で正解。", "から": "起点の「から」では「アクチュエーターから使われている」と文が通らない。", "より": "比較の「より」では「使われている」の主語にならず、文が成り立たない。", "の": "「アクチュエーターの使われている」では名詞が続かず、文が成り立たない。"}, "error_tags": {"から": "起点の助詞", "より": "比較の助詞", "の": "連体の助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52556, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "機械やロボットに指令を送り、実際に動かすための装置。モーターなどが該当する。", "primary_collocate": null, "pronunciation": "あくちゅえーたー", "ipa": "akɯt͡ɕɯeːtaː", "syllable_count": 7, "sentences": [{"text": "制御装置から指令を受けると、アクチュエーターがバルブを開く。", "target_word": "アクチュエーター", "complexity_tier": "T3", "furigana": "制御装置[せいぎょそうち]から指令[しれい]を受[う]けると、アクチュエーターがバルブを開[ひら]く。", "sentence_source": "generated"}, {"text": "工場の機械では、アクチュエーターが電気の信号を動きに変える。", "target_word": "アクチュエーター", "complexity_tier": "T3", "furigana": "工場[こうじょう]の機械[きかい]では、アクチュエーターが電気[でんき]の信号[しんごう]を動[うご]きに変[か]える。", "sentence_source": "generated"}, {"text": "モーターは、機械を動かす代表的なアクチュエーターだ。", "target_word": "アクチュエーター", "complexity_tier": "T3", "furigana": "モーターは、機械[きかい]を動[うご]かす代表的[だいひょうてき]なアクチュエーターだ。", "sentence_source": "generated"}, {"text": "コンピューターの指示は、アクチュエーターを通して機械の動きになる。", "target_word": "アクチュエーター", "complexity_tier": "T3", "furigana": "コンピューターの指示[しじ]は、アクチュエーターを通[とお]して機械[きかい]の動[うご]きになる。", "sentence_source": "generated"}, {"text": "ドローンの羽の角度は、小さなアクチュエーターで変えている。", "target_word": "アクチュエーター", "complexity_tier": "T3", "furigana": "ドローンの羽[はね]の角度[かくど]は、小[ちい]さなアクチュエーターで変[か]えている。", "sentence_source": "generated"}, {"text": "自動ドアのセンサーが人を見つけると、アクチュエーターがドアを開ける。", "target_word": "アクチュエーター", "complexity_tier": "T3", "furigana": "自動[じどう]ドアのセンサーが人[ひと]を見[み]つけると、アクチュエーターがドアを開[あ]ける。", "sentence_source": "generated"}, {"text": "空気の力で動くアクチュエーターは、工場で多く使われている。", "target_word": "アクチュエーター", "complexity_tier": "T3", "furigana": "空気[くうき]の力[ちから]で動[うご]くアクチュエーターは、工場[こうじょう]で多[おお]く使[つか]われている。", "sentence_source": "generated"}, {"text": "車のブレーキ装置にも、アクチュエーターが使われている。", "target_word": "アクチュエーター", "complexity_tier": "T3", "furigana": "車[くるま]のブレーキ装置[そうち]にも、アクチュエーターが使[つか]われている。", "sentence_source": "generated"}, {"text": "指令が届いても、アクチュエーターが故障していれば機械は動かない。", "target_word": "アクチュエーター", "complexity_tier": "T3", "furigana": "指令[しれい]が届[とど]いても、アクチュエーターが故障[こしょう]していれば機械[きかい]は動[うご]かない。", "sentence_source": "generated"}, {"text": "設計者は、機械の大きさに合うアクチュエーターを選んだ。", "target_word": "アクチュエーター", "complexity_tier": "T3", "furigana": "設計者[せっけいしゃ]は、機械[きかい]の大[おお]きさに合[あ]うアクチュエーターを選[えら]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アクチュエーター", "label": "基本形"}, {"form": "アクチュエーターの", "label": "連体(の)"}, {"form": "アクチュエーターを", "label": "目的格(を)"}], "register": "technical", "sense_fingerprint": "制御の指令を受けて機械を実際に動かす装置(モーターなど)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b6f44e-98bc-47ea-8709-e20223619fec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52556, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アクチュエーター", "is_correct": true, "explanation": "指令を受けてバルブを動かす装置を表し、「アクチュエーターがバルブを開く」で文が通る。"}, {"text": "取扱説明書", "is_correct": false, "explanation": "読むための書類で、バルブを開く装置ではない。"}, {"text": "表示画面", "is_correct": false, "explanation": "情報を映す板で、バルブを開けることはできない。"}, {"text": "配線図", "is_correct": false, "explanation": "配線を示す図で、バルブを開く働きはない。"}], "explanations": {"アクチュエーター": "指令を受けてバルブを動かす装置を表し、「アクチュエーターがバルブを開く」で文が通る。", "取扱説明書": "読むための書類で、バルブを開く装置ではない。", "表示画面": "情報を映す板で、バルブを開けることはできない。", "配線図": "配線を示す図で、バルブを開く働きはない。"}, "sentence_index": 0, "correct_answer": "アクチュエーター"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "アクチュエーターを押して、部屋の電気をつけた。", "explanation": "ここは〈スイッチ〉の意味。押して電気をつけるのはスイッチで、アクチュエーターは機械を動かす部品。"}, {"text": "アクチュエーターで音楽を流した。", "explanation": "ここは〈スピーカー〉の意味。音楽を流すのはスピーカーで、アクチュエーターは動かす装置。"}, {"text": "アクチュエーターを握って、坂道で車を止めた。", "explanation": "ここは〈サイドブレーキ〉の意味。坂道で車を止めるために握るのはサイドブレーキで、アクチュエーターは握る物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52556, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アクチュエーター", "is_correct": true, "explanation": "空気の力で動く部品を表し、「工場で多く使われている」で文が通る。"}, {"text": "絶縁体", "is_correct": false, "explanation": "電気を通さない材料で、空気の力で動く部品ではない。"}, {"text": "計算機", "is_correct": false, "explanation": "計算をする機械で、空気の力で動く部品ではない。"}, {"text": "蛍光灯", "is_correct": false, "explanation": "光源で、空気の力で動くものではない。"}], "explanations": {"アクチュエーター": "空気の力で動く部品を表し、「工場で多く使われている」で文が通る。", "絶縁体": "電気を通さない材料で、空気の力で動く部品ではない。", "計算機": "計算をする機械で、空気の力で動く部品ではない。", "蛍光灯": "光源で、空気の力で動くものではない。"}, "sentence_index": 6, "correct_answer": "アクチュエーター"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "アクチュエーターをひねって、お湯を出した。", "explanation": "ここは〈蛇口〉の意味。ひねってお湯を出すのは蛇口で、アクチュエーターは動かす装置。"}, {"text": "アクチュエーターで髪を乾かした。", "explanation": "ここは〈ドライヤー〉の意味。髪を乾かす家電で、アクチュエーターは動かす装置。"}, {"text": "アクチュエーターの画面に、機械の状態が表示される。", "explanation": "ここは〈制御盤〉の意味。状態を表示するのは制御盤で、アクチュエーターは画面を持たない部品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52556, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工場の制御盤から指令を受けると、アクチュエーターをタンクの弁を開く。", "corrected_sentence": "工場の制御盤から指令を受けると、アクチュエーターがタンクの弁を開く。", "error_description": "「アクチュエーター」に続く助詞の誤り。主語を示す「が」が正しい。「を」は目的語を示すため、後ろの「弁を」と二重になり文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52556, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "油圧で動いてアクチュエーターは、重い扉を開け閉めする。", "corrected_sentence": "油圧で動くアクチュエーターは、重い扉を開け閉めする。", "error_description": "「アクチュエーター」を修飾する動詞の形の誤り。名詞に直接かかる連体形は「動く」で、「動いて」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1f807c-199a-4fd1-ad36-06678d7bb2e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52557, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「筋肉」が「痛かった」の主語を表すので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語を示すが、「痛かった」は形容詞なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を示し、主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所を示すので、主語の位置には入らない。"}], "correct_answer": "が", "explanations": {"が": "「筋肉」が「痛かった」の主語を表すので正しい。", "を": "「を」は他動詞の目的語を示すが、「痛かった」は形容詞なので合わない。", "に": "「に」は位置や相手を示し、主語にはならない。", "で": "「で」は手段・場所を示すので、主語の位置には入らない。"}, "error_tags": {"を": "対象", "に": "位置・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52557, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「筋肉」が「疲れた」の主語を表すので正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、主語の位置には入らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示し、「疲れた」の主語にはならない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語につくが、「疲れた」は目的語を取れず非文になる。"}], "correct_answer": "が", "explanations": {"が": "「筋肉」が「疲れた」の主語を表すので正しい。", "へ": "「へ」は方向を示すので、主語の位置には入らない。", "と": "「と」は並列や相手を示し、「疲れた」の主語にはならない。", "を": "「を」は他動詞の目的語につくが、「疲れた」は目的語を取れず非文になる。"}, "error_tags": {"へ": "方向", "と": "並列・相手", "を": "対象"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52557, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "体の中で、ものを動かすときにつかう力のあるところだ。", "primary_collocate": null, "pronunciation": "きんにく", "ipa": "kiɴɲikɯ", "syllable_count": 4, "sentences": [{"text": "筋肉をつけたいので、毎晩腕立て伏せをしている。", "target_word": "筋肉", "complexity_tier": "T3", "furigana": "筋肉[きんにく]をつけたいので、毎晩[まいばん]腕立[うでた]て伏[ふ]せをしている。", "sentence_source": "generated"}, {"text": "重い荷物を運んだら、次の日に全身の筋肉が痛かった。", "target_word": "筋肉", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]を運[はこ]んだら、次[つぎ]の日[ひ]に全身[ぜんしん]の筋肉[きんにく]が痛[いた]かった。", "sentence_source": "generated"}, {"text": "兄は筋肉があるから、重い箱も楽に持てる。", "target_word": "筋肉", "complexity_tier": "T3", "furigana": "兄[あに]は筋肉[きんにく]があるから、重[おも]い箱[はこ]も楽[らく]に持[も]てる。", "sentence_source": "generated"}, {"text": "準備運動をしないと、筋肉を痛めやすい。", "target_word": "筋肉", "complexity_tier": "T3", "furigana": "準備運動[じゅんびうんどう]をしないと、筋肉[きんにく]を痛[いた]めやすい。", "sentence_source": "generated"}, {"text": "水泳は全身の筋肉を使うスポーツだ。", "target_word": "筋肉", "complexity_tier": "T3", "furigana": "水泳[すいえい]は全身[ぜんしん]の筋肉[きんにく]を使[つか]うスポーツだ。", "sentence_source": "generated"}, {"text": "年をとると、筋肉が落ちて歩くのが遅くなる。", "target_word": "筋肉", "complexity_tier": "T3", "furigana": "年[とし]をとると、筋肉[きんにく]が落[お]ちて歩[ある]くのが遅[おそ]くなる。", "sentence_source": "generated"}, {"text": "笑うときには、顔の筋肉が動く。", "target_word": "筋肉", "complexity_tier": "T3", "furigana": "笑[わら]うときには、顔[かお]の筋肉[きんにく]が動[うご]く。", "sentence_source": "generated"}, {"text": "筋肉が疲れたときは、ゆっくりお風呂に入って休もう。", "target_word": "筋肉", "complexity_tier": "T3", "furigana": "筋肉[きんにく]が疲[つか]れたときは、ゆっくりお風呂[ふろ]に入[はい]って休[やす]もう。", "sentence_source": "generated"}, {"text": "選手の太い腕を見て、すごい筋肉だと思った。", "target_word": "筋肉", "complexity_tier": "T3", "furigana": "選手[せんしゅ]の太[ふと]い腕[うで]を見[み]て、すごい筋肉[きんにく]だと思[おも]った。", "sentence_source": "generated"}, {"text": "犬は走るときに、足の筋肉をたくさん使っている。", "target_word": "筋肉", "complexity_tier": "T3", "furigana": "犬[いぬ]は走[はし]るときに、足[あし]の筋肉[きんにく]をたくさん使[つか]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "筋肉", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "体の中の、動かすときに力を出す部分(体の筋肉)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba344cc6-eef7-4152-b08a-769bb2bfac14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52557, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "筋肉", "is_correct": true, "explanation": "「筋肉をつけたい」の目的語として、体を動かす組織の「筋肉」が入る。"}, {"text": "箸", "is_correct": false, "explanation": "「箸をつけたい」は成り立たず、文の流れに合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は身につけるものではなく、「天気をつけたい」は不自然。"}, {"text": "寝室", "is_correct": false, "explanation": "寝室は体につけるものではなく、「寝室をつけたい」は合わない。"}], "explanations": {"筋肉": "「筋肉をつけたい」の目的語として、体を動かす組織の「筋肉」が入る。", "箸": "「箸をつけたい」は成り立たず、文の流れに合わない。", "天気": "天気は身につけるものではなく、「天気をつけたい」は不自然。", "寝室": "寝室は体につけるものではなく、「寝室をつけたい」は合わない。"}, "sentence_index": 0, "correct_answer": "筋肉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "年をとると、筋肉が折れやすくなる。", "explanation": "ここは〈骨〉の話。年齢で折れやすくなるのは骨で、筋肉は折れないので合わない。"}, {"text": "筋肉が指令を出して、手を動かす。", "explanation": "ここは〈脳〉の働き。指令を出して体を動かすのは脳で、筋肉は指令を出さないので合わない。"}, {"text": "汗で筋肉がべたつく。", "explanation": "ここは〈皮膚〉の話。汗でべたつくのは皮膚の表面で、筋肉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52557, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "筋肉", "is_correct": true, "explanation": "顔の動きを生む組織としての「筋肉」が入る。"}, {"text": "指", "is_correct": false, "explanation": "「顔の指が動く」は成り立たず、文脈に合わない。"}, {"text": "爪", "is_correct": false, "explanation": "「顔の爪が動く」は不自然で、表情の動きを表せない。"}, {"text": "腕", "is_correct": false, "explanation": "「顔の腕が動く」は成り立たず、文脈に合わない。"}], "explanations": {"筋肉": "顔の動きを生む組織としての「筋肉」が入る。", "指": "「顔の指が動く」は成り立たず、文脈に合わない。", "爪": "「顔の爪が動く」は不自然で、表情の動きを表せない。", "腕": "「顔の腕が動く」は成り立たず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "筋肉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "熱いものに触れると、筋肉が信号を脳に送る。", "explanation": "ここは〈神経〉の働き。感覚の信号を脳に送るのは神経で、筋肉は合わない。"}, {"text": "筋肉で有害物質を分解する。", "explanation": "ここは〈肝臓〉の働き。有害物質を分解するのは肝臓で、筋肉は合わない。"}, {"text": "彼の意見は筋肉が通っている。", "explanation": "ここは〈筋〉（筋道）の意味。「筋が通る」は道理のことで、筋肉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52557, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎晩、腕立て伏せで胸の筋肉に鍛えている。", "corrected_sentence": "毎晩、腕立て伏せで胸の筋肉を鍛えている。", "error_description": "助詞の誤り。「鍛える」は対象を「を」で表すので、「筋肉に」は誤りで「筋肉を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52557, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ずっと寝ていたので、腹の筋肉を落ちて、体が重くなった。", "corrected_sentence": "ずっと寝ていたので、腹の筋肉が落ちて、体が重くなった。", "error_description": "助詞の誤り。「落ちる」は自動詞なので、主語の「筋肉」は「が」で表す。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52558, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「筋肉」が「太くなる」の主語を表すので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語につくが、「太くなる」は自動詞なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は結果や位置を示すが、主語にはならないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾する位置で、述語「太くなる」の前には入らず非文になる。"}], "correct_answer": "が", "explanations": {"が": "「筋肉」が「太くなる」の主語を表すので正しい。", "を": "「を」は他動詞の目的語につくが、「太くなる」は自動詞なので合わない。", "に": "「に」は結果や位置を示すが、主語にはならないので合わない。", "の": "「の」は名詞を修飾する位置で、述語「太くなる」の前には入らず非文になる。"}, "error_tags": {"を": "対象", "に": "結果・位置", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
