INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52558, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "動物の体を動かすための組織で、縮んだり伸びたりすることで力を生み出す。", "primary_collocate": null, "pronunciation": "きんにく", "ipa": "kiɴɲikɯ", "syllable_count": 4, "sentences": [{"text": "電子工作により、センサーやアクチュエータといった「感覚器官」と「筋肉」を物理的に実装する。", "target_word": "筋肉", "complexity_tier": "T3", "furigana": "電子工作[でんしこうさく]により、センサーやアクチュエータといった「感覚器官[かんかくきかん]」と「筋肉[きんにく]」を物理的[ぶつりてき]に実装[じっそう]する。", "sentence_source": "mined"}, {"text": "運動をすると、筋肉が太くなる。", "target_word": "筋肉", "complexity_tier": "T3", "furigana": "運動[うんどう]をすると、筋肉[きんにく]が太[ふと]くなる。", "sentence_source": "generated"}, {"text": "毎日歩いているので、足の筋肉が強くなった。", "target_word": "筋肉", "complexity_tier": "T3", "furigana": "毎日[まいにち]歩[ある]いているので、足[あし]の筋肉[きんにく]が強[つよ]くなった。", "sentence_source": "generated"}, {"text": "筋肉は縮んだり伸びたりして、体を動かす力を生み出す。", "target_word": "筋肉", "complexity_tier": "T3", "furigana": "筋肉[きんにく]は縮[ちぢ]んだり伸[の]びたりして、体[からだ]を動[うご]かす力[ちから]を生[う]み出[だ]す。", "sentence_source": "generated"}, {"text": "急に走ったせいで、ふくらはぎの筋肉が痛くなった。", "target_word": "筋肉", "complexity_tier": "T3", "furigana": "急[きゅう]に走[はし]ったせいで、ふくらはぎの筋肉[きんにく]が痛[いた]くなった。", "sentence_source": "generated"}, {"text": "彼は筋肉を鍛えるために、毎朝ジムに通っている。", "target_word": "筋肉", "complexity_tier": "T3", "furigana": "彼[かれ]は筋肉[きんにく]を鍛[きた]えるために、毎朝[まいあさ]ジムに通[かよ]っている。", "sentence_source": "generated"}, {"text": "運動の前には、筋肉をよくほぐしておこう。", "target_word": "筋肉", "complexity_tier": "T3", "furigana": "運動[うんどう]の前[まえ]には、筋肉[きんにく]をよくほぐしておこう。", "sentence_source": "generated"}, {"text": "寝たきりの生活が続くと、筋肉が弱ってしまう。", "target_word": "筋肉", "complexity_tier": "T3", "furigana": "寝[ね]たきりの生活[せいかつ]が続[つづ]くと、筋肉[きんにく]が弱[よわ]ってしまう。", "sentence_source": "generated"}, {"text": "肉や魚に含まれるたんぱく質は、筋肉を作る材料になる。", "target_word": "筋肉", "complexity_tier": "T4", "furigana": "肉[にく]や魚[さかな]に含[ふく]まれるたんぱく質[しつ]は、筋肉[きんにく]を作[つく]る材料[ざいりょう]になる。", "sentence_source": "generated"}, {"text": "重いものを持ち上げるときは、腕の筋肉を使う。", "target_word": "筋肉", "complexity_tier": "T3", "furigana": "重[おも]いものを持[も]ち上[あ]げるときは、腕[うで]の筋肉[きんにく]を使[つか]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "筋肉", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "動物の体を動かす、収縮して力を出す組織(体の筋肉)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: アクチュエータ (Zipf 2.3)']::text[], 'ba344cc6-eef7-4152-b08a-769bb2bfac14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52558, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "筋肉", "is_correct": true, "explanation": "「感覚器官」と並ぶ、体を動かす組織としての「筋肉」が入る。"}, {"text": "砂糖", "is_correct": false, "explanation": "器官ではないので「砂糖を物理的に実装する」は成り立たない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は器官ではなく、「紙を物理的に実装する」は文脈に合わない。"}, {"text": "水", "is_correct": false, "explanation": "水は組織ではないので、「水を物理的に実装する」は不自然で合わない。"}], "explanations": {"筋肉": "「感覚器官」と並ぶ、体を動かす組織としての「筋肉」が入る。", "砂糖": "器官ではないので「砂糖を物理的に実装する」は成り立たない。", "紙": "紙は器官ではなく、「紙を物理的に実装する」は文脈に合わない。", "水": "水は組織ではないので、「水を物理的に実装する」は不自然で合わない。"}, "sentence_index": 0, "correct_answer": "筋肉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "余ったエネルギーは、筋肉としてお腹にたまる。", "explanation": "ここは〈脂肪〉の話。余った栄養をお腹に蓄えるのは脂肪で、筋肉は蓄える組織ではないので合わない。"}, {"text": "筋肉が乾燥すると、かゆくなりやすい。", "explanation": "ここは〈皮膚〉の話。乾燥してかゆくなるのは皮膚で、筋肉は合わない。"}, {"text": "転んで筋肉が折れ、しばらく歩けなかった。", "explanation": "ここは〈骨〉の話。折れるのは骨で、筋肉は折れず、痛めたり切れたりするので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52558, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "筋肉", "is_correct": true, "explanation": "運動の前にほぐす対象として「筋肉」が入る。"}, {"text": "血管", "is_correct": false, "explanation": "血管はほぐす対象ではなく、「血管をよくほぐす」は不自然で合わない。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題は身体の組織ではなく、「宿題をよくほぐす」は不自然で文脈に合わない。"}, {"text": "血液", "is_correct": false, "explanation": "血液はほぐすものではないので、「血液をよくほぐす」は成り立たない。"}], "explanations": {"筋肉": "運動の前にほぐす対象として「筋肉」が入る。", "血管": "血管はほぐす対象ではなく、「血管をよくほぐす」は不自然で合わない。", "宿題": "宿題は身体の組織ではなく、「宿題をよくほぐす」は不自然で文脈に合わない。", "血液": "血液はほぐすものではないので、「血液をよくほぐす」は成り立たない。"}, "sentence_index": 6, "correct_answer": "筋肉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "筋肉が信号を脳に伝える。", "explanation": "ここは〈神経〉の働き。信号を脳へ伝えるのは神経で、筋肉は合わない。"}, {"text": "筋肉は空気を取り込んで、酸素を血に渡す。", "explanation": "ここは〈肺〉の働き。空気を取り込み酸素を血に渡すのは肺で、筋肉は合わない。"}, {"text": "この話は筋肉が通っている。", "explanation": "ここは〈筋〉（筋道）の意味。「筋が通る」は話の道理を言う表現で、筋肉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52558, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "マラソンに向けて、ふくらはぎの筋肉に鍛えている。", "corrected_sentence": "マラソンに向けて、ふくらはぎの筋肉を鍛えている。", "error_description": "助詞の誤り。「鍛える」は鍛える対象を「を」で表すので、「筋肉に」は誤りで「筋肉を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52558, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は筋肉に保つため、毎日散歩をしている。", "corrected_sentence": "祖父は筋肉を保つため、毎日散歩をしている。", "error_description": "助詞の誤り。「保つ」は保つ対象を「を」で表すので、「筋肉に」は誤りで「筋肉を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52559, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「先生」が叱る行為の主体を表すので「に」が正しい。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所を示すので、行為者には入らない。"}, {"text": "を", "is_correct": false, "explanation": "「叱られる」の行為者は「に」で表すので、「を」は入らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、行為者を表す位置には合わない。"}], "correct_answer": "に", "explanations": {"に": "「先生」が叱る行為の主体を表すので「に」が正しい。", "で": "「で」は手段・場所を示すので、行為者には入らない。", "を": "「叱られる」の行為者は「に」で表すので、「を」は入らない。", "より": "「より」は比較を示すので、行為者を表す位置には合わない。"}, "error_tags": {"で": "手段・場所", "を": "目的語の誤り", "より": "比較"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "褒める", "is_correct": true, "explanation": "「叱る」の対義語。相手の良い行いを認めて言葉をかける。"}, {"text": "教える", "is_correct": false, "explanation": "「叱る」と反対の関係にはなく、対義語ではない。"}, {"text": "怒る", "is_correct": false, "explanation": "感情を表す語で、「叱る」の対義語ではない。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "大きな声を出す動作で、「叱る」の対義語ではない。"}], "correct_answer": "褒める", "explanations": {"褒める": "「叱る」の対義語。相手の良い行いを認めて言葉をかける。", "教える": "「叱る」と反対の関係にはなく、対義語ではない。", "怒る": "感情を表す語で、「叱る」の対義語ではない。", "叫ぶ": "大きな声を出す動作で、「叱る」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52559, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "褒める", "is_correct": true, "explanation": "「叱る」の対義語。相手の良い点を認めて言葉をかける。"}, {"text": "眠る", "is_correct": false, "explanation": "眠ることを表し、「叱る」の対義語ではない。"}, {"text": "任せる", "is_correct": false, "explanation": "仕事などを預ける意味で、「叱る」の対義語ではない。"}, {"text": "祈る", "is_correct": false, "explanation": "願う行為を表し、「叱る」の対義語ではない。"}], "correct_answer": "褒める", "explanations": {"褒める": "「叱る」の対義語。相手の良い点を認めて言葉をかける。", "眠る": "眠ることを表し、「叱る」の対義語ではない。", "任せる": "仕事などを預ける意味で、「叱る」の対義語ではない。", "祈る": "願う行為を表し、「叱る」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52559, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "だめなことをしたときに、おこること。", "primary_collocate": null, "pronunciation": "しかる", "ipa": "ɕikaɾɯ", "syllable_count": 3, "sentences": [{"text": "弟が宿題をしなかったので、母が叱った。", "target_word": "叱った", "complexity_tier": "T3", "furigana": "弟[おとうと]が宿題[しゅくだい]をしなかったので、母[はは]が叱[しか]った。", "sentence_source": "generated"}, {"text": "道路で遊んでいて、先生に叱られた。", "target_word": "叱られ", "complexity_tier": "T3", "furigana": "道路[どうろ]で遊[あそ]んでいて、先生[せんせい]に叱[しか]られた。", "sentence_source": "generated"}, {"text": "犬がいたずらをしても、そんなに叱ってはいけない。", "target_word": "叱って", "complexity_tier": "T3", "furigana": "犬[いぬ]がいたずらをしても、そんなに叱[しか]ってはいけない。", "sentence_source": "generated"}, {"text": "うそをついた妹を、姉が叱っている。", "target_word": "叱って", "complexity_tier": "T3", "furigana": "うそをついた妹[いもうと]を、姉[あね]が叱[しか]っている。", "sentence_source": "generated"}, {"text": "ゲームをやめないので、父が叱るだろう。", "target_word": "叱る", "complexity_tier": "T3", "furigana": "ゲームをやめないので、父[ちち]が叱[しか]るだろう。", "sentence_source": "generated"}, {"text": "友だちをたたいたので、先生に叱られました。", "target_word": "叱られ", "complexity_tier": "T3", "furigana": "友[とも]だちをたたいたので、先生[せんせい]に叱[しか]られました。", "sentence_source": "generated"}, {"text": "大きな声で叱ると、子どもは泣いてしまう。", "target_word": "叱る", "complexity_tier": "T3", "furigana": "大[おお]きな声[こえ]で叱[しか]ると、子[こ]どもは泣[な]いてしまう。", "sentence_source": "generated"}, {"text": "窓ガラスを割った息子を叱った。", "target_word": "叱った", "complexity_tier": "T3", "furigana": "窓[まど]ガラスを割[わ]った息子[むすこ]を叱[しか]った。", "sentence_source": "generated"}, {"text": "悪いことをしたら、叱られるのは当然だ。", "target_word": "叱られる", "complexity_tier": "T3", "furigana": "悪[わる]いことをしたら、叱[しか]られるのは当然[とうぜん]だ。", "sentence_source": "generated"}, {"text": "兄は私を叱らないで、やさしく教えてくれた。", "target_word": "叱ら", "complexity_tier": "T3", "furigana": "兄[あに]は私[わたし]を叱[しか]らないで、やさしく教[おし]えてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "叱る", "label": "辞書形"}, {"form": "叱った", "label": "過去形"}, {"form": "叱って", "label": "て形"}, {"form": "叱らない", "label": "否定形"}, {"form": "叱られる", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "だめなことをした相手に、おこって注意する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba344cc6-eef7-4152-b08a-769bb2bfac14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52559, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "叱った", "is_correct": true, "explanation": "過去形で、母が弟を叱ったという出来事に合う。"}, {"text": "叱ら", "is_correct": false, "explanation": "未然形なので、「母が叱ら」と文が続かない。"}, {"text": "叱られ", "is_correct": false, "explanation": "受身の語幹で、「母が叱られた」では主語と行為が逆になる。"}, {"text": "叱って", "is_correct": false, "explanation": "て形で、「母が叱って」では文を完結できない。"}], "explanations": {"叱った": "過去形で、母が弟を叱ったという出来事に合う。", "叱ら": "未然形なので、「母が叱ら」と文が続かない。", "叱られ": "受身の語幹で、「母が叱られた」では主語と行為が逆になる。", "叱って": "て形で、「母が叱って」では文を完結できない。"}, "sentence_index": 0, "correct_answer": "叱った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨が降ったので、傘を叱った。", "explanation": "ここは〈差す〉の動作。傘を差すのは動作で、叱るは人の過ちを咎める行為なので合わない。"}, {"text": "窓ガラスを叱った。", "explanation": "ここは〈拭く〉の動作。窓を拭くのは動作で、叱るは人の過ちを咎める行為なので合わない。"}, {"text": "コーヒーを叱った。", "explanation": "ここは〈淹れる〉の動作。コーヒーを淹れるのは動作で、叱るは人の過ちを咎める行為なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52559, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "叱る", "is_correct": true, "explanation": "基本形で「叱ると、子どもは泣いてしまう」の条件節として合う。"}, {"text": "叱り", "is_correct": false, "explanation": "連用形で、「叱りと」は条件を示せず文に合わない。"}, {"text": "叱れ", "is_correct": false, "explanation": "命令形で、「叱れと」は文の条件として成り立たない。"}, {"text": "叱らせ", "is_correct": false, "explanation": "使役の語幹で、「叱らせと」は文に合わない。"}], "explanations": {"叱る": "基本形で「叱ると、子どもは泣いてしまう」の条件節として合う。", "叱り": "連用形で、「叱りと」は条件を示せず文に合わない。", "叱れ": "命令形で、「叱れと」は文の条件として成り立たない。", "叱らせ": "使役の語幹で、「叱らせと」は文に合わない。"}, "sentence_index": 6, "correct_answer": "叱る"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "プレゼントを叱った。", "explanation": "ここは〈包む〉の動作。プレゼントを包むのは動作で、叱るは人の過ちを咎める行為なので合わない。"}, {"text": "濡れた服を叱った。", "explanation": "ここは〈乾かす〉の動作。服を乾かすのは動作で、叱るは人の過ちを咎める行為なので合わない。"}, {"text": "庭の花を叱った。", "explanation": "ここは〈植える〉の動作。花を植えるのは動作で、叱るは人の過ちを咎める行為なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52559, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ゲームをやめなかった弟で、母が叱った。", "corrected_sentence": "ゲームをやめなかった弟を、母が叱った。", "error_description": "助詞の誤り。「叱る」の対象は「を」で表すので、「弟で」は誤りで「弟を」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "叱られ", "is_correct": true, "explanation": "受身形で、先生に叱られたという文に合う。"}, {"text": "叱る", "is_correct": false, "explanation": "基本形で、先生が叱るという能動の意味になり文に合わない。"}, {"text": "叱った", "is_correct": false, "explanation": "過去形で、先生が叱った（能動）の意味になり文に合わない。"}, {"text": "叱って", "is_correct": false, "explanation": "て形で、文を完結させる形ではない。"}], "correct_form": "叱られ", "base_form": "叱る", "form_label": "受身形", "sentence_index": 1, "explanations": {"叱られ": "受身形で、先生に叱られたという文に合う。", "叱る": "基本形で、先生が叱るという能動の意味になり文に合わない。", "叱った": "過去形で、先生が叱った（能動）の意味になり文に合わない。", "叱って": "て形で、文を完結させる形ではない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52559, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厳しい口調で叱りと、弟は反省する。", "corrected_sentence": "厳しい口調で叱ると、弟は反省する。", "error_description": "活用の誤り。「叱る」に条件の「と」をつけるときは基本形の「叱ると」。「叱りと」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "叱った", "is_correct": true, "explanation": "過去形で、窓ガラスを割った息子を叱ったという出来事に合う。"}, {"text": "叱らせ", "is_correct": false, "explanation": "使役の語幹で、「叱らせ。」と文を終えられない。"}, {"text": "叱れ", "is_correct": false, "explanation": "命令形で、過去の出来事を述べる文には合わない。"}, {"text": "叱り", "is_correct": false, "explanation": "連用形で、文を終わらせる過去の形ではない。"}], "correct_form": "叱った", "base_form": "叱る", "form_label": "過去形", "sentence_index": 7, "explanations": {"叱った": "過去形で、窓ガラスを割った息子を叱ったという出来事に合う。", "叱らせ": "使役の語幹で、「叱らせ。」と文を終えられない。", "叱れ": "命令形で、過去の出来事を述べる文には合わない。", "叱り": "連用形で、文を終わらせる過去の形ではない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
