INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52560, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "相手の間違いや悪い行いを指摘して、厳しい言葉で注意すること。", "primary_collocate": null, "pronunciation": "しかる", "ipa": "ɕikaɾɯ", "syllable_count": 3, "sentences": [{"text": "廊下を走って友達にぶつかった弟を、姉が叱った。", "target_word": "叱った", "complexity_tier": "T3", "furigana": "廊下[ろうか]を走[はし]って友達[ともだち]にぶつかった弟[おとうと]を、姉[あね]が叱[しか]った。", "sentence_source": "generated"}, {"text": "先生は、うそをついた生徒を厳しく叱った。", "target_word": "叱った", "complexity_tier": "T3", "furigana": "先生[せんせい]は、うそをついた生徒[せいと]を厳[きび]しく叱[しか]った。", "sentence_source": "generated"}, {"text": "子どもを叱るときは、理由もきちんと説明したい。", "target_word": "叱る", "complexity_tier": "T3", "furigana": "子[こ]どもを叱[しか]るときは、理由[りゆう]もきちんと説明[せつめい]したい。", "sentence_source": "generated"}, {"text": "遅刻を重ねた部下を、課長が人前で叱った。", "target_word": "叱った", "complexity_tier": "T3", "furigana": "遅刻[ちこく]を重[かさ]ねた部下[ぶか]を、課長[かちょう]が人前[ひとまえ]で叱[しか]った。", "sentence_source": "generated"}, {"text": "母に叱られても、弟は反省しなかった。", "target_word": "叱られ", "complexity_tier": "T3", "furigana": "母[はは]に叱[しか]られても、弟[おとうと]は反省[はんせい]しなかった。", "sentence_source": "generated"}, {"text": "間違いを指摘して叱ることと、感情的に怒鳴ることは違う。", "target_word": "叱る", "complexity_tier": "T4", "furigana": "間違[まちが]いを指摘[してき]して叱[しか]ることと、感情的[かんじょうてき]に怒鳴[どな]ることは違[ちが]う。", "sentence_source": "generated"}, {"text": "約束を破ったので、父にひどく叱られた。", "target_word": "叱られ", "complexity_tier": "T3", "furigana": "約束[やくそく]を破[やぶ]ったので、父[ちち]にひどく叱[しか]られた。", "sentence_source": "generated"}, {"text": "試合でミスをした選手を、監督は叱らず、次の対策を話し合った。", "target_word": "叱ら", "complexity_tier": "T4", "furigana": "試合[しあい]でミスをした選手[せんしゅ]を、監督[かんとく]は叱[しか]らず、次[つぎ]の対策[たいさく]を話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "上司に叱られないよう、報告書は期限までに出した。", "target_word": "叱られ", "complexity_tier": "T4", "furigana": "上司[じょうし]に叱[しか]られないよう、報告書[ほうこくしょ]は期限[きげん]までに出[だ]した。", "sentence_source": "generated"}, {"text": "後輩のためを思うからこそ、あえて叱ることもある。", "target_word": "叱る", "complexity_tier": "T4", "furigana": "後輩[こうはい]のためを思[おも]うからこそ、あえて叱[しか]ることもある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "叱る", "label": "辞書形"}, {"form": "叱った", "label": "過去形"}, {"form": "叱って", "label": "て形"}, {"form": "叱らない", "label": "否定形"}, {"form": "叱られる", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "間違いや悪い行いを指摘し、厳しい言葉で注意する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba344cc6-eef7-4152-b08a-769bb2bfac14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52560, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "叱った", "is_correct": true, "explanation": "過去形で、姉が弟を叱ったという出来事に合う。"}, {"text": "叱ら", "is_correct": false, "explanation": "未然形なので、「姉が叱ら。」と文を終えられない。"}, {"text": "叱れ", "is_correct": false, "explanation": "命令形なので、事実を述べる文には合わない。"}, {"text": "叱って", "is_correct": false, "explanation": "て形なので、「姉が叱って。」では文を完結できない。"}], "explanations": {"叱った": "過去形で、姉が弟を叱ったという出来事に合う。", "叱ら": "未然形なので、「姉が叱ら。」と文を終えられない。", "叱れ": "命令形なので、事実を述べる文には合わない。", "叱って": "て形なので、「姉が叱って。」では文を完結できない。"}, "sentence_index": 0, "correct_answer": "叱った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母が洗濯物を叱った。", "explanation": "ここは〈干す〉の動作。洗濯物を干すのは動作で、叱るは人の過ちを咎める行為なので合わない。"}, {"text": "雨の日は足元を叱ってください。", "explanation": "ここは〈注意する〉の意味。足元に気をつけるよう促すのが注意で、叱るは相手の過ちを咎める行為なので合わない。"}, {"text": "子どもが種を叱った。", "explanation": "ここは〈まく〉の動作。種をまくのは動作で、叱るは人の過ちを咎める行為なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52560, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "叱られ", "is_correct": true, "explanation": "「父にひどく叱られた」の語幹として入り、「た」に続く。"}, {"text": "叱ら", "is_correct": false, "explanation": "未然形なので、後ろの「た」に続かない。"}, {"text": "叱ろう", "is_correct": false, "explanation": "意向形なので、後ろの「た」に続かない。"}, {"text": "叱り", "is_correct": false, "explanation": "連用形では後ろの「た」に続く形にならない。"}], "explanations": {"叱られ": "「父にひどく叱られた」の語幹として入り、「た」に続く。", "叱ら": "未然形なので、後ろの「た」に続かない。", "叱ろう": "意向形なので、後ろの「た」に続かない。", "叱り": "連用形では後ろの「た」に続く形にならない。"}, "sentence_index": 6, "correct_answer": "叱られ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友達の忘れ物を叱った。", "explanation": "ここは〈届ける〉の動作。忘れ物を届けるのは動作で、叱るは人の過ちを咎める行為なので合わない。"}, {"text": "母は、野菜を叱った。", "explanation": "ここは〈洗う〉の動作。野菜を洗うのは動作で、叱るは人の過ちを咎める行為なので合わない。"}, {"text": "会議の資料を叱った。", "explanation": "ここは〈配る〉の動作。資料を配るのは動作で、叱るは人の過ちを咎める行為なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52560, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は弟を叱りて、おやつを取り上げた。", "corrected_sentence": "母は弟を叱って、おやつを取り上げた。", "error_description": "て形の誤り。「叱る」は五段活用なので、て形は「叱って」。「叱りて」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "叱った", "is_correct": true, "explanation": "過去形で、先生が生徒を叱ったという過去の出来事に合う。"}, {"text": "叱れ", "is_correct": false, "explanation": "命令形なので、事実を述べる文には合わない。"}, {"text": "叱らせ", "is_correct": false, "explanation": "使役の語幹で、「叱らせ。」と文を終えられない。"}, {"text": "叱って", "is_correct": false, "explanation": "て形で、文を完結させる形ではない。"}], "correct_form": "叱った", "base_form": "叱る", "form_label": "過去形", "sentence_index": 1, "explanations": {"叱った": "過去形で、先生が生徒を叱ったという過去の出来事に合う。", "叱れ": "命令形なので、事実を述べる文には合わない。", "叱らせ": "使役の語幹で、「叱らせ。」と文を終えられない。", "叱って": "て形で、文を完結させる形ではない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52560, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友達は先生で叱られた。", "corrected_sentence": "友達は先生に叱られた。", "error_description": "助詞の誤り。「叱られる」の行為者は「に」で表すので、「先生で」は誤りで「先生に」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "叱ら", "is_correct": true, "explanation": "否定の「ず」形で、「叱らず」として文を続ける形。"}, {"text": "叱られ", "is_correct": false, "explanation": "受身の形で、監督が選手を叱る文の形とは合わない。"}, {"text": "叱った", "is_correct": false, "explanation": "過去形で、「叱らず」の否定の流れに合わない。"}, {"text": "叱れ", "is_correct": false, "explanation": "命令形なので、「叱れ、」と文を続けられない。"}], "correct_form": "叱ら", "base_form": "叱る", "form_label": "否定形", "sentence_index": 7, "explanations": {"叱ら": "否定の「ず」形で、「叱らず」として文を続ける形。", "叱られ": "受身の形で、監督が選手を叱る文の形とは合わない。", "叱った": "過去形で、「叱らず」の否定の流れに合わない。", "叱れ": "命令形なので、「叱れ、」と文を続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52561, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「机の上」で、机の場所を示す「の」。正解。"}, {"text": "が", "is_correct": false, "explanation": "「机が上に」は主語になり、「上」に続かず不自然。"}, {"text": "を", "is_correct": false, "explanation": "「机を上に」は目的語の形になり、場所の名詞「上」に続かない。"}, {"text": "で", "is_correct": false, "explanation": "場所の「で」で、「机で上に」は場所の名詞に続かず不自然。"}], "correct_answer": "の", "explanations": {"の": "「机の上」で、机の場所を示す「の」。正解。", "が": "「机が上に」は主語になり、「上」に続かず不自然。", "を": "「机を上に」は目的語の形になり、場所の名詞「上」に続かない。", "で": "場所の「で」で、「机で上に」は場所の名詞に続かず不自然。"}, "error_tags": {"が": "主語化の誤り", "を": "目的語の誤り", "で": "場所の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52561, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「机は大きいので」で、主題として机を示す「は」。正解。"}, {"text": "を", "is_correct": false, "explanation": "「机を大きいので」は目的語の形になり、形容詞「大きい」に続かない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞で、「机へ大きいので」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "共同や相手を示す「と」で、「机と大きいので」は不自然。"}], "correct_answer": "は", "explanations": {"は": "「机は大きいので」で、主題として机を示す「は」。正解。", "を": "「机を大きいので」は目的語の形になり、形容詞「大きい」に続かない。", "へ": "方向の助詞で、「机へ大きいので」は意味が通らない。", "と": "共同や相手を示す「と」で、「机と大きいので」は不自然。"}, "error_tags": {"を": "目的語の誤り", "へ": "方向", "と": "共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52561, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "つくえは、ものをおいたり、べんきょうしたりするためのどうぐです。", "primary_collocate": null, "pronunciation": "つくえ", "ipa": "tsɯkɯe", "syllable_count": 3, "sentences": [{"text": "私の机は窓のそばにあります。", "target_word": "机", "complexity_tier": "T2", "furigana": "私[わたし]の机[つくえ]は窓[まど]のそばにあります。", "sentence_source": "generated"}, {"text": "机の上にえんぴつと消しゴムがあります。", "target_word": "机", "complexity_tier": "T2", "furigana": "机[つくえ]の上[うえ]にえんぴつと消[け]しゴムがあります。", "sentence_source": "generated"}, {"text": "毎日、机で宿題をします。", "target_word": "机", "complexity_tier": "T2", "furigana": "毎日[まいにち]、机[つくえ]で宿題[しゅくだい]をします。", "sentence_source": "generated"}, {"text": "新しい机がほしいです。", "target_word": "机", "complexity_tier": "T2", "furigana": "新[あたら]しい机[つくえ]がほしいです。", "sentence_source": "generated"}, {"text": "机の下にねこがいます。", "target_word": "机", "complexity_tier": "T2", "furigana": "机[つくえ]の下[した]にねこがいます。", "sentence_source": "generated"}, {"text": "学校の机はみんな同じ形です。", "target_word": "机", "complexity_tier": "T2", "furigana": "学校[がっこう]の机[つくえ]はみんな同[おな]じ形[かたち]です。", "sentence_source": "generated"}, {"text": "机の中に教科書を入れました。", "target_word": "机", "complexity_tier": "T2", "furigana": "机[つくえ]の中[なか]に教科書[きょうかしょ]を入[い]れました。", "sentence_source": "generated"}, {"text": "この机は大きいので、本をたくさん置けます。", "target_word": "机", "complexity_tier": "T3", "furigana": "この机[つくえ]は大[おお]きいので、本[ほん]をたくさん置[お]けます。", "sentence_source": "generated"}, {"text": "兄は机に向かって手紙を書いています。", "target_word": "机", "complexity_tier": "T3", "furigana": "兄[あに]は机[つくえ]に向[む]かって手紙[てがみ]を書[か]いています。", "sentence_source": "generated"}, {"text": "机がよごれていたので、ふきました。", "target_word": "机", "complexity_tier": "T2", "furigana": "机[つくえ]がよごれていたので、ふきました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "机", "label": "基本形"}], "register": "中立", "sense_fingerprint": "ものを置いたり勉強したりするための家具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba344cc6-eef7-4152-b08a-769bb2bfac14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52561, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机", "is_correct": true, "explanation": "「私の机は窓のそばにあります」で、持ち物の家具を指す。正解。"}, {"text": "夜明け", "is_correct": false, "explanation": "「私の夜明けは窓のそばにあります」は意味が通らない。"}, {"text": "雷", "is_correct": false, "explanation": "「私の雷は窓のそばにあります」は意味が通らない。"}, {"text": "雲", "is_correct": false, "explanation": "「私の雲は窓のそばにあります」は意味が通らない。"}], "explanations": {"机": "「私の机は窓のそばにあります」で、持ち物の家具を指す。正解。", "夜明け": "「私の夜明けは窓のそばにあります」は意味が通らない。", "雷": "「私の雷は窓のそばにあります」は意味が通らない。", "雲": "「私の雲は窓のそばにあります」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机で牛乳を冷やした。", "explanation": "ここは〈冷蔵庫〉の意味。牛乳を冷やすのは〈冷蔵庫〉で、机では冷やせないので、〈机〉の使い方として合わない。"}, {"text": "本を読むとき、机に座ってくつろいだ。", "explanation": "座るのは〈椅子〉。机は座る家具ではないので、座る対象として〈机〉を使うのは合わない。"}, {"text": "疲れたので、机に寝転がってテレビを見た。", "explanation": "寝転がれるのは〈ソファ〉や〈ベッド〉。机には寝転がれないので、〈机〉の使い方として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52561, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机", "is_correct": true, "explanation": "「机の中に教科書を入れました」で、教科書を入れる家具の一部を指す。正解。"}, {"text": "波", "is_correct": false, "explanation": "「波の中に教科書を入れました」は意味が通らない。"}, {"text": "霧", "is_correct": false, "explanation": "「霧の中に教科書を入れました」は文脈に合わず、教科書を入れる対象にならない。"}, {"text": "星", "is_correct": false, "explanation": "「星の中に教科書を入れました」は意味が通らない。"}], "explanations": {"机": "「机の中に教科書を入れました」で、教科書を入れる家具の一部を指す。正解。", "波": "「波の中に教科書を入れました」は意味が通らない。", "霧": "「霧の中に教科書を入れました」は文脈に合わず、教科書を入れる対象にならない。", "星": "「星の中に教科書を入れました」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "机で味噌汁を作った。", "explanation": "ここは〈鍋〉の意味。味噌汁を作るのは〈鍋〉で、〈机〉では作れないので、〈机〉の使い方として合わない。"}, {"text": "風を入れるため、机を開けた。", "explanation": "ここは〈窓〉の意味。風を入れるために開けるのは〈窓〉で、机は開けられないので、〈机〉の使い方として合わない。"}, {"text": "雨が降ってきたので、机を広げて歩いた。", "explanation": "ここは〈傘〉の意味。雨をよけるために広げるのは〈傘〉で、〈机〉を広げて使うのは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52561, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ねこが机を下で寝ています。", "corrected_sentence": "ねこが机の下で寝ています。", "error_description": "「机の下」の「の」が「を」になっている。場所を示す「机の」が正しく、「机を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52561, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は机で向かって勉強した。", "corrected_sentence": "妹は机に向かって勉強した。", "error_description": "「向かう」の相手を示すには「に」を使う。「で」は場所を示すので誤り。正しくは「机に向かって」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52562, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「机の上」で、机の場所を示す「の」。正解。"}, {"text": "が", "is_correct": false, "explanation": "「机が上に」は主語になり、「上」を修飾する形として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「机を上に」は目的語の形になり、場所の名詞「上」に続かない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段の「で」で、「机で上」は場所を示す名詞に続かず不自然。"}], "correct_answer": "の", "explanations": {"の": "「机の上」で、机の場所を示す「の」。正解。", "が": "「机が上に」は主語になり、「上」を修飾する形として成り立たない。", "を": "「机を上に」は目的語の形になり、場所の名詞「上」に続かない。", "で": "場所や手段の「で」で、「机で上」は場所を示す名詞に続かず不自然。"}, "error_tags": {"が": "主語化の誤り", "を": "目的語の誤り", "で": "場所の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52562, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52562, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物を置いたり、書いたり、仕事や勉強をするための、平らな板と脚からなる家具。", "primary_collocate": null, "pronunciation": "つくえ", "ipa": "tsɯkɯe", "syllable_count": 3, "sentences": [{"text": "この製作の全工程は、まさに宇宙の理を机の上に縮図として描き出す、崇高な知的探究なのである。", "target_word": "机", "complexity_tier": "T4", "furigana": "この製作[せいさく]の全工程[ぜんこうてい]は、まさに宇宙[うちゅう]の理[り]を机[つくえ]の上[うえ]に縮図[しゅくず]として描[えが]き出[だ]す、崇高[すうこう]な知的[ちてき]探究[たんきゅう]なのである。", "sentence_source": "mined"}, {"text": "机の上に辞書とノートが置いてあります。", "target_word": "机", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]に辞書[じしょ]とノートが置[お]いてあります。", "sentence_source": "generated"}, {"text": "新しい机を買ったので、部屋の模様替えをした。", "target_word": "机", "complexity_tier": "T3", "furigana": "新[あたら]しい机[つくえ]を買[か]ったので、部屋[へや]の模様替[もようが]えをした。", "sentence_source": "generated"}, {"text": "弟は毎晩、机に向かって宿題をしている。", "target_word": "机", "complexity_tier": "T3", "furigana": "弟[おとうと]は毎晩[まいばん]、机[つくえ]に向[む]かって宿題[しゅくだい]をしている。", "sentence_source": "generated"}, {"text": "机の引き出しに、古い手紙をしまっておいた。", "target_word": "机", "complexity_tier": "T3", "furigana": "机[つくえ]の引[ひ]き出[だ]しに、古[ふる]い手紙[てがみ]をしまっておいた。", "sentence_source": "generated"}, {"text": "机が小さすぎて、ノートパソコンと本を同時に広げられない。", "target_word": "机", "complexity_tier": "T3", "furigana": "机[つくえ]が小[ちい]さすぎて、ノートパソコンと本[ほん]を同時[どうじ]に広[ひろ]げられない。", "sentence_source": "generated"}, {"text": "教室の机を並べ直してから、授業を始めた。", "target_word": "机", "complexity_tier": "T3", "furigana": "教室[きょうしつ]の机[つくえ]を並[なら]べ直[なお]してから、授業[じゅぎょう]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "祖父が使っていた大きな机は、今も書斎に残っている。", "target_word": "机", "complexity_tier": "T3", "furigana": "祖父[そふ]が使[つか]っていた大[おお]きな机[つくえ]は、今[いま]も書斎[しょさい]に残[のこ]っている。", "sentence_source": "generated"}, {"text": "窓際の机は日当たりがよく、勉強がはかどる。", "target_word": "机", "complexity_tier": "T3", "furigana": "窓際[まどぎわ]の机[つくえ]は日当[ひあ]たりがよく、勉強[べんきょう]がはかどる。", "sentence_source": "generated"}, {"text": "机の脚がぐらついていたので、ネジを締め直した。", "target_word": "机", "complexity_tier": "T3", "furigana": "机[つくえ]の脚[あし]がぐらついていたので、ネジを締[し]め直[なお]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "机", "label": "基本形"}], "register": "中立", "sense_fingerprint": "勉強や仕事に使う平らな天板と脚のある家具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 縮図 (Zipf 2.69), 描き出す (Zipf 2.48), 崇高 (Zipf 3.16), 探究 (Zipf 3.15)']::text[], 'ba344cc6-eef7-4152-b08a-769bb2bfac14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52562, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机", "is_correct": true, "explanation": "「机の上に縮図として描き出す」で、描き出す平らな場所を示す。正解。"}, {"text": "病院", "is_correct": false, "explanation": "「病院の上に縮図として描き出す」は場所として不自然で、文が成り立たない。"}, {"text": "風", "is_correct": false, "explanation": "「風の上に縮図として描き出す」は意味が通らない。"}, {"text": "夜明け", "is_correct": false, "explanation": "「夜明けの上に縮図として描き出す」は意味が通らない。"}], "explanations": {"机": "「机の上に縮図として描き出す」で、描き出す平らな場所を示す。正解。", "病院": "「病院の上に縮図として描き出す」は場所として不自然で、文が成り立たない。", "風": "「風の上に縮図として描き出す」は意味が通らない。", "夜明け": "「夜明けの上に縮図として描き出す」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "床のほこりを、机で吸い取った。", "explanation": "ここは〈掃除機〉の意味。ほこりを吸い取るのは〈掃除機〉で、机では吸い取れないので、〈机〉の使い方として合わない。"}, {"text": "本を読むとき、机に座ってくつろいだ。", "explanation": "座るのは〈椅子〉。机は座る家具ではないので、〈机〉を座る対象として使うのは合わない。"}, {"text": "疲れた夜は、机に横になって眠った。", "explanation": "横になるのは〈ベッド〉や〈布団〉。机に横になって眠るのは不自然で、〈机〉の使い方として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52562, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机", "is_correct": true, "explanation": "「教室の机を並べ直す」で、教室の机の配置を変える意味。正解。"}, {"text": "雲", "is_correct": false, "explanation": "「教室の雲を並べ直す」は意味が通らない。"}, {"text": "花火", "is_correct": false, "explanation": "「教室の花火を並べ直す」は文脈に合わない。"}, {"text": "波", "is_correct": false, "explanation": "「教室の波を並べ直す」は意味が通らない。"}], "explanations": {"机": "「教室の机を並べ直す」で、教室の机の配置を変える意味。正解。", "雲": "「教室の雲を並べ直す」は意味が通らない。", "花火": "「教室の花火を並べ直す」は文脈に合わない。", "波": "「教室の波を並べ直す」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨の日は、机で服を洗った。", "explanation": "ここは〈洗濯機〉の意味。服を洗うのは〈洗濯機〉で、机では洗えないので、〈机〉の使い方として合わない。"}, {"text": "部屋を出るとき、机を開けて外に出た。", "explanation": "ここは〈扉〉の意味。開けて出入りするのは〈扉〉で、机は開けられないので、〈机〉の使い方として合わない。"}, {"text": "雨が降ってきたので、机を広げて歩いた。", "explanation": "ここは〈傘〉の意味。雨をよけるために広げるのは〈傘〉で、〈机〉を広げて使うのは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52562, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机をよごれていたので、すぐにふいた。", "corrected_sentence": "机がよごれていたので、すぐにふいた。", "error_description": "「よごれる」は自動詞なので、主語には「机が」を使う。「机を」は誤りで、正しくは「机がよごれていた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52562, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教室の机を並べ直ると、広く見える。", "corrected_sentence": "教室の机を並べ直すと、広く見える。", "error_description": "「並べ直す」の活用が誤り。「並べ直ると」は不自然で、正しくは「並べ直すと」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52563, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「理にかなう」の「に」。道理にかなうという固定した形。"}, {"text": "で", "is_correct": false, "explanation": "「理でかなう」は成立せず、「で」は手段を表すので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「理へかなう」は不自然で、「へ」は方向を表すため合わない。"}, {"text": "と", "is_correct": false, "explanation": "「理とかなう」は誤りで、「と」は相手や並列を表すため合わない。"}], "correct_answer": "に", "explanations": {"に": "「理にかなう」の「に」。道理にかなうという固定した形。", "で": "「理でかなう」は成立せず、「で」は手段を表すので合わない。", "へ": "「理へかなう」は不自然で、「へ」は方向を表すため合わない。", "と": "「理とかなう」は誤りで、「と」は相手や並列を表すため合わない。"}, "error_tags": {"で": "手段", "へ": "方向", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52563, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「理を追う」で、追う対象を表す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「理に追う」は不自然で、「追う」は「を」で対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「理が追う」は主語として成立せず、追跡する主体にならないので誤り。"}, {"text": "の", "is_correct": false, "explanation": "「理の追って」は文法的に成立せず、所属の意味にもならない。"}], "correct_answer": "を", "explanations": {"を": "「理を追う」で、追う対象を表す「を」。", "に": "「理に追う」は不自然で、「追う」は「を」で対象を示す。", "が": "「理が追う」は主語として成立せず、追跡する主体にならないので誤り。", "の": "「理の追って」は文法的に成立せず、所属の意味にもならない。"}, "error_tags": {"に": "方向", "が": "主語", "の": "所属"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52563, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものごとのしくみや、なぜそうなるかという道理のこと。", "primary_collocate": null, "pronunciation": "り", "ipa": "ɾi", "syllable_count": 1, "sentences": [{"text": "雨が降るのには、ちゃんと理がある。", "target_word": "理", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]るのには、ちゃんと理[り]がある。", "sentence_source": "generated"}, {"text": "この話は理にかなっています。", "target_word": "理", "complexity_tier": "T3", "furigana": "この話[はなし]は理[り]にかなっています。", "sentence_source": "generated"}, {"text": "先生は、物が落ちるわけを理に沿って説明してくれました。", "target_word": "理", "complexity_tier": "T3", "furigana": "先生[せんせい]は、物[もの]が落[お]ちるわけを理[り]に沿[そ]って説明[せつめい]してくれました。", "sentence_source": "generated"}, {"text": "理に合わないことは、おかしいと思います。", "target_word": "理", "complexity_tier": "T3", "furigana": "理[り]に合[あ]わないことは、おかしいと思[おも]います。", "sentence_source": "generated"}, {"text": "夏のあとに秋が来るのは、季節の流れとして理に合っている。", "target_word": "理", "complexity_tier": "T3", "furigana": "夏[なつ]のあとに秋[あき]が来[く]るのは、季節[きせつ]の流[なが]れとして理[り]に合[あ]っている。", "sentence_source": "generated"}, {"text": "昔の人は、星の動きにも理があるはずだと考えた。", "target_word": "理", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]は、星[ほし]の動[うご]きにも理[り]があるはずだと考[かんが]えた。", "sentence_source": "generated"}, {"text": "弟の言い分にも理がある。", "target_word": "理", "complexity_tier": "T3", "furigana": "弟[おとうと]の言[い]い分[ぶん]にも理[り]がある。", "sentence_source": "generated"}, {"text": "勉強は、理を追って考えるとおもしろくなります。", "target_word": "理", "complexity_tier": "T3", "furigana": "勉強[べんきょう]は、理[り]を追[お]って考[かんが]えるとおもしろくなります。", "sentence_source": "generated"}, {"text": "水が高いところから低いところへ流れるのは、理にかなっている。", "target_word": "理", "complexity_tier": "T3", "furigana": "水[みず]が高[たか]いところから低[ひく]いところへ流[なが]れるのは、理[り]にかなっている。", "sentence_source": "generated"}, {"text": "どんな出来事にも、理にかなった説明がつくものだ。", "target_word": "理", "complexity_tier": "T3", "furigana": "どんな出来事[できごと]にも、理[り]にかなった説明[せつめい]がつくものだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "理", "label": "基本形"}], "register": "文章語", "sense_fingerprint": "ものごとのしくみやそうなる道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba344cc6-eef7-4152-b08a-769bb2bfac14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52563, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "理", "is_correct": true, "explanation": "正解は「理」。「雨が降るわけには理がある」で、そうなる道理を表す。"}, {"text": "期限", "is_correct": false, "explanation": "「期限」は締め切りの意味で、「雨が降るのには期限がある」は合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "「年齢」は人の年の数で、雨の降る理由には当てはまらない。"}, {"text": "順番", "is_correct": false, "explanation": "「順番」は並ぶ順序で、「ちゃんと順番がある」は不自然。"}], "explanations": {"理": "正解は「理」。「雨が降るわけには理がある」で、そうなる道理を表す。", "期限": "「期限」は締め切りの意味で、「雨が降るのには期限がある」は合わない。", "年齢": "「年齢」は人の年の数で、雨の降る理由には当てはまらない。", "順番": "「順番」は並ぶ順序で、「ちゃんと順番がある」は不自然。"}, "sentence_index": 0, "correct_answer": "理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日の理を決めた。", "explanation": "ここは〈予定〉の置き換え。理は〈しくみ・道理〉で、予定の意味は持たない。"}, {"text": "映画の理を友達に話した。", "explanation": "ここは〈感想〉の置き換え。理は道理やしくみで、感想の意味では使えない。"}, {"text": "この店は月に大きな理を上げている。", "explanation": "ここは〈利〉（利益）の意味。理は〈しくみ・道理〉なので、利益を上げるとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52563, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理", "is_correct": true, "explanation": "正解は「理」。「理がある」で、言い分に道理があるという意味。"}, {"text": "面積", "is_correct": false, "explanation": "「面積」は広さのことで、「言い分に面積がある」は合わない。"}, {"text": "寿命", "is_correct": false, "explanation": "「寿命」は生き続ける期間で、言い分には当てはまらない。"}, {"text": "座席", "is_correct": false, "explanation": "「座席」は座る場所で、言い分に座席があるとは言えない。"}], "explanations": {"理": "正解は「理」。「理がある」で、言い分に道理があるという意味。", "面積": "「面積」は広さのことで、「言い分に面積がある」は合わない。", "寿命": "「寿命」は生き続ける期間で、言い分には当てはまらない。", "座席": "「座席」は座る場所で、言い分に座席があるとは言えない。"}, "sentence_index": 6, "correct_answer": "理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅の理を決めた。", "explanation": "ここは〈目的〉の意味。理は道理やしくみで、目的の代わりにはならない。"}, {"text": "試合の理を発表した。", "explanation": "ここは〈結果〉の意味。理は道理やしくみで、試合の結果は指せない。"}, {"text": "目的のための理を選んだ。", "explanation": "ここは〈手段〉の意味。理は道理やしくみで、手段の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
