INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52564, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「理に従う」で、従う対象を表す「に」。"}, {"text": "を", "is_correct": false, "explanation": "「理を従う」は不自然。「従う」の対象は「に」で示す。"}, {"text": "で", "is_correct": false, "explanation": "「理で従う」は手段の意味にならず、文が成立しない。"}, {"text": "と", "is_correct": false, "explanation": "「理と従う」は並列の意味にならず、誤り。"}], "correct_answer": "に", "explanations": {"に": "「理に従う」で、従う対象を表す「に」。", "を": "「理を従う」は不自然。「従う」の対象は「に」で示す。", "で": "「理で従う」は手段の意味にならず、文が成立しない。", "と": "「理と従う」は並列の意味にならず、誤り。"}, "error_tags": {"を": "目的語", "で": "手段", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52564, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の筋道や道理。また、正しい判断や考え方の基準。", "primary_collocate": null, "pronunciation": "り", "ipa": "ɾi", "syllable_count": 1, "sentences": [{"text": "その判断には、ちゃんと理がある。", "target_word": "理", "complexity_tier": "T3", "furigana": "その判断[はんだん]には、ちゃんと理[り]がある。", "sentence_source": "generated"}, {"text": "その論文には、理の通った議論が貫かれている。", "target_word": "理", "complexity_tier": "T4", "furigana": "その論文[ろんぶん]には、理[り]の通[とお]った議論[ぎろん]が貫[つらぬ]かれている。", "sentence_source": "generated"}, {"text": "この製作の全工程は、まさに宇宙の理を机の上に縮図として描き出す、崇高な知的探究なのである。", "target_word": "理", "complexity_tier": "T4", "furigana": "この製作[せいさく]の全工程[ぜんこうてい]は、まさに宇宙[うちゅう]の理[り]を机[つくえ]の上[うえ]に縮図[しゅくず]として描[えが]き出[だ]す、崇高[すうこう]な知的[ちてき]探究[たんきゅう]なのである。", "sentence_source": "mined"}, {"text": "彼の主張は理にかなっているので、反対する人はいなかった。", "target_word": "理", "complexity_tier": "T3", "furigana": "彼[かれ]の主張[しゅちょう]は理[り]にかなっているので、反対[はんたい]する人[ひと]はいなかった。", "sentence_source": "generated"}, {"text": "この問題は、理を尽くして話し合うしかない。", "target_word": "理", "complexity_tier": "T3", "furigana": "この問題[もんだい]は、理[り]を尽[つ]くして話[はな]し合[あ]うしかない。", "sentence_source": "generated"}, {"text": "その計画には理が通っていて、すぐに実行に移された。", "target_word": "理", "complexity_tier": "T3", "furigana": "その計画[けいかく]には理[り]が通[とお]っていて、すぐに実行[じっこう]に移[うつ]された。", "sentence_source": "generated"}, {"text": "この考え方には理があると思う。", "target_word": "理", "complexity_tier": "T3", "furigana": "この考え方[かんがえかた]には理[り]があると思[おも]う。", "sentence_source": "generated"}, {"text": "理に従って判断すれば、答えは自然に決まる。", "target_word": "理", "complexity_tier": "T3", "furigana": "理[り]に従[したが]って判断[はんだん]すれば、答[こた]えは自然[しぜん]に決[き]まる。", "sentence_source": "generated"}, {"text": "昔の人は、畑仕事の失敗を重ねて、理にかなったやり方を見つけた。", "target_word": "理", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]は、畑仕事[はたけしごと]の失敗[しっぱい]を重[かさ]ねて、理[り]にかなったやり方[かた]を見[み]つけた。", "sentence_source": "generated"}, {"text": "彼は感情ではなく理を重んじて、冷静に結論を出した。", "target_word": "理", "complexity_tier": "T3", "furigana": "彼[かれ]は感情[かんじょう]ではなく理[り]を重[おも]んじて、冷静[れいせい]に結論[けつろん]を出[だ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "理", "label": "基本形"}], "register": "文章語", "sense_fingerprint": "物事の筋道・道理、正しい判断の基準", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T3: 4 words above tier T3 (max 3): 縮図 (Zipf 2.69), 描き出す (Zipf 2.48), 崇高 (Zipf 3.16), 探究 (Zipf 3.15)']::text[], 'ba344cc6-eef7-4152-b08a-769bb2bfac14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52564, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "理", "is_correct": true, "explanation": "正解は「理」。「理がある」で、判断に道理があるという意味。"}, {"text": "面積", "is_correct": false, "explanation": "「面積」は広さのことで、判断に面積があるとは言えない。"}, {"text": "座席", "is_correct": false, "explanation": "「座席」は座る場所で、判断に座席があるとは言えない。"}, {"text": "体重", "is_correct": false, "explanation": "「体重」は重さのことで、判断の意味には当てはまらない。"}], "explanations": {"理": "正解は「理」。「理がある」で、判断に道理があるという意味。", "面積": "「面積」は広さのことで、判断に面積があるとは言えない。", "座席": "「座席」は座る場所で、判断に座席があるとは言えない。", "体重": "「体重」は重さのことで、判断の意味には当てはまらない。"}, "sentence_index": 0, "correct_answer": "理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この言葉の理を辞書で調べた。", "explanation": "ここは〈意味〉の置き換え。理は〈道理〉で、言葉の意味は指せないので誤り。"}, {"text": "休んだ理を先生に説明した。", "explanation": "ここは〈理由〉の置き換え。理は〈筋道・道理〉で、休んだ理由の代わりにはならない。"}, {"text": "テストの理を書いた。", "explanation": "ここは〈答え〉の置き換え。理は道理であり、答案に書く答えの意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52564, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理", "is_correct": true, "explanation": "正解は「理」。「理がある」で、考え方の道理があるという意味。"}, {"text": "期限", "is_correct": false, "explanation": "「期限」は締め切りの意味で、「考え方には期限がある」は合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "「年齢」は人の年の数で、考え方には当てはまらない。"}, {"text": "座席", "is_correct": false, "explanation": "「座席」は座る場所で、考え方に座席があるとは言えない。"}], "explanations": {"理": "正解は「理」。「理がある」で、考え方の道理があるという意味。", "期限": "「期限」は締め切りの意味で、「考え方には期限がある」は合わない。", "年齢": "「年齢」は人の年の数で、考え方には当てはまらない。", "座席": "「座席」は座る場所で、考え方に座席があるとは言えない。"}, "sentence_index": 6, "correct_answer": "理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この会社は毎年大きな理を上げている。", "explanation": "ここは〈利〉（利益）の意味。理は〈道理〉なので、利益を上げるとは言えない。"}, {"text": "旅の理を先生に話した。", "explanation": "ここは〈目的〉の意味。理は道理で、旅の目的の代わりにはならない。"}, {"text": "次のレポートに理を書いた。", "explanation": "ここは〈感想〉の意味。理は道理なので、感想として書く内容にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52564, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その方法は理にかなうている。", "corrected_sentence": "その方法は理にかなっている。", "error_description": "「理にかなう」の継続形は「かなっている」。「かなうている」は誤った活用形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52564, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その説明には理を通っている。", "corrected_sentence": "その説明には理が通っている。", "error_description": "「理が通る」の主語は「が」。「理を通る」は助詞が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
