INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52567, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とても高くて立派で、大切にしたい気持ちになること。", "primary_collocate": null, "pronunciation": "すうこう", "ipa": "sɯːkoː", "syllable_count": 4, "sentences": [{"text": "彼女は、人々を救うという崇高な目的のために働いている。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は、人々[ひとびと]を救[すく]うという崇高[すうこう]な目的[もくてき]のために働[はたら]いている。", "sentence_source": "generated"}, {"text": "山頂から見た朝日は、言葉を失うほど崇高だった。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "山頂[さんちょう]から見[み]た朝日[あさひ]は、言葉[ことば]を失[うしな]うほど崇高[すうこう]だった。", "sentence_source": "generated"}, {"text": "医者という仕事を崇高な使命と考えて、彼は一生を捧げた。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "医者[いしゃ]という仕事[しごと]を崇高[すうこう]な使命[しめい]と考[かんが]えて、彼[かれ]は一生[いっしょう]を捧[ささ]げた。", "sentence_source": "generated"}, {"text": "厳しい戦争の中でも、他人を助けた彼の行いは崇高だ。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "厳[きび]しい戦争[せんそう]の中[なか]でも、他人[たにん]を助[たす]けた彼[かれ]の行[おこな]いは崇高[すうこう]だ。", "sentence_source": "generated"}, {"text": "崇高な理想を持つことと、それを実現することは別の問題だ。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "崇高[すうこう]な理想[りそう]を持[も]つことと、それを実現[じつげん]することは別[べつ]の問題[もんだい]だ。", "sentence_source": "generated"}, {"text": "美しさと恐ろしさをあわせ持つ大自然には、崇高な力を感じる。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "美[うつく]しさと恐[おそ]ろしさをあわせ持[も]つ大自然[だいしぜん]には、崇高[すうこう]な力[ちから]を感[かん]じる。", "sentence_source": "generated"}, {"text": "多くの人が、その僧の崇高な生き方に心を打たれた。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "多[おお]くの人[ひと]が、その僧[そう]の崇高[すうこう]な生[い]き方[かた]に心[こころ]を打[う]たれた。", "sentence_source": "generated"}, {"text": "彼は金のためではなく、崇高な精神から仕事を引き受けた。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "彼[かれ]は金[かね]のためではなく、崇高[すうこう]な精神[せいしん]から仕事[しごと]を引[ひ]き受[う]けた。", "sentence_source": "generated"}, {"text": "国民を守った兵士の崇高な犠牲に、人々は深く頭を下げた。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "国民[こくみん]を守[まも]った兵士[へいし]の崇高[すうこう]な犠牲[ぎせい]に、人々[ひとびと]は深[ふか]く頭[あたま]を下[さ]げた。", "sentence_source": "generated"}, {"text": "この絵に描かれた聖母の顔は、崇高で近づきがたい。", "target_word": "崇高", "complexity_tier": "T3", "furigana": "この絵[え]に描[えが]かれた聖母[せいぼ]の顔[かお]は、崇高[すうこう]で近[ちか]づきがたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "崇高", "label": "基本形"}, {"form": "崇高な", "label": "連体形"}, {"form": "崇高だ", "label": "終止形"}, {"form": "崇高で", "label": "連用形"}], "register": "formal", "sense_fingerprint": "気高く立派で、尊敬や畏敬の念を起こさせる様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e68b13-de29-4e18-b8c1-858f5a03d21e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52567, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "崇高", "is_correct": true, "explanation": "「崇高な目的」は、人々を救う目的を気高いと評価する語で、この文の意味に合う。"}, {"text": "陽気", "is_correct": false, "explanation": "陽気は明るく快活な性格を表すので、目的を修飾すると意味が通らない。"}, {"text": "柔軟", "is_correct": false, "explanation": "柔軟は考え方がしなやかなことを表し、目的の性質を説明する語としては使えない。"}, {"text": "活発", "is_correct": false, "explanation": "活発は動きや活動が盛んなことを表し、「目的」を修飾すると不自然になる。"}], "explanations": {"崇高": "「崇高な目的」は、人々を救う目的を気高いと評価する語で、この文の意味に合う。", "陽気": "陽気は明るく快活な性格を表すので、目的を修飾すると意味が通らない。", "柔軟": "柔軟は考え方がしなやかなことを表し、目的の性質を説明する語としては使えない。", "活発": "活発は動きや活動が盛んなことを表し、「目的」を修飾すると不自然になる。"}, "sentence_index": 0, "correct_answer": "崇高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は崇高な趣味を持ち、休日はいつも美術館に通っている。", "explanation": "ここは〈高尚〉の意味（上品で教養がある）。崇高は理想や精神の尊さを表すので、趣味の説明には合わない。"}, {"text": "このホテルは崇高な設備がそろっていて、客の評判がいい。", "explanation": "ここは〈高級〉の意味。崇高は精神的に気高い様子を表し、設備の品質には使わない。"}, {"text": "崇高なシャンデリアが広間を照らしていた。", "explanation": "ここは〈豪華〉の意味（きらびやかで立派）。崇高は精神や理想の尊さを表し、照明器具の見た目には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52567, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "崇高", "is_correct": true, "explanation": "「生き方」を尊く気高いものとして評価する語で、この文の意味に合う。"}, {"text": "露骨", "is_correct": false, "explanation": "露骨はあからさまで遠慮がない様子を表し、生き方への評価には合わない。"}, {"text": "無礼", "is_correct": false, "explanation": "無礼は礼儀を欠く様子を表し、「心を打たれた」という文脈と矛盾する。"}, {"text": "乱暴", "is_correct": false, "explanation": "乱暴は荒々しく粗い振る舞いを表し、僧の生き方を説明する語としては合わない。"}], "explanations": {"崇高": "「生き方」を尊く気高いものとして評価する語で、この文の意味に合う。", "露骨": "露骨はあからさまで遠慮がない様子を表し、生き方への評価には合わない。", "無礼": "無礼は礼儀を欠く様子を表し、「心を打たれた」という文脈と矛盾する。", "乱暴": "乱暴は荒々しく粗い振る舞いを表し、僧の生き方を説明する語としては合わない。"}, "sentence_index": 6, "correct_answer": "崇高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その壁は崇高な高さで、誰も越えられなかった。", "explanation": "ここは〈高い〉の意味（物の高さ）。崇高は精神や理想の尊さを表すので、壁の高さには使わない。"}, {"text": "崇高な音量で歌ったので、隣の部屋まで聞こえた。", "explanation": "ここは〈大きい〉の意味（音量が大きい）。崇高は精神や理想の尊さを表すので、音量には使わない。"}, {"text": "崇高な服装で面接に来た。", "explanation": "ここは〈清楚〉の意味（清らかで品がある）。崇高は精神や理想の尊さを表すので、服装には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52567, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その行いは崇高くて、誰もが感動した。", "corrected_sentence": "その行いは崇高で、誰もが感動した。", "error_description": "活用の誤り。「崇高」は形状詞なので「くて」ではなく「で」で続ける。正しくは「崇高で」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "崇高", "is_correct": true, "explanation": "「だった」の直前に置く語幹形で、文中の形と一致する。"}, {"text": "崇高な", "is_correct": false, "explanation": "連体形。名詞の前に付く形なので、「だった」の前には置けない。"}, {"text": "崇高で", "is_correct": false, "explanation": "連用形。後ろへつなぐ形で、「だった」と続けると文が成り立たない。"}, {"text": "崇高だ", "is_correct": false, "explanation": "終止形。「だった」と重なって「崇高だだった」となり誤り。"}], "correct_form": "崇高", "base_form": "崇高", "form_label": "「だった」の前に置く語幹形", "sentence_index": 1, "explanations": {"崇高": "「だった」の直前に置く語幹形で、文中の形と一致する。", "崇高な": "連体形。名詞の前に付く形なので、「だった」の前には置けない。", "崇高で": "連用形。後ろへつなぐ形で、「だった」と続けると文が成り立たない。", "崇高だ": "終止形。「だった」と重なって「崇高だだった」となり誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52567, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は崇高だ精神を持つ人物として知られている。", "corrected_sentence": "彼は崇高な精神を持つ人物として知られている。", "error_description": "形容動詞「崇高」は終止形「だ」のままでは名詞の前に置けない。連体形「な」を使い、正しくは「崇高な精神」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "崇高", "is_correct": true, "explanation": "「な精神」に続く語幹形で、文中の形と一致する。"}, {"text": "崇高さ", "is_correct": false, "explanation": "名詞化した形（〜さ）。「精神」を直接修飾できず、「な精神」の形にならない。"}, {"text": "崇高に", "is_correct": false, "explanation": "副詞的な連用形。「精神」を修飾できず、「な精神」として続かない。"}, {"text": "崇高だった", "is_correct": false, "explanation": "過去の終止形。名詞を修飾できず、「な精神」の前には入らない。"}], "correct_form": "崇高", "base_form": "崇高", "form_label": "「な精神」の前に置く語幹形", "sentence_index": 7, "explanations": {"崇高": "「な精神」に続く語幹形で、文中の形と一致する。", "崇高さ": "名詞化した形（〜さ）。「精神」を直接修飾できず、「な精神」の形にならない。", "崇高に": "副詞的な連用形。「精神」を修飾できず、「な精神」として続かない。", "崇高だった": "過去の終止形。名詞を修飾できず、「な精神」の前には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52569, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「町を描き出した」の「を」。描き出す対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「町に描き出した」は対象を示せず、文が成立しない。"}, {"text": "で", "is_correct": false, "explanation": "「町で描き出した」は手段の意味にならず、不自然。"}, {"text": "より", "is_correct": false, "explanation": "「町より描き出した」は比較の意味になり、文に合わない。"}], "correct_answer": "を", "explanations": {"を": "「町を描き出した」の「を」。描き出す対象を示す。", "に": "「町に描き出した」は対象を示せず、文が成立しない。", "で": "「町で描き出した」は手段の意味にならず、不自然。", "より": "「町より描き出した」は比較の意味になり、文に合わない。"}, "error_tags": {"に": "方向", "で": "手段", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52569, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「いきいきと描き出している」の「と」。様子を表す語に付く「と」。"}, {"text": "へ", "is_correct": false, "explanation": "「いきいきへ描き出している」は成立せず、「へ」は方向を表すので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「いきいきから描き出している」は起点の意味になり、文が不自然。"}, {"text": "の", "is_correct": false, "explanation": "「いきいきの描き出している」は文法的に成立しない。"}], "correct_answer": "と", "explanations": {"と": "「いきいきと描き出している」の「と」。様子を表す語に付く「と」。", "へ": "「いきいきへ描き出している」は成立せず、「へ」は方向を表すので合わない。", "から": "「いきいきから描き出している」は起点の意味になり、文が不自然。", "の": "「いきいきの描き出している」は文法的に成立しない。"}, "error_tags": {"へ": "方向", "から": "起点", "の": "所属"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52569, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "絵をかくように、ようすをはっきりとあらわすこと。", "primary_collocate": null, "pronunciation": "えがきだす", "ipa": "eɡakidasɯ", "syllable_count": 5, "sentences": [{"text": "この本は、森の中のようすをはっきり描き出している。", "target_word": "描き出", "complexity_tier": "T3", "furigana": "この本[ほん]は、森[もり]の中[なか]のようすをはっきり描[えが]き出[だ]している。", "sentence_source": "generated"}, {"text": "昨日の作文で、祭りの日の町を描き出した。", "target_word": "描き出した", "complexity_tier": "T3", "furigana": "昨日[きのう]の作文[さくぶん]で、祭[まつ]りの日[ひ]の町[まち]を描[えが]き出[だ]した。", "sentence_source": "generated"}, {"text": "彼女は言葉で、海の青さを描き出した。", "target_word": "描き出した", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は言葉[ことば]で、海[うみ]の青[あお]さを描[えが]き出[だ]した。", "sentence_source": "generated"}, {"text": "その映画は、家族のあたたかさを描き出している。", "target_word": "描き出", "complexity_tier": "T3", "furigana": "その映画[えいが]は、家族[かぞく]のあたたかさを描[えが]き出[だ]している。", "sentence_source": "generated"}, {"text": "先生の話は、昔の村の生活を目に見えるように描き出した。", "target_word": "描き出した", "complexity_tier": "T3", "furigana": "先生[せんせい]の話[はなし]は、昔[むかし]の村[むら]の生活[せいかつ]を目[め]に見[み]えるように描[えが]き出[だ]した。", "sentence_source": "generated"}, {"text": "絵本は、雪の朝の静かなようすを描き出す。", "target_word": "描き出す", "complexity_tier": "T3", "furigana": "絵本[えほん]は、雪[ゆき]の朝[あさ]の静[しず]かなようすを描[えが]き出[だ]す。", "sentence_source": "generated"}, {"text": "詩人は、秋の夕方の色を描き出した。", "target_word": "描き出した", "complexity_tier": "T3", "furigana": "詩人[しじん]は、秋[あき]の夕方[ゆうがた]の色[いろ]を描[えが]き出[だ]した。", "sentence_source": "generated"}, {"text": "兄の日記は、旅の一日をいきいきと描き出している。", "target_word": "描き出", "complexity_tier": "T3", "furigana": "兄[あに]の日記[にっき]は、旅[たび]の一日[いちにち]をいきいきと描[えが]き出[だ]している。", "sentence_source": "generated"}, {"text": "この歌は、故郷の風景を描き出している。", "target_word": "描き出", "complexity_tier": "T3", "furigana": "この歌[うた]は、故郷[こきょう]の風景[ふうけい]を描[えが]き出[だ]している。", "sentence_source": "generated"}, {"text": "彼は短い文で、あの夏の暑さを描き出した。", "target_word": "描き出した", "complexity_tier": "T3", "furigana": "彼[かれ]は短[みじか]い文[ぶん]で、あの夏[なつ]の暑[あつ]さを描[えが]き出[だ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "描き出す", "label": "終止形"}, {"form": "描き出した", "label": "過去形"}, {"form": "描き出して", "label": "て形"}, {"form": "描き出さない", "label": "否定形"}, {"form": "描き出し", "label": "連用形"}, {"form": "描き出せる", "label": "可能形"}], "register": "中立", "sense_fingerprint": "絵のようにようすをはっきり言葉や作品で表す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba344cc6-eef7-4152-b08a-769bb2bfac14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52569, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "描き出", "is_correct": true, "explanation": "正解は「描き出」。「はっきり描き出している」で、ようすを明確に表す意味。"}, {"text": "描き", "is_correct": false, "explanation": "「はっきり描きしている」は文法的に成立しない。"}, {"text": "見せ", "is_correct": false, "explanation": "「はっきり見せしている」は成立せず、文に合わない。"}, {"text": "作り", "is_correct": false, "explanation": "「はっきり作りしている」は不自然で、ようすを表す意味にならない。"}], "explanations": {"描き出": "正解は「描き出」。「はっきり描き出している」で、ようすを明確に表す意味。", "描き": "「はっきり描きしている」は文法的に成立しない。", "見せ": "「はっきり見せしている」は成立せず、文に合わない。", "作り": "「はっきり作りしている」は不自然で、ようすを表す意味にならない。"}, "sentence_index": 0, "correct_answer": "描き出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "かばんから財布を描き出した。", "explanation": "ここは〈取り出す〉の意味。描き出すは様子を表す語で、物を取り出す動作には使わない。"}, {"text": "先生に手紙を描き出した。", "explanation": "ここは〈差し出す〉の意味。描き出すは手渡す動作ではないので誤り。"}, {"text": "会議の話題を描き出した。", "explanation": "ここは〈切り出す〉の意味。描き出すは様子を表すので、話題を切り出す意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52569, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "描き出した", "is_correct": true, "explanation": "正解は「描き出した」。秋の夕方の色を、ようすとして明確に表した意味になる。"}, {"text": "洗った", "is_correct": false, "explanation": "「色を洗った」は意味が通らず、文に合わない。"}, {"text": "割った", "is_correct": false, "explanation": "「色を割った」は意味が通らず、文脈に合わない。"}, {"text": "踏んだ", "is_correct": false, "explanation": "「色を踏んだ」は意味が通らず、文に合わない。"}], "explanations": {"描き出した": "正解は「描き出した」。秋の夕方の色を、ようすとして明確に表した意味になる。", "洗った": "「色を洗った」は意味が通らず、文に合わない。", "割った": "「色を割った」は意味が通らず、文脈に合わない。", "踏んだ": "「色を踏んだ」は意味が通らず、文に合わない。"}, "sentence_index": 6, "correct_answer": "描き出した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "銀行でお金を描き出した。", "explanation": "ここは〈引き出す〉の意味。描き出すは様子を言葉や絵で表す語で、お金は描けない。"}, {"text": "土の中から宝物を描き出した。", "explanation": "ここは〈掘り出す〉の意味。描き出すは物を掘る動作ではないので誤り。"}, {"text": "本から大事な一文を描き出した。", "explanation": "ここは〈抜き出す〉の意味。描き出すは文章を抜粋する動作ではなく、ようすを表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52569, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その文章は、雨の日の町を描き出いる。", "corrected_sentence": "その文章は、雨の日の町を描き出している。", "error_description": "「描き出している」の「して」が抜けている。「描き出いる」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "描き出した", "is_correct": true, "explanation": "正解は「描き出した」。作文で町を描いた過去の出来事なので、過去形が文末に合う。"}, {"text": "描き出す", "is_correct": false, "explanation": "「描き出す」は非過去の形で、過去の出来事を述べる文末には合わない。"}, {"text": "描き出して", "is_correct": false, "explanation": "て形は文を言い切れないため、文末の「した」の位置には入らない。"}, {"text": "描き出せる", "is_correct": false, "explanation": "可能形は「描ける」という能力の意味になり、実際に描いた出来事とは合わない。"}], "correct_form": "描き出した", "base_form": "描き出す", "form_label": "過去形", "sentence_index": 1, "explanations": {"描き出した": "正解は「描き出した」。作文で町を描いた過去の出来事なので、過去形が文末に合う。", "描き出す": "「描き出す」は非過去の形で、過去の出来事を述べる文末には合わない。", "描き出して": "て形は文を言い切れないため、文末の「した」の位置には入らない。", "描き出せる": "可能形は「描ける」という能力の意味になり、実際に描いた出来事とは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52569, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その写真は、都会の孤独を描き出するている。", "corrected_sentence": "その写真は、都会の孤独を描き出している。", "error_description": "「描き出している」が正しい。「描き出するている」は余分な「する」が入った誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "描き出し", "is_correct": true, "explanation": "正解は「描き出し」。「描き出している」の「ている」の前で、連用形として続く。"}, {"text": "描き出さない", "is_correct": false, "explanation": "否定形の「描き出さない」は「している」の前には置けず、「描き出さないしている」は成立しない。"}, {"text": "描き出そう", "is_correct": false, "explanation": "意向形の「描き出そう」は「と」を挟まないと「している」に続かず、「描き出そうしている」は不自然で文に合わない。"}, {"text": "描き出して", "is_correct": false, "explanation": "て形は「ている」と続けると「描き出してている」となり、成立しない。"}], "correct_form": "描き出し", "base_form": "描き出す", "form_label": "連用形", "sentence_index": 7, "explanations": {"描き出し": "正解は「描き出し」。「描き出している」の「ている」の前で、連用形として続く。", "描き出さない": "否定形の「描き出さない」は「している」の前には置けず、「描き出さないしている」は成立しない。", "描き出そう": "意向形の「描き出そう」は「と」を挟まないと「している」に続かず、「描き出そうしている」は不自然で文に合わない。", "描き出して": "て形は「ている」と続けると「描き出してている」となり、成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52570, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52570, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「描き出そうとした」の「と」。「〜うとする」の形で、試みた意味になる。"}, {"text": "が", "is_correct": false, "explanation": "「描き出そうがした」は文法的に成立せず、「が」は合わない。"}, {"text": "で", "is_correct": false, "explanation": "「描き出そうでした」は成立せず、「で」は文に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「描き出そうへした」は成立せず、「へ」は方向を表すので合わない。"}], "correct_answer": "と", "explanations": {"と": "「描き出そうとした」の「と」。「〜うとする」の形で、試みた意味になる。", "が": "「描き出そうがした」は文法的に成立せず、「が」は合わない。", "で": "「描き出そうでした」は成立せず、「で」は文に合わない。", "へ": "「描き出そうへした」は成立せず、「へ」は方向を表すので合わない。"}, "error_tags": {"が": "主語", "で": "手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52570, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "細かいところまで詳しく描写する。はっきりと描く。", "primary_collocate": null, "pronunciation": "えがきだす", "ipa": "eɡakidasɯ", "syllable_count": 5, "sentences": [{"text": "この製作の全工程は、まさに宇宙の理を机の上に縮図として描き出す、崇高な知的探究なのである。", "target_word": "描き出す", "complexity_tier": "T4", "furigana": "この製作[せいさく]の全工程[ぜんこうてい]は、まさに宇宙[うちゅう]の理[り]を机[つくえ]の上[うえ]に縮図[しゅくず]として描[えが]き出[だ]す、崇高[すうこう]な知的[ちてき]探究[たんきゅう]なのである。", "sentence_source": "mined"}, {"text": "この小説は、戦後の貧しい暮らしを細部まで描き出している。", "target_word": "描き出", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は、戦後[せんご]の貧[まず]しい暮[く]らしを細部[さいぶ]まで描[えが]き出[だ]している。", "sentence_source": "generated"}, {"text": "画家は、一本の線で港町の朝の空気を描き出した。", "target_word": "描き出した", "complexity_tier": "T3", "furigana": "画家[がか]は、一本[いっぽん]の線[せん]で港町[みなとまち]の朝[あさ]の空気[くうき]を描[えが]き出[だ]した。", "sentence_source": "generated"}, {"text": "監督は、移民の家族の苦労を丁寧に描き出す。", "target_word": "描き出す", "complexity_tier": "T3", "furigana": "監督[かんとく]は、移民[いみん]の家族[かぞく]の苦労[くろう]を丁寧[ていねい]に描[えが]き出[だ]す。", "sentence_source": "generated"}, {"text": "その写真集は、都会の孤独をありありと描き出している。", "target_word": "描き出", "complexity_tier": "T3", "furigana": "その写真集[しゃしんしゅう]は、都会[とかい]の孤独[こどく]をありありと描[えが]き出[だ]している。", "sentence_source": "generated"}, {"text": "彼女の文章は、人物の心の揺れを鮮やかに描き出す。", "target_word": "描き出す", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の文章[ぶんしょう]は、人物[じんぶつ]の心[こころ]の揺[ゆ]れを鮮[あざ]やかに描[えが]き出[だ]す。", "sentence_source": "generated"}, {"text": "映画は、戦争が普通の人々に残した傷を描き出した。", "target_word": "描き出した", "complexity_tier": "T3", "furigana": "映画[えいが]は、戦争[せんそう]が普通[ふつう]の人々[ひとびと]に残[のこ]した傷[きず]を描[えが]き出[だ]した。", "sentence_source": "generated"}, {"text": "作者は、江戸の町人の暮らしをいきいきと描き出そうとした。", "target_word": "描き出そう", "complexity_tier": "T3", "furigana": "作者[さくしゃ]は、江戸[えど]の町人[ちょうにん]の暮[く]らしをいきいきと描[えが]き出[だ]そうとした。", "sentence_source": "generated"}, {"text": "この絵は、雨上がりの町の湿った空気まで描き出している。", "target_word": "描き出している", "complexity_tier": "T3", "furigana": "この絵[え]は、雨上がり[あまあがり]の町[まち]の湿[しめ]った空気[くうき]まで描[えが]き出[だ]している。", "sentence_source": "generated"}, {"text": "彼の短い詩は、冬の夜の静けさを描き出した。", "target_word": "描き出した", "complexity_tier": "T3", "furigana": "彼[かれ]の短[みじか]い詩[し]は、冬[ふゆ]の夜[よる]の静[しず]けさを描[えが]き出[だ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "描き出す", "label": "終止形"}, {"form": "描き出した", "label": "過去形"}, {"form": "描き出して", "label": "て形"}, {"form": "描き出さない", "label": "否定形"}, {"form": "描き出し", "label": "連用形"}, {"form": "描き出せる", "label": "可能形"}], "register": "中立", "sense_fingerprint": "細部まで詳しくはっきりと描写する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba344cc6-eef7-4152-b08a-769bb2bfac14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52570, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "描き出す", "is_correct": true, "explanation": "正解は「描き出す」。宇宙の理を縮図として詳しく表す、という意味に合う。"}, {"text": "割る", "is_correct": false, "explanation": "「縮図として割る」は意味が通らず、文に合わない。"}, {"text": "洗う", "is_correct": false, "explanation": "「縮図として洗う」は意味が通らず、文に合わない。"}, {"text": "止める", "is_correct": false, "explanation": "「縮図として止める」は文脈に合わず、意味が通らない。"}], "explanations": {"描き出す": "正解は「描き出す」。宇宙の理を縮図として詳しく表す、という意味に合う。", "割る": "「縮図として割る」は意味が通らず、文に合わない。", "洗う": "「縮図として洗う」は意味が通らず、文に合わない。", "止める": "「縮図として止める」は文脈に合わず、意味が通らない。"}, "sentence_index": 0, "correct_answer": "描き出す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "銀行でお金を描き出した。", "explanation": "ここは〈引き出す〉の意味。描き出すは様子を言葉や絵で詳しく表す語で、お金は描けない。"}, {"text": "ポケットからハンカチを描き出した。", "explanation": "ここは〈取り出す〉の意味。描き出すは物を出す動作ではないので誤り。"}, {"text": "買い物のリストを描き出した。", "explanation": "ここは〈書き出す〉の意味。描き出すは書き並べる動作ではなく、様子を表す動詞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52570, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "描き出した", "is_correct": true, "explanation": "正解は「描き出した」。戦争が残した傷を詳しく表す、という意味に合う。"}, {"text": "踏んだ", "is_correct": false, "explanation": "「傷を踏んだ」は意味が通らず、文脈に合わない。"}, {"text": "投げた", "is_correct": false, "explanation": "「傷を投げた」は意味が通らず、文に合わない。"}, {"text": "沸かした", "is_correct": false, "explanation": "「傷を沸かした」は意味が通らず、文に合わない。"}], "explanations": {"描き出した": "正解は「描き出した」。戦争が残した傷を詳しく表す、という意味に合う。", "踏んだ": "「傷を踏んだ」は意味が通らず、文脈に合わない。", "投げた": "「傷を投げた」は意味が通らず、文に合わない。", "沸かした": "「傷を沸かした」は意味が通らず、文に合わない。"}, "sentence_index": 6, "correct_answer": "描き出した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "土の中から宝物を描き出した。", "explanation": "ここは〈掘り出す〉の意味。描き出すは様子を表す動詞で、物を掘り出す意味はない。"}, {"text": "先生に手紙を描き出した。", "explanation": "ここは〈差し出す〉の意味。描き出すは手渡す動作ではないので誤り。"}, {"text": "本から大事な一文を描き出した。", "explanation": "ここは〈抜き出す〉の意味。描き出すは文章を抜粋する動作ではなく、様子を表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52570, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作者は、町の姿を描き出しる。", "corrected_sentence": "作者は、町の姿を描き出した。", "error_description": "過去形は「描き出した」。「描き出しる」は活用として存在しない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "描き出し", "is_correct": true, "explanation": "正解は「描き出し」。「描き出している」の「ている」の前で、連用形として続く。"}, {"text": "描き出す", "is_correct": false, "explanation": "終止形の「描き出す」は「している」の前に置けず、「描き出すしている」は誤り。"}, {"text": "描き出した", "is_correct": false, "explanation": "過去形は「している」と続かず、「描き出したしている」は誤り。"}, {"text": "描き出して", "is_correct": false, "explanation": "て形は「ている」と続けると「描き出してている」となり、成立しない。"}], "correct_form": "描き出し", "base_form": "描き出す", "form_label": "連用形", "sentence_index": 1, "explanations": {"描き出し": "正解は「描き出し」。「描き出している」の「ている」の前で、連用形として続く。", "描き出す": "終止形の「描き出す」は「している」の前に置けず、「描き出すしている」は誤り。", "描き出した": "過去形は「している」と続かず、「描き出したしている」は誤り。", "描き出して": "て形は「ている」と続けると「描き出してている」となり、成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52570, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作者は、町の暮らしを描き出さた。", "corrected_sentence": "作者は、町の暮らしを描き出した。", "error_description": "「描き出す」の過去形は「描き出した」。「描き出さた」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "描き出そう", "is_correct": true, "explanation": "正解は「描き出そう」。意志を表す形で、「とした」と続けて試みたという意味になる。"}, {"text": "描き出して", "is_correct": false, "explanation": "て形は「とした」と続かず、「描き出してとした」は文が成立しない。"}, {"text": "描き出し", "is_correct": false, "explanation": "連用形は「とした」と続かず、文が成立しない。"}, {"text": "描き出せ", "is_correct": false, "explanation": "命令形は「とした」と続かず、「描き出せとした」は誤り。"}], "correct_form": "描き出そう", "base_form": "描き出す", "form_label": "意志形", "sentence_index": 7, "explanations": {"描き出そう": "正解は「描き出そう」。意志を表す形で、「とした」と続けて試みたという意味になる。", "描き出して": "て形は「とした」と続かず、「描き出してとした」は文が成立しない。", "描き出し": "連用形は「とした」と続かず、文が成立しない。", "描き出せ": "命令形は「とした」と続かず、「描き出せとした」は誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de2e87d-d8b3-4d62-9ef4-2a893ed50514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
