INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52573, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とてもかしこくて、たくさん考える力があること。", "primary_collocate": null, "pronunciation": "ちてき", "ipa": "tɕiteki", "syllable_count": 3, "sentences": [{"text": "あの先生は知的で、どんな質問にもわかりやすく答えてくれる。", "target_word": "知的", "complexity_tier": "T3", "furigana": "あの先生(せんせい)は知的(ちてき)で、どんな質問(しつもん)にもわかりやすく答(こた)えてくれる。", "sentence_source": "generated"}, {"text": "姉は知的な人なので、むずかしい問題もすぐに解いてしまう。", "target_word": "知的", "complexity_tier": "T3", "furigana": "姉(あね)は知的(ちてき)な人(ひと)なので、むずかしい問題(もんだい)もすぐに解(と)いてしまう。", "sentence_source": "generated"}, {"text": "知的な犬として有名なボーダーコリーは、芸をすぐに覚える。", "target_word": "知的", "complexity_tier": "T3", "furigana": "知的(ちてき)な犬(いぬ)として有名(ゆうめい)なボーダーコリーは、芸(げい)をすぐに覚(おぼ)える。", "sentence_source": "generated"}, {"text": "彼は話し方が知的で、初めて会った人にも信頼される。", "target_word": "知的", "complexity_tier": "T3", "furigana": "彼(かれ)は話(はな)し方(かた)が知的(ちてき)で、初(はじ)めて会(あ)った人(ひと)にも信頼(しんらい)される。", "sentence_source": "generated"}, {"text": "知的な女優として知られる彼女は、インタビューでもいつも的確に答える。", "target_word": "知的", "complexity_tier": "T3", "furigana": "知的(ちてき)な女優(じょゆう)として知(し)られる彼女(かのじょ)は、インタビューでもいつも的確(てきかく)に答(こた)える。", "sentence_source": "generated"}, {"text": "弟は小さいころから知的で、大人でも驚くほど質問が鋭かった。", "target_word": "知的", "complexity_tier": "T3", "furigana": "弟(おとうと)は小(ちい)さいころから知的(ちてき)で、大人(おとな)でも驚(おどろ)くほど質問(しつもん)が鋭(するど)かった。", "sentence_source": "generated"}, {"text": "知的な子どもは、答えを教わるより自分で考えることを好む。", "target_word": "知的", "complexity_tier": "T3", "furigana": "知的(ちてき)な子(こ)どもは、答(こた)えを教(おそ)わるより自分(じぶん)で考(かんが)えることを好(この)む。", "sentence_source": "generated"}, {"text": "眼鏡をかけた彼は知的に見えるが、実はとても運動が得意だ。", "target_word": "知的", "complexity_tier": "T3", "furigana": "眼鏡(めがね)をかけた彼(かれ)は知的(ちてき)に見(み)えるが、実(じつ)はとても運動(うんどう)が得意(とくい)だ。", "sentence_source": "generated"}, {"text": "知的な彼女なら、この複雑な問題にも良い答えを出せるだろう。", "target_word": "知的", "complexity_tier": "T3", "furigana": "知的(ちてき)な彼女(かのじょ)なら、この複雑(ふくざつ)な問題(もんだい)にも良(よ)い答(こた)えを出(だ)せるだろう。", "sentence_source": "generated"}, {"text": "校長先生は知的で、生徒の悩みにも的確な助言をくれる。", "target_word": "知的", "complexity_tier": "T3", "furigana": "校長先生(こうちょうせんせい)は知的(ちてき)で、生徒(せいと)の悩(なや)みにも的確(てきかく)な助言(じょげん)をくれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "知的だ", "label": "終止形"}, {"form": "知的な", "label": "連体形"}, {"form": "知的に", "label": "連用形"}, {"form": "知的で", "label": "連用形（で）"}], "register": "neutral", "sense_fingerprint": "人がかしこく、考える力が高いこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e80f88b3-ea1d-43b4-8f13-7d86ed2c4372') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52573, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "知的", "is_correct": true, "explanation": "「先生は知的で」の形。「で」で続けて先生の性質を述べる語幹。"}, {"text": "知的な", "is_correct": false, "explanation": "連体形。「先生は知的な、で」とは続かず、述語として成立しない。"}, {"text": "知的だ", "is_correct": false, "explanation": "終止形。「先生は知的だ、で」となり、「で」の後に続く文が組めない。"}, {"text": "知的に", "is_correct": false, "explanation": "連用形。「先生は知的に、で」となり、先生の性質を表す述語にならない。"}], "explanations": {"知的": "「先生は知的で」の形。「で」で続けて先生の性質を述べる語幹。", "知的な": "連体形。「先生は知的な、で」とは続かず、述語として成立しない。", "知的だ": "終止形。「先生は知的だ、で」となり、「で」の後に続く文が組めない。", "知的に": "連用形。「先生は知的に、で」となり、先生の性質を表す述語にならない。"}, "sentence_index": 0, "correct_answer": "知的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は朝からずっと知的で、いつも元気いっぱいに遊んでいる。", "explanation": "ここは〈活発な〉の意味。動き回る様子に知的を使うのは合わない。"}, {"text": "この自転車は知的で、坂道でもすいすい登る。", "explanation": "ここは〈丈夫な〉の意味。乗り物の性能は知的ではなく丈夫で表す。"}, {"text": "彼は昨日、宿題を知的に忘れてしまった。", "explanation": "ここは〈うっかり〉の意味。失敗の仕方に知的を副詞として使うのは不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52573, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "知的", "is_correct": true, "explanation": "「知的な子ども」の語幹。「な子ども」で名詞を修飾する形で、文中の形と一致する。"}, {"text": "知的さ", "is_correct": false, "explanation": "名詞。「知的さな子ども」となり、子どもを修飾する形として成立しない。"}, {"text": "知的であり", "is_correct": false, "explanation": "中止形。名詞「子ども」を修飾できず、「な子ども」とつながらない。"}, {"text": "知的なら", "is_correct": false, "explanation": "仮定形。「知的なら子ども」となり、名詞を修飾する形として成立しない。"}], "explanations": {"知的": "「知的な子ども」の語幹。「な子ども」で名詞を修飾する形で、文中の形と一致する。", "知的さ": "名詞。「知的さな子ども」となり、子どもを修飾する形として成立しない。", "知的であり": "中止形。名詞「子ども」を修飾できず、「な子ども」とつながらない。", "知的なら": "仮定形。「知的なら子ども」となり、名詞を修飾する形として成立しない。"}, "sentence_index": 6, "correct_answer": "知的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この靴は知的で、長く歩いても足が疲れない。", "explanation": "ここは〈快適な〉の意味。履き心地を表すのに知的は使わない。"}, {"text": "今日の空は知的で、雨は降らないだろう。", "explanation": "ここは〈晴れた〉の意味。天気の状態には知的を使わない。"}, {"text": "彼は足が知的で、サッカーのシュートが強い。", "explanation": "ここは〈たくましい〉の意味。体格や身体能力を表すのに知的は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52573, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は知的人で、難しいクロスワードも簡単に解いてしまう。", "corrected_sentence": "祖母は知的な人で、難しいクロスワードも簡単に解いてしまう。", "error_description": "「知的」が名詞「人」を修飾するのに「な」が抜けている。形容動詞は連体修飾で「な」が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "知的な", "is_correct": true, "explanation": "文中の「知的な人」の連体形。"}, {"text": "知的だ", "is_correct": false, "explanation": "終止形。「知的だ人」となり、名詞を直接修飾できない。"}, {"text": "知的に", "is_correct": false, "explanation": "連用形。名詞「人」を修飾できず、「人なので」の形に合わない。"}, {"text": "知的で", "is_correct": false, "explanation": "連用形（で）。「知的で人」となり、名詞を修飾する形として成立しない。"}], "correct_form": "知的な", "base_form": "知的だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"知的な": "文中の「知的な人」の連体形。", "知的だ": "終止形。「知的だ人」となり、名詞を直接修飾できない。", "知的に": "連用形。名詞「人」を修飾できず、「人なので」の形に合わない。", "知的で": "連用形（で）。「知的で人」となり、名詞を修飾する形として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52573, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の父は知的の人なので、難しい本をいつも読んでいる。", "corrected_sentence": "彼の父は知的な人なので、難しい本をいつも読んでいる。", "error_description": "名詞「人」を修飾する形が「知的の」になっている。形容動詞の連体修飾は「知的な」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "知的に", "is_correct": true, "explanation": "文中の「知的に見える」の連用形。"}, {"text": "知的でない", "is_correct": false, "explanation": "否定形。「知的でない見える」となり、文の構造に合わない。"}, {"text": "知的なら", "is_correct": false, "explanation": "仮定形。「知的なら見える」となり、「見えるが」の文が成立しない。"}, {"text": "知的であり", "is_correct": false, "explanation": "中止形。「知的であり見える」となり、動詞「見える」の前に置けない。"}], "correct_form": "知的に", "base_form": "知的だ", "form_label": "連用形", "sentence_index": 7, "explanations": {"知的に": "文中の「知的に見える」の連用形。", "知的でない": "否定形。「知的でない見える」となり、文の構造に合わない。", "知的なら": "仮定形。「知的なら見える」となり、「見えるが」の文が成立しない。", "知的であり": "中止形。「知的であり見える」となり、動詞「見える」の前に置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
