INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52574, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52574, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "物事を深く考えたり、理解したりする能力が優れている様子。知識や思考に関わるさま。", "primary_collocate": null, "pronunciation": "ちてき", "ipa": "tɕiteki", "syllable_count": 3, "sentences": [{"text": "この製作の全工程は、まさに宇宙の理を机の上に縮図として描き出す、崇高な知的探究なのである。", "target_word": "知的", "complexity_tier": "T4", "furigana": "この製作(せいさく)の全工程(ぜんこうてい)は、まさに宇宙(うちゅう)の理(ことわり)を机(つくえ)の上(うえ)に縮図(しゅくず)として描(えが)き出(だ)す、崇高(すうこう)な知的(ちてき)探究(たんきゅう)なのである。", "sentence_source": "mined"}, {"text": "彼女は難しい本をよく読むので、友人たちから知的な人だと言われている。", "target_word": "知的", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は難(むずか)しい本(ほん)をよく読(よ)むので、友人(ゆうじん)たちから知的(ちてき)な人(ひと)だと言(い)われている。", "sentence_source": "generated"}, {"text": "読書は、暇つぶしではなく知的な楽しみとして、私の毎日に欠かせない。", "target_word": "知的", "complexity_tier": "T3", "furigana": "読書(どくしょ)は、暇(ひま)つぶしではなく知的(ちてき)な楽(たの)しみとして、私(わたし)の毎日(まいにち)に欠(か)かせない。", "sentence_source": "generated"}, {"text": "この博物館は展示が工夫されていて、大人も子どもも知的な刺激を受けられる。", "target_word": "知的", "complexity_tier": "T3", "furigana": "この博物館(はくぶつかん)は展示(てんじ)が工夫(くふう)されていて、大人(おとな)も子(こ)どもも知的(ちてき)な刺激(しげき)を受(う)けられる。", "sentence_source": "generated"}, {"text": "祖父は定年後も大学の講義に通い、知的な好奇心を失わない。", "target_word": "知的", "complexity_tier": "T3", "furigana": "祖父(そふ)は定年後(ていねんご)も大学(だいがく)の講義(こうぎ)に通(かよ)い、知的(ちてき)な好奇心(こうきしん)を失(うしな)わない。", "sentence_source": "generated"}, {"text": "彼の話し方は落ち着いていて、いかにも知的な印象を与える。", "target_word": "知的", "complexity_tier": "T3", "furigana": "彼(かれ)の話(はな)し方(かた)は落(お)ち着(つ)いていて、いかにも知的(ちてき)な印象(いんしょう)を与(あた)える。", "sentence_source": "generated"}, {"text": "知的な議論をするには、まず相手の意見を最後まで聞くことが大切だ。", "target_word": "知的", "complexity_tier": "T3", "furigana": "知的(ちてき)な議論(ぎろん)をするには、まず相手(あいて)の意見(いけん)を最後(さいご)まで聞(き)くことが大切(たいせつ)だ。", "sentence_source": "generated"}, {"text": "パズルは遊びでありながら、頭を使う知的な作業でもある。", "target_word": "知的", "complexity_tier": "T3", "furigana": "パズルは遊(あそ)びでありながら、頭(あたま)を使(つか)う知的(ちてき)な作業(さぎょう)でもある。", "sentence_source": "generated"}, {"text": "彼は派手な服を着ないが、静かで知的な雰囲気がある。", "target_word": "知的", "complexity_tier": "T3", "furigana": "彼(かれ)は派手(はで)な服(ふく)を着(き)ないが、静(しず)かで知的(ちてき)な雰囲気(ふんいき)がある。", "sentence_source": "generated"}, {"text": "研究者という仕事は、体力よりも知的な粘り強さが求められる。", "target_word": "知的", "complexity_tier": "T4", "furigana": "研究者(けんきゅうしゃ)という仕事(しごと)は、体力(たいりょく)よりも知的(ちてき)な粘(ねば)り強(づよ)さが求(もと)められる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "知的だ", "label": "終止形"}, {"form": "知的な", "label": "連体形"}, {"form": "知的に", "label": "連用形"}, {"form": "知的で", "label": "連用形（で）"}], "register": "neutral", "sense_fingerprint": "知識や思考に関わる、頭を使うさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 縮図 (Zipf 2.69), 描き出す (Zipf 2.48), 崇高 (Zipf 3.16), 探究 (Zipf 3.15)']::text[], 'e80f88b3-ea1d-43b4-8f13-7d86ed2c4372') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52574, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "知的", "is_correct": true, "explanation": "文中の「崇高な知的探究」の語幹そのもの。「な」なしで名詞「探究」を直接修飾する。"}, {"text": "知的だ", "is_correct": false, "explanation": "終止形。「崇高な」の後に続けると「崇高な知的だ探究」となり、文が成立しない。"}, {"text": "知的で", "is_correct": false, "explanation": "連用形（で）。名詞「探究」を修飾できず、「崇高な」とも続かない。"}, {"text": "知的に", "is_correct": false, "explanation": "連用形。「崇高な知的に探究」となり、名詞を修飾する形として成立しない。"}], "explanations": {"知的": "文中の「崇高な知的探究」の語幹そのもの。「な」なしで名詞「探究」を直接修飾する。", "知的だ": "終止形。「崇高な」の後に続けると「崇高な知的だ探究」となり、文が成立しない。", "知的で": "連用形（で）。名詞「探究」を修飾できず、「崇高な」とも続かない。", "知的に": "連用形。「崇高な知的に探究」となり、名詞を修飾する形として成立しない。"}, "sentence_index": 0, "correct_answer": "知的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は毎朝走って、知的な体を保っている。", "explanation": "ここは〈健康な〉の意味。知的は頭の働きに使う語で、体の状態には合わない。"}, {"text": "子どもたちは知的に駆け回って、公園で遊んだ。", "explanation": "ここは〈活発に〉の意味。走り回る様子に知的を副詞として使うのは不自然。"}, {"text": "この店は知的な価格で、学生にも手が出しやすい。", "explanation": "ここは〈手頃な〉の意味。値段は知的ではなく手頃で表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52574, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "知的", "is_correct": true, "explanation": "「知的な議論」の語幹。「な」を伴って議論を修飾する形で、文中の形と一致する。"}, {"text": "知的だった", "is_correct": false, "explanation": "過去形。「知的だった な議論」とは続かず、名詞を修飾できない。"}, {"text": "知的であり", "is_correct": false, "explanation": "中止形。名詞「議論」を修飾できず、「な議論」とつながらない。"}, {"text": "知的さ", "is_correct": false, "explanation": "名詞。「知的さ な議論」となり、議論を修飾する形として成立しない。"}], "explanations": {"知的": "「知的な議論」の語幹。「な」を伴って議論を修飾する形で、文中の形と一致する。", "知的だった": "過去形。「知的だった な議論」とは続かず、名詞を修飾できない。", "知的であり": "中止形。名詞「議論」を修飾できず、「な議論」とつながらない。", "知的さ": "名詞。「知的さ な議論」となり、議論を修飾する形として成立しない。"}, "sentence_index": 6, "correct_answer": "知的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このスープは知的な味で、子どもたちにも人気がある。", "explanation": "ここは〈おいしい〉の意味。食べ物の良さを表すのに知的は使わない。"}, {"text": "彼は約束をすっかり知的に忘れてしまった。", "explanation": "ここは〈完全に〉の意味。忘れ方の程度を知的で表すのは不自然。"}, {"text": "このシャツは知的な布で、雨にも強い。", "explanation": "ここは〈丈夫な〉の意味。布の丈夫さを表すのに知的は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52574, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は知的の議論が得意で、会議でいつも的確に意見を言う。", "corrected_sentence": "彼女は知的な議論が得意で、会議でいつも的確に意見を言う。", "error_description": "名詞を修飾する形で「の」を使っている。形容動詞の語幹「知的」は「知的な議論」と「な」で名詞に続く。「知的の議論」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "知的な", "is_correct": true, "explanation": "文中の「知的な人」の連体形。"}, {"text": "知的だ", "is_correct": false, "explanation": "終止形。「友人たちから知的だ人」となり、名詞に直接つながらない。"}, {"text": "知的に", "is_correct": false, "explanation": "連用形。名詞「人」を修飾できず、「だと言われている」にもつながらない。"}, {"text": "知的で", "is_correct": false, "explanation": "連用形（で）。「知的で人」となり、名詞を修飾する形として成立しない。"}], "correct_form": "知的な", "base_form": "知的だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"知的な": "文中の「知的な人」の連体形。", "知的だ": "終止形。「友人たちから知的だ人」となり、名詞に直接つながらない。", "知的に": "連用形。名詞「人」を修飾できず、「だと言われている」にもつながらない。", "知的で": "連用形（で）。「知的で人」となり、名詞を修飾する形として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52574, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この授業は知的だ議論が多く、学生が活発に参加する。", "corrected_sentence": "この授業は知的な議論が多く、学生が活発に参加する。", "error_description": "名詞「議論」を修飾する形が「知的だ」になっている。「だ」は終止形なので名詞に直接続けられない。連体形は「知的な」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "知的な", "is_correct": true, "explanation": "文中の「知的な作業」の連体形。"}, {"text": "知的さ", "is_correct": false, "explanation": "名詞「さ」は作業を修飾できず、「知的さな作業」の形も成立しない。"}, {"text": "知的なら", "is_correct": false, "explanation": "仮定形。名詞「作業」を修飾できず、文の構造に合わない。"}, {"text": "知的であり", "is_correct": false, "explanation": "中止形。名詞「作業」を直接修飾できず、「な作業」とつながらない。"}], "correct_form": "知的な", "base_form": "知的だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"知的な": "文中の「知的な作業」の連体形。", "知的さ": "名詞「さ」は作業を修飾できず、「知的さな作業」の形も成立しない。", "知的なら": "仮定形。名詞「作業」を修飾できず、文の構造に合わない。", "知的であり": "中止形。名詞「作業」を直接修飾できず、「な作業」とつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba4d439-fd9a-4a68-8645-1395dba27092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
