INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52575, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「奔流が岩にぶつかって」の「が」は、奔流を主語として示すので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「奔流を岩にぶつかって」は「を」が「ぶつかる」の目的語にならず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「奔流から岩にぶつかって」は起点を示すが、ぶつかる主語にはならないので入らない。"}, {"text": "へ", "is_correct": false, "explanation": "「奔流へ岩にぶつかって」は方向を示すが、主語にはならないので入らない。"}], "correct_answer": "が", "explanations": {"が": "「奔流が岩にぶつかって」の「が」は、奔流を主語として示すので正しい。", "を": "「奔流を岩にぶつかって」は「を」が「ぶつかる」の目的語にならず、文が成り立たない。", "から": "「奔流から岩にぶつかって」は起点を示すが、ぶつかる主語にはならないので入らない。", "へ": "「奔流へ岩にぶつかって」は方向を示すが、主語にはならないので入らない。"}, "error_tags": {"を": "対象", "から": "起点の「から」", "へ": "方向の「へ」"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52575, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "水がとても強い力で流れること。", "primary_collocate": null, "pronunciation": "ほんりゅう", "ipa": "hoɴɾʲɯː", "syllable_count": 4, "sentences": [{"text": "大雨で増水した川は、茶色の奔流となって橋の下をうなりながら流れた。", "target_word": "奔流", "complexity_tier": "T3", "furigana": "大雨[おおあめ]で増水[ぞうすい]した川[かわ]は、茶色[ちゃいろ]の奔流[ほんりゅう]となって橋[はし]の下[した]をうなりながら流[なが]れた。", "sentence_source": "generated"}, {"text": "山の斜面を落ちる奔流の音が、遠くの村まで聞こえてきた。", "target_word": "奔流", "complexity_tier": "T3", "furigana": "山[やま]の斜面[しゃめん]を落[お]ちる奔流[ほんりゅう]の音[おと]が、遠[とお]くの村[むら]まで聞[き]こえてきた。", "sentence_source": "generated"}, {"text": "雪解けの奔流が谷を削り、岸の木々を根こそぎ押し流した。", "target_word": "奔流", "complexity_tier": "T3", "furigana": "雪解[ゆきど]けの奔流[ほんりゅう]が谷[たに]を削[けず]り、岸[きし]の木々[きぎ]を根[ね]こそぎ押[お]し流[なが]した。", "sentence_source": "generated"}, {"text": "堤防が切れると、水は奔流となって町へ流れ込んだ。", "target_word": "奔流", "complexity_tier": "T3", "furigana": "堤防[ていぼう]が切[き]れると、水[みず]は奔流[ほんりゅう]となって町[まち]へ流[なが]れ込[こ]んだ。", "sentence_source": "generated"}, {"text": "カヌーの選手たちは、岩の間を抜ける奔流に挑んだ。", "target_word": "奔流", "complexity_tier": "T3", "furigana": "カヌーの選手[せんしゅ]たちは、岩[いわ]の間[あいだ]を抜[ぬ]ける奔流[ほんりゅう]に挑[いど]んだ。", "sentence_source": "generated"}, {"text": "滝の下で渦を巻く奔流を前にして、私たちは言葉を失った。", "target_word": "奔流", "complexity_tier": "T3", "furigana": "滝[たき]の下[した]で渦[うず]を巻[ま]く奔流[ほんりゅう]を前[まえ]にして、私[わたし]たちは言葉[ことば]を失[うしな]った。", "sentence_source": "generated"}, {"text": "放水が始まると、ダムから白い奔流が一気に吹き出した。", "target_word": "奔流", "complexity_tier": "T3", "furigana": "放水[ほうすい]が始[はじ]まると、ダムから白[しろ]い奔流[ほんりゅう]が一気[いっき]に吹[ふ]き出[だ]した。", "sentence_source": "generated"}, {"text": "橋の上から見ると、奔流が岩にぶつかって高くしぶきを上げていた。", "target_word": "奔流", "complexity_tier": "T3", "furigana": "橋[はし]の上[うえ]から見[み]ると、奔流[ほんりゅう]が岩[いわ]にぶつかって高[たか]くしぶきを上[あ]げていた。", "sentence_source": "generated"}, {"text": "先週の台風で、いつもは静かな小川が激しい奔流に変わった。", "target_word": "奔流", "complexity_tier": "T3", "furigana": "先週[せんしゅう]の台風[たいふう]で、いつもは静[しず]かな小川[おがわ]が激[はげ]しい奔流[ほんりゅう]に変[か]わった。", "sentence_source": "generated"}, {"text": "登山道を横切る奔流は深くて速く、私たちは渡るのを諦めて引き返した。", "target_word": "奔流", "complexity_tier": "T3", "furigana": "登山道[とざんどう]を横切[よこぎ]る奔流[ほんりゅう]は深[ふか]くて速[はや]く、私[わたし]たちは渡[わた]るのを諦[あきら]めて引[ひ]き返[かえ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "奔流", "label": "基本形"}], "register": "formal", "sense_fingerprint": "川・滝・洪水など、水が激しい勢いで流れる様子やその流れ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '448d110d-502d-4765-a516-917bc7c1e24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52575, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奔流", "is_correct": true, "explanation": "「茶色の奔流」は勢いよく流れる水の様子を表し、文脈に合う。"}, {"text": "切手", "is_correct": false, "explanation": "切手は郵便に使う紙片で、「茶色の切手となって」は流れを表せないので入らない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は敷物で、水の流れとしては成り立たないので入らない。"}, {"text": "薬箱", "is_correct": false, "explanation": "薬箱は薬を入れる箱で、流れの様子を表せないので入らない。"}], "explanations": {"奔流": "「茶色の奔流」は勢いよく流れる水の様子を表し、文脈に合う。", "切手": "切手は郵便に使う紙片で、「茶色の切手となって」は流れを表せないので入らない。", "座布団": "座布団は敷物で、水の流れとしては成り立たないので入らない。", "薬箱": "薬箱は薬を入れる箱で、流れの様子を表せないので入らない。"}, "sentence_index": 0, "correct_answer": "奔流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "牧場の柵が壊れ、牛の奔流が道路へ飛び出した。", "explanation": "ここは〈群れ〉の意味。まとまって動く牛は群れで言い、奔流は水がとても強い力で流れることに使う。"}, {"text": "山道で奔流が転がり落ちて、車が止まった。", "explanation": "ここは〈落石〉の意味。転がり落ちるのは石で、水の流れを表す奔流は使わない。"}, {"text": "地震で道路に奔流が走った。", "explanation": "ここは〈割れ目〉の意味。地面の裂け目は割れ目で言い、奔流は水の強い流れに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52575, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奔流", "is_correct": true, "explanation": "「白い奔流が一気に吹き出した」の奔流は、水が強い力で流れ出す様子で文脈に合う。"}, {"text": "砂袋", "is_correct": false, "explanation": "砂袋は土のうのような袋で、白い水の流れにはならないので入らない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は花を生ける器で、水が吹き出す文には合わないので入らない。"}, {"text": "座椅子", "is_correct": false, "explanation": "座椅子は床に置く座具で、吹き出す文には合わないので入らない。"}], "explanations": {"奔流": "「白い奔流が一気に吹き出した」の奔流は、水が強い力で流れ出す様子で文脈に合う。", "砂袋": "砂袋は土のうのような袋で、白い水の流れにはならないので入らない。", "花瓶": "花瓶は花を生ける器で、水が吹き出す文には合わないので入らない。", "座椅子": "座椅子は床に置く座具で、吹き出す文には合わないので入らない。"}, "sentence_index": 6, "correct_answer": "奔流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "淹れたてのコーヒーの奔流が、カップから立ち昇った。", "explanation": "ここは〈湯気〉の意味。立ち昇る蒸気は湯気で表し、水が強い力で流れる様子には奔流を使わない。"}, {"text": "廊下に奔流が響いた。", "explanation": "ここは〈足音〉の意味。廊下に響くのは足音で、奔流は水がとても強い力で流れることに使うので合わない。"}, {"text": "窓の外に奔流が立ちこめた。", "explanation": "ここは〈煙〉の意味。立ちこめるのは煙や霧で、水の強い流れを表す奔流は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52575, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "梅雨の大雨で、川の奔流に町を襲った。", "corrected_sentence": "梅雨の大雨で、川の奔流が町を襲った。", "error_description": "誤りは助詞「に」。奔流は主語なので「が」で続け、「奔流が町を襲った」が正しい。「奔流に町を襲った」とは言わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52575, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "放水の合図で、ダムから白い奔流が一気に吹き出しる。", "corrected_sentence": "放水の合図で、ダムから白い奔流が一気に吹き出した。", "error_description": "誤りは動詞の活用。「吹き出す」の過去形は「吹き出した」で、「吹き出しる」は活用として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52576, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「奔流が顔に吹きつけた」の主語を示す「が」で正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「奔流へ」は方向を示すが、ここでは主語にはなれないので入らない。"}, {"text": "と", "is_correct": false, "explanation": "「奔流と」は並列を示すが、ここでは文が成り立たないので入らない。"}, {"text": "の", "is_correct": false, "explanation": "「奔流の」は所有や修飾を示すが、「吹きつけた」の主語にはならないので入らない。"}], "correct_answer": "が", "explanations": {"が": "「奔流が顔に吹きつけた」の主語を示す「が」で正しい。", "へ": "「奔流へ」は方向を示すが、ここでは主語にはなれないので入らない。", "と": "「奔流と」は並列を示すが、ここでは文が成り立たないので入らない。", "の": "「奔流の」は所有や修飾を示すが、「吹きつけた」の主語にはならないので入らない。"}, "error_tags": {"へ": "方向の「へ」", "と": "並列の「と」", "の": "連体修飾の「の」"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52576, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「奔流に押されて」の「に」は、押す力の出どころを示すので正しい。"}, {"text": "が", "is_correct": false, "explanation": "「奔流が押されて」では奔流が押す側になってしまい、受身の文として合わないので入らない。"}, {"text": "を", "is_correct": false, "explanation": "「奔流を押されて」は受身の対象として不自然なので入らない。"}, {"text": "から", "is_correct": false, "explanation": "「奔流から押されて」は起点を示し、押す力の表し方としては合わないので入らない。"}], "correct_answer": "に", "explanations": {"に": "「奔流に押されて」の「に」は、押す力の出どころを示すので正しい。", "が": "「奔流が押されて」では奔流が押す側になってしまい、受身の文として合わないので入らない。", "を": "「奔流を押されて」は受身の対象として不自然なので入らない。", "から": "「奔流から押されて」は起点を示し、押す力の表し方としては合わないので入らない。"}, "error_tags": {"が": "主語の「が」（受身の動作主にならない）", "を": "目的語の「を」（受身では使わない）", "から": "起点の「から」"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52576, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "水や空気などが、勢いよく流れること。また、その流れ。", "primary_collocate": null, "pronunciation": "ほんりゅう", "ipa": "hoɴɾʲɯː", "syllable_count": 4, "sentences": [{"text": "犯罪現場という苛烈な情報の奔流の中から、科学捜査の担い手は微細な痕跡を拾い上げる。", "target_word": "奔流", "complexity_tier": "T5", "furigana": "犯罪[はんざい]現場[げんば]という苛烈[かれつ]な情報[じょうほう]の奔流[ほんりゅう]の中[なか]から、科学[かがく]捜査[そうさ]の担[にな]い手[て]は微細[びさい]な痕跡[こんせき]を拾[ひろ]い上[あ]げる。", "sentence_source": "mined"}, {"text": "トンネルを抜けると、冷たい空気の奔流が顔に吹きつけた。", "target_word": "奔流", "complexity_tier": "T3", "furigana": "トンネルを抜[ぬ]けると、冷[つめ]たい空気[くうき]の奔流[ほんりゅう]が顔[かお]に吹[ふ]きつけた。", "sentence_source": "generated"}, {"text": "ネットには情報の奔流が押し寄せ、必要な話を選ぶのが難しい。", "target_word": "奔流", "complexity_tier": "T3", "furigana": "ネットには情報[じょうほう]の奔流[ほんりゅう]が押[お]し寄[よ]せ、必要[ひつよう]な話[はなし]を選[えら]ぶのが難[むずか]しい。", "sentence_source": "generated"}, {"text": "朝の通勤客の奔流にのまれて、改札までなかなか進めなかった。", "target_word": "奔流", "complexity_tier": "T3", "furigana": "朝[あさ]の通勤客[つうきんきゃく]の奔流[ほんりゅう]にのまれて、改札[かいさつ]までなかなか進[すす]めなかった。", "sentence_source": "generated"}, {"text": "彼の口から言葉の奔流があふれ、だれも口をはさめなかった。", "target_word": "奔流", "complexity_tier": "T3", "furigana": "彼[かれ]の口[くち]から言葉[ことば]の奔流[ほんりゅう]があふれ、だれも口[くち]をはさめなかった。", "sentence_source": "generated"}, {"text": "噴火で流れ出した溶岩の奔流が、夜の斜面を赤く染めた。", "target_word": "奔流", "complexity_tier": "T3", "furigana": "噴火[ふんか]で流[なが]れ出[だ]した溶岩[ようがん]の奔流[ほんりゅう]が、夜[よる]の斜面[しゃめん]を赤[あか]く染[そ]めた。", "sentence_source": "generated"}, {"text": "ダムの放水口から、白い水の奔流が空気を震わせて噴き出した。", "target_word": "奔流", "complexity_tier": "T3", "furigana": "ダムの放水口[ほうすいこう]から、白[しろ]い水[みず]の奔流[ほんりゅう]が空気[くうき]を震[ふる]わせて噴[ふ]き出[だ]した。", "sentence_source": "generated"}, {"text": "感情の奔流に押されて、彼女は思わず叫んだ。", "target_word": "奔流", "complexity_tier": "T3", "furigana": "感情[かんじょう]の奔流[ほんりゅう]に押[お]されて、彼女[かのじょ]は思[おも]わず叫[さけ]んだ。", "sentence_source": "generated"}, {"text": "春の嵐が生んだ風の奔流は、屋根の瓦を次々に吹き飛ばした。", "target_word": "奔流", "complexity_tier": "T3", "furigana": "春[はる]の嵐[あらし]が生[う]んだ風[かぜ]の奔流[ほんりゅう]は、屋根[やね]の瓦[かわら]を次々[つぎつぎ]に吹[ふ]き飛[と]ばした。", "sentence_source": "generated"}, {"text": "換気口から入る風の奔流で、机の紙が一斉に舞い上がった。", "target_word": "奔流", "complexity_tier": "T3", "furigana": "換気口[かんきこう]から入[はい]る風[かぜ]の奔流[ほんりゅう]で、机[つくえ]の紙[かみ]が一斉[いっせい]に舞[ま]い上[あ]がった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "奔流", "label": "基本形"}], "register": "formal", "sense_fingerprint": "水・空気・溶岩・情報などの激しく勢いのある流れ。比喩的にも使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '448d110d-502d-4765-a516-917bc7c1e24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52576, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奔流", "is_correct": true, "explanation": "激しく流れ込む情報を勢いのある流れとして表す比喩で、文脈に合う。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は筆記具で、「情報の鉛筆の中から」は意味が通らないので入らない。"}, {"text": "墓石", "is_correct": false, "explanation": "墓石は墓に置く石で、情報の流れを表す比喩としても合わないので入らない。"}, {"text": "煎餅", "is_correct": false, "explanation": "煎餅は食べ物で、「情報の煎餅」は文脈に合わないので入らない。"}], "explanations": {"奔流": "激しく流れ込む情報を勢いのある流れとして表す比喩で、文脈に合う。", "鉛筆": "鉛筆は筆記具で、「情報の鉛筆の中から」は意味が通らないので入らない。", "墓石": "墓石は墓に置く石で、情報の流れを表す比喩としても合わないので入らない。", "煎餅": "煎餅は食べ物で、「情報の煎餅」は文脈に合わないので入らない。"}, "sentence_index": 0, "correct_answer": "奔流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小石を投げると、池に奔流が広がった。", "explanation": "ここは〈波紋〉の意味。静かに輪になって広がる波には奔流を使わず、勢いよく流れる様子に使う。"}, {"text": "教室の奔流が、授業の後もいつまでも続いた。", "explanation": "ここは〈ざわめき〉の意味。教室の話し声やざわめきは奔流とは言わず、奔流は水や空気が勢いよく流れることに使う。"}, {"text": "山道で奔流が転がり落ちて、車が止まった。", "explanation": "ここは〈落石〉の意味。転がり落ちるのは石で、流れを表す奔流は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52576, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奔流", "is_correct": true, "explanation": "白い水が空気を震わせて勢いよく流れ出す様子を表し、文脈に合う。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は敷物で、「白い水の座布団」は成り立たないので入らない。"}, {"text": "切手", "is_correct": false, "explanation": "切手は郵便に使う紙片で、水の流れを表せないので入らない。"}, {"text": "薬箱", "is_correct": false, "explanation": "薬箱は薬を入れる箱で、白い水の勢いを表せないので入らない。"}], "explanations": {"奔流": "白い水が空気を震わせて勢いよく流れ出す様子を表し、文脈に合う。", "座布団": "座布団は敷物で、「白い水の座布団」は成り立たないので入らない。", "切手": "切手は郵便に使う紙片で、水の流れを表せないので入らない。", "薬箱": "薬箱は薬を入れる箱で、白い水の勢いを表せないので入らない。"}, "sentence_index": 6, "correct_answer": "奔流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "コーヒーの奔流が、カップから立ち昇った。", "explanation": "ここは〈湯気〉の意味。立ち昇る蒸気は湯気で表し、奔流は水や空気の勢いある流れに使う。"}, {"text": "地震で、道路に奔流が走った。", "explanation": "ここは〈割れ目〉の意味。地面の裂け目は割れ目で言い、奔流は勢いよく流れるものに使う。"}, {"text": "香ばしい奔流が台所に漂った。", "explanation": "ここは〈におい〉の意味。漂うのは香りやにおいで、奔流は水や空気が勢いよく流れることに使い、香りには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52576, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "堤防が切れ、町は奔流を飲み込まれた。", "corrected_sentence": "堤防が切れ、町は奔流に飲み込まれた。", "error_description": "誤りは助詞「を」。「飲み込まれる」は受身で「に」を取るので、「奔流に飲み込まれた」が正しい。「奔流を飲み込まれた」とは言わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52576, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の嵐で、川の奔流の橋を押し流した。", "corrected_sentence": "夏の嵐で、川の奔流が橋を押し流した。", "error_description": "誤りは助詞「の」。「奔流が」の「が」を「の」に変えると、奔流は主語にならず、「押し流した」の主語が欠ける。「奔流が橋を押し流した」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52577, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「見つからない」は探されている対象（担い手）を「が」で示すので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「見つからない」は「を」を取らないので不可。"}, {"text": "に", "is_correct": false, "explanation": "「担い手に見つからず」は相手を表し、この文の意味に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「担い手で見つからず」は手段や場所を表し、ここでは不自然。"}], "correct_answer": "が", "explanations": {"が": "「見つからない」は探されている対象（担い手）を「が」で示すので正しい。", "を": "「見つからない」は「を」を取らないので不可。", "に": "「担い手に見つからず」は相手を表し、この文の意味に合わない。", "で": "「担い手で見つからず」は手段や場所を表し、ここでは不自然。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52577, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「担い手として」の「として」にあたり、役割を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「担い手へ」は方向を表し、役割を示す文脈と合わない。"}, {"text": "が", "is_correct": false, "explanation": "「担い手がして」は主語になり、役割を示せず不自然。"}, {"text": "より", "is_correct": false, "explanation": "「担い手より」は比較を表し、ここでは意味が通らない。"}], "correct_answer": "と", "explanations": {"と": "「担い手として」の「として」にあたり、役割を示す。", "へ": "「担い手へ」は方向を表し、役割を示す文脈と合わない。", "が": "「担い手がして」は主語になり、役割を示せず不自然。", "より": "「担い手より」は比較を表し、ここでは意味が通らない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52577, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "仕事や役目を引き受ける人のこと。", "primary_collocate": null, "pronunciation": "にないて", "ipa": "ninaite", "syllable_count": 4, "sentences": [{"text": "町の清掃活動の担い手は、近所に住むボランティアの人たちだ。", "target_word": "担い手", "complexity_tier": "T3", "furigana": "町[まち]の清掃[せいそう]活動[かつどう]の担[にな]い手[て]は、近所[きんじょ]に住[す]むボランティアの人[ひと]たちだ。", "sentence_source": "generated"}, {"text": "この仕事の担い手が見つからず、締め切りが遅れてしまった。", "target_word": "担い手", "complexity_tier": "T3", "furigana": "この仕事[しごと]の担[にな]い手[て]が見[み]つからず、締[し]め切[き]りが遅[おく]れてしまった。", "sentence_source": "generated"}, {"text": "学校の行事では、六年生が運営の担い手になる。", "target_word": "担い手", "complexity_tier": "T3", "furigana": "学校[がっこう]の行事[ぎょうじ]では、六年生[ろくねんせい]が運営[うんえい]の担[にな]い手[て]になる。", "sentence_source": "generated"}, {"text": "家事の担い手が母だけでは大変なので、家族で分けることにした。", "target_word": "担い手", "complexity_tier": "T3", "furigana": "家事[かじ]の担[にな]い手[て]が母[はは]だけでは大変[たいへん]なので、家族[かぞく]で分[わ]けることにした。", "sentence_source": "generated"}, {"text": "昔は祭りの担い手が多かったが、今は参加する人が少ない。", "target_word": "担い手", "complexity_tier": "T3", "furigana": "昔[むかし]は祭[まつ]りの担[にな]い手[て]が多[おお]かったが、今[いま]は参加[さんか]する人[ひと]が少[すく]ない。", "sentence_source": "generated"}, {"text": "だれが新しい企画の担い手になるのか、会議で話し合った。", "target_word": "担い手", "complexity_tier": "T3", "furigana": "だれが新[あたら]しい企画[きかく]の担[にな]い手[て]になるのか、会議[かいぎ]で話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "小さな商店街でも、イベントの担い手がいればにぎやかになる。", "target_word": "担い手", "complexity_tier": "T3", "furigana": "小[ちい]さな商店街[しょうてんがい]でも、イベントの担[にな]い手[て]がいればにぎやかになる。", "sentence_source": "generated"}, {"text": "彼女は地域の見守り活動の担い手として、毎朝子どもに声をかけている。", "target_word": "担い手", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は地域[ちいき]の見守[みまも]り活動[かつどう]の担[にな]い手[て]として、毎朝[まいあさ]子[こ]どもに声[こえ]をかけている。", "sentence_source": "generated"}, {"text": "引っ越しの手伝いでは、体力のある若い担い手がいて助かった。", "target_word": "担い手", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの手伝[てつだ]いでは、体力[たいりょく]のある若[わか]い担[にな]い手[て]がいて助[たす]かった。", "sentence_source": "generated"}, {"text": "公園の花壇の世話は、ボランティアの担い手が交代で行っている。", "target_word": "担い手", "complexity_tier": "T3", "furigana": "公園[こうえん]の花壇[かだん]の世話[せわ]は、ボランティアの担[にな]い手[て]が交代[こうたい]で行[おこな]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "担い手", "label": "基本形"}], "register": "中立", "sense_fingerprint": "身近な仕事や役目を引き受けて行う人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30f189a2-d0da-4e3f-9dc8-fbca6dc3d32d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52577, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "担い手", "is_correct": true, "explanation": "清掃活動を実際に引き受けて行う人を指し、ボランティアの人たちと結びつく語なので正しい。"}, {"text": "目的", "is_correct": false, "explanation": "活動の狙いを表す語で、それが人であることはないので文が成り立たない。"}, {"text": "範囲", "is_correct": false, "explanation": "活動が及ぶ区域を表す語で、人を指さないので主語として合わない。"}, {"text": "日程", "is_correct": false, "explanation": "予定の日取りを表す語で、人を指さないため「〜の日程は人たちだ」とは続かない。"}], "explanations": {"担い手": "清掃活動を実際に引き受けて行う人を指し、ボランティアの人たちと結びつく語なので正しい。", "目的": "活動の狙いを表す語で、それが人であることはないので文が成り立たない。", "範囲": "活動が及ぶ区域を表す語で、人を指さないので主語として合わない。", "日程": "予定の日取りを表す語で、人を指さないため「〜の日程は人たちだ」とは続かない。"}, "sentence_index": 0, "correct_answer": "担い手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この展示会の担い手は、とても大きくて入口に入らなかった。", "explanation": "ここは〈作品〉の意味。展示される品物を指す語で、担い手は仕事や役目を引き受ける人なので、作品の大きさを述べる文には合わない。"}, {"text": "この料理の担い手は、とても柔らかく、すぐにとろけた。", "explanation": "ここは〈食材〉の意味。料理に使う材料を指す語で、担い手は人を指すので、食べ物の柔らかさを述べる文には合わない。"}, {"text": "この水の担い手は、冷たくて飲みにくい。", "explanation": "ここは〈水〉の意味。飲み物としての水を指す語で、担い手は役目を引き受ける人なので、水の性質を述べる文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52577, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "担い手", "is_correct": true, "explanation": "イベントを実際に担う人を指し、「いれば〜になる」で人手として働く語なので正しい。"}, {"text": "予算", "is_correct": false, "explanation": "お金の枠を表す語で、「いればにぎやかになる」の人手の文脈に合わない。"}, {"text": "参加費", "is_correct": false, "explanation": "参加に払うお金を表し、人を前提とする「がいれば」の文に合わない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語で、イベントの人手を表せないので合わない。"}], "explanations": {"担い手": "イベントを実際に担う人を指し、「いれば〜になる」で人手として働く語なので正しい。", "予算": "お金の枠を表す語で、「いればにぎやかになる」の人手の文脈に合わない。", "参加費": "参加に払うお金を表し、人を前提とする「がいれば」の文に合わない。", "天気": "空模様を表す語で、イベントの人手を表せないので合わない。"}, "sentence_index": 6, "correct_answer": "担い手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店の担い手は、とても甘くて、すぐに売り切れる。", "explanation": "ここは〈商品〉の意味。店で売られる品物を指す語で、担い手は役目を引き受ける人なので、売れ行きを述べる文には合わない。"}, {"text": "店の入り口の担い手が、夜になると光る。", "explanation": "ここは〈看板〉の意味。物として光る対象を表す語で、担い手は人を指すので合わない。"}, {"text": "席の担い手は、前日までに済ませてください。", "explanation": "ここは〈予約〉の意味。事前の手続きを表す語で、役目を引き受ける人を指す担い手とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52577, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は来年から地域の見守りの担い手をなる。", "corrected_sentence": "彼は来年から地域の見守りの担い手になる。", "error_description": "「担い手」に続く助詞が誤り。「担い手になる」と「に」を取るのが正しく、「を」では「なる」が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52577, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祭りの担い手に数が、年々減っている。", "corrected_sentence": "祭りの担い手の数が、年々減っている。", "error_description": "「担い手」に続く助詞が誤り。「担い手の数」と「の」で数を示すのが正しく、「に」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
