INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52578, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ある役割や責任を引き受けて、それを実行する人。また、物事を支える中心となる人。", "primary_collocate": null, "pronunciation": "にないて", "ipa": "ninaite", "syllable_count": 4, "sentences": [{"text": "犯罪現場という苛烈な情報の奔流の中から、科学捜査の担い手は微細な痕跡を拾い上げる。", "target_word": "担い手", "complexity_tier": "T3", "furigana": "犯罪現場[はんざいげんば]という苛烈[かれつ]な情報[じょうほう]の奔流[ほんりゅう]の中[なか]から、科学捜査[かがくそうさ]の担[にな]い手[て]は微細[びさい]な痕跡[こんせき]を拾[ひろ]い上[あ]げる。", "sentence_source": "mined"}, {"text": "農村では高齢化が進み、地域の農業を支える担い手が足りなくなっている。", "target_word": "担い手", "complexity_tier": "T3", "furigana": "農村[のうそん]では高齢化[こうれいか]が進[すす]み、地域[ちいき]の農業[のうぎょう]を支[ささ]える担[にな]い手[て]が足[た]りなくなっている。", "sentence_source": "generated"}, {"text": "これからの社会の担い手である若者に、正しい情報を伝えたい。", "target_word": "担い手", "complexity_tier": "T3", "furigana": "これからの社会[しゃかい]の担[にな]い手[て]である若者[わかもの]に、正[ただ]しい情報[じょうほう]を伝[つた]えたい。", "sentence_source": "generated"}, {"text": "伝統工芸の担い手が減ったため、技術を学ぶ若い人を募集している。", "target_word": "担い手", "complexity_tier": "T3", "furigana": "伝統[でんとう]工芸[こうげい]の担[にな]い手[て]が減[へ]ったため、技術[ぎじゅつ]を学[まな]ぶ若[わか]い人[ひと]を募集[ぼしゅう]している。", "sentence_source": "generated"}, {"text": "この町の祭りは、地元の高校生が新しい担い手となって続いている。", "target_word": "担い手", "complexity_tier": "T3", "furigana": "この町[まち]の祭[まつ]りは、地元[じもと]の高校生[こうこうせい]が新[あたら]しい担[にな]い手[て]となって続[つづ]いている。", "sentence_source": "generated"}, {"text": "再生可能エネルギーの普及には、企業だけでなく市民も担い手になる必要がある。", "target_word": "担い手", "complexity_tier": "T3", "furigana": "再生[さいせい]可能[かのう]エネルギーの普及[ふきゅう]には、企業[きぎょう]だけでなく市民[しみん]も担[にな]い手[て]になる必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "彼は村の復興の中心的な担い手として、毎日忙しく働いた。", "target_word": "担い手", "complexity_tier": "T3", "furigana": "彼[かれ]は村[むら]の復興[ふっこう]の中心的[ちゅうしんてき]な担[にな]い手[て]として、毎日[まいにち]忙[いそが]しく働[はたら]いた。", "sentence_source": "generated"}, {"text": "文化を次の世代に残すためには、受け継ぐ担い手を育てることが大切だ。", "target_word": "担い手", "complexity_tier": "T3", "furigana": "文化[ぶんか]を次[つぎ]の世代[せだい]に残[のこ]すためには、受[う]け継[つ]ぐ担[にな]い手[て]を育[そだ]てることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "介護の担い手が不足しているので、国は外国人の受け入れも検討している。", "target_word": "担い手", "complexity_tier": "T3", "furigana": "介護[かいご]の担[にな]い手[て]が不足[ふそく]しているので、国[くに]は外国人[がいこくじん]の受[う]け入[い]れも検討[けんとう]している。", "sentence_source": "generated"}, {"text": "地域の安全を守る担い手として、消防団の活動が見直されている。", "target_word": "担い手", "complexity_tier": "T3", "furigana": "地域[ちいき]の安全[あんぜん]を守[まも]る担[にな]い手[て]として、消防団[しょうぼうだん]の活動[かつどう]が見直[みなお]されている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "担い手", "label": "基本形"}], "register": "中立", "sense_fingerprint": "役割や責任を引き受け、物事を支える中心となる人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30f189a2-d0da-4e3f-9dc8-fbca6dc3d32d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52578, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "担い手", "is_correct": true, "explanation": "文の主語になり、科学捜査を実際に担う人を指すので、この空所に入る語はこれだけ。"}, {"text": "奔流", "is_correct": false, "explanation": "情報が勢いよく流れる様子を表す語で、捜査を担う人は指せないので主語にならない。"}, {"text": "高齢化", "is_correct": false, "explanation": "人口が高齢になる現象を表す語で、主語として微細な痕跡を拾う行為はできない。"}, {"text": "挫折", "is_correct": false, "explanation": "目標を果たせず折れる出来事を表す語で、人を指さないので主語に置けない。"}], "explanations": {"担い手": "文の主語になり、科学捜査を実際に担う人を指すので、この空所に入る語はこれだけ。", "奔流": "情報が勢いよく流れる様子を表す語で、捜査を担う人は指せないので主語にならない。", "高齢化": "人口が高齢になる現象を表す語で、主語として微細な痕跡を拾う行為はできない。", "挫折": "目標を果たせず折れる出来事を表す語で、人を指さないので主語に置けない。"}, "sentence_index": 0, "correct_answer": "担い手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このかばんの担い手が切れて、中身が落ちた。", "explanation": "ここは〈持ち手〉の意味。かばんを提げる紐を指す語で、担い手は役割を引き受ける人を指すので、紐の話には合わない。"}, {"text": "この扉の担い手が古くなって、きしむ音がする。", "explanation": "ここは〈蝶番〉の意味。扉を支える金具を指す語で、担い手は人を指すので、金具の話には合わない。"}, {"text": "この棚の担い手は、重い本で曲がった。", "explanation": "ここは〈支柱〉の意味。棚を支える柱を指す語で、担い手は人を指すので、柱の話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52578, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "担い手", "is_correct": true, "explanation": "「中心的な〜として」で、村の復興を実際に担う人を指す語なので、ここに入るのはこれだけ。"}, {"text": "天候", "is_correct": false, "explanation": "空模様を表す語で、人の役割を表せないので「中心的な天候として」は成り立たない。"}, {"text": "方言", "is_correct": false, "explanation": "地域独特の言葉を表す語で、役割を担う人の立場を表さないので合わない。"}, {"text": "地震", "is_correct": false, "explanation": "地面が揺れる自然現象で、役割として働く人を指せないので合わない。"}], "explanations": {"担い手": "「中心的な〜として」で、村の復興を実際に担う人を指す語なので、ここに入るのはこれだけ。", "天候": "空模様を表す語で、人の役割を表せないので「中心的な天候として」は成り立たない。", "方言": "地域独特の言葉を表す語で、役割を担う人の立場を表さないので合わない。", "地震": "地面が揺れる自然現象で、役割として働く人を指せないので合わない。"}, "sentence_index": 6, "correct_answer": "担い手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この鍋の担い手は、熱くて持てない。", "explanation": "ここは〈持ち手〉の意味。鍋などの取っ手を指す語で、担い手は役割を引き受けて支える人を指すので、物の部分を表す文には合わない。"}, {"text": "この時計の担い手は、朝になると針が止まる。", "explanation": "ここは〈部品〉の意味。機械の動きを生む部品を指す語で、担い手は人を指すので、時計の部品を述べる文には合わない。"}, {"text": "台所の担い手が壊れて、水が止まらない。", "explanation": "ここは〈水道〉の意味。水を送る設備を表す語で、担い手は人を指すので設備の話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52578, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町では、子どもの減少で祭りの担い手を不足している。", "corrected_sentence": "この町では、子どもの減少で祭りの担い手が不足している。", "error_description": "「担い手」に続く助詞が誤り。「不足する」は「〜が不足する」と主語に「が」を取るので、「を」ではなく「が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52578, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "若者が新しい担い手に、祭りを続けている。", "corrected_sentence": "若者が新しい担い手として、祭りを続けている。", "error_description": "「担い手」に続く助詞が誤り。役割を示す「として」が正しく、「に」では「担い手」が動作の相手になり意味が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52579, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「始めました」の目的語を示す格助詞で、「捜査を始めました」と続く"}, {"text": "に", "is_correct": false, "explanation": "「捜査に」では「始めました」の対象にならない"}, {"text": "で", "is_correct": false, "explanation": "「捜査で」は手段の意味になり、「始めました」の対象にならない"}, {"text": "と", "is_correct": false, "explanation": "「捜査と」は並列や相手を表し、「始める」の目的語にはならない"}], "correct_answer": "を", "explanations": {"を": "「始めました」の目的語を示す格助詞で、「捜査を始めました」と続く", "に": "「捜査に」では「始めました」の対象にならない", "で": "「捜査で」は手段の意味になり、「始めました」の対象にならない", "と": "「捜査と」は並列や相手を表し、「始める」の目的語にはならない"}, "error_tags": {"に": "方向", "で": "手段", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52579, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「終わる」の主語を示す「が」で、「捜査が終わる」と続く"}, {"text": "を", "is_correct": false, "explanation": "「終わる」は自動詞なので「捜査を」は目的語として成り立たない"}, {"text": "に", "is_correct": false, "explanation": "「捜査に」では主語を示せず、文が通らない"}, {"text": "と", "is_correct": false, "explanation": "「捜査と」は並列の相手を表し、「終わる」の主語にならない"}], "correct_answer": "が", "explanations": {"が": "「終わる」の主語を示す「が」で、「捜査が終わる」と続く", "を": "「終わる」は自動詞なので「捜査を」は目的語として成り立たない", "に": "「捜査に」では主語を示せず、文が通らない", "と": "「捜査と」は並列の相手を表し、「終わる」の主語にならない"}, "error_tags": {"を": "対象", "に": "位置", "と": "相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52579, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "おまわりさんが、じけんをしらべることです。", "primary_collocate": null, "pronunciation": "そうさ", "ipa": "soːsa", "syllable_count": 3, "sentences": [{"text": "おまわりさんが、どろぼうの捜査をしています。", "target_word": "捜査", "complexity_tier": "T3", "furigana": "おまわりさんが、どろぼうの捜査[そうさ]をしています。", "sentence_source": "generated"}, {"text": "警察は、きのうの事件の捜査を始めました。", "target_word": "捜査", "complexity_tier": "T3", "furigana": "警察[けいさつ]は、きのうの事件[じけん]の捜査[そうさ]を始[はじ]めました。", "sentence_source": "generated"}, {"text": "捜査をしたので、どろぼうがつかまりました。", "target_word": "捜査", "complexity_tier": "T3", "furigana": "捜査[そうさ]をしたので、どろぼうがつかまりました。", "sentence_source": "generated"}, {"text": "刑事ドラマでは、主人公が事件の捜査をする。", "target_word": "捜査", "complexity_tier": "T3", "furigana": "刑事[けいじ]ドラマでは、主人公[しゅじんこう]が事件[じけん]の捜査[そうさ]をする。", "sentence_source": "generated"}, {"text": "近所で事件があり、警察の捜査が夜まで続いた。", "target_word": "捜査", "complexity_tier": "T3", "furigana": "近所[きんじょ]で事件[じけん]があり、警察[けいさつ]の捜査[そうさ]が夜[よる]まで続[つづ]いた。", "sentence_source": "generated"}, {"text": "捜査のおかげで、ぬすまれた自転車が見つかった。", "target_word": "捜査", "complexity_tier": "T3", "furigana": "捜査[そうさ]のおかげで、ぬすまれた自転車[じてんしゃ]が見[み]つかった。", "sentence_source": "generated"}, {"text": "警察官は、事件の手がかりを探して捜査している。", "target_word": "捜査", "complexity_tier": "T3", "furigana": "警察官[けいさつかん]は、事件[じけん]の手[て]がかりを探[さが]して捜査[そうさ]している。", "sentence_source": "generated"}, {"text": "捜査が終わるまで、この道は通れません。", "target_word": "捜査", "complexity_tier": "T3", "furigana": "捜査[そうさ]が終[お]わるまで、この道[みち]は通[とお]れません。", "sentence_source": "generated"}, {"text": "犯人が分からないので、警察は捜査を続けている。", "target_word": "捜査", "complexity_tier": "T3", "furigana": "犯人[はんにん]が分[わ]からないので、警察[けいさつ]は捜査[そうさ]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "おまわりさんの捜査で、ぬすまれた財布が戻ってきた。", "target_word": "捜査", "complexity_tier": "T3", "furigana": "おまわりさんの捜査[そうさ]で、ぬすまれた財布[さいふ]が戻[もど]ってきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "捜査", "label": "基本形"}, {"form": "捜査する", "label": "サ変動詞"}], "register": "中立", "sense_fingerprint": "警察官が事件について調べること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: ぬすま (Zipf 1.87)','sentence 9 above tier T2: contains vocabulary far above tier T2: ぬすま (Zipf 1.87)']::text[], '30f189a2-d0da-4e3f-9dc8-fbca6dc3d32d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52579, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "捜査", "is_correct": true, "explanation": "どろぼうを調べる活動の意味で、「どろぼうの〜をしています」に合う"}, {"text": "散歩", "is_correct": false, "explanation": "ぶらぶら歩く意味で、どろぼうを対象にできない"}, {"text": "洗濯", "is_correct": false, "explanation": "衣類を洗う意味で、どろぼうに対しては使えない"}, {"text": "掃除", "is_correct": false, "explanation": "場所をきれいにする意味で、どろぼうを対象にできない"}], "explanations": {"捜査": "どろぼうを調べる活動の意味で、「どろぼうの〜をしています」に合う", "散歩": "ぶらぶら歩く意味で、どろぼうを対象にできない", "洗濯": "衣類を洗う意味で、どろぼうに対しては使えない", "掃除": "場所をきれいにする意味で、どろぼうを対象にできない"}, "sentence_index": 0, "correct_answer": "捜査"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は、クラスの好き嫌いを捜査するためにアンケートをとった。", "explanation": "ここは〈調査〉の意味。捜査は事件を調べることに使い、好みの傾向を調べるときは使わない"}, {"text": "ゲームのコントローラーを捜査して、キャラクターを動かした。", "explanation": "ここは〈操作〉の意味。機械やコントローラーを動かすことは捜査とは言わない"}, {"text": "出かける前に、自転車の捜査をした。", "explanation": "ここは〈点検〉の意味。自転車の状態を確かめるときは点検を使い、捜査は使わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52579, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捜査", "is_correct": true, "explanation": "手がかりを探して事件を調べる意味で、「探して〜している」に合う"}, {"text": "配達", "is_correct": false, "explanation": "品物を届ける意味で、手がかりを探す文脈に合わない"}, {"text": "改築", "is_correct": false, "explanation": "建物を建て直す意味で、手がかりを探す文脈に合わない"}, {"text": "演奏", "is_correct": false, "explanation": "音楽を披露する意味で、手がかりを探す文脈に合わない"}], "explanations": {"捜査": "手がかりを探して事件を調べる意味で、「探して〜している」に合う", "配達": "品物を届ける意味で、手がかりを探す文脈に合わない", "改築": "建物を建て直す意味で、手がかりを探す文脈に合わない", "演奏": "音楽を披露する意味で、手がかりを探す文脈に合わない"}, "sentence_index": 6, "correct_answer": "捜査"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ロケットが火星を捜査して、写真を送ってきた。", "explanation": "ここは〈探査〉の意味。宇宙の未知の場所を調べるときに使い、事件には使わない"}, {"text": "この計算は、先生が何度も捜査して正しさを確かめた。", "explanation": "ここは〈検証〉の意味。結果の正しさを確かめる場面に捜査は使わない"}, {"text": "科学者は、集めた数値を捜査して新しい傾向を見つけた。", "explanation": "ここは〈解析〉の意味。数値を分析する場面に捜査は使わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52579, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "犯人を見つけるために、警察は町の捜査が始めました。", "corrected_sentence": "犯人を見つけるために、警察は町の捜査を始めました。", "error_description": "「始める」は他動詞なので目的語に「を」が必要。「捜査が」は誤りで、正しくは「捜査を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52579, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日も、警察は犯人の捜査に続けました。", "corrected_sentence": "雨の日も、警察は犯人の捜査を続けました。", "error_description": "「続ける」は他動詞なので目的語に「を」が必要。「捜査に」は助詞の誤りで、正しくは「捜査を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
