INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52580, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」。「捜査は」で文の主題になり、「予想より早く進んだ」と続く"}, {"text": "を", "is_correct": false, "explanation": "「進んだ」は自動詞なので、「捜査を」は目的語として成り立たない"}, {"text": "に", "is_correct": false, "explanation": "「捜査に」では主題を示せず、文が通らない"}, {"text": "と", "is_correct": false, "explanation": "「捜査と」は並列や相手を表し、主題を示さない"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」。「捜査は」で文の主題になり、「予想より早く進んだ」と続く", "を": "「進んだ」は自動詞なので、「捜査を」は目的語として成り立たない", "に": "「捜査に」では主題を示せず、文が通らない", "と": "「捜査と」は並列や相手を表し、主題を示さない"}, "error_tags": {"を": "対象", "に": "方向", "と": "相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52580, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "犯罪や事件の真相を明らかにするため、証拠を集めたり調べたりする活動。", "primary_collocate": null, "pronunciation": "そうさ", "ipa": "soːsa", "syllable_count": 3, "sentences": [{"text": "警察官は、現場に残った微細な痕跡を拾い上げて捜査した。", "target_word": "捜査", "complexity_tier": "T3", "furigana": "警察官[けいさつかん]は、現場[げんば]に残[のこ]った微細[びさい]な痕跡[こんせき]を拾[ひろ]い上[あ]げて捜査[そうさ]した。", "sentence_source": "generated"}, {"text": "警察は目撃者の証言をもとに、事件の捜査を本格的に始めた。", "target_word": "捜査", "complexity_tier": "T3", "furigana": "警察[けいさつ]は目撃者[もくげきしゃ]の証言[しょうげん]をもとに、事件[じけん]の捜査[そうさ]を本格的[ほんかくてき]に始[はじ]めた。", "sentence_source": "generated"}, {"text": "捜査が長引いているが、決定的な証拠はまだ見つかっていない。", "target_word": "捜査", "complexity_tier": "T3", "furigana": "捜査[そうさ]が長引[ながび]いているが、決定的[けっていてき]な証拠[しょうこ]はまだ見[み]つかっていない。", "sentence_source": "generated"}, {"text": "防犯カメラの映像が、捜査を大きく進めるきっかけになった。", "target_word": "捜査", "complexity_tier": "T3", "furigana": "防犯[ぼうはん]カメラの映像[えいぞう]が、捜査[そうさ]を大[おお]きく進[すす]めるきっかけになった。", "sentence_source": "generated"}, {"text": "警察は容疑者の行方を追って、広い範囲で捜査を続けている。", "target_word": "捜査", "complexity_tier": "T3", "furigana": "警察[けいさつ]は容疑者[ようぎしゃ]の行方[ゆくえ]を追[お]って、広[ひろ]い範囲[はんい]で捜査[そうさ]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "捜査の結果、犯人は被害者の知り合いだったことが分かった。", "target_word": "捜査", "complexity_tier": "T3", "furigana": "捜査[そうさ]の結果[けっか]、犯人[はんにん]は被害者[ひがいしゃ]の知[し]り合[あ]いだったことが分[わ]かった。", "sentence_source": "generated"}, {"text": "担当の刑事は、証拠が少ない難しい捜査にも粘り強く取り組んだ。", "target_word": "捜査", "complexity_tier": "T3", "furigana": "担当[たんとう]の刑事[けいじ]は、証拠[しょうこ]が少[すく]ない難[むずか]しい捜査[そうさ]にも粘[ねば]り強[づよ]く取[と]り組[く]んだ。", "sentence_source": "generated"}, {"text": "鑑識の協力で、捜査は予想より早く進んだ。", "target_word": "捜査", "complexity_tier": "T3", "furigana": "鑑識[かんしき]の協力[きょうりょく]で、捜査[そうさ]は予想[よそう]より早[はや]く進[すす]んだ。", "sentence_source": "generated"}, {"text": "捜査に必要な情報だけを公開し、ほかのことは発表しなかった。", "target_word": "捜査", "complexity_tier": "T3", "furigana": "捜査[そうさ]に必要[ひつよう]な情報[じょうほう]だけを公開[こうかい]し、ほかのことは発表[はっぴょう]しなかった。", "sentence_source": "generated"}, {"text": "事件から十年たっても、警察は捜査をあきらめていない。", "target_word": "捜査", "complexity_tier": "T3", "furigana": "事件[じけん]から十年[じゅうねん]たっても、警察[けいさつ]は捜査[そうさ]をあきらめていない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "捜査", "label": "基本形"}, {"form": "捜査する", "label": "サ変動詞"}], "register": "中立", "sense_fingerprint": "警察などが事件の真相を明らかにするために証拠を集め調べる活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30f189a2-d0da-4e3f-9dc8-fbca6dc3d32d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52580, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "捜査", "is_correct": true, "explanation": "現場の痕跡を集めて事件を調べる意味で、「拾い上げて〜した」に合う"}, {"text": "演奏", "is_correct": false, "explanation": "楽器や歌で音楽を披露する意味で、痕跡を拾う文脈に合わない"}, {"text": "改築", "is_correct": false, "explanation": "建物を建て直す意味で、科学的な証拠を集める話には合わない"}, {"text": "配達", "is_correct": false, "explanation": "品物を届ける意味で、痕跡を拾い上げる文脈とは合わない"}], "explanations": {"捜査": "現場の痕跡を集めて事件を調べる意味で、「拾い上げて〜した」に合う", "演奏": "楽器や歌で音楽を披露する意味で、痕跡を拾う文脈に合わない", "改築": "建物を建て直す意味で、科学的な証拠を集める話には合わない", "配達": "品物を届ける意味で、痕跡を拾い上げる文脈とは合わない"}, "sentence_index": 0, "correct_answer": "捜査"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市は住民の生活実態を捜査するため、アンケートを配った。", "explanation": "ここは〈調査〉の意味。捜査は犯罪や事件の真相を明らかにする活動で、住民の実態を調べる場面では使わない"}, {"text": "新しい機械を捜査するため、まず説明書を読んだ。", "explanation": "ここは〈操作〉の意味（読みは同じそうさ）。機械を動かすことは捜査とは言わない"}, {"text": "健康診断で、血液の捜査を受けた。", "explanation": "ここは〈検査〉の意味。捜査は犯罪の真相を調べる活動で、健康状態を調べる場面では使わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52580, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捜査", "is_correct": true, "explanation": "証拠が少ない難しい事件を調べる意味で、粘り強く取り組む対象になる"}, {"text": "辞職", "is_correct": false, "explanation": "職を辞める意味で、取り組む対象にはならない"}, {"text": "離婚", "is_correct": false, "explanation": "夫婦が別れる意味で、「取り組む」対象として文が通らない"}, {"text": "誕生", "is_correct": false, "explanation": "生まれる意味で、取り組む対象にならない"}], "explanations": {"捜査": "証拠が少ない難しい事件を調べる意味で、粘り強く取り組む対象になる", "辞職": "職を辞める意味で、取り組む対象にはならない", "離婚": "夫婦が別れる意味で、「取り組む」対象として文が通らない", "誕生": "生まれる意味で、取り組む対象にならない"}, "sentence_index": 6, "correct_answer": "捜査"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "探査機が月の裏側を捜査した。", "explanation": "ここは〈探査〉の意味。未知の天体や場所を調べる語で、事件を調べる捜査とは使い分ける"}, {"text": "この仮説は実験で捜査され、正しさが確かめられた。", "explanation": "ここは〈検証〉の意味。仮説の正しさを確かめる場面に捜査は使わない"}, {"text": "出発前に車の捜査をしてもらった。", "explanation": "ここは〈点検〉の意味。機械の状態を確かめる場面に捜査は使わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52580, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい手がかりが見つかり、警察は町の捜査が本格的に進めている。", "corrected_sentence": "新しい手がかりが見つかり、警察は町の捜査を本格的に進めている。", "error_description": "「捜査」に続く助詞が誤り。「進める」は他動詞なので目的語に「を」が必要。「捜査が」は誤りで、正しくは「捜査を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52580, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "捜査員は、現場に残った足跡を手がかりに捜査に続けた。", "corrected_sentence": "捜査員は、現場に残った足跡を手がかりに捜査を続けた。", "error_description": "「続ける」は他動詞なので目的語に「を」が必要。「捜査に」は助詞の誤りで、正しくは「捜査を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52581, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」。「彼の生涯は」で文の主題になり、「波乱に満ちた」と続く"}, {"text": "と", "is_correct": false, "explanation": "「生涯と」は並列や相手を表し、主題にならない"}, {"text": "を", "is_correct": false, "explanation": "「生涯を」は動詞の目的語を示すが、ここには動詞がなく文として成り立たない"}, {"text": "へ", "is_correct": false, "explanation": "「生涯へ」は方向を表し、「満ちた」の主題にならない"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」。「彼の生涯は」で文の主題になり、「波乱に満ちた」と続く", "と": "「生涯と」は並列や相手を表し、主題にならない", "を": "「生涯を」は動詞の目的語を示すが、ここには動詞がなく文として成り立たない", "へ": "「生涯へ」は方向を表し、「満ちた」の主題にならない"}, "error_tags": {"と": "相手", "を": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
