INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52581, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が生まれてから死ぬまでの間のこと。", "primary_collocate": null, "pronunciation": "しょうがい", "ipa": "ɕoːɡai", "syllable_count": 4, "sentences": [{"text": "人の生涯は長いようで、実は短いものだ。", "target_word": "生涯", "complexity_tier": "T3", "furigana": "人[ひと]の生涯[しょうがい]は長[なが]いようで、実[じつ]は短[みじか]いものだ。", "sentence_source": "generated"}, {"text": "彼の生涯は、波乱に満ちたものだった。", "target_word": "生涯", "complexity_tier": "T3", "furigana": "彼[かれ]の生涯[しょうがい]は、波乱[はらん]に満[み]ちたものだった。", "sentence_source": "generated"}, {"text": "博物館で、作曲家の生涯をたどる展示を見た。", "target_word": "生涯", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]で、作曲家[さっきょくか]の生涯[しょうがい]をたどる展示[てんじ]を見[み]た。", "sentence_source": "generated"}, {"text": "彼は生涯をふるさとの村で過ごした。", "target_word": "生涯", "complexity_tier": "T3", "furigana": "彼[かれ]は生涯[しょうがい]をふるさとの村[むら]で過[す]ごした。", "sentence_source": "generated"}, {"text": "伝記には、偉人の生涯が詳しく書かれている。", "target_word": "生涯", "complexity_tier": "T3", "furigana": "伝記[でんき]には、偉人[いじん]の生涯[しょうがい]が詳[くわ]しく書[か]かれている。", "sentence_source": "generated"}, {"text": "父は、仕事一筋の生涯を送った。", "target_word": "生涯", "complexity_tier": "T3", "furigana": "父[ちち]は、仕事一筋[しごとひとすじ]の生涯[しょうがい]を送[おく]った。", "sentence_source": "generated"}, {"text": "若いころの一度の失敗が、その後の生涯を左右することもある。", "target_word": "生涯", "complexity_tier": "T4", "furigana": "若[わか]いころの一度[いちど]の失敗[しっぱい]が、その後[ご]の生涯[しょうがい]を左右[さゆう]することもある。", "sentence_source": "generated"}, {"text": "彼女は生涯、動物の命を大切にした。", "target_word": "生涯", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は生涯[しょうがい]、動物[どうぶつ]の命[いのち]を大切[たいせつ]にした。", "sentence_source": "generated"}, {"text": "祖母は九十年の生涯を、家族に囲まれて終えた。", "target_word": "生涯", "complexity_tier": "T3", "furigana": "祖母[そぼ]は九十年[きゅうじゅうねん]の生涯[しょうがい]を、家族[かぞく]に囲[かこ]まれて終[お]えた。", "sentence_source": "generated"}, {"text": "映画は、一人の医者の生涯を描いている。", "target_word": "生涯", "complexity_tier": "T3", "furigana": "映画[えいが]は、一人[ひとり]の医者[いしゃ]の生涯[しょうがい]を描[えが]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生涯", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "生まれてから死ぬまでの期間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30f189a2-d0da-4e3f-9dc8-fbca6dc3d32d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52581, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生涯", "is_correct": true, "explanation": "生まれてから死ぬまでの期間を表し、「人の〜は長いようで」に合う"}, {"text": "週末", "is_correct": false, "explanation": "一週間の終わりの二日間を指し、人の一生の期間を表せない"}, {"text": "午後", "is_correct": false, "explanation": "昼以降の時間を指し、人の一生の期間を表せない"}, {"text": "夕方", "is_correct": false, "explanation": "日が暮れかかる時間を指し、人の一生の期間を表せない"}], "explanations": {"生涯": "生まれてから死ぬまでの期間を表し、「人の〜は長いようで」に合う", "週末": "一週間の終わりの二日間を指し、人の一生の期間を表せない", "午後": "昼以降の時間を指し、人の一生の期間を表せない", "夕方": "日が暮れかかる時間を指し、人の一生の期間を表せない"}, "sentence_index": 0, "correct_answer": "生涯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この冷蔵庫の生涯は十年ほどだ。", "explanation": "ここは〈寿命〉の意味。機械が使える期間には生涯ではなく寿命を使う"}, {"text": "彼は毎日の生涯を楽しんでいる。", "explanation": "ここは〈生活〉の意味。毎日の暮らしを指す語で、生まれてから死ぬまでの期間の生涯とは合わない"}, {"text": "この契約の生涯は一年だ。", "explanation": "ここは〈期間〉の意味。契約の存続期間を指すので、人の一生を表す生涯は合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52581, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生涯", "is_correct": true, "explanation": "その後の人生の期間を表し、「その後の〜を左右する」に合う"}, {"text": "深夜", "is_correct": false, "explanation": "夜ふけの時間を指し、人生の期間として左右する対象にならない"}, {"text": "食器", "is_correct": false, "explanation": "食事に使う器を指す語で、人生の期間を左右するという文には合わない"}, {"text": "紙袋", "is_correct": false, "explanation": "物を入れる紙製の袋を指す語で、人生の期間を表せないので合わない"}], "explanations": {"生涯": "その後の人生の期間を表し、「その後の〜を左右する」に合う", "深夜": "夜ふけの時間を指し、人生の期間として左右する対象にならない", "食器": "食事に使う器を指す語で、人生の期間を左右するという文には合わない", "紙袋": "物を入れる紙製の袋を指す語で、人生の期間を表せないので合わない"}, "sentence_index": 6, "correct_answer": "生涯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "遭難した登山者の生涯が確認された。", "explanation": "ここは〈生存〉の意味。命が無事であることを確かめる場面で、一生を表す生涯は合わない"}, {"text": "この寺は三百年の生涯を持つ。", "explanation": "ここは〈歴史〉の意味。建物や組織の過去の積み重ねを指すので、個人の一生の生涯とは合わない"}, {"text": "祖父は生涯のわりに足腰が丈夫だ。", "explanation": "ここは〈年齢〉の意味。何歳かを表す語で、生涯は一生の期間全体を指すので合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52581, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友人は、彼女の生涯が見守り続けた。", "corrected_sentence": "友人は、彼女の生涯を見守り続けた。", "error_description": "「見守る」は他動詞なので目的語に「を」が必要。「生涯が」は助詞の誤りで、正しくは「生涯を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52581, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は、遠い故郷で生涯が穏やかに終えた。", "corrected_sentence": "祖母は、遠い故郷で生涯を穏やかに終えた。", "error_description": "「終える」は他動詞なので目的語に「を」が必要。「生涯が」は助詞の誤りで、正しくは「生涯を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52582, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ささげ」の目的語を示す「を」で、「生涯を教育にささげ」と続く"}, {"text": "に", "is_correct": false, "explanation": "「生涯に」では「ささげ」の目的語にならない"}, {"text": "で", "is_correct": false, "explanation": "「生涯で」は時間の範囲を表し、目的語にはならない"}, {"text": "へ", "is_correct": false, "explanation": "「生涯へ」は方向を表すが、「ささげ」の対象としては不自然"}], "correct_answer": "を", "explanations": {"を": "「ささげ」の目的語を示す「を」で、「生涯を教育にささげ」と続く", "に": "「生涯に」では「ささげ」の目的語にならない", "で": "「生涯で」は時間の範囲を表し、目的語にはならない", "へ": "「生涯へ」は方向を表すが、「ささげ」の対象としては不自然"}, "error_tags": {"に": "位置", "で": "時間", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52582, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「その短い生涯に」で、その期間に絵を描いたという時間の範囲を示す"}, {"text": "と", "is_correct": false, "explanation": "「生涯と」は並列を表し、時間の範囲を示せない"}, {"text": "から", "is_correct": false, "explanation": "「生涯から」は起点を表し、絵を描いた時間の範囲にならない"}, {"text": "へ", "is_correct": false, "explanation": "「生涯へ」は方向を示すが、期間の説明には合わない"}], "correct_answer": "に", "explanations": {"に": "「その短い生涯に」で、その期間に絵を描いたという時間の範囲を示す", "と": "「生涯と」は並列を表し、時間の範囲を示せない", "から": "「生涯から」は起点を表し、絵を描いた時間の範囲にならない", "へ": "「生涯へ」は方向を示すが、期間の説明には合わない"}, "error_tags": {"と": "相手", "から": "起点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52582, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が生まれてから死ぬまでの、その人の一生。", "primary_collocate": null, "pronunciation": "しょうがい", "ipa": "ɕoːɡai", "syllable_count": 4, "sentences": [{"text": "その人の生涯は、誰にとっても忘れられないものだ。", "target_word": "生涯", "complexity_tier": "T3", "furigana": "その人[ひと]の生涯[しょうがい]は、誰[だれ]にとっても忘[わす]れられないものだ。", "sentence_source": "generated"}, {"text": "祖父は生涯を教育にささげ、多くの教え子に慕われた。", "target_word": "生涯", "complexity_tier": "T3", "furigana": "祖父[そふ]は生涯[しょうがい]を教育[きょういく]にささげ、多[おお]くの教[おし]え子[ご]に慕[した]われた。", "sentence_source": "generated"}, {"text": "彼女は生涯、一度も故郷を離れなかった。", "target_word": "生涯", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は生涯[しょうがい]、一度[いちど]も故郷[こきょう]を離[はな]れなかった。", "sentence_source": "generated"}, {"text": "この出会いは、私の生涯で最も大きな出来事だった。", "target_word": "生涯", "complexity_tier": "T3", "furigana": "この出会[であ]いは、私[わたし]の生涯[しょうがい]で最[もっと]も大[おお]きな出来事[できごと]だった。", "sentence_source": "generated"}, {"text": "彼は七十年の生涯を静かに閉じた。", "target_word": "生涯", "complexity_tier": "T3", "furigana": "彼[かれ]は七十年[ななじゅうねん]の生涯[しょうがい]を静[しず]かに閉[と]じた。", "sentence_source": "generated"}, {"text": "生涯をかけて研究した成果が、ついに認められた。", "target_word": "生涯", "complexity_tier": "T3", "furigana": "生涯[しょうがい]をかけて研究[けんきゅう]した成果[せいか]が、ついに認[みと]められた。", "sentence_source": "generated"}, {"text": "母に言われた言葉は、生涯忘れることはないだろう。", "target_word": "生涯", "complexity_tier": "T3", "furigana": "母[はは]に言[い]われた言葉[ことば]は、生涯[しょうがい]忘[わす]れることはないだろう。", "sentence_source": "generated"}, {"text": "画家はその短い生涯に、千枚以上の絵を描いた。", "target_word": "生涯", "complexity_tier": "T3", "furigana": "画家[がか]はその短[みじか]い生涯[しょうがい]に、千枚以上[せんまいいじょう]の絵[え]を描[か]いた。", "sentence_source": "generated"}, {"text": "子どものころの約束を、彼は生涯守り続けた。", "target_word": "生涯", "complexity_tier": "T3", "furigana": "子[こ]どものころの約束[やくそく]を、彼[かれ]は生涯[しょうがい]守[まも]り続[つづ]けた。", "sentence_source": "generated"}, {"text": "彼女は大学で、生涯を通じて支え合える人に出会った。", "target_word": "生涯", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は大学[だいがく]で、生涯[しょうがい]を通[つう]じて支[ささ]え合[あ]える人[ひと]に出会[であ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生涯", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "生まれてから死ぬまでの一人の人の一生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30f189a2-d0da-4e3f-9dc8-fbca6dc3d32d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52582, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生涯", "is_correct": true, "explanation": "人が生まれてから死ぬまでの一生の意味で、「その人の〜は」に合う"}, {"text": "週末", "is_correct": false, "explanation": "一週間の終わりの二日間を指し、人の一生の範囲を表せない"}, {"text": "午後", "is_correct": false, "explanation": "昼以降の時間を指し、人の一生の範囲を表せない"}, {"text": "夕方", "is_correct": false, "explanation": "日が暮れかかる時間を指し、人の一生の範囲を表せない"}], "explanations": {"生涯": "人が生まれてから死ぬまでの一生の意味で、「その人の〜は」に合う", "週末": "一週間の終わりの二日間を指し、人の一生の範囲を表せない", "午後": "昼以降の時間を指し、人の一生の範囲を表せない", "夕方": "日が暮れかかる時間を指し、人の一生の範囲を表せない"}, "sentence_index": 0, "correct_answer": "生涯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このパソコンの生涯は、思ったより短かった。", "explanation": "ここは〈寿命〉の意味。機械が使える期間には生涯ではなく寿命を使う"}, {"text": "この町の生涯は便利で、買い物にも困らない。", "explanation": "ここは〈生活〉の意味。暮らしの様子を指す語で、一人の人の一生を表す生涯とは合わない"}, {"text": "この工事の生涯は三か月だ。", "explanation": "ここは〈期間〉の意味。工事などの区切られた期間を指すので、人の一生を表す生涯は合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52582, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生涯", "is_correct": true, "explanation": "人の一生を表す副詞で、「生涯忘れることはない」と続く"}, {"text": "深夜", "is_correct": false, "explanation": "夜ふけの時間を指し、忘れない期間としては合わない"}, {"text": "年末", "is_correct": false, "explanation": "一年の終わりを指し、忘れない期間を表せない"}, {"text": "早朝", "is_correct": false, "explanation": "朝早い時間を指し、忘れない期間を表せない"}], "explanations": {"生涯": "人の一生を表す副詞で、「生涯忘れることはない」と続く", "深夜": "夜ふけの時間を指し、忘れない期間としては合わない", "年末": "一年の終わりを指し、忘れない期間を表せない", "早朝": "朝早い時間を指し、忘れない期間を表せない"}, "sentence_index": 6, "correct_answer": "生涯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事故の後、生涯が確認された。", "explanation": "ここは〈生存〉の意味。命が無事であることを確かめる場面で、一生を表す生涯は合わない"}, {"text": "この町は千年の生涯を持つ。", "explanation": "ここは〈歴史〉の意味。町や組織の過去の積み重ねを指すので、個人の一生の生涯とは合わない"}, {"text": "この犬は生涯のわりに元気だ。", "explanation": "ここは〈年齢〉の意味。何歳かを表す語で、生涯は一生の期間全体を指すので合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52582, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は生涯が平和のために捧げた。", "corrected_sentence": "彼は生涯を平和のために捧げた。", "error_description": "「捧げる」は他動詞なので目的語に「を」が必要。「生涯が」は助詞の誤りで、正しくは「生涯を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52582, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は生涯へかけて夢を追い続けた。", "corrected_sentence": "彼は生涯をかけて夢を追い続けた。", "error_description": "「かける」は、かける対象を「を」で示す。「生涯へ」の「へ」は方向を表す助詞で、ここでは誤り。正しくは「生涯を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
