INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52583, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かがあったあとに、小さく残ったあと。", "primary_collocate": null, "pronunciation": "こんせき", "ipa": "koɴseki", "syllable_count": 4, "sentences": [{"text": "床に残った靴の痕跡から、侵入経路を調べた。", "target_word": "痕跡", "complexity_tier": "T3", "furigana": "床[ゆか]に残[のこ]った靴[くつ]の痕跡[こんせき]から、侵入経路[しんにゅうけいろ]を調[しら]べた。", "sentence_source": "generated"}, {"text": "壁の傷は、昔ここで工事をした痕跡だ。", "target_word": "痕跡", "complexity_tier": "T3", "furigana": "壁[かべ]の傷[きず]は、昔[むかし]ここで工事[こうじ]をした痕跡[こんせき]だ。", "sentence_source": "generated"}, {"text": "台風が通った痕跡が、海岸にはっきり残っている。", "target_word": "痕跡", "complexity_tier": "T3", "furigana": "台風[たいふう]が通[とお]った痕跡[こんせき]が、海岸[かいがん]にはっきり残[のこ]っている。", "sentence_source": "generated"}, {"text": "彼女の部屋には、猫がいた痕跡はもうなかった。", "target_word": "痕跡", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の部屋[へや]には、猫[ねこ]がいた痕跡[こんせき]はもうなかった。", "sentence_source": "generated"}, {"text": "調査団は、火山の噴火の痕跡を山の斜面で見つけた。", "target_word": "痕跡", "complexity_tier": "T3", "furigana": "調査団[ちょうさだん]は、火山[かざん]の噴火[ふんか]の痕跡[こんせき]を山[やま]の斜面[しゃめん]で見[み]つけた。", "sentence_source": "generated"}, {"text": "机の上の小さな痕跡から、誰かが水をこぼしたとわかった。", "target_word": "痕跡", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]の小[ちい]さな痕跡[こんせき]から、誰[だれ]かが水[みず]をこぼしたとわかった。", "sentence_source": "generated"}, {"text": "古い手術の痕跡が、腕にうっすらと残っている。", "target_word": "痕跡", "complexity_tier": "T3", "furigana": "古[ふる]い手術[しゅじゅつ]の痕跡[こんせき]が、腕[うで]にうっすらと残[のこ]っている。", "sentence_source": "generated"}, {"text": "雨がやんだあとも、道にはタイヤの痕跡が長く続いていた。", "target_word": "痕跡", "complexity_tier": "T3", "furigana": "雨[あめ]がやんだあとも、道[みち]にはタイヤの痕跡[こんせき]が長[なが]く続[つづ]いていた。", "sentence_source": "generated"}, {"text": "戦争の痕跡を残す建物は、町にいくつもある。", "target_word": "痕跡", "complexity_tier": "T3", "furigana": "戦争[せんそう]の痕跡[こんせき]を残[のこ]す建物[たてもの]は、町[まち]にいくつもある。", "sentence_source": "generated"}, {"text": "彼は証拠を残さないように、データの痕跡を消して会社を去った。", "target_word": "痕跡", "complexity_tier": "T3", "furigana": "彼[かれ]は証拠[しょうこ]を残[のこ]さないように、データの痕跡[こんせき]を消[け]して会社[かいしゃ]を去[さ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "痕跡", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "何かがあった後に小さく残ったあと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30f189a2-d0da-4e3f-9dc8-fbca6dc3d32d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52583, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "痕跡", "is_correct": true, "explanation": "床に残った靴のしるしから侵入経路を調べるので、残ったあとのしるしを表す痕跡が入る。"}, {"text": "祝日", "is_correct": false, "explanation": "祝日は休日のことで、靴から侵入経路を調べる文脈に合わない。"}, {"text": "悲鳴", "is_correct": false, "explanation": "悲鳴は叫び声で、靴の残したものとして侵入経路を調べる材料にはならない。"}, {"text": "寝具", "is_correct": false, "explanation": "寝具は寝るための道具で、床に残った靴の話には合わない。"}], "explanations": {"痕跡": "床に残った靴のしるしから侵入経路を調べるので、残ったあとのしるしを表す痕跡が入る。", "祝日": "祝日は休日のことで、靴から侵入経路を調べる文脈に合わない。", "悲鳴": "悲鳴は叫び声で、靴の残したものとして侵入経路を調べる材料にはならない。", "寝具": "寝具は寝るための道具で、床に残った靴の話には合わない。"}, "sentence_index": 0, "correct_answer": "痕跡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい痕跡を五つ注文して、店に届けてもらった。", "explanation": "ここは〈商品〉の意味。痕跡は残ったしるしで、注文して届けてもらう品物を指さない。"}, {"text": "彼の痕跡は誠実で、部下から信頼されている。", "explanation": "ここは〈人柄〉の意味。痕跡は残ったしるしで、人の性質を表さない。"}, {"text": "来週の会議の痕跡を変更した。", "explanation": "ここは〈日程〉の意味。痕跡は過去に残ったしるしで、決めた予定を変えるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52583, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "痕跡", "is_correct": true, "explanation": "手術のあとに腕に残るしるしを表すので、腕にうっすら残っているという文に合う。"}, {"text": "残高", "is_correct": false, "explanation": "残高は口座などに残った金額で、腕に残るものではない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は部屋の上の面で、古い手術の跡として腕に残るものではない。"}, {"text": "楽譜", "is_correct": false, "explanation": "楽譜は音楽を書いたもので、腕にうっすら残るものとして合わない。"}], "explanations": {"痕跡": "手術のあとに腕に残るしるしを表すので、腕にうっすら残っているという文に合う。", "残高": "残高は口座などに残った金額で、腕に残るものではない。", "天井": "天井は部屋の上の面で、古い手術の跡として腕に残るものではない。", "楽譜": "楽譜は音楽を書いたもので、腕にうっすら残るものとして合わない。"}, "sentence_index": 6, "correct_answer": "痕跡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い痕跡を居間に置いて、家具として使った。", "explanation": "ここは〈家具〉の意味。痕跡は残ったしるしで、居間に置いて使う物ではない。"}, {"text": "毎朝、痕跡を配って歩いた。", "explanation": "ここは〈新聞〉の意味。痕跡は残ったしるしで、配って歩く物ではない。"}, {"text": "彼は英語の痕跡がとても上手だ。", "explanation": "ここは〈発音〉の意味。痕跡は残ったしるしで、話し方の上手さを表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52583, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓枠の周りに、こじ開けた痕跡をはっきり残っていた。", "corrected_sentence": "窓枠の周りに、こじ開けた痕跡がはっきり残っていた。", "error_description": "『残る』は自動詞なので、痕跡には『が』を付ける。『痕跡をはっきり残っていた』は誤りで、正しくは『痕跡がはっきり残っていた』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52583, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "倉庫の床には、重い荷物を引きずった痕跡を残っていた。", "corrected_sentence": "倉庫の床には、重い荷物を引きずった痕跡が残っていた。", "error_description": "『残る』は自動詞なので、痕跡には『が』を付ける。『痕跡を残っていた』は誤りで、正しくは『痕跡が残っていた』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
