INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52584, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が存在したり起こったりした後に残る、わずかなあとやしるし。", "primary_collocate": null, "pronunciation": "こんせき", "ipa": "koɴseki", "syllable_count": 4, "sentences": [{"text": "犯罪現場という苛烈な情報の奔流の中から、科学捜査の担い手は微細な痕跡を拾い上げる。", "target_word": "痕跡", "complexity_tier": "T4", "furigana": "犯罪現場[はんざいげんば]という苛烈[かれつ]な情報[じょうほう]の奔流[ほんりゅう]の中[なか]から、科学捜査[かがくそうさ]の担[にな]い手[て]は微細[びさい]な痕跡[こんせき]を拾[ひろ]い上[あ]げる。", "sentence_source": "mined"}, {"text": "雪の上に、動物が歩いた痕跡が残っていた。", "target_word": "痕跡", "complexity_tier": "T3", "furigana": "雪[ゆき]の上[うえ]に、動物[どうぶつ]が歩[ある]いた痕跡[こんせき]が残[のこ]っていた。", "sentence_source": "generated"}, {"text": "部屋には、誰かが侵入した痕跡は見つからなかった。", "target_word": "痕跡", "complexity_tier": "T3", "furigana": "部屋[へや]には、誰[だれ]かが侵入[しんにゅう]した痕跡[こんせき]は見[み]つからなかった。", "sentence_source": "generated"}, {"text": "遺跡の壁には、古い火災の痕跡が今も黒く残っている。", "target_word": "痕跡", "complexity_tier": "T3", "furigana": "遺跡[いせき]の壁[かべ]には、古[ふる]い火災[かさい]の痕跡[こんせき]が今[いま]も黒[くろ]く残[のこ]っている。", "sentence_source": "generated"}, {"text": "犯人は、逃げる前に指紋の痕跡をすべて拭き取った。", "target_word": "痕跡", "complexity_tier": "T3", "furigana": "犯人[はんにん]は、逃[に]げる前[まえ]に指紋[しもん]の痕跡[こんせき]をすべて拭[ふ]き取[と]った。", "sentence_source": "generated"}, {"text": "彼は部屋を出たあとも、香水の痕跡がしばらく残っていた。", "target_word": "痕跡", "complexity_tier": "T3", "furigana": "彼[かれ]は部屋[へや]を出[で]たあとも、香水[こうすい]の痕跡[こんせき]がしばらく残[のこ]っていた。", "sentence_source": "generated"}, {"text": "古代の生物の痕跡が、岩の中から見つかった。", "target_word": "痕跡", "complexity_tier": "T3", "furigana": "古代[こだい]の生物[せいぶつ]の痕跡[こんせき]が、岩[いわ]の中[なか]から見[み]つかった。", "sentence_source": "generated"}, {"text": "洪水の痕跡は、川沿いの家の壁にまだ見える。", "target_word": "痕跡", "complexity_tier": "T3", "furigana": "洪水[こうずい]の痕跡[こんせき]は、川沿[かわぞ]いの家[いえ]の壁[かべ]にまだ見[み]える。", "sentence_source": "generated"}, {"text": "警察はパソコンに不正アクセスの痕跡があるか調べた。", "target_word": "痕跡", "complexity_tier": "T3", "furigana": "警察[けいさつ]はパソコンに不正[ふせい]アクセスの痕跡[こんせき]があるか調[しら]べた。", "sentence_source": "generated"}, {"text": "引っ越したあとの部屋には、住んでいた人の痕跡がほとんどなかった。", "target_word": "痕跡", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]したあとの部屋[へや]には、住[す]んでいた人[ひと]の痕跡[こんせき]がほとんどなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "痕跡", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物事があった証拠として残るわずかなしるし", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 5 words above tier T3 (max 3): 苛烈 (Zipf 2.89), 奔流 (Zipf 2.32), 担い手 (Zipf 3.01), 微細 (Zipf 3.24), 拾い上げる (Zipf 2.14)']::text[], '30f189a2-d0da-4e3f-9dc8-fbca6dc3d32d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52584, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "痕跡", "is_correct": true, "explanation": "「微細な〜を拾い上げる」に入るのは、残されたわずかなしるしを表す痕跡だけ。"}, {"text": "祝福", "is_correct": false, "explanation": "祝福は人に贈る喜びの言葉や気持ちで、微細なものとして拾い上げる対象にはならない。"}, {"text": "渋滞", "is_correct": false, "explanation": "渋滞は車などが滞ることを指し、微細な物を拾い上げる文脈には合わない。"}, {"text": "寝床", "is_correct": false, "explanation": "寝床は寝るための場所で、拾い上げる対象にはならない。"}], "explanations": {"痕跡": "「微細な〜を拾い上げる」に入るのは、残されたわずかなしるしを表す痕跡だけ。", "祝福": "祝福は人に贈る喜びの言葉や気持ちで、微細なものとして拾い上げる対象にはならない。", "渋滞": "渋滞は車などが滞ることを指し、微細な物を拾い上げる文脈には合わない。", "寝床": "寝床は寝るための場所で、拾い上げる対象にはならない。"}, "sentence_index": 0, "correct_answer": "痕跡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "展覧会で、画家は新しい痕跡を一点だけ出品した。", "explanation": "ここは〈作品〉の意味。痕跡は残ったしるしで、画家が描いて出品する作品を指さない。"}, {"text": "会議で、新しい痕跡を配って全員に説明した。", "explanation": "ここは〈資料〉の意味。痕跡は残ったしるしで、配ったり説明したりする物ではない。"}, {"text": "来年の痕跡に向かって、毎日練習している。", "explanation": "ここは〈目標〉の意味。痕跡は過去に残ったしるしで、これから目指すものには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52584, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "痕跡", "is_correct": true, "explanation": "古代の生物が岩に残したしるしを指すので、岩の中から見つかる対象として合う。"}, {"text": "祭典", "is_correct": false, "explanation": "祭典は催しを指し、古代の生物が岩の中から見つかるという文に合わない。"}, {"text": "食欲", "is_correct": false, "explanation": "食欲は人の感覚や欲求で、岩の中から見つかるものではない。"}, {"text": "停電", "is_correct": false, "explanation": "停電は電気が止まることで、古代の生物について岩の中から見つかるという文と合わない。"}], "explanations": {"痕跡": "古代の生物が岩に残したしるしを指すので、岩の中から見つかる対象として合う。", "祭典": "祭典は催しを指し、古代の生物が岩の中から見つかるという文に合わない。", "食欲": "食欲は人の感覚や欲求で、岩の中から見つかるものではない。", "停電": "停電は電気が止まることで、古代の生物について岩の中から見つかるという文と合わない。"}, "sentence_index": 6, "correct_answer": "痕跡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昔の痕跡を店先に並べて、お客に売った。", "explanation": "ここは〈商品〉の意味。痕跡は残ったしるしで、店先に並べて売る品物ではない。"}, {"text": "彼女の痕跡は温かく、誰にでも好かれる。", "explanation": "ここは〈人柄〉の意味。痕跡は残ったしるしで、人の性質や雰囲気を表さない。"}, {"text": "明日の午後の痕跡をキャンセルした。", "explanation": "ここは〈予約〉の意味。痕跡は過去に残ったしるしで、取り消せる約束ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52584, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨上がりの道に、タイヤの痕跡を残っていた。", "corrected_sentence": "雨上がりの道に、タイヤの痕跡が残っていた。", "error_description": "『残る』は自動詞なので、主語の痕跡には『が』を付ける。『痕跡を残っていた』は誤りで、正しくは『痕跡が残っていた』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52584, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪解けの庭に、野良猫が歩いた痕跡をくっきり残っていた。", "corrected_sentence": "雪解けの庭に、野良猫が歩いた痕跡がくっきり残っていた。", "error_description": "『残る』は自動詞なので、痕跡には『が』を付ける。『痕跡をくっきり残っていた』は誤りで、正しくは『痕跡がくっきり残っていた』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52585, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『隆線の模様』と名詞を修飾する『の』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『隆線を模様は』となり、目的語を示す『を』では文の主語を作れない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は位置や相手を示すため、『隆線に模様は』では名詞を修飾できない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すため、『隆線へ模様は』では名詞を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "『隆線の模様』と名詞を修飾する『の』が正しい。", "を": "『隆線を模様は』となり、目的語を示す『を』では文の主語を作れない。", "に": "『に』は位置や相手を示すため、『隆線に模様は』では名詞を修飾できない。", "へ": "『へ』は方向を示すため、『隆線へ模様は』では名詞を修飾できない。"}, "error_tags": {"を": "object marker with no verb", "に": "location or target", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52585, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『隆線が途中で枝分かれしている』の主語を示す『が』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『枝分かれする』は自動詞なので、目的語を示す『を』とは合わない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は相手や並列を示すため、『隆線と途中で枝分かれ』では主語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すため、『枝分かれしている』の主語を作れない。"}], "correct_answer": "が", "explanations": {"が": "『隆線が途中で枝分かれしている』の主語を示す『が』が正しい。", "を": "『枝分かれする』は自動詞なので、目的語を示す『を』とは合わない。", "と": "『と』は相手や並列を示すため、『隆線と途中で枝分かれ』では主語にならない。", "へ": "『へ』は方向を示すため、『枝分かれしている』の主語を作れない。"}, "error_tags": {"を": "object marker with intransitive verb", "と": "companion or pairing", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52585, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "指の先にある、細くて長く盛り上がった線のことです。", "primary_collocate": null, "pronunciation": "りゅうせん", "ipa": "ɾʲɯːseɴ", "syllable_count": 4, "sentences": [{"text": "指の腹をよく見ると、細い隆線が何本も並んでいる。", "target_word": "隆線", "complexity_tier": "T3", "furigana": "指[ゆび]の腹[はら]をよく見[み]ると、細[ほそ]い隆線[りゅうせん]が何本[なんぼん]も並[なら]んでいる。", "sentence_source": "generated"}, {"text": "隆線の模様は人によって違うため、本人確認に使われる。", "target_word": "隆線", "complexity_tier": "T3", "furigana": "隆線[りゅうせん]の模様[もよう]は人[ひと]によって違[ちが]うため、本人確認[ほんにんかくにん]に使[つか]われる。", "sentence_source": "generated"}, {"text": "長く砂を触る仕事で、彼の隆線はすり減っていた。", "target_word": "隆線", "complexity_tier": "T3", "furigana": "長[なが]く砂[すな]を触[さわ]る仕事[しごと]で、彼[かれ]の隆線[りゅうせん]はすり減[へ]っていた。", "sentence_source": "generated"}, {"text": "指紋を採るには、隆線にまんべんなくインクがつくように指を転がす。", "target_word": "隆線", "complexity_tier": "T3", "furigana": "指紋[しもん]を採[と]るには、隆線[りゅうせん]にまんべんなくインクがつくように指[ゆび]を転[ころ]がす。", "sentence_source": "generated"}, {"text": "顕微鏡で見ると、隆線の上に小さな汗の穴が並んでいる。", "target_word": "隆線", "complexity_tier": "T3", "furigana": "顕微鏡[けんびきょう]で見[み]ると、隆線[りゅうせん]の上[うえ]に小[ちい]さな汗[あせ]の穴[あな]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "隆線が不鮮明な人は、指紋認証がうまくいかないことがある。", "target_word": "隆線", "complexity_tier": "T3", "furigana": "隆線[りゅうせん]が不鮮明[ふせんめい]な人[ひと]は、指紋認証[しもんにんしょう]がうまくいかないことがある。", "sentence_source": "generated"}, {"text": "刑事は、コップに残った隆線の一部から持ち主を探した。", "target_word": "隆線", "complexity_tier": "T3", "furigana": "刑事[けいじ]は、コップに残[のこ]った隆線[りゅうせん]の一部[いちぶ]から持[も]ち主[ぬし]を探[さが]した。", "sentence_source": "generated"}, {"text": "隆線が途中で枝分かれしている点が、照合の手がかりになる。", "target_word": "隆線", "complexity_tier": "T3", "furigana": "隆線[りゅうせん]が途中[とちゅう]で枝分[えだわ]かれしている点[てん]が、照合[しょうごう]の手[て]がかりになる。", "sentence_source": "generated"}, {"text": "子どもの隆線は細く、大人より間隔がせまい。", "target_word": "隆線", "complexity_tier": "T3", "furigana": "子[こ]どもの隆線[りゅうせん]は細[ほそ]く、大人[おとな]より間隔[かんかく]がせまい。", "sentence_source": "generated"}, {"text": "手のしわと違い、隆線は一生変わらないと言われる。", "target_word": "隆線", "complexity_tier": "T3", "furigana": "手[て]のしわと違[ちが]い、隆線[りゅうせん]は一生[いっしょう]変[か]わらないと言[い]われる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "隆線", "label": "基本形"}], "register": "technical", "sense_fingerprint": "指先にある細長く盛り上がった線", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30f189a2-d0da-4e3f-9dc8-fbca6dc3d32d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52585, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "隆線", "is_correct": true, "explanation": "指の腹にある細い盛り上がった線で、何本も並んでいるという文に合う。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢は人の年の数を表し、指の腹に並んでいる線とは合わない。"}, {"text": "会議", "is_correct": false, "explanation": "会議は集まって話し合うことで、指の線が並んでいる文には合わない。"}, {"text": "台所", "is_correct": false, "explanation": "台所は料理をする場所で、指の腹に並ぶものとして合わない。"}], "explanations": {"隆線": "指の腹にある細い盛り上がった線で、何本も並んでいるという文に合う。", "年齢": "年齢は人の年の数を表し、指の腹に並んでいる線とは合わない。", "会議": "会議は集まって話し合うことで、指の線が並んでいる文には合わない。", "台所": "台所は料理をする場所で、指の腹に並ぶものとして合わない。"}, "sentence_index": 0, "correct_answer": "隆線"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "布に隆線を通して縫った。", "explanation": "ここは〈糸〉の意味。隆線は指にある盛り上がった線で、布に通して縫うものではない。"}, {"text": "年を取って目尻に隆線ができた。", "explanation": "ここは〈しわ〉の意味。隆線は指先にある盛り上がった線で、目尻のしわには使わない。"}, {"text": "馬の隆線をしっかり握った。", "explanation": "ここは〈手綱〉の意味。隆線は指にある線で、握って操る道具ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52585, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隆線", "is_correct": true, "explanation": "コップに残った指紋の一部として、持ち主を探す文脈に合う。"}, {"text": "残業", "is_correct": false, "explanation": "残業は仕事を遅くまで続けることで、コップに残るものではない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は部屋の上の面で、コップに残った持ち主の手がかりにはならない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は学ぶための本で、コップに残って持ち主を探す材料にはならない。"}], "explanations": {"隆線": "コップに残った指紋の一部として、持ち主を探す文脈に合う。", "残業": "残業は仕事を遅くまで続けることで、コップに残るものではない。", "天井": "天井は部屋の上の面で、コップに残った持ち主の手がかりにはならない。", "教科書": "教科書は学ぶための本で、コップに残って持ち主を探す材料にはならない。"}, "sentence_index": 6, "correct_answer": "隆線"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ケーキに隆線を絞った。", "explanation": "ここは〈生クリーム〉の意味。隆線は指紋の線で、絞り出して飾る食材ではない。"}, {"text": "仏壇に隆線を灯した。", "explanation": "ここは〈線香〉の意味。隆線は火をつけて灯す物ではない。"}, {"text": "着物の隆線が鮮やかだ。", "explanation": "ここは〈模様〉の意味。隆線は指の盛り上がった線で、着物の柄には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52585, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "指の腹に細い隆線をくっきり並んでいる。", "corrected_sentence": "指の腹に細い隆線がくっきり並んでいる。", "error_description": "『並ぶ』は自動詞なので、主語の隆線には『が』を付ける。『隆線をくっきり並んでいる』は誤りで、正しくは『隆線がくっきり並んでいる』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52585, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "やけどが治ったあとも、隆線を元の形に戻らなかった。", "corrected_sentence": "やけどが治ったあとも、隆線が元の形に戻らなかった。", "error_description": "『戻る』は自動詞なので、主語の隆線には『が』を付ける。『隆線を元の形に戻らなかった』は誤りで、正しくは『隆線が元の形に戻らなかった』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52586, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『隆線が作る模様』という修飾関係を示す『の』が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すため、『つくる』と組み合わせて模様を修飾できない。"}, {"text": "に", "is_correct": false, "explanation": "『隆線につくる模様』は『つくる』に場所の『に』が合わず、隆線が作る模様という意味にならない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を示すため、『つくる模様』を修飾する形にならない。"}], "correct_answer": "の", "explanations": {"の": "『隆線が作る模様』という修飾関係を示す『の』が正しい。", "へ": "『へ』は方向を示すため、『つくる』と組み合わせて模様を修飾できない。", "に": "『隆線につくる模様』は『つくる』に場所の『に』が合わず、隆線が作る模様という意味にならない。", "と": "『と』は並列や相手を示すため、『つくる模様』を修飾する形にならない。"}, "error_tags": {"へ": "direction", "に": "target or attachment", "と": "companion or pairing"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52586, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『隆線の数』と名詞を修飾する『の』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『隆線を数を数えて』となり、目的語が二つ重なって不自然。"}, {"text": "に", "is_correct": false, "explanation": "『に』は位置や相手を示すため、『隆線に数』では数を修飾できない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すため、『隆線へ数』では名詞を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "『隆線の数』と名詞を修飾する『の』が正しい。", "を": "『隆線を数を数えて』となり、目的語が二つ重なって不自然。", "に": "『に』は位置や相手を示すため、『隆線に数』では数を修飾できない。", "へ": "『へ』は方向を示すため、『隆線へ数』では名詞を修飾できない。"}, "error_tags": {"を": "object marker (double object)", "に": "location or target", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52586, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "指の腹などにある、細く盛り上がった線。指紋を構成する一つ一つの線。", "primary_collocate": null, "pronunciation": "りゅうせん", "ipa": "ɾʲɯːseɴ", "syllable_count": 4, "sentences": [{"text": "それは、誰しもが生涯唯一無二の隆線パターンを有するという生体認証の絶対性に拠る。", "target_word": "隆線", "complexity_tier": "T4", "furigana": "それは、誰[だれ]しもが生涯[しょうがい]唯一無二[ゆいいつむに]の隆線[りゅうせん]パターンを有[ゆう]するという生体認証[せいたいにんしょう]の絶対性[ぜったいせい]に拠[よ]る。", "sentence_source": "mined"}, {"text": "指紋は、指先にある隆線のつくる模様のことだ。", "target_word": "隆線", "complexity_tier": "T3", "furigana": "指紋[しもん]は、指先[ゆびさき]にある隆線[りゅうせん]のつくる模様[もよう]のことだ。", "sentence_source": "generated"}, {"text": "隆線と隆線の間には、細い溝がある。", "target_word": "隆線", "complexity_tier": "T3", "furigana": "隆線[りゅうせん]と隆線[りゅうせん]の間[あいだ]には、細[ほそ]い溝[みぞ]がある。", "sentence_source": "generated"}, {"text": "指を強く押しつけると、隆線の形が紙にはっきり写る。", "target_word": "隆線", "complexity_tier": "T3", "furigana": "指[ゆび]を強[つよ]く押[お]しつけると、隆線[りゅうせん]の形[かたち]が紙[かみ]にはっきり写[うつ]る。", "sentence_source": "generated"}, {"text": "鑑識官は、拡大鏡で隆線の流れを丁寧に調べた。", "target_word": "隆線", "complexity_tier": "T3", "furigana": "鑑識官[かんしきかん]は、拡大鏡[かくだいきょう]で隆線[りゅうせん]の流[なが]れを丁寧[ていねい]に調[しら]べた。", "sentence_source": "generated"}, {"text": "手が荒れて隆線がかすれ、指紋の読み取りが失敗した。", "target_word": "隆線", "complexity_tier": "T3", "furigana": "手[て]が荒[あ]れて隆線[りゅうせん]がかすれ、指紋[しもん]の読[よ]み取[と]りが失敗[しっぱい]した。", "sentence_source": "generated"}, {"text": "隆線は、赤ちゃんが母親のおなかにいるときにできる。", "target_word": "隆線", "complexity_tier": "T3", "furigana": "隆線[りゅうせん]は、赤[あか]ちゃんが母親[ははおや]のおなかにいるときにできる。", "sentence_source": "generated"}, {"text": "隆線の数を数えて、二つの指紋が同じか比べる。", "target_word": "隆線", "complexity_tier": "T3", "furigana": "隆線[りゅうせん]の数[かず]を数[かぞ]えて、二[ふた]つの指紋[しもん]が同[おな]じか比[くら]べる。", "sentence_source": "generated"}, {"text": "指先のやけどで、隆線が一部消えてしまった。", "target_word": "隆線", "complexity_tier": "T3", "furigana": "指先[ゆびさき]のやけどで、隆線[りゅうせん]が一部[いちぶ]消[き]えてしまった。", "sentence_source": "generated"}, {"text": "隆線が渦を巻く指紋は、渦状紋と呼ばれる。", "target_word": "隆線", "complexity_tier": "T4", "furigana": "隆線[りゅうせん]が渦[うず]を巻[ま]く指紋[しもん]は、渦状紋[かじょうもん]と呼[よ]ばれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "隆線", "label": "基本形"}], "register": "technical", "sense_fingerprint": "指紋をつくる細く盛り上がった一本一本の線", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: contains vocabulary far above tier T3: 渦状 (Zipf 1.25)']::text[], '30f189a2-d0da-4e3f-9dc8-fbca6dc3d32d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52586, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "隆線", "is_correct": true, "explanation": "指紋を作る一本一本の盛り上がった線で、唯一無二のパターンを持つという文に合う。"}, {"text": "天候", "is_correct": false, "explanation": "天候は空模様のことで、生体認証のパターンとして唯一無二という文に合わない。"}, {"text": "陳列", "is_correct": false, "explanation": "陳列は品物を並べることで、生体認証のパターンを表さない。"}, {"text": "配給", "is_correct": false, "explanation": "配給は物資を配ることで、人の生体的な特徴を表す文には合わない。"}], "explanations": {"隆線": "指紋を作る一本一本の盛り上がった線で、唯一無二のパターンを持つという文に合う。", "天候": "天候は空模様のことで、生体認証のパターンとして唯一無二という文に合わない。", "陳列": "陳列は品物を並べることで、生体認証のパターンを表さない。", "配給": "配給は物資を配ることで、人の生体的な特徴を表す文には合わない。"}, "sentence_index": 0, "correct_answer": "隆線"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨で道に深い隆線ができた。", "explanation": "ここは〈溝〉の意味。隆線は盛り上がった線なので、深くくぼんだ溝には使わない。"}, {"text": "高速道路で、走行中に隆線を変更した。", "explanation": "ここは〈車線〉の意味。隆線は指紋を作る線で、車が走る道筋を指さない。"}, {"text": "踏切の前で、電車が隆線の上をゆっくり走った。", "explanation": "ここは〈線路〉の意味。隆線は指にある盛り上がった線で、電車が走る軌道ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52586, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隆線", "is_correct": true, "explanation": "指紋の盛り上がった線で、母親のおなかにいるときにできるという文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空の状態で、赤ちゃんの体にできるものとしては合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は文章を書いたもので、おなかにいるときにできるものではない。"}, {"text": "雷", "is_correct": false, "explanation": "雷は自然現象で、赤ちゃんの体にできるという文に合わない。"}], "explanations": {"隆線": "指紋の盛り上がった線で、母親のおなかにいるときにできるという文に合う。", "天気": "天気は空の状態で、赤ちゃんの体にできるものとしては合わない。", "手紙": "手紙は文章を書いたもので、おなかにいるときにできるものではない。", "雷": "雷は自然現象で、赤ちゃんの体にできるという文に合わない。"}, "sentence_index": 6, "correct_answer": "隆線"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "年を重ねて目元に深い隆線ができた。", "explanation": "ここは〈しわ〉の意味。隆線は指紋を作る盛り上がった線で、顔の皮膚のしわには使わない。"}, {"text": "彼女は朝、隆線を三つ編みにしてから出かけた。", "explanation": "ここは〈髪〉の意味。隆線は指紋の線で、髪を編むことはできない。"}, {"text": "着物に美しい隆線が描かれている。", "explanation": "ここは〈模様〉の意味。隆線は指の盛り上がった線で、着物の柄を指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52586, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "指先の隆線を擦り減って、指紋が読み取れなくなった。", "corrected_sentence": "指先の隆線が擦り減って、指紋が読み取れなくなった。", "error_description": "『擦り減る』は自動詞なので、主語の隆線には『が』を付ける。『隆線を擦り減って』は誤りで、正しくは『隆線が擦り減って』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52586, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "指紋の隆線に一本ずつ数えて、鑑定書に記入した。", "corrected_sentence": "指紋の隆線を一本ずつ数えて、鑑定書に記入した。", "error_description": "『数える』の対象は『を』で示す。『隆線に数えて』は誤りで、正しくは『隆線を数えて』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26774ff2-055d-4cbe-95bd-8020a2d6b6a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
