INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52587, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "ほかに同じものがないこと。", "primary_collocate": null, "pronunciation": "むに", "ipa": "mɯɲi", "syllable_count": 2, "sentences": [{"text": "彼の絵は無二の個性があり、他の画家と間違える人は誰もいない。", "target_word": "無二", "complexity_tier": "T3", "furigana": "彼[かれ]の絵[え]は無二[むに]の個性[こせい]があり、他[ほか]の画家[がか]と間違[まちが]える人[ひと]は誰[だれ]もいない。", "sentence_source": "generated"}, {"text": "この古い手紙は、無二の記録として博物館に保管されている。", "target_word": "無二", "complexity_tier": "T3", "furigana": "この古[ふる]い手紙[てがみ]は、無二[むに]の記録[きろく]として博物館[はくぶつかん]に保管[ほかん]されている。", "sentence_source": "generated"}, {"text": "彼女は無二の経験を積み、他の誰にも書けない本を出した。", "target_word": "無二", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は無二[むに]の経験[けいけん]を積[つ]み、他[ほか]の誰[だれ]にも書[か]けない本[ほん]を出[だ]した。", "sentence_source": "generated"}, {"text": "無二の風景を写真に残そうと、早朝から山に登った。", "target_word": "無二", "complexity_tier": "T3", "furigana": "無二[むに]の風景[ふうけい]を写真[しゃしん]に残[のこ]そうと、早朝[そうちょう]から山[やま]に登[のぼ]った。", "sentence_source": "generated"}, {"text": "手作りの指輪は無二の品で、同じ形のものは店にない。", "target_word": "無二", "complexity_tier": "T3", "furigana": "手作[てづく]りの指輪[ゆびわ]は無二[むに]の品[しな]で、同[おな]じ形[かたち]のものは店[みせ]にない。", "sentence_source": "generated"}, {"text": "無二の味を守るため、店主は作り方を誰にも教えなかった。", "target_word": "無二", "complexity_tier": "T3", "furigana": "無二[むに]の味[あじ]を守[まも]るため、店主[てんしゅ]は作[つく]り方[かた]を誰[だれ]にも教[おし]えなかった。", "sentence_source": "generated"}, {"text": "この仏像は無二の価値を持つとして、国が保護している。", "target_word": "無二", "complexity_tier": "T3", "furigana": "この仏像[ぶつぞう]は無二[むに]の価値[かち]を持[も]つとして、国[くに]が保護[ほご]している。", "sentence_source": "generated"}, {"text": "私にとって無二の思い出は、祖母と歩いた夏祭りの夜だ。", "target_word": "無二", "complexity_tier": "T3", "furigana": "私[わたし]にとって無二[むに]の思[おも]い出[で]は、祖母[そぼ]と歩[ある]いた夏祭[なつまつ]りの夜[よる]だ。", "sentence_source": "generated"}, {"text": "無二の恩師に出会えたことを、今も誇りに思っている。", "target_word": "無二", "complexity_tier": "T3", "furigana": "無二[むに]の恩師[おんし]に出会[であ]えたことを、今[いま]も誇[ほこ]りに思[おも]っている。", "sentence_source": "generated"}, {"text": "兄は無二の相棒である愛犬と、毎朝公園を走る。", "target_word": "無二", "complexity_tier": "T3", "furigana": "兄[あに]は無二[むに]の相棒[あいぼう]である愛犬[あいけん]と、毎朝[まいあさ]公園[こうえん]を走[はし]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "無二", "label": "基本形"}, {"form": "無二の", "label": "連体形"}], "register": "formal", "sense_fingerprint": "ほかに同じものがない、そのもの一つだけであること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c159ce9d-4761-4f07-94d2-f261ff2177aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52587, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "無二", "is_correct": true, "explanation": "「無二の個性」で、ほかに同じものがない個性を表す。この空欄に入るのはこの語だけ。"}, {"text": "無効", "is_correct": false, "explanation": "効力がないことを表す語。「無効の個性」では意味が通らない。"}, {"text": "無念", "is_correct": false, "explanation": "残念に思う気持ちを表す語。個性を修飾する位置には入らない。"}, {"text": "無礼", "is_correct": false, "explanation": "礼儀に欠けることを表す語。「無礼の個性」は成り立たない。"}], "explanations": {"無二": "「無二の個性」で、ほかに同じものがない個性を表す。この空欄に入るのはこの語だけ。", "無効": "効力がないことを表す語。「無効の個性」では意味が通らない。", "無念": "残念に思う気持ちを表す語。個性を修飾する位置には入らない。", "無礼": "礼儀に欠けることを表す語。「無礼の個性」は成り立たない。"}, "sentence_index": 0, "correct_answer": "無二"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この地方には無二の湖が点在し、数えきれないほどある。", "explanation": "ここは〈無数〉の意味。無二は一つしかないことを表すので、多数の湖を描く文には合わない。"}, {"text": "彼は無二の手で重い荷物を抱え上げた。", "explanation": "ここは〈両方の〉の意味。無二は「ほかに同じものがない」ことで、両手を表す語ではないので合わない。"}, {"text": "彼は無二の成績で、クラスで二番目になった。", "explanation": "ここは〈順位〉の意味。無二は「ほかに同じものがない」ことで、二番目を表す語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52587, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "無二", "is_correct": true, "explanation": "「無二の価値」で、ほかに代わるもののない価値を表す。この空欄に入るのはこの語だけ。"}, {"text": "無関心", "is_correct": false, "explanation": "物事に関心がないことを表す語。「無関心の価値」では意味が通らない。"}, {"text": "無邪気", "is_correct": false, "explanation": "悪意や裏表がない様子を表す語。価値を表す文には合わない。"}, {"text": "無意味", "is_correct": false, "explanation": "意味がないことを表す語。価値を持つという文と意味が矛盾するので入らない。"}], "explanations": {"無二": "「無二の価値」で、ほかに代わるもののない価値を表す。この空欄に入るのはこの語だけ。", "無関心": "物事に関心がないことを表す語。「無関心の価値」では意味が通らない。", "無邪気": "悪意や裏表がない様子を表す語。価値を表す文には合わない。", "無意味": "意味がないことを表す語。価値を持つという文と意味が矛盾するので入らない。"}, "sentence_index": 6, "correct_answer": "無二"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この二つの茶碗は無二の組で、片方ずつ店に並んでいる。", "explanation": "ここは〈一対の〉の意味。無二は一つしかないことを表し、二つで一組になるものには使わないので合わない。"}, {"text": "電池が切れたので、予備の鍵を無二として使った。", "explanation": "ここは〈代用〉の意味。無二は「唯一のもの」を表し、代わりに使う品を指す語ではないので合わない。"}, {"text": "レシピの分量に無二があったので、料理が失敗した。", "explanation": "ここは〈誤り〉の意味。無二は「ほかに同じものがない」ことで、間違いを指す語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52587, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この書道家の字は無二に味わいがあり、一目で誰の字か分かる。", "corrected_sentence": "この書道家の字は無二の味わいがあり、一目で誰の字か分かる。", "error_description": "「無二」に続く助詞が「に」になっている。「無二の〜」の形で後ろの名詞を修飾するため、正しくは「の」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52587, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は無二に釣り竿を大切に保管している。", "corrected_sentence": "祖父は無二の釣り竿を大切に保管している。", "error_description": "「無二」に続く助詞が「に」になっている。「無二の〜」の形で後ろの名詞を修飾するため、正しくは「の」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
