INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52588, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "他に並ぶものがないこと。唯一であること。", "primary_collocate": null, "pronunciation": "むに", "ipa": "mɯɲi", "syllable_count": 2, "sentences": [{"text": "彼の声は無二の響きを持っていて、すぐに分かる。", "target_word": "無二", "complexity_tier": "T3", "furigana": "彼[かれ]の声[こえ]は無二[むに]の響[ひび]きを持[も]っていて、すぐに分[わ]かる。", "sentence_source": "generated"}, {"text": "彼は私にとって無二の親友で、どんな秘密も話せる。", "target_word": "無二", "complexity_tier": "T3", "furigana": "彼[かれ]は私[わたし]にとって無二[むに]の親友[しんゆう]で、どんな秘密[ひみつ]も話[はな]せる。", "sentence_source": "generated"}, {"text": "この湖の景色は無二のものだと、旅人たちは口をそろえて言う。", "target_word": "無二", "complexity_tier": "T3", "furigana": "この湖[みずうみ]の景色[けしき]は無二[むに]のものだと、旅人[たびびと]たちは口[くち]をそろえて言[い]う。", "sentence_source": "generated"}, {"text": "祖父が焼いた茶碗は無二の宝物で、割れないよう棚の奥にしまってある。", "target_word": "無二", "complexity_tier": "T3", "furigana": "祖父[そふ]が焼[や]いた茶碗[ちゃわん]は無二[むに]の宝物[たからもの]で、割[わ]れないよう棚[たな]の奥[おく]にしまってある。", "sentence_source": "generated"}, {"text": "彼女の歌声は無二の魅力があり、一度聞くと忘れられない。", "target_word": "無二", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の歌声[うたごえ]は無二[むに]の魅力[みりょく]があり、一度[いちど]聞[き]くと忘[わす]れられない。", "sentence_source": "generated"}, {"text": "師匠は私に無二の技を授けてくれた。", "target_word": "無二", "complexity_tier": "T3", "furigana": "師匠[ししょう]は私[わたし]に無二[むに]の技[わざ]を授[さず]けてくれた。", "sentence_source": "generated"}, {"text": "無二の存在である母を失い、彼はしばらく立ち直れなかった。", "target_word": "無二", "complexity_tier": "T3", "furigana": "無二[むに]の存在[そんざい]である母[はは]を失[うしな]い、彼[かれ]はしばらく立[た]ち直[なお]れなかった。", "sentence_source": "generated"}, {"text": "このチームには無二のエースがいるので、試合の最後まで安心して見ていられる。", "target_word": "無二", "complexity_tier": "T3", "furigana": "このチームには無二[むに]のエースがいるので、試合[しあい]の最後[さいご]まで安心[あんしん]して見[み]ていられる。", "sentence_source": "generated"}, {"text": "無二の才能を持つ少年は、十歳で国際大会に出場した。", "target_word": "無二", "complexity_tier": "T3", "furigana": "無二[むに]の才能[さいのう]を持[も]つ少年[しょうねん]は、十歳[じっさい]で国際[こくさい]大会[たいかい]に出場[しゅつじょう]した。", "sentence_source": "generated"}, {"text": "二人は無二の友として、五十年間互いを支え合ってきた。", "target_word": "無二", "complexity_tier": "T3", "furigana": "二人[ふたり]は無二[むに]の友[とも]として、五十年間[ごじゅうねんかん]互[たが]いを支[ささ]え合[あ]ってきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "無二", "label": "基本形"}, {"form": "無二の", "label": "連体形"}], "register": "formal", "sense_fingerprint": "他に並ぶものがない唯一のこと(無二の〜)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c159ce9d-4761-4f07-94d2-f261ff2177aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52588, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "無二", "is_correct": true, "explanation": "「無二の響き」で、ほかに並ぶもののない響きを表す。この空欄に入るのはこの語だけ。"}, {"text": "無効", "is_correct": false, "explanation": "効力がないことを表す語。「無効の響き」では意味が通らない。"}, {"text": "無念", "is_correct": false, "explanation": "残念に思う気持ちを表す語。「無念の響き」は成り立たない。"}, {"text": "無礼", "is_correct": false, "explanation": "礼儀を欠くことを表す語。「無礼の響き」では意味が通らない。"}], "explanations": {"無二": "「無二の響き」で、ほかに並ぶもののない響きを表す。この空欄に入るのはこの語だけ。", "無効": "効力がないことを表す語。「無効の響き」では意味が通らない。", "無念": "残念に思う気持ちを表す語。「無念の響き」は成り立たない。", "無礼": "礼儀を欠くことを表す語。「無礼の響き」では意味が通らない。"}, "sentence_index": 0, "correct_answer": "無二"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜空には無二の星が輝き、数えきれないほどだった。", "explanation": "ここは〈無数〉の意味。無二は「ほかに同じものがない」ことで、数が多いことは表せないので合わない。"}, {"text": "彼は無二の成績で、クラスで二番目の順位を取った。", "explanation": "ここは〈序列〉の意味。無二は「ほかに同じものがない」ことで、成績の並び方を表す語ではないので合わない。"}, {"text": "壊れた時計の無二として、古い時計を使っている。", "explanation": "ここは〈代用〉の意味。無二は「唯一のもの」を表し、代わりに使う品を指す語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52588, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "無二", "is_correct": true, "explanation": "「無二の存在」で、かけがえのない唯一の存在を表す。この空欄に入るのはこの語だけ。"}, {"text": "無関心", "is_correct": false, "explanation": "物事に関心がないことを表す語。「無関心の存在である母」では人を修飾する意味として成り立たない。"}, {"text": "無邪気", "is_correct": false, "explanation": "悪意や裏表がない様子を表す語。「無邪気の存在である母」とは言えず、この空欄には入らない。"}, {"text": "無理", "is_correct": false, "explanation": "道理に合わないことや、できないことを表す語。「無理の存在である母」では意味が通らない。"}], "explanations": {"無二": "「無二の存在」で、かけがえのない唯一の存在を表す。この空欄に入るのはこの語だけ。", "無関心": "物事に関心がないことを表す語。「無関心の存在である母」では人を修飾する意味として成り立たない。", "無邪気": "悪意や裏表がない様子を表す語。「無邪気の存在である母」とは言えず、この空欄には入らない。", "無理": "道理に合わないことや、できないことを表す語。「無理の存在である母」では意味が通らない。"}, "sentence_index": 6, "correct_answer": "無二"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は無二の手で重い箱を抱えて運んだ。", "explanation": "ここは〈両方の〉の意味。無二は「ほかに同じものがない」ことで、両手を表す語ではないので合わない。"}, {"text": "この二つの靴は無二の組で、片方ずつ売られている。", "explanation": "ここは〈一対の〉の意味。無二は一つしかないことを表し、二つで一組になるものには使わないので合わない。"}, {"text": "答案の計算に無二があったので、点数が下がった。", "explanation": "ここは〈誤り〉の意味。無二は「ほかに同じものがない」ことで、間違いを指す語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52588, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は私にとって無二に相談相手で、いつも話を聞いてくれる。", "corrected_sentence": "彼女は私にとって無二の相談相手で、いつも話を聞いてくれる。", "error_description": "「無二」に続く助詞が「に」になっている。「無二の〜」の形で後ろの名詞を修飾するため、正しくは「の」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52588, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は無二を職人として、昔ながらの技法を守り続けている。", "corrected_sentence": "彼は無二の職人として、昔ながらの技法を守り続けている。", "error_description": "「無二」に続く助詞が「を」になっている。「無二の職人」と連体修飾で使うため、正しくは「の」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52589, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「認証がうまくいく」の形で、認証が主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「うまくいく」は目的語を取らないので、「を」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、「認証へうまくいかず」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "相手や引用を表す助詞で、「認証とうまくいかず」は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「認証がうまくいく」の形で、認証が主語になる。", "を": "「うまくいく」は目的語を取らないので、「を」は合わない。", "へ": "方向を表す助詞で、「認証へうまくいかず」は意味が通らない。", "と": "相手や引用を表す助詞で、「認証とうまくいかず」は文として成り立たない。"}, "error_tags": {"を": "目的語（「うまくいく」は取らない）", "へ": "方向（移動の意味がない）", "と": "相手・引用（文脈に当てはまらない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52589, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「認証を設定する」の形で、認証が設定の対象になる。"}, {"text": "が", "is_correct": false, "explanation": "「設定する」は他動詞なので、主語を表す「が」は取らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、「認証へ設定する」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "相手や引用を表す助詞で、「認証と設定する」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「認証を設定する」の形で、認証が設定の対象になる。", "が": "「設定する」は他動詞なので、主語を表す「が」は取らない。", "へ": "方向を表す助詞で、「認証へ設定する」は意味が通らない。", "と": "相手や引用を表す助詞で、「認証と設定する」は文として成り立たない。"}, "error_tags": {"が": "主格（他動詞「設定する」は取らない）", "へ": "方向（移動の意味がない）", "と": "相手・引用（文脈に当てはまらない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52589, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "「本当にその人かどうか」を、特別な体の特徴で確かめることです。", "primary_collocate": null, "pronunciation": "にんしょう", "ipa": "ɲiɴɕoː", "syllable_count": 4, "sentences": [{"text": "銀行のATMで、手のひらを使って認証をした。", "target_word": "認証", "complexity_tier": "T3", "furigana": "銀行[ぎんこう]のATMで、手[て]のひらを使[つか]って認証[にんしょう]をした。", "sentence_source": "generated"}, {"text": "認証がうまくいかず、スマホの画面が開かなかった。", "target_word": "認証", "complexity_tier": "T3", "furigana": "認証[にんしょう]がうまくいかず、スマホの画面[がめん]が開[ひら]かなかった。", "sentence_source": "generated"}, {"text": "目の模様で認証する機械が、駅の改札に置かれた。", "target_word": "認証", "complexity_tier": "T3", "furigana": "目[め]の模様[もよう]で認証[にんしょう]する機械[きかい]が、駅[えき]の改札[かいさつ]に置[お]かれた。", "sentence_source": "generated"}, {"text": "父は声による認証が苦手で、何度も言い直している。", "target_word": "認証", "complexity_tier": "T3", "furigana": "父[ちち]は声[こえ]による認証[にんしょう]が苦手[にがて]で、何度[なんど]も言[い]い直[なお]している。", "sentence_source": "generated"}, {"text": "認証が終わるまで、ドアの前で少し待ってください。", "target_word": "認証", "complexity_tier": "T3", "furigana": "認証[にんしょう]が終[お]わるまで、ドアの前[まえ]で少[すこ]し待[ま]ってください。", "sentence_source": "generated"}, {"text": "学校の図書館では、指を置いて認証すれば本が借りられる。", "target_word": "認証", "complexity_tier": "T3", "furigana": "学校[がっこう]の図書館[としょかん]では、指[ゆび]を置[お]いて認証[にんしょう]すれば本[ほん]が借[か]りられる。", "sentence_source": "generated"}, {"text": "風邪で声が変わり、認証が通らなくなった。", "target_word": "認証", "complexity_tier": "T3", "furigana": "風邪[かぜ]で声[こえ]が変[か]わり、認証[にんしょう]が通[とお]らなくなった。", "sentence_source": "generated"}, {"text": "兄は新しい鍵の認証を設定するため、説明書を読んでいる。", "target_word": "認証", "complexity_tier": "T3", "furigana": "兄[あに]は新[あたら]しい鍵[かぎ]の認証[にんしょう]を設定[せってい]するため、説明書[せつめいしょ]を読[よ]んでいる。", "sentence_source": "generated"}, {"text": "認証の音が鳴ったら、手を離しても大丈夫です。", "target_word": "認証", "complexity_tier": "T3", "furigana": "認証[にんしょう]の音[おと]が鳴[な]ったら、手[て]を離[はな]しても大丈夫[だいじょうぶ]です。", "sentence_source": "generated"}, {"text": "顔の認証に使う写真は、あらかじめ登録しておく。", "target_word": "認証", "complexity_tier": "T3", "furigana": "顔[かお]の認証[にんしょう]に使[つか]う写真[しゃしん]は、あらかじめ登録[とうろく]しておく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "認証", "label": "基本形"}, {"form": "認証する", "label": "サ変動詞"}, {"form": "認証した", "label": "過去形"}, {"form": "認証される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "指・顔・声など体の特徴で本人かどうか確かめること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c159ce9d-4761-4f07-94d2-f261ff2177aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52589, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "認証", "is_correct": true, "explanation": "「認証をした」で、手のひらの特徴で本人確認をすることを表す。この空欄に入るのはこの語だけ。"}, {"text": "散歩", "is_correct": false, "explanation": "歩いて出かける行為。「手のひらを使って散歩をした」は意味が通らない。"}, {"text": "食事", "is_correct": false, "explanation": "食べ物を口にする行為。手のひらを使う文脈とは結びつかない。"}, {"text": "昼寝", "is_correct": false, "explanation": "昼間に眠ること。「手のひらを使って昼寝をした」は成り立たない。"}], "explanations": {"認証": "「認証をした」で、手のひらの特徴で本人確認をすることを表す。この空欄に入るのはこの語だけ。", "散歩": "歩いて出かける行為。「手のひらを使って散歩をした」は意味が通らない。", "食事": "食べ物を口にする行為。手のひらを使う文脈とは結びつかない。", "昼寝": "昼間に眠ること。「手のひらを使って昼寝をした」は成り立たない。"}, "sentence_index": 0, "correct_answer": "認証"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は自分の間違いを認証して、素直に謝った。", "explanation": "ここは〈認める〉の意味。認証は本人確認の手続きを指し、過ちを認める意味では使わないので合わない。"}, {"text": "部長は観葉植物を認証して、窓辺に並べた。", "explanation": "ここは〈飾る・置く〉の意味。認証は本人確認や公的な認定の手続きを指し、植物を並べる意味では使わないので合わない。"}, {"text": "妹は家中を探して、失くした鍵を認証した。", "explanation": "ここは〈発見〉の意味。認証は本人かどうかを確かめる行為で、物を見つける意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52589, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "認証", "is_correct": true, "explanation": "「認証が通る」の形で、本人確認が通ることを表す。この空欄に入るのはこの語だけ。"}, {"text": "食欲", "is_correct": false, "explanation": "食べたい気持ちを表す語。「食欲が通らなくなった」は成り立たない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを表す語。「体重が通らなくなった」は文として合わない。"}, {"text": "寝息", "is_correct": false, "explanation": "眠っている時の呼吸を表す語。「寝息が通らなくなった」は意味が通らない。"}], "explanations": {"認証": "「認証が通る」の形で、本人確認が通ることを表す。この空欄に入るのはこの語だけ。", "食欲": "食べたい気持ちを表す語。「食欲が通らなくなった」は成り立たない。", "体重": "体の重さを表す語。「体重が通らなくなった」は文として合わない。", "寝息": "眠っている時の呼吸を表す語。「寝息が通らなくなった」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "認証"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医者は検査の結果から病名を認証した。", "explanation": "ここは〈診断〉の意味。認証は本人確認の手続きを指し、病気を判断する意味では使わないので合わない。"}, {"text": "先生は小テストを認証して、一人ずつ点数を書き込んだ。", "explanation": "ここは〈採点〉の意味。認証は本人確認の手続きで、答案の出来を評価して点数を付ける意味では使わないので合わない。"}, {"text": "祖父は孫の名前を認証できず、少し困った顔をした。", "explanation": "ここは〈覚える・見分ける〉の意味。認証は機器などで本人かどうかを確かめる行為で、人の名前を思い出す意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52589, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "指紋の認証をうまくいかず、エラーの音が鳴った。", "corrected_sentence": "指紋の認証がうまくいかず、エラーの音が鳴った。", "error_description": "「認証」に続く助詞が「を」になっている。「うまくいかない」は主語を取るので、認証に付く助詞は「が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52589, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会議室の扉は、ICカードの認証を済むと開く。", "corrected_sentence": "会議室の扉は、ICカードの認証が済むと開く。", "error_description": "「認証」に続く助詞が「を」になっている。「済む」は自動詞なので、認証に付く助詞は「が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52590, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「〜を済ませる」の形で、認証が動作の対象になる。"}, {"text": "が", "is_correct": false, "explanation": "「済ませる」は他動詞なので、主語を表す「が」は取らない。"}, {"text": "に", "is_correct": false, "explanation": "「認証に済ませる」は成り立たず、位置や相手を表す文脈がない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、「認証へ済ませる」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「〜を済ませる」の形で、認証が動作の対象になる。", "が": "「済ませる」は他動詞なので、主語を表す「が」は取らない。", "に": "「認証に済ませる」は成り立たず、位置や相手を表す文脈がない。", "へ": "方向を表す助詞で、「認証へ済ませる」は意味が通らない。"}, "error_tags": {"が": "主格（他動詞「済ませる」は取らない）", "に": "位置・相手（文脈に当てはまらない）", "へ": "方向（移動の意味がない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52590, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「認証を終える」の形で、認証が終える動作の対象になる。"}, {"text": "と", "is_correct": false, "explanation": "並列の相手を示す「と」だが、「認証と終えた」では終える動作の対象にならず文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は比べる相手が必要だが、この文にはなく、「認証より終えた」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」だが、「認証の終えた人」は続きの語句とつながらず不自然。"}], "correct_answer": "を", "explanations": {"を": "「認証を終える」の形で、認証が終える動作の対象になる。", "と": "並列の相手を示す「と」だが、「認証と終えた」では終える動作の対象にならず文が成り立たない。", "より": "比較の「より」は比べる相手が必要だが、この文にはなく、「認証より終えた」は成り立たない。", "の": "連体修飾の「の」だが、「認証の終えた人」は続きの語句とつながらず不自然。"}, "error_tags": {"と": "並列（終える動作の対象にならない）", "より": "比較（比べる相手がない）", "の": "連体修飾（続きとつながらない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52590, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある人が本人であることを、身体的特徴や行動のパターンを用いて確認すること。", "primary_collocate": null, "pronunciation": "にんしょう", "ipa": "ɲiɴɕoː", "syllable_count": 4, "sentences": [{"text": "空港では、指紋による認証が新たに導入された。", "target_word": "認証", "complexity_tier": "T3", "furigana": "空港[くうこう]では、指紋[しもん]による認証[にんしょう]が新[あら]たに導入[どうにゅう]された。", "sentence_source": "generated"}, {"text": "空港の入口で顔の認証を済ませると、扉が自動で開いた。", "target_word": "認証", "complexity_tier": "T3", "furigana": "空港[くうこう]の入口[いりぐち]で顔[かお]の認証[にんしょう]を済[す]ませると、扉[とびら]が自動[じどう]で開[ひら]いた。", "sentence_source": "generated"}, {"text": "指先が濡れていると、認証に失敗することがある。", "target_word": "認証", "complexity_tier": "T3", "furigana": "指先[ゆびさき]が濡[ぬ]れていると、認証[にんしょう]に失敗[しっぱい]することがある。", "sentence_source": "generated"}, {"text": "認証が通らなかったので、警備員が本人かどうかを直接確認した。", "target_word": "認証", "complexity_tier": "T3", "furigana": "認証[にんしょう]が通[とお]らなかったので、警備員[けいびいん]が本人[ほんにん]かどうかを直接[ちょくせつ]確認[かくにん]した。", "sentence_source": "generated"}, {"text": "新しいスマートフォンは、持ち主の認証を一秒以内に終える。", "target_word": "認証", "complexity_tier": "T3", "furigana": "新[あたら]しいスマートフォンは、持[も]ち主[ぬし]の認証[にんしょう]を一秒[いちびょう]以内[いない]に終[お]える。", "sentence_source": "generated"}, {"text": "金庫を開けるには、社員一人ずつの認証が必要だ。", "target_word": "認証", "complexity_tier": "T3", "furigana": "金庫[きんこ]を開[あ]けるには、社員[しゃいん]一人[ひとり]ずつの認証[にんしょう]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "虹彩は双子でも違うため、認証の精度が高い。", "target_word": "認証", "complexity_tier": "T3", "furigana": "虹彩[こうさい]は双子[ふたご]でも違[ちが]うため、認証[にんしょう]の精度[せいど]が高[たか]い。", "sentence_source": "generated"}, {"text": "認証を終えた人だけが、研究室の奥へ入ることができる。", "target_word": "認証", "complexity_tier": "T3", "furigana": "認証[にんしょう]を終[お]えた人[ひと]だけが、研究室[けんきゅうしつ]の奥[おく]へ入[はい]ることができる。", "sentence_source": "generated"}, {"text": "認証の際は、カメラの前で帽子を取ってください。", "target_word": "認証", "complexity_tier": "T3", "furigana": "認証[にんしょう]の際[さい]は、カメラの前[まえ]で帽子[ぼうし]を取[と]ってください。", "sentence_source": "generated"}, {"text": "登録した手のひらで認証を行うので、カードを持ち歩く必要がない。", "target_word": "認証", "complexity_tier": "T3", "furigana": "登録[とうろく]した手[て]のひらで認証[にんしょう]を行[おこな]うので、カードを持[も]ち歩[ある]く必要[ひつよう]がない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "認証", "label": "基本形"}, {"form": "認証する", "label": "サ変動詞"}, {"form": "認証した", "label": "過去形"}, {"form": "認証される", "label": "受身形"}], "register": "technical", "sense_fingerprint": "身体的特徴などで本人かどうかを確認する手続き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c159ce9d-4761-4f07-94d2-f261ff2177aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52590, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "認証", "is_correct": true, "explanation": "「指紋による認証」で、身体の特徴から本人かどうかを確かめる手続きを表す。この空欄に入るのはこの語だけ。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度を表す語。「指紋による体温」は文として成り立たない。"}, {"text": "脈拍", "is_correct": false, "explanation": "心臓の拍動を表す語。「指紋による脈拍」は文として成り立たない。"}, {"text": "血圧", "is_correct": false, "explanation": "血管内の圧力を表す語。「指紋による血圧」は文として成り立たない。"}], "explanations": {"認証": "「指紋による認証」で、身体の特徴から本人かどうかを確かめる手続きを表す。この空欄に入るのはこの語だけ。", "体温": "体の温度を表す語。「指紋による体温」は文として成り立たない。", "脈拍": "心臓の拍動を表す語。「指紋による脈拍」は文として成り立たない。", "血圧": "血管内の圧力を表す語。「指紋による血圧」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "認証"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母は最近、家族の名前を認証できなくなってきた。", "explanation": "ここは〈見分ける・覚える〉の意味。認証は本人確認の手続きを指し、人の名前を思い出す意味では使わないので合わない。"}, {"text": "彼は自分のミスを認証して、すぐに謝った。", "explanation": "ここは〈認める〉の意味。認証は本人確認の手続きを指し、過ちを認める意味では使わないので合わない。"}, {"text": "部長は新しい机を認証して、午後に部屋へ運ばせた。", "explanation": "ここは〈運ぶ〉の意味。認証は本人確認や認定の手続きを指し、物を運ぶ意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52590, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "認証", "is_correct": true, "explanation": "「認証の精度」で、本人かどうかを判定する正確さを表す。この空欄に入るのはこの語だけ。"}, {"text": "紙", "is_correct": false, "explanation": "材料の名前で、「紙の精度」という言い方は成り立たない。"}, {"text": "雨", "is_correct": false, "explanation": "天気の現象で、判定の正確さを表す「精度」とは結びつかない。"}, {"text": "音楽", "is_correct": false, "explanation": "芸術の分野を表す語で、「音楽の精度」では文脈に合わない。"}], "explanations": {"認証": "「認証の精度」で、本人かどうかを判定する正確さを表す。この空欄に入るのはこの語だけ。", "紙": "材料の名前で、「紙の精度」という言い方は成り立たない。", "雨": "天気の現象で、判定の正確さを表す「精度」とは結びつかない。", "音楽": "芸術の分野を表す語で、「音楽の精度」では文脈に合わない。"}, "sentence_index": 6, "correct_answer": "認証"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は夕食のスープを認証して、塩を一つまみ足した。", "explanation": "ここは〈味見〉の意味。認証は本人確認の手続きを指し、料理の味を確かめる意味では使わないので合わない。"}, {"text": "母は冷蔵庫の中身を認証して、古い牛乳を捨てた。", "explanation": "ここは〈点検〉の意味。認証は本人確認や認定の手続きを指し、中身を調べる意味では使わないので合わない。"}, {"text": "先生は答案を認証して、一問ずつ点数を付けた。", "explanation": "ここは〈採点〉の意味。認証は本人確認の手続きで、答案の正誤を判定して点数を付ける意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52590, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社員証の認証を済むまで、扉は開かない。", "corrected_sentence": "社員証の認証が済むまで、扉は開かない。", "error_description": "「認証」に続く助詞が「を」になっている。「済む」は自動詞なので、認証に付く助詞は「が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52590, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "スマートフォンの認証を失敗すると、ロック画面は解除されない。", "corrected_sentence": "スマートフォンの認証に失敗すると、ロック画面は解除されない。", "error_description": "「失敗する」は「〜に失敗する」の形を取るため、認証に続く助詞は「を」ではなく「に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52591, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。『鑑識の結果』で、鑑識を名詞『結果』に結びつける連体修飾の助詞。"}, {"text": "が", "is_correct": false, "explanation": "『鑑識が結果』では鑑識が主語になり、『結果』が名詞として続かず成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "『鑑識を結果』では鑑識が目的語になり、『結果』と続けられない。"}, {"text": "で", "is_correct": false, "explanation": "『鑑識で結果』は手段を示すが、名詞句『鑑識の結果』の形が崩れる。"}], "correct_answer": "の", "explanations": {"の": "正解。『鑑識の結果』で、鑑識を名詞『結果』に結びつける連体修飾の助詞。", "が": "『鑑識が結果』では鑑識が主語になり、『結果』が名詞として続かず成り立たない。", "を": "『鑑識を結果』では鑑識が目的語になり、『結果』と続けられない。", "で": "『鑑識で結果』は手段を示すが、名詞句『鑑識の結果』の形が崩れる。"}, "error_tags": {"の": "連体修飾", "が": "主語", "を": "目的語", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
