INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52591, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事を見分けること。特に、証拠を調べて正しく判断すること。", "primary_collocate": null, "pronunciation": "かんしき", "ipa": "kaɴɕikʲi", "syllable_count": 4, "sentences": [{"text": "この絵が本物かどうかは、専門家の鑑識の結果を待たなければ分からない。", "target_word": "鑑識", "complexity_tier": "T3", "furigana": "この絵が本物かどうかは、専門家の[鑑識|かんしき]の結果を待たなければ分からない。", "sentence_source": "generated"}, {"text": "鑑識の結果、この手紙は偽物だと分かった。", "target_word": "鑑識", "complexity_tier": "T3", "furigana": "鑑識[かんしき]の結果[けっか]、この手紙[てがみ]は偽物[にせもの]だと分[わ]かった。", "sentence_source": "generated"}, {"text": "警察の鑑識が、窓についた泥を詳しく調べている。", "target_word": "鑑識", "complexity_tier": "T3", "furigana": "警察[けいさつ]の鑑識[かんしき]が、窓[まど]についた泥[どろ]を詳[くわ]しく調[しら]べている。", "sentence_source": "generated"}, {"text": "彼女は筆跡の鑑識に二十年携わってきた。", "target_word": "鑑識", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は筆跡[ひっせき]の鑑識[かんしき]に二十年[にじゅうねん]携[たずさ]わってきた。", "sentence_source": "generated"}, {"text": "鑑識が終わるまで、証拠品には手を触れないでください。", "target_word": "鑑識", "complexity_tier": "T3", "furigana": "鑑識[かんしき]が終[お]わるまで、証拠品[しょうこひん]には手[て]を触[ふ]れないでください。", "sentence_source": "generated"}, {"text": "火事の原因は、鑑識の調査でようやく明らかになった。", "target_word": "鑑識", "complexity_tier": "T3", "furigana": "火事[かじ]の原因[げんいん]は、鑑識[かんしき]の調査[ちょうさ]でようやく明[あき]らかになった。", "sentence_source": "generated"}, {"text": "弟は警察の鑑識の仕事に憧れ、大学で化学を勉強している。", "target_word": "鑑識", "complexity_tier": "T3", "furigana": "弟は警察の[鑑識|かんしき]の仕事に憧れ、大学で化学を勉強している。", "sentence_source": "generated"}, {"text": "新しい鑑識の技術により、古い事件が解決した。", "target_word": "鑑識", "complexity_tier": "T3", "furigana": "新[あたら]しい鑑識[かんしき]の技術[ぎじゅつ]により、古[ふる]い事件[じけん]が解決[かいけつ]した。", "sentence_source": "generated"}, {"text": "鑑識を担当する人は、小さな違いも見逃さない注意深さが必要だ。", "target_word": "鑑識", "complexity_tier": "T3", "furigana": "鑑識[かんしき]を担当[たんとう]する人[ひと]は、小[ちい]さな違[ちが]いも見逃[みのが]さない注意深[ちゅういぶか]さが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "売り手の話だけでは分からないので、鑑識の専門家に依頼して真偽を確かめた。", "target_word": "鑑識", "complexity_tier": "T3", "furigana": "売り手の話だけでは分からないので、[鑑識|かんしき]の専門家に依頼して真偽を確かめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鑑識", "label": "基本形"}, {"form": "鑑識の", "label": "連体形"}, {"form": "鑑識に出す", "label": "慣用的な言い方"}], "register": "technical", "sense_fingerprint": "本物か偽物かなどを調べて見分け、正しく判断すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T4: contains vocabulary far above tier T4: 注意深 (Zipf 1.07)']::text[], 'c159ce9d-4761-4f07-94d2-f261ff2177aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52591, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鑑識", "is_correct": true, "explanation": "正解。専門家が絵の真偽を見分けて判定する作業を指し、結果を待つ文脈に合う。"}, {"text": "出版", "is_correct": false, "explanation": "本などを世に出すこと。『出版の結果』は意味をなさず、真偽の判断の文脈に合わない。"}, {"text": "演奏", "is_correct": false, "explanation": "音楽を奏でること。演奏の結果を待つ対象にならず、真偽の判断とは結びつかない。"}, {"text": "注文", "is_correct": false, "explanation": "品物を頼むこと。『注文の結果を待つ』では真偽を判断する内容にならない。"}], "explanations": {"鑑識": "正解。専門家が絵の真偽を見分けて判定する作業を指し、結果を待つ文脈に合う。", "出版": "本などを世に出すこと。『出版の結果』は意味をなさず、真偽の判断の文脈に合わない。", "演奏": "音楽を奏でること。演奏の結果を待つ対象にならず、真偽の判断とは結びつかない。", "注文": "品物を頼むこと。『注文の結果を待つ』では真偽を判断する内容にならない。"}, "sentence_index": 0, "correct_answer": "鑑識"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は床を鑑識して、毎朝ぴかぴかに磨いている。", "explanation": "ここは〈掃除する〉の意味。鑑識は見分けることで、床を磨く意味はないので合わない。"}, {"text": "彼女は皿の上の料理を鑑識して、床にこぼした。", "explanation": "ここは〈こぼす〉の意味。鑑識は見分けることで、物を落とす意味はないので合わない。"}, {"text": "彼女は重い荷物を鑑識して、二階まで運んだ。", "explanation": "ここは〈運ぶ〉の意味。鑑識は見分けることで、荷物を移動させる意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52591, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鑑識", "is_correct": true, "explanation": "正解。警察の鑑識という職業を指し、『鑑識の仕事』として成り立つ。"}, {"text": "放火", "is_correct": false, "explanation": "火をつける犯罪。『放火の仕事』とは言えず、職業として成り立たない。"}, {"text": "盗難", "is_correct": false, "explanation": "物が盗まれること。『盗難の仕事』は成り立たず、職業を示せない。"}, {"text": "誘拐", "is_correct": false, "explanation": "人を連れ去る犯罪。『誘拐の仕事』は職業として不自然で、文が成立しない。"}], "explanations": {"鑑識": "正解。警察の鑑識という職業を指し、『鑑識の仕事』として成り立つ。", "放火": "火をつける犯罪。『放火の仕事』とは言えず、職業として成り立たない。", "盗難": "物が盗まれること。『盗難の仕事』は成り立たず、職業を示せない。", "誘拐": "人を連れ去る犯罪。『誘拐の仕事』は職業として不自然で、文が成立しない。"}, "sentence_index": 6, "correct_answer": "鑑識"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は朝、野菜を鑑識して味噌汁の具にした。", "explanation": "ここは〈調理する〉の意味。鑑識は見分ける行為で、野菜を料理に仕立てる意味はないので合わない。"}, {"text": "彼は英語の論文を鑑識して、日本語に訳した。", "explanation": "ここは〈翻訳する〉の意味。鑑識は真偽や良し悪しを見分けることで、言語を置き換える意味はないので合わない。"}, {"text": "古いCDを鑑識して、床に投げ捨てた。", "explanation": "ここは〈投げ捨てる〉の意味。鑑識は見分けることで、物を乱暴に捨てる意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52591, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この壺が本物かどうかは、専門家の鑑識を結果を待たなければ分からない。", "corrected_sentence": "この壺が本物かどうかは、専門家の鑑識の結果を待たなければ分からない。", "error_description": "『鑑識』の後は『の』で『鑑識の結果』と続ける。『を』では『結果』と目的語が並んでしまい、名詞句が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52591, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟は警察の鑑識を仕事に憧れて、大学で化学を学んでいる。", "corrected_sentence": "弟は警察の鑑識の仕事に憧れて、大学で化学を学んでいる。", "error_description": "『鑑識』は『鑑識の仕事』と続け、『の』で『仕事』を修飾する。『鑑識を』と助詞を変えると『仕事に憧れる』へつながらず不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
