INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52592, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52592, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の良し悪しや真偽を見分けること。特に、犯罪捜査などで証拠を詳しく調べること。", "primary_collocate": null, "pronunciation": "かんしき", "ipa": "kaɴɕikʲi", "syllable_count": 4, "sentences": [{"text": "まず、現場や鑑識ラボにおいて、肉眼では捉えられぬ潜在指紋を、シアノアクリレート法や光学的手法といったアプローチにより顕在化させる。", "target_word": "鑑識", "complexity_tier": "T5", "furigana": "まず、現場[げんば]や鑑識[かんしき]ラボにおいて、肉眼[にくがん]では捉[とら]えられぬ潜在指紋[せんざいしもん]を、シアノアクリレート法[ほう]や光学的[こうがくてき]手法[しゅほう]といったアプローチにより顕在化[けんざいか]させる。", "sentence_source": "mined"}, {"text": "現場に到着した鑑識は、床に残った足跡を慎重に写真に撮った。", "target_word": "鑑識", "complexity_tier": "T3", "furigana": "現場[げんば]に到着[とうちゃく]した鑑識[かんしき]は、床[ゆか]に残[のこ]った足跡[あしあと]を慎重[しんちょう]に写真[しゃしん]に撮[と]った。", "sentence_source": "generated"}, {"text": "鑑識の調べで、割れた窓の指紋が犯人のものと一致した。", "target_word": "鑑識", "complexity_tier": "T3", "furigana": "鑑識[かんしき]の調[しら]べで、割[わ]れた窓[まど]の指紋[しもん]が犯人[はんにん]のものと一致[いっち]した。", "sentence_source": "generated"}, {"text": "事件の翌朝、鑑識が部屋の隅々まで証拠を探した。", "target_word": "鑑識", "complexity_tier": "T3", "furigana": "事件[じけん]の翌朝[よくあさ]、鑑識[かんしき]が部屋[へや]の隅々[すみずみ]まで証拠[しょうこ]を探[さが]した。", "sentence_source": "generated"}, {"text": "髪の毛は鑑識に回され、DNAの検査が行われる。", "target_word": "鑑識", "complexity_tier": "T3", "furigana": "髪[かみ]の毛[け]は鑑識[かんしき]に回[まわ]され、DNAの検査[けんさ]が行[おこな]われる。", "sentence_source": "generated"}, {"text": "鑑識の報告によると、凶器は包丁ではなく工具だった。", "target_word": "鑑識", "complexity_tier": "T3", "furigana": "鑑識[かんしき]の報告[ほうこく]によると、凶器[きょうき]は包丁[ほうちょう]ではなく工具[こうぐ]だった。", "sentence_source": "generated"}, {"text": "雨で足跡が消えたため、鑑識は土の中の繊維を調べた。", "target_word": "鑑識", "complexity_tier": "T3", "furigana": "雨[あめ]で足跡[あしあと]が消[き]えたため、鑑識[かんしき]は土[つち]の中[なか]の繊維[せんい]を調[しら]べた。", "sentence_source": "generated"}, {"text": "彼は長年、警察で鑑識の仕事に就いている。", "target_word": "鑑識", "complexity_tier": "T3", "furigana": "彼[かれ]は長年[ながねん]、警察[けいさつ]で鑑識[かんしき]の仕事[しごと]に就[つ]いている。", "sentence_source": "generated"}, {"text": "鑑識が到着するまで、現場に入らないでください。", "target_word": "鑑識", "complexity_tier": "T3", "furigana": "鑑識[かんしき]が到着[とうちゃく]するまで、現場[げんば]に入[はい]らないでください。", "sentence_source": "generated"}, {"text": "鑑識の結果が出るまで、警察は犯人を決めつけなかった。", "target_word": "鑑識", "complexity_tier": "T3", "furigana": "鑑識[かんしき]の結果[けっか]が出[で]るまで、警察[けいさつ]は犯人[はんにん]を決[き]めつけなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鑑識", "label": "基本形"}, {"form": "鑑識の", "label": "連体形"}, {"form": "鑑識に回す", "label": "慣用的な言い方"}], "register": "technical", "sense_fingerprint": "犯罪捜査で指紋や足跡などの証拠を詳しく調べること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T4: contains vocabulary far above tier T4: シアノアクリレート (Zipf 1.04)']::text[], 'c159ce9d-4761-4f07-94d2-f261ff2177aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52592, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鑑識", "is_correct": true, "explanation": "正解。現場や鑑識ラボで指紋などの証拠を詳しく調べる作業を指し、文脈に合う。"}, {"text": "尋問", "is_correct": false, "explanation": "容疑者に質問して供述を得る行為。尋問ラボとは言えず、指紋を顕在化させる文脈に合わない。"}, {"text": "押収", "is_correct": false, "explanation": "証拠品を強制的に取り上げること。押収ラボでは意味をなさず、検出の作業を表せない。"}, {"text": "逮捕", "is_correct": false, "explanation": "容疑者の身柄を拘束すること。逮捕ラボは成り立たず、指紋の検出という内容に合わない。"}], "explanations": {"鑑識": "正解。現場や鑑識ラボで指紋などの証拠を詳しく調べる作業を指し、文脈に合う。", "尋問": "容疑者に質問して供述を得る行為。尋問ラボとは言えず、指紋を顕在化させる文脈に合わない。", "押収": "証拠品を強制的に取り上げること。押収ラボでは意味をなさず、検出の作業を表せない。", "逮捕": "容疑者の身柄を拘束すること。逮捕ラボは成り立たず、指紋の検出という内容に合わない。"}, "sentence_index": 0, "correct_answer": "鑑識"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察は容疑者を鑑識して、朝早くに身柄を押さえた。", "explanation": "ここは〈逮捕する〉の意味。鑑識は物の真偽や証拠を見分けることで、人の身柄を押さえる意味はないので合わない。"}, {"text": "彼は有名画家の作品を鑑識して、紙くずのように丸めた。", "explanation": "ここは〈丸める〉の意味。鑑識は見分けることで、紙を丸める意味はないので合わない。"}, {"text": "彼女は大きな箱を鑑識して、庭で燃やした。", "explanation": "ここは〈燃やす〉の意味。鑑識は見分けることで、焼く意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52592, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鑑識", "is_correct": true, "explanation": "正解。主語として、足跡が消えた後に土の繊維を調べる主体になる。"}, {"text": "証言", "is_correct": false, "explanation": "人が事実を述べること。主語にしても『土の中の繊維を調べた』と続かない。"}, {"text": "監視", "is_correct": false, "explanation": "見張ること。『監視は繊維を調べた』と主語が合わず、調査の主体にならない。"}, {"text": "発見", "is_correct": false, "explanation": "見つけること。『発見は〜調べた』と行為者にならず、文が成立しない。"}], "explanations": {"鑑識": "正解。主語として、足跡が消えた後に土の繊維を調べる主体になる。", "証言": "人が事実を述べること。主語にしても『土の中の繊維を調べた』と続かない。", "監視": "見張ること。『監視は繊維を調べた』と主語が合わず、調査の主体にならない。", "発見": "見つけること。『発見は〜調べた』と行為者にならず、文が成立しない。"}, "sentence_index": 6, "correct_answer": "鑑識"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は朝、魚を鑑識して刺身にした。", "explanation": "ここは〈調理する〉の意味。鑑識は見分ける行為で、料理として手を加える意味はないので合わない。"}, {"text": "彼は英語の手紙を鑑識して、日本語に直した。", "explanation": "ここは〈翻訳する〉の意味。鑑識は真偽や良し悪しを見分けることで、言語を置き換える意味はないので合わない。"}, {"text": "古本を鑑識して、別の本と交換した。", "explanation": "ここは〈交換する〉の意味。鑑識は見分けることで、物を取り替える意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52592, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鑑識が調べで、割れた窓の指紋が犯人のものだと分かった。", "corrected_sentence": "鑑識の調べで、割れた窓の指紋が犯人のものだと分かった。", "error_description": "『鑑識』の後は『の』で『鑑識の調べ』と続ける。『が』では主語になり、『調べで』と続かず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52592, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨で足跡が消えたため、鑑識を土の中の繊維を調べることにした。", "corrected_sentence": "雨で足跡が消えたため、鑑識は土の中の繊維を調べることにした。", "error_description": "『鑑識』は主語なので『は』。『を』では目的語になり、『土の中の繊維を調べる』と目的語が二つ並んで不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
