INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52593, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "おちているものを、てでとること。", "primary_collocate": null, "pronunciation": "ひろいあげる", "ipa": "çiɾoiaɡeɾɯ", "syllable_count": 6, "sentences": [{"text": "床に落ちた鍵を拾い上げて、彼に渡した。", "target_word": "拾い上げて", "complexity_tier": "T2", "furigana": "床[ゆか]に落[お]ちた鍵[かぎ]を拾[ひろ]い上[あ]げて、彼[かれ]に渡[わた]した。", "sentence_source": "generated"}, {"text": "子どもは道に落ちていたボールを拾い上げた。", "target_word": "拾い上げた", "complexity_tier": "T2", "furigana": "子[こ]どもは道[みち]に落[お]ちていたボールを拾[ひろ]い上[あ]げた。", "sentence_source": "generated"}, {"text": "風で飛んだ帽子を、男の人が拾い上げてくれた。", "target_word": "拾い上げて", "complexity_tier": "T3", "furigana": "風[かぜ]で飛[と]んだ帽子[ぼうし]を、男[おとこ]の人[ひと]が拾[ひろ]い上[あ]げてくれた。", "sentence_source": "generated"}, {"text": "彼女はかがんで、地面に落ちたどんぐりを拾い上げた。", "target_word": "拾い上げた", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はかがんで、地面[じめん]に落[お]ちたどんぐりを拾[ひろ]い上[あ]げた。", "sentence_source": "generated"}, {"text": "机の下に落ちたペンを拾い上げて、筆箱に入れた。", "target_word": "拾い上げて", "complexity_tier": "T2", "furigana": "机[つくえ]の下[した]に落[お]ちたペンを拾[ひろ]い上[あ]げて、筆箱[ふでばこ]に入[い]れた。", "sentence_source": "generated"}, {"text": "祖母は庭に落ちた柿を一つずつ拾い上げている。", "target_word": "拾い上げている", "complexity_tier": "T3", "furigana": "祖母[そぼ]は庭[にわ]に落[お]ちた柿[かき]を一[ひと]つずつ拾[ひろ]い上[あ]げている。", "sentence_source": "generated"}, {"text": "電車の中で落とした財布を、親切な人が拾い上げて届けてくれた。", "target_word": "拾い上げて", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の中[なか]で落[お]とした財布[さいふ]を、親切[しんせつ]な人[ひと]が拾[ひろ]い上[あ]げて届[とど]けてくれた。", "sentence_source": "generated"}, {"text": "犬は散歩中に落ちていた枝を拾い上げて、主人のところへ持ってきた。", "target_word": "拾い上げて", "complexity_tier": "T3", "furigana": "犬[いぬ]は散歩中[さんぽちゅう]に落[お]ちていた枝[えだ]を拾[ひろ]い上[あ]げて、主人[しゅじん]のところへ持[も]ってきた。", "sentence_source": "generated"}, {"text": "割れたコップのかけらを、手を切らないように拾い上げた。", "target_word": "拾い上げた", "complexity_tier": "T3", "furigana": "割[わ]れたコップのかけらを、手[て]を切[き]らないように拾[ひろ]い上[あ]げた。", "sentence_source": "generated"}, {"text": "試合のあと、選手たちはグラウンドに落ちたごみを拾い上げた。", "target_word": "拾い上げた", "complexity_tier": "T3", "furigana": "試合[しあい]のあと、選手[せんしゅ]たちはグラウンドに落[お]ちたごみを拾[ひろ]い上[あ]げた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "拾い上げる", "label": "辞書形"}, {"form": "拾い上げます", "label": "ます形"}, {"form": "拾い上げた", "label": "た形"}, {"form": "拾い上げて", "label": "て形"}, {"form": "拾い上げない", "label": "ない形"}, {"form": "拾い上げれば", "label": "仮定形"}, {"form": "拾い上げられる", "label": "可能形"}, {"form": "拾い上げよう", "label": "意向形"}], "register": "neutral", "sense_fingerprint": "落ちている物を手で持ち上げて取る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c159ce9d-4761-4f07-94d2-f261ff2177aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52593, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拾い上げて", "is_correct": true, "explanation": "正解。手で拾い上げて、後続の『彼に渡した』へつなぐて形。"}, {"text": "歌って", "is_correct": false, "explanation": "『鍵を歌う』は成り立たず、落ちた物を取る文脈に合わない。"}, {"text": "溶かして", "is_correct": false, "explanation": "『鍵を溶かす』では手渡す流れが成立せず、文脈に合わない。"}, {"text": "吹いて", "is_correct": false, "explanation": "『鍵を吹く』は意味をなさず、落ちた物を取る文脈に合わない。"}], "explanations": {"拾い上げて": "正解。手で拾い上げて、後続の『彼に渡した』へつなぐて形。", "歌って": "『鍵を歌う』は成り立たず、落ちた物を取る文脈に合わない。", "溶かして": "『鍵を溶かす』では手渡す流れが成立せず、文脈に合わない。", "吹いて": "『鍵を吹く』は意味をなさず、落ちた物を取る文脈に合わない。"}, "sentence_index": 0, "correct_answer": "拾い上げて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は庭の大きな木を拾い上げて、業者に片付けてもらった。", "explanation": "ここは〈取り除く〉の意味。拾い上げるは手で物を取る意味で、大きな木を撤去する意味はないので合わない。"}, {"text": "彼女は床にこぼれた水を、雑巾で拾い上げた。", "explanation": "ここは〈拭き取る〉の意味。拾い上げるは散らばった物を手で取る意味で、液体を拭く意味はないので合わない。"}, {"text": "彼女は部屋の空気を拾い上げて、窓を開けた。", "explanation": "ここは〈入れ替える〉の意味。拾い上げるは物を取る意味で、空気を入れ替える意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52593, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拾い上げて", "is_correct": true, "explanation": "正解。て形で、後続の『届けてくれた』へ続き、親切な人の動作として合う。"}, {"text": "踊って", "is_correct": false, "explanation": "『財布を踊る』は成り立たず、届ける文脈に合わない。"}, {"text": "煮込んで", "is_correct": false, "explanation": "『財布を煮込む』は成り立たず、届ける文脈に合わない。"}, {"text": "割って", "is_correct": false, "explanation": "『財布を割る』は届ける文脈に合わず、財布を返すという内容と矛盾する。"}], "explanations": {"拾い上げて": "正解。て形で、後続の『届けてくれた』へ続き、親切な人の動作として合う。", "踊って": "『財布を踊る』は成り立たず、届ける文脈に合わない。", "煮込んで": "『財布を煮込む』は成り立たず、届ける文脈に合わない。", "割って": "『財布を割る』は届ける文脈に合わず、財布を返すという内容と矛盾する。"}, "sentence_index": 6, "correct_answer": "拾い上げて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "選手たちはグラウンドの広さを拾い上げた。", "explanation": "ここは〈測る〉の意味。拾い上げるは物を手で取る意味で、広さを量る意味はないので合わない。"}, {"text": "彼らは夜、旅の行き先を拾い上げて、すぐに決めた。", "explanation": "ここは〈決める〉の意味。拾い上げるは落ちた物を手で取る意味で、行き先を選び定める意味はないので合わない。"}, {"text": "審判はグラウンドを拾い上げて、点検した。", "explanation": "ここは〈点検する〉の意味。拾い上げるは物を取る意味で、場所を調べる意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52593, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "床に落ちた鍵に拾い上げて、彼に返した。", "corrected_sentence": "床に落ちた鍵を拾い上げて、彼に返した。", "error_description": "『拾い上げる』の目的語は『〜を』。『鍵に』では対象を示せず、『鍵に拾い上げて』は不自然。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "拾い上げた", "is_correct": true, "explanation": "正解。文末の過去の動作を表すた形で、ボールを拾った出来事と合う。"}, {"text": "拾い上げない", "is_correct": false, "explanation": "否定形。実際に行った動作『拾い上げた』と合わない。"}, {"text": "拾い上げられる", "is_correct": false, "explanation": "可能・受け身の形。過去に実際に行った動作を述べる文では不自然。"}, {"text": "拾い上げよう", "is_correct": false, "explanation": "意向形で『〜しよう』と意志を表し、過去の出来事を述べる文と合わない。"}], "correct_form": "拾い上げた", "base_form": "拾い上げる", "form_label": "た形", "sentence_index": 1, "explanations": {"拾い上げた": "正解。文末の過去の動作を表すた形で、ボールを拾った出来事と合う。", "拾い上げない": "否定形。実際に行った動作『拾い上げた』と合わない。", "拾い上げられる": "可能・受け身の形。過去に実際に行った動作を述べる文では不自然。", "拾い上げよう": "意向形で『〜しよう』と意志を表し、過去の出来事を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52593, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電車の中で落とした財布を、親切な人が拾い上げられて駅に届けてくれた。", "corrected_sentence": "電車の中で落とした財布を、親切な人が拾い上げて駅に届けてくれた。", "error_description": "行為者は『親切な人』なので能動の『拾い上げて』が正しい。『拾い上げられて』は受け身で、財布が動作を受ける形になり文の主語と合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "拾い上げて", "is_correct": true, "explanation": "正解。て形で、後続の『持ってきた』へ続ける。"}, {"text": "拾い上げます", "is_correct": false, "explanation": "丁寧体。『〜て、持ってきた』と続かず、文の流れに合わない。"}, {"text": "拾い上げれば", "is_correct": false, "explanation": "仮定形。『〜て』の連続を作れず、文がつながらない。"}, {"text": "拾い上げている", "is_correct": false, "explanation": "継続・結果の形。『〜て、持ってきた』と続く一連の動作の流れに合わない。"}], "correct_form": "拾い上げて", "base_form": "拾い上げる", "form_label": "て形", "sentence_index": 7, "explanations": {"拾い上げて": "正解。て形で、後続の『持ってきた』へ続ける。", "拾い上げます": "丁寧体。『〜て、持ってきた』と続かず、文の流れに合わない。", "拾い上げれば": "仮定形。『〜て』の連続を作れず、文がつながらない。", "拾い上げている": "継続・結果の形。『〜て、持ってきた』と続く一連の動作の流れに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
