INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52594, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "注意深く探し出して拾うこと。", "primary_collocate": null, "pronunciation": "ひろいあげる", "ipa": "çiɾoiaɡeɾɯ", "syllable_count": 6, "sentences": [{"text": "犯罪現場という苛烈な情報の奔流の中から、科学捜査の担い手は微細な痕跡を拾い上げる。", "target_word": "拾い上げる", "complexity_tier": "T4", "furigana": "犯罪[はんざい]現場[げんば]という苛烈[かれつ]な情報[じょうほう]の奔流[ほんりゅう]の中[なか]から、科学[かがく]捜査[そうさ]の担[にな]い手[て]は微細[びさい]な痕跡[こんせき]を拾[ひろ]い上[あ]げる。", "sentence_source": "mined"}, {"text": "刑事は床に散らばった砂粒の中から、小さな繊維を一本ずつ拾い上げた。", "target_word": "拾い上げた", "complexity_tier": "T3", "furigana": "刑事[けいじ]は床[ゆか]に散[ち]らばった砂粒[すなつぶ]の中[なか]から、小[ちい]さな繊維[せんい]を一本[いっぽん]ずつ拾[ひろ]い上[あ]げた。", "sentence_source": "generated"}, {"text": "彼女は会議で、誰も気づかなかった小さな問題点を拾い上げて指摘した。", "target_word": "拾い上げて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は会議[かいぎ]で、誰[だれ]も気[き]づかなかった小[ちい]さな問題点[もんだいてん]を拾[ひろ]い上[あ]げて指摘[してき]した。", "sentence_source": "generated"}, {"text": "記者は市民の小さな声を丁寧に拾い上げ、記事にまとめた。", "target_word": "拾い上げ", "complexity_tier": "T3", "furigana": "記者[きしゃ]は市民[しみん]の小[ちい]さな声[こえ]を丁寧[ていねい]に拾[ひろ]い上[あ]げ、記事[きじ]にまとめた。", "sentence_source": "generated"}, {"text": "古い資料の中から重要な数字だけを拾い上げて、表を作った。", "target_word": "拾い上げて", "complexity_tier": "T3", "furigana": "古[ふる]い資料[しりょう]の中[なか]から重要[じゅうよう]な数字[すうじ]だけを拾[ひろ]い上[あ]げて、表[ひょう]を作[つく]った。", "sentence_source": "generated"}, {"text": "先生は生徒の何気ない質問を拾い上げて、授業で詳しく説明した。", "target_word": "拾い上げて", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]の何気[なにげ]ない質問[しつもん]を拾[ひろ]い上[あ]げて、授業[じゅぎょう]で詳[くわ]しく説明[せつめい]した。", "sentence_source": "generated"}, {"text": "捜査員は雑音の中から犯人の声を拾い上げようと、録音を何度も聞き直した。", "target_word": "拾い上げよう", "complexity_tier": "T4", "furigana": "捜査員[そうさいん]は雑音[ざつおん]の中[なか]から犯人[はんにん]の声[こえ]を拾[ひろ]い上[あ]げようと、録音[ろくおん]を何度[なんど]も聞[き]き直[なお]した。", "sentence_source": "generated"}, {"text": "彼は砂浜で、波に洗われた小さな貝殻だけを慎重に拾い上げた。", "target_word": "拾い上げた", "complexity_tier": "T3", "furigana": "彼[かれ]は砂浜[すなはま]で、波[なみ]に洗[あら]われた小[ちい]さな貝殻[かいがら]だけを慎重[しんちょう]に拾[ひろ]い上[あ]げた。", "sentence_source": "generated"}, {"text": "調査員は大量のデータから、異常な値を拾い上げる作業を続けている。", "target_word": "拾い上げる", "complexity_tier": "T3", "furigana": "調査員[ちょうさいん]は大量[たいりょう]のデータから、異常[いじょう]な値[あたい]を拾[ひろ]い上[あ]げる作業[さぎょう]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "店長はお客様の小さな不満を拾い上げることで、サービスを良くしてきた。", "target_word": "拾い上げる", "complexity_tier": "T3", "furigana": "店長[てんちょう]はお客様[きゃくさま]の小[ちい]さな不満[ふまん]を拾[ひろ]い上[あ]げることで、サービスを良[よ]くしてきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "拾い上げる", "label": "辞書形"}, {"form": "拾い上げます", "label": "ます形"}, {"form": "拾い上げた", "label": "た形"}, {"form": "拾い上げて", "label": "て形"}, {"form": "拾い上げない", "label": "ない形"}, {"form": "拾い上げれば", "label": "仮定形"}, {"form": "拾い上げられる", "label": "可能形"}, {"form": "拾い上げよう", "label": "意向形"}], "register": "neutral written", "sense_fingerprint": "多くのものの中から小さな手がかりや声などを注意深く探し出して取り上げる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c159ce9d-4761-4f07-94d2-f261ff2177aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52594, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拾い上げる", "is_correct": true, "explanation": "正解。多くの情報の中から微細な痕跡を注意深く探し出して取る意味で、文脈に合う。"}, {"text": "解体する", "is_correct": false, "explanation": "ばらばらにすること。痕跡を解体するとは言えず、探し出す文脈に合わない。"}, {"text": "配る", "is_correct": false, "explanation": "分け与えること。痕跡を配るとは言わず、探し出して取る文脈に合わない。"}, {"text": "注ぐ", "is_correct": false, "explanation": "液体を流し入れること。固形の痕跡には使えず、探す文脈に合わない。"}], "explanations": {"拾い上げる": "正解。多くの情報の中から微細な痕跡を注意深く探し出して取る意味で、文脈に合う。", "解体する": "ばらばらにすること。痕跡を解体するとは言えず、探し出す文脈に合わない。", "配る": "分け与えること。痕跡を配るとは言わず、探し出して取る文脈に合わない。", "注ぐ": "液体を流し入れること。固形の痕跡には使えず、探す文脈に合わない。"}, "sentence_index": 0, "correct_answer": "拾い上げる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "やかんの水をコップに拾い上げた。", "explanation": "ここは〈注ぐ〉の意味。拾い上げるは散らばった物を手で探して取る意味で、液体を入れる意味はないので合わない。"}, {"text": "祖父は古い時計の部品を、夕食の材料として拾い上げた。", "explanation": "ここは〈調達する〉の意味。拾い上げるは落ちた物を手で取る意味で、食材をそろえる意味はないので合わない。"}, {"text": "教師は全員にプリントを拾い上げた。", "explanation": "ここは〈配る〉の意味。拾い上げるは取る行為で、人に分け与える意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52594, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拾い上げよう", "is_correct": true, "explanation": "正解。意向形で『〜ようと』と目的を表し、録音を聞き直す動機に合う。"}, {"text": "眺めよう", "is_correct": false, "explanation": "見つめる意向形。声を眺めるとは言わず、雑音から探し出す目的に合わない。"}, {"text": "処分しよう", "is_correct": false, "explanation": "処理する意向形。犯人の声を処分する目的は文脈に合わない。"}, {"text": "撮影しよう", "is_correct": false, "explanation": "写真や映像に収める意向形。声を撮影するという文脈に合わない。"}], "explanations": {"拾い上げよう": "正解。意向形で『〜ようと』と目的を表し、録音を聞き直す動機に合う。", "眺めよう": "見つめる意向形。声を眺めるとは言わず、雑音から探し出す目的に合わない。", "処分しよう": "処理する意向形。犯人の声を処分する目的は文脈に合わない。", "撮影しよう": "写真や映像に収める意向形。声を撮影するという文脈に合わない。"}, "sentence_index": 6, "correct_answer": "拾い上げよう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "看護師は傷口を拾い上げて、消毒液で洗った。", "explanation": "ここは〈消毒する〉の意味。拾い上げるは物を手で取る意味で、傷を消毒する意味はないので合わない。"}, {"text": "彼は書類を、ホチキスで拾い上げた。", "explanation": "ここは〈綴じる〉の意味。拾い上げるは物を手で探して取る意味で、紙を綴じる意味はないので合わない。"}, {"text": "主催者は会議を拾い上げて、来週に移した。", "explanation": "ここは〈延期する〉の意味。拾い上げるは取る行為で、予定を先送りする意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52594, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "科学捜査の担い手は、微細な痕跡に丹念に拾い上げる。", "corrected_sentence": "科学捜査の担い手は、微細な痕跡を丹念に拾い上げる。", "error_description": "『拾い上げる』の目的語は『〜を』。『痕跡に』では対象を示せず、『〜に拾い上げる』は不自然。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "拾い上げた", "is_correct": true, "explanation": "正解。文末の過去の動作を表すた形で、文脈に合う。"}, {"text": "拾い上げない", "is_correct": false, "explanation": "否定形。実際に行った動作『拾い上げた』と合わない。"}, {"text": "拾い上げられる", "is_correct": false, "explanation": "可能・受け身の形。過去に実際に行った動作を述べる文では不自然。"}, {"text": "拾い上げよう", "is_correct": false, "explanation": "意向形で『〜しよう』と意志を表し、過去の出来事を述べる文と合わない。"}], "correct_form": "拾い上げた", "base_form": "拾い上げる", "form_label": "た形", "sentence_index": 1, "explanations": {"拾い上げた": "正解。文末の過去の動作を表すた形で、文脈に合う。", "拾い上げない": "否定形。実際に行った動作『拾い上げた』と合わない。", "拾い上げられる": "可能・受け身の形。過去に実際に行った動作を述べる文では不自然。", "拾い上げよう": "意向形で『〜しよう』と意志を表し、過去の出来事を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52594, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "捜査員は雑音の中から犯人の声を拾い上げたと、録音を何度も聞き取った。", "corrected_sentence": "捜査員は雑音の中から犯人の声を拾い上げようと、録音を何度も聞き取った。", "error_description": "『〜ようと』（意向形）が正しい。『〜たと』では既に起きた事実になり、目的を表す文脈に合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "拾い上げた", "is_correct": true, "explanation": "正解。貝殻を拾った過去の動作を表すた形で、文脈に合う。"}, {"text": "拾い上げます", "is_correct": false, "explanation": "丁寧体。普通体で続く文の流れと合わない。"}, {"text": "拾い上げれば", "is_correct": false, "explanation": "仮定形。条件を示すため、過去の動作を述べる文を終えられない。"}, {"text": "拾い上げている", "is_correct": false, "explanation": "継続・結果の状態を表す形。完了した一回の動作を述べる文とは合わない。"}], "correct_form": "拾い上げた", "base_form": "拾い上げる", "form_label": "た形", "sentence_index": 7, "explanations": {"拾い上げた": "正解。貝殻を拾った過去の動作を表すた形で、文脈に合う。", "拾い上げます": "丁寧体。普通体で続く文の流れと合わない。", "拾い上げれば": "仮定形。条件を示すため、過去の動作を述べる文を終えられない。", "拾い上げている": "継続・結果の状態を表す形。完了した一回の動作を述べる文とは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52595, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "『大学のラボ』で植物を調べるので、場所を示す『で』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『ラボを』とすると『毎日植物を』と目的語が重なり、文が崩れる。"}, {"text": "の", "is_correct": false, "explanation": "『ラボの』と続けると修飾になり、文の続きがつながらない。"}, {"text": "より", "is_correct": false, "explanation": "比較の『より』は比べる対象を示すが、この文には比較がない。"}], "correct_answer": "で", "explanations": {"で": "『大学のラボ』で植物を調べるので、場所を示す『で』が正しい。", "を": "『ラボを』とすると『毎日植物を』と目的語が重なり、文が崩れる。", "の": "『ラボの』と続けると修飾になり、文の続きがつながらない。", "より": "比較の『より』は比べる対象を示すが、この文には比較がない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52595, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『行く』の目的地を示す『に』が正しい。"}, {"text": "で", "is_correct": false, "explanation": "場所を示す助詞だが、『行って』と移動する文では目的地の『に』が必要。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞だが、『ラボが行って』では主語と動詞が合わない。"}, {"text": "の", "is_correct": false, "explanation": "『ラボの』と続けると名詞の修飾になり、『行って』につながらない。"}], "correct_answer": "に", "explanations": {"に": "『行く』の目的地を示す『に』が正しい。", "で": "場所を示す助詞だが、『行って』と移動する文では目的地の『に』が必要。", "が": "主語を示す助詞だが、『ラボが行って』では主語と動詞が合わない。", "の": "『ラボの』と続けると名詞の修飾になり、『行って』につながらない。"}, "error_tags": {"で": "場所", "が": "主語", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52595, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものごとを調べたり、実験をしたりするためのへやです。", "primary_collocate": null, "pronunciation": "らぼ", "ipa": "ɾabo", "syllable_count": 2, "sentences": [{"text": "ラボで、先生と一緒に水の実験をした。", "target_word": "ラボ", "complexity_tier": "T2", "furigana": "ラボで、先生[せんせい]と一緒[いっしょ]に水[みず]の実験[じっけん]をした。", "sentence_source": "generated"}, {"text": "兄は大学のラボで、毎日植物を調べている。", "target_word": "ラボ", "complexity_tier": "T2", "furigana": "兄[あに]は大学[だいがく]のラボで、毎日[まいにち]植物[しょくぶつ]を調[しら]べている。", "sentence_source": "generated"}, {"text": "このラボは静かで、実験に集中しやすい。", "target_word": "ラボ", "complexity_tier": "T3", "furigana": "このラボは静[しず]かで、実験[じっけん]に集中[しゅうちゅう]しやすい。", "sentence_source": "generated"}, {"text": "ラボの机の上には、たくさんの試験管が並んでいる。", "target_word": "ラボ", "complexity_tier": "T3", "furigana": "ラボの机[つくえ]の上[うえ]には、たくさんの試験管[しけんかん]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "新しいラボができて、研究者たちは喜んだ。", "target_word": "ラボ", "complexity_tier": "T3", "furigana": "新[あたら]しいラボができて、研究者[けんきゅうしゃ]たちは喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "ラボでは、実験の前に必ず手袋をつける。", "target_word": "ラボ", "complexity_tier": "T3", "furigana": "ラボでは、実験[じっけん]の前[まえ]に必[かなら]ず手袋[てぶくろ]をつける。", "sentence_source": "generated"}, {"text": "彼は夜遅くまでラボに残って、結果をまとめていた。", "target_word": "ラボ", "complexity_tier": "T3", "furigana": "彼[かれ]は夜遅[よるおそ]くまでラボに残[のこ]って、結果[けっか]をまとめていた。", "sentence_source": "generated"}, {"text": "化学の授業で、ラボに行って薬品の勉強をした。", "target_word": "ラボ", "complexity_tier": "T3", "furigana": "化学[かがく]の授業[じゅぎょう]で、ラボに行[い]って薬品[やくひん]の勉強[べんきょう]をした。", "sentence_source": "generated"}, {"text": "ラボの窓から、大学の庭がよく見える。", "target_word": "ラボ", "complexity_tier": "T2", "furigana": "ラボの窓[まど]から、大学[だいがく]の庭[にわ]がよく見[み]える。", "sentence_source": "generated"}, {"text": "食品会社のラボで、新しいお菓子の味を調べている。", "target_word": "ラボ", "complexity_tier": "T3", "furigana": "食品[しょくひん]会社[かいしゃ]のラボで、新[あたら]しいお菓子[かし]の味[あじ]を調[しら]べている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ラボ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "調べものや実験をするための部屋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c159ce9d-4761-4f07-94d2-f261ff2177aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52595, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ラボ", "is_correct": true, "explanation": "水の実験を行う部屋なので、ラボが入る。"}, {"text": "劇場", "is_correct": false, "explanation": "演技を見せる施設で、実験を行う場所ではない。"}, {"text": "売店", "is_correct": false, "explanation": "商品を売る店で、実験は行わない。"}, {"text": "ロビー", "is_correct": false, "explanation": "人が集まる広間で、実験をする場所ではない。"}], "explanations": {"ラボ": "水の実験を行う部屋なので、ラボが入る。", "劇場": "演技を見せる施設で、実験を行う場所ではない。", "売店": "商品を売る店で、実験は行わない。", "ロビー": "人が集まる広間で、実験をする場所ではない。"}, "sentence_index": 0, "correct_answer": "ラボ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ラボの湯船で、客がゆっくり温まった。", "explanation": "ここは〈銭湯〉の意味。湯船につかる話なので、実験や研究を行う部屋のラボは合わない。"}, {"text": "ラボのフロントで、宿泊の手続きをした。", "explanation": "ここは〈ホテル〉のフロントの意味。宿泊の受付の話なので、実験をするための部屋のラボは合わない。"}, {"text": "ラボの改札を通って、電車に乗った。", "explanation": "ここは〈駅〉の意味。改札を通って電車に乗る話なので、実験を行う部屋のラボは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52595, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ラボ", "is_correct": true, "explanation": "結果をまとめる作業をする部屋なので、ラボが入る。"}, {"text": "駅", "is_correct": false, "explanation": "乗り降りのための施設で、夜遅くまで結果をまとめる場所ではない。"}, {"text": "駐車場", "is_correct": false, "explanation": "車を停める場所で、結果をまとめる作業には合わない。"}, {"text": "美術館", "is_correct": false, "explanation": "絵画を展示する施設で、結果をまとめる場所ではない。"}], "explanations": {"ラボ": "結果をまとめる作業をする部屋なので、ラボが入る。", "駅": "乗り降りのための施設で、夜遅くまで結果をまとめる場所ではない。", "駐車場": "車を停める場所で、結果をまとめる作業には合わない。", "美術館": "絵画を展示する施設で、結果をまとめる場所ではない。"}, "sentence_index": 6, "correct_answer": "ラボ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "日曜の朝、ラボの鐘が町中に鳴り響いた。", "explanation": "ここは〈教会〉の意味。鐘を鳴らす礼拝の施設の話なので、実験用の部屋のラボは合わない。"}, {"text": "夜中、ラボのナースコールが鳴って、看護師が駆けつけた。", "explanation": "ここは〈病室〉の意味。患者が看護師を呼ぶ病棟の話なので、研究施設のラボは合わない。"}, {"text": "ラボの閲覧室は、夜九時に閉まる。", "explanation": "ここは〈図書館〉の閲覧室の意味。本を読む場所の話なので、実験や分析を行うラボは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52595, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今日は朝からラボにで、実験の準備をした。", "corrected_sentence": "今日は朝からラボで、実験の準備をした。", "error_description": "『に』と『で』が重なっていて不自然。場所は『で』だけで示すので、『にで』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52595, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は深夜までラボに残て、結果をまとめていた。", "corrected_sentence": "彼は深夜までラボに残って、結果をまとめていた。", "error_description": "『残る』のて形は『残って』。『残て』は誤った活用形なので、正しくは『残って』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52596, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "『大学のラボ』は実験をする場所なので、場所を示す『で』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『ラボを』とすると『毎日…実験をしている』と目的語が重なり、文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "『ラボの』と続けると名詞の修飾になり、文の続きがつながらない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比べる相手を示す助詞だが、この文には比較の対象がない。"}], "correct_answer": "で", "explanations": {"で": "『大学のラボ』は実験をする場所なので、場所を示す『で』が正しい。", "を": "『ラボを』とすると『毎日…実験をしている』と目的語が重なり、文として成り立たない。", "の": "『ラボの』と続けると名詞の修飾になり、文の続きがつながらない。", "より": "『より』は比べる相手を示す助詞だが、この文には比較の対象がない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52596, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『警察のラボ』が証拠品を調べた主体を示すので、主語を表す『が』が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞だが、『調べた』は移動を伴わないため合わない。"}, {"text": "を", "is_correct": false, "explanation": "『ラボを』と『証拠品を』で目的語が二つ重なり、文が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "『に』は到達点を示すため、『調べた』の場所には『で』が必要で不自然。"}], "correct_answer": "が", "explanations": {"が": "『警察のラボ』が証拠品を調べた主体を示すので、主語を表す『が』が正しい。", "へ": "方向を示す助詞だが、『調べた』は移動を伴わないため合わない。", "を": "『ラボを』と『証拠品を』で目的語が二つ重なり、文が崩れる。", "に": "『に』は到達点を示すため、『調べた』の場所には『で』が必要で不自然。"}, "error_tags": {"へ": "方向", "を": "目的語", "に": "着点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52596, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "科学的な実験や研究、分析などを行うための特別な部屋や施設のこと。", "primary_collocate": null, "pronunciation": "らぼ", "ipa": "ɾabo", "syllable_count": 2, "sentences": [{"text": "まず、現場や鑑識ラボにおいて、肉眼では捉えられぬ潜在指紋を、シアノアクリレート法や光学的手法といったアプローチにより顕在化させる。", "target_word": "ラボ", "complexity_tier": "T4", "furigana": "まず、現場[げんば]や鑑識[かんしき]ラボにおいて、肉眼[にくがん]では捉[とら]えられぬ潜在[せんざい]指紋[しもん]を、シアノアクリレート法[ほう]や光学的[こうがくてき]手法[しゅほう]といったアプローチにより顕在化[けんざいか]させる。", "sentence_source": "mined"}, {"text": "私の姉は大学のラボで、毎日遅くまで実験をしている。", "target_word": "ラボ", "complexity_tier": "T3", "furigana": "私[わたし]の姉[あね]は大学[だいがく]のラボで、毎日[まいにち]遅[おそ]くまで実験[じっけん]をしている。", "sentence_source": "generated"}, {"text": "採取した血液は、すぐにラボへ送られて分析された。", "target_word": "ラボ", "complexity_tier": "T3", "furigana": "採取[さいしゅ]した血液[けつえき]は、すぐにラボへ送[おく]られて分析[ぶんせき]された。", "sentence_source": "generated"}, {"text": "新しい薬は、会社のラボで何度も試験を重ねて作られた。", "target_word": "ラボ", "complexity_tier": "T3", "furigana": "新[あたら]しい薬[くすり]は、会社[かいしゃ]のラボで何度[なんど]も試験[しけん]を重[かさ]ねて作[つく]られた。", "sentence_source": "generated"}, {"text": "ラボに入るときは、白衣を着て手を洗わなければならない。", "target_word": "ラボ", "complexity_tier": "T3", "furigana": "ラボに入[はい]るときは、白衣[はくい]を着[き]て手[て]を洗[あら]わなければならない。", "sentence_source": "generated"}, {"text": "このラボには、高価な顕微鏡が何台も置かれている。", "target_word": "ラボ", "complexity_tier": "T3", "furigana": "このラボには、高価[こうか]な顕微鏡[けんびきょう]が何台[なんだい]も置[お]かれている。", "sentence_source": "generated"}, {"text": "研究者たちはラボにこもって、新しい素材の開発を続けた。", "target_word": "ラボ", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]たちはラボにこもって、新[あたら]しい素材[そざい]の開発[かいはつ]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "警察のラボが証拠品を調べた結果、犯人が特定された。", "target_word": "ラボ", "complexity_tier": "T3", "furigana": "警察[けいさつ]のラボが証拠品[しょうこひん]を調[しら]べた結果[けっか]、犯人[はんにん]が特定[とくてい]された。", "sentence_source": "generated"}, {"text": "見学に来た小学生たちは、ラボの中の機械に興味を持った。", "target_word": "ラボ", "complexity_tier": "T3", "furigana": "見学[けんがく]に来[き]た小学生[しょうがくせい]たちは、ラボの中[なか]の機械[きかい]に興味[きょうみ]を持[も]った。", "sentence_source": "generated"}, {"text": "火事のあと、ラボの実験データがすべて消えてしまった。", "target_word": "ラボ", "complexity_tier": "T3", "furigana": "火事[かじ]のあと、ラボの実験[じっけん]データがすべて消[き]えてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ラボ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "実験・研究・分析を行う専用の施設", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: シアノアクリレート (Zipf 1.04)']::text[], 'c159ce9d-4761-4f07-94d2-f261ff2177aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52596, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ラボ", "is_correct": true, "explanation": "鑑識で指紋の分析を行う施設なので、この文の場所にはラボが入る。"}, {"text": "ラウンジ", "is_correct": false, "explanation": "くつろぐための休憩場所で、鑑識の分析作業を行う場所ではない。"}, {"text": "ロッカー", "is_correct": false, "explanation": "荷物を入れる収納設備で、作業を行う場所を表さないため入らない。"}, {"text": "売店", "is_correct": false, "explanation": "商品を売る店で、潜在指紋を顕在化させる施設ではない。"}], "explanations": {"ラボ": "鑑識で指紋の分析を行う施設なので、この文の場所にはラボが入る。", "ラウンジ": "くつろぐための休憩場所で、鑑識の分析作業を行う場所ではない。", "ロッカー": "荷物を入れる収納設備で、作業を行う場所を表さないため入らない。", "売店": "商品を売る店で、潜在指紋を顕在化させる施設ではない。"}, "sentence_index": 0, "correct_answer": "ラボ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昼休みにラボで日替わり定食を注文した。", "explanation": "ここは〈食堂〉の意味。料理を注文して食べる店の話なので、実験を行う施設のラボは合わない。"}, {"text": "市民会館のラボで、地元の合唱団が週末に演奏会を開いた。", "explanation": "ここは〈ホール〉の意味。演奏会を開く会場の話なので、研究用の施設であるラボは合わない。"}, {"text": "新しい車は、都心のラボに並べられて来客に披露された。", "explanation": "ここは〈ショールーム〉の意味。商品を客に見せる展示の場の話なので、実験施設のラボは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52596, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ラボ", "is_correct": true, "explanation": "研究者が素材の開発を続ける施設なので、ラボが入る。"}, {"text": "ゲームセンター", "is_correct": false, "explanation": "遊ぶための施設で、素材の開発とは結びつかない。"}, {"text": "サウナ", "is_correct": false, "explanation": "蒸し風呂で、研究や開発を行う場所ではない。"}, {"text": "遊園地", "is_correct": false, "explanation": "娯楽施設で、新しい素材を開発する場所ではない。"}], "explanations": {"ラボ": "研究者が素材の開発を続ける施設なので、ラボが入る。", "ゲームセンター": "遊ぶための施設で、素材の開発とは結びつかない。", "サウナ": "蒸し風呂で、研究や開発を行う場所ではない。", "遊園地": "娯楽施設で、新しい素材を開発する場所ではない。"}, "sentence_index": 6, "correct_answer": "ラボ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "手術のあと、患者は静かなラボで一晩休んだ。", "explanation": "ここは〈病室〉の意味。患者が休む場所の話なので、研究や分析の施設であるラボは合わない。"}, {"text": "日曜日、信者たちはラボに集まって祈りをささげた。", "explanation": "ここは〈礼拝堂〉の意味。祈りをささげる場所の話なので、実験のための施設のラボは合わない。"}, {"text": "朝のラボには、新鮮な野菜を売る店が並んでいた。", "explanation": "ここは〈市場〉の意味。野菜などを売る店が並ぶ話なので、実験を行う施設のラボは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52596, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい薬は、社内のラボを何度も試験を重ねて作られた。", "corrected_sentence": "新しい薬は、社内のラボで何度も試験を重ねて作られた。", "error_description": "ラボは試験を行う場所なので、場所を示す『で』が正しい。『を』は動作の対象を示すため、ここでは文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52596, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究者たちは深夜もラボにこもらって、新しい素材の開発を続けた。", "corrected_sentence": "研究者たちは深夜もラボにこもって、新しい素材の開発を続けた。", "error_description": "『こもる』のて形は『こもって』。『こもらって』は誤った活用形なので、正しくは『こもって』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52597, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「絶対の存在」と名詞を修飾する「の」で、「として信じている」と続く。"}, {"text": "を", "is_correct": false, "explanation": "「神を 絶対を存在として」と目的語が重なり、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「絶対で存在」と状態の「で」は続かず、意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「絶対へ存在」と方向の「へ」は結べず、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「絶対の存在」と名詞を修飾する「の」で、「として信じている」と続く。", "を": "「神を 絶対を存在として」と目的語が重なり、文が成り立たない。", "で": "「絶対で存在」と状態の「で」は続かず、意味が通らない。", "へ": "「絶対へ存在」と方向の「へ」は結べず、文が成り立たない。"}, "error_tags": {"を": "目的格", "で": "手段・状態", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相対", "is_correct": true, "explanation": "「絶対」は他と比べず変わらないこと、「相対」は他との関係で決まることを表し、反対語の関係にある。"}, {"text": "相互", "is_correct": false, "explanation": "「相互」は互いに関わり合うことで、絶対の反対語ではない。"}, {"text": "平等", "is_correct": false, "explanation": "「平等」は差がないことで、絶対の反対語ではない。"}, {"text": "偶然", "is_correct": false, "explanation": "「偶然」は予期しない出来事で、絶対の反対語ではない。"}], "correct_answer": "相対", "explanations": {"相対": "「絶対」は他と比べず変わらないこと、「相対」は他との関係で決まることを表し、反対語の関係にある。", "相互": "「相互」は互いに関わり合うことで、絶対の反対語ではない。", "平等": "「平等」は差がないことで、絶対の反対語ではない。", "偶然": "「偶然」は予期しない出来事で、絶対の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52597, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「絶対の安全」と名詞を修飾する「の」で、文として正しく続く。"}, {"text": "を", "is_correct": false, "explanation": "「絶対を 安全を約束」と目的語が重なり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「絶対へ安全を約束」と方向の「へ」は結べず、意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「絶対から安全を約束」と起点の「から」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「絶対の安全」と名詞を修飾する「の」で、文として正しく続く。", "を": "「絶対を 安全を約束」と目的語が重なり、文が成り立たない。", "へ": "「絶対へ安全を約束」と方向の「へ」は結べず、意味が通らない。", "から": "「絶対から安全を約束」と起点の「から」は意味が通らない。"}, "error_tags": {"を": "目的格", "へ": "方向", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相対", "is_correct": true, "explanation": "「絶対の信頼」の「絶対」は他と比べない変わらなさを表し、その反対語は「相対」である。"}, {"text": "相違", "is_correct": false, "explanation": "「相違」は食い違いのことで、絶対の反対語ではない。"}, {"text": "偏見", "is_correct": false, "explanation": "「偏見」は偏った見方のことで、絶対の反対語ではない。"}, {"text": "個別", "is_correct": false, "explanation": "「個別」は一つ一つ別々のことで、絶対の反対語ではない。"}], "correct_answer": "相対", "explanations": {"相対": "「絶対の信頼」の「絶対」は他と比べない変わらなさを表し、その反対語は「相対」である。", "相違": "「相違」は食い違いのことで、絶対の反対語ではない。", "偏見": "「偏見」は偏った見方のことで、絶対の反対語ではない。", "個別": "「個別」は一つ一つ別々のことで、絶対の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52597, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "絶対は、何があっても変わらないことです。", "primary_collocate": null, "pronunciation": "ぜったい", "ipa": "zettai", "syllable_count": 4, "sentences": [{"text": "この世に絶対はないと、先生はよく言っていた。", "target_word": "絶対", "complexity_tier": "T3", "furigana": "この世[よ]に絶対[ぜったい]はないと、先生[せんせい]はよく言[い]っていた。", "sentence_source": "generated"}, {"text": "彼は、神を絶対の存在として信じている。", "target_word": "絶対", "complexity_tier": "T3", "furigana": "彼[かれ]は、神[かみ]を絶対[ぜったい]の存在[そんざい]として信[しん]じている。", "sentence_source": "generated"}, {"text": "王の命令は絶対で、誰も逆らえなかった。", "target_word": "絶対", "complexity_tier": "T3", "furigana": "王[おう]の命令[めいれい]は絶対[ぜったい]で、誰[だれ]も逆[さか]らえなかった。", "sentence_source": "generated"}, {"text": "絶対の自信があったので、彼は少しも迷わなかった。", "target_word": "絶対", "complexity_tier": "T3", "furigana": "絶対[ぜったい]の自信[じしん]があったので、彼[かれ]は少[すこ]しも迷[まよ]わなかった。", "sentence_source": "generated"}, {"text": "この学校では、先輩の言うことが絶対だった。", "target_word": "絶対", "complexity_tier": "T3", "furigana": "この学校[がっこう]では、先輩[せんぱい]の言[い]うことが絶対[ぜったい]だった。", "sentence_source": "generated"}, {"text": "科学の世界に、絶対と言えるものはほとんどない。", "target_word": "絶対", "complexity_tier": "T3", "furigana": "科学[かがく]の世界[せかい]に、絶対[ぜったい]と言[い]えるものはほとんどない。", "sentence_source": "generated"}, {"text": "母は私にとって、何があっても変わらない絶対の味方だ。", "target_word": "絶対", "complexity_tier": "T3", "furigana": "母[はは]は私[わたし]にとって、何[なに]があっても変[か]わらない絶対[ぜったい]の味方[みかた]だ。", "sentence_source": "generated"}, {"text": "絶対の安全を約束できる乗り物は、どこにもない。", "target_word": "絶対", "complexity_tier": "T3", "furigana": "絶対[ぜったい]の安全[あんぜん]を約束[やくそく]できる乗[の]り物[もの]は、どこにもない。", "sentence_source": "generated"}, {"text": "チームの中で、監督の判断は絶対とされている。", "target_word": "絶対", "complexity_tier": "T3", "furigana": "チームの中[なか]で、監督[かんとく]の判断[はんだん]は絶対[ぜったい]とされている。", "sentence_source": "generated"}, {"text": "彼は絶対の信頼を寄せていた友人に裏切られた。", "target_word": "絶対", "complexity_tier": "T3", "furigana": "彼[かれ]は絶対[ぜったい]の信頼[しんらい]を寄[よ]せていた友人[ゆうじん]に裏切[うらぎ]られた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "絶対", "label": "基本形"}, {"form": "絶対の", "label": "連体形"}, {"form": "絶対は", "label": "助詞つき"}], "register": "中立（普通体）", "sense_fingerprint": "他と比べず、どんな場合も変わらないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19296fb3-942a-43e0-bd14-652689089628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52597, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "絶対", "is_correct": true, "explanation": "「この世に絶対はない」は、どんな場合も変わらないものは存在しないという意味で、文脈に合う。"}, {"text": "人間", "is_correct": false, "explanation": "「この世に人間はない」では意味が通らず、先生の言葉の文脈に合わない。"}, {"text": "天気", "is_correct": false, "explanation": "「この世に天気はない」では意味が通らず、文脈に合わない。"}, {"text": "椅子", "is_correct": false, "explanation": "「この世に椅子はない」では意味が通らず、文脈に合わない。"}], "explanations": {"絶対": "「この世に絶対はない」は、どんな場合も変わらないものは存在しないという意味で、文脈に合う。", "人間": "「この世に人間はない」では意味が通らず、先生の言葉の文脈に合わない。", "天気": "「この世に天気はない」では意味が通らず、文脈に合わない。", "椅子": "「この世に椅子はない」では意味が通らず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "絶対"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山頂から見た景色は、まさに絶対だった。", "explanation": "絶対は変わらないことを表すので、景色のすばらしさを言うのには使えない。"}, {"text": "この店のケーキは、どれも絶対で、毎日行列ができる。", "explanation": "絶対は変わらないことなので、味の良さを言い表す語にはならない。"}, {"text": "遊園地で、絶対マシンに乗って大声で笑った。", "explanation": "絶対は変わらないことなので、スリルのある乗り物の名称にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52597, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "絶対", "is_correct": true, "explanation": "「何があっても変わらない絶対の味方」と、変わらない信頼を表す「絶対」が文脈に合う。"}, {"text": "電車", "is_correct": false, "explanation": "「電車の味方」では意味が通らず、文脈に合わない。"}, {"text": "玄関", "is_correct": false, "explanation": "「玄関の味方」では意味が通らず、文脈に合わない。"}, {"text": "名刺", "is_correct": false, "explanation": "「名刺の味方」では意味が通らず、文脈に合わない。"}], "explanations": {"絶対": "「何があっても変わらない絶対の味方」と、変わらない信頼を表す「絶対」が文脈に合う。", "電車": "「電車の味方」では意味が通らず、文脈に合わない。", "玄関": "「玄関の味方」では意味が通らず、文脈に合わない。", "名刺": "「名刺の味方」では意味が通らず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "絶対"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電気を通さないこの素材は、ケーブルの絶対として使われている。", "explanation": "絶対は変わらないことなので、電気を通さない素材の働きを表す語にはならない。"}, {"text": "料理の塩加減が絶対で、家族みんなが驚いた。", "explanation": "絶対は変わらないことなので、味の良さを言い表す語にはならない。"}, {"text": "今日は絶対の釣り日和だと、朝から楽しみにしていた。", "explanation": "絶対は変わらないことなので、適した状態を言い表す語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52597, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は、絶対を味方を探していた。", "corrected_sentence": "彼女は、絶対の味方を探していた。", "error_description": "正しくは「絶対の味方」。「絶対」が「味方」を修飾するので連体修飾の「の」が必要で、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52597, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は、絶対で言えない秘密を抱えていた。", "corrected_sentence": "彼女は、絶対に言えない秘密を抱えていた。", "error_description": "正しくは「絶対に言えない」。副詞として使うときは「絶対に」の形が必要で、「絶対で」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e3cb16b-534e-4328-83e1-c8cdd5344d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52599, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "『肉眼で』見る手段を示すので、『で』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『肉眼を』とすると目的語になり、『は』でつながらない。"}, {"text": "と", "is_correct": false, "explanation": "『肉眼と』は並列の相手を示すが、ここでは文が成り立たない。"}, {"text": "も", "is_correct": false, "explanation": "『肉眼も』の後に『は』が続き、助詞が重なって文が崩れる。"}], "correct_answer": "で", "explanations": {"で": "『肉眼で』見る手段を示すので、『で』が正しい。", "を": "『肉眼を』とすると目的語になり、『は』でつながらない。", "と": "『肉眼と』は並列の相手を示すが、ここでは文が成り立たない。", "も": "『肉眼も』の後に『は』が続き、助詞が重なって文が崩れる。"}, "error_tags": {"を": "目的語", "と": "並列", "も": "助詞の重なり"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
