INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52599, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "目で見ること。", "primary_collocate": null, "pronunciation": "にくがん", "ipa": "ɲikɯɡaɴ", "syllable_count": 4, "sentences": [{"text": "星は肉眼でも見えるが、望遠鏡のほうがよく見える。", "target_word": "肉眼", "complexity_tier": "T2", "furigana": "星[ほし]は肉眼[にくがん]でも見[み]えるが、望遠鏡[ぼうえんきょう]のほうがよく見[み]える。", "sentence_source": "generated"}, {"text": "虫の足は小さくて、肉眼ではよく見えない。", "target_word": "肉眼", "complexity_tier": "T2", "furigana": "虫[むし]の足[あし]は小[ちい]さくて、肉眼[にくがん]ではよく見[み]えない。", "sentence_source": "generated"}, {"text": "今夜は空がきれいで、肉眼で天の川が見えた。", "target_word": "肉眼", "complexity_tier": "T3", "furigana": "今夜[こんや]は空[そら]がきれいで、肉眼[にくがん]で天[あま]の川[がわ]が見[み]えた。", "sentence_source": "generated"}, {"text": "肉眼で見ると、この二つの石は同じに見える。", "target_word": "肉眼", "complexity_tier": "T2", "furigana": "肉眼[にくがん]で見[み]ると、この二[ふた]つの石[いし]は同[おな]じに見[み]える。", "sentence_source": "generated"}, {"text": "先生は、肉眼で観察してから顕微鏡を使うように言った。", "target_word": "肉眼", "complexity_tier": "T3", "furigana": "先生[せんせい]は、肉眼[にくがん]で観察[かんさつ]してから顕微鏡[けんびきょう]を使[つか]うように言[い]った。", "sentence_source": "generated"}, {"text": "それは肉眼では見えないほど、細い糸だった。", "target_word": "肉眼", "complexity_tier": "T3", "furigana": "それは肉眼[にくがん]では見[み]えないほど、細[ほそ]い糸[いと]だった。", "sentence_source": "generated"}, {"text": "遠くの島も、天気がよければ肉眼で見える。", "target_word": "肉眼", "complexity_tier": "T2", "furigana": "遠[とお]くの島[しま]も、天気[てんき]がよければ肉眼[にくがん]で見[み]える。", "sentence_source": "generated"}, {"text": "工場では、製品を肉眼で一つずつ確認している。", "target_word": "肉眼", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、製品[せいひん]を肉眼[にくがん]で一[ひと]つずつ確認[かくにん]している。", "sentence_source": "generated"}, {"text": "肉眼で見るかぎり、このガラスに傷はない。", "target_word": "肉眼", "complexity_tier": "T3", "furigana": "肉眼[にくがん]で見[み]るかぎり、このガラスに傷[きず]はない。", "sentence_source": "generated"}, {"text": "ほこりのような小さな粒は、肉眼では分かりにくい。", "target_word": "肉眼", "complexity_tier": "T3", "furigana": "ほこりのような小[ちい]さな粒[つぶ]は、肉眼[にくがん]では分[わ]かりにくい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "肉眼", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "道具を使わずに自分の目で見ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c159ce9d-4761-4f07-94d2-f261ff2177aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52599, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肉眼", "is_correct": true, "explanation": "道具を使わず目で見ることなので、肉眼が入る。"}, {"text": "耳", "is_correct": false, "explanation": "音を聞く器官で、星を見るという文には入らない。"}, {"text": "鼻", "is_correct": false, "explanation": "においを感じる器官で、見ることには合わない。"}, {"text": "手", "is_correct": false, "explanation": "触れる器官で、星を見るという文には合わない。"}], "explanations": {"肉眼": "道具を使わず目で見ることなので、肉眼が入る。", "耳": "音を聞く器官で、星を見るという文には入らない。", "鼻": "においを感じる器官で、見ることには合わない。", "手": "触れる器官で、星を見るという文には合わない。"}, "sentence_index": 0, "correct_answer": "肉眼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "肉眼が赤くなって、かゆくてたまらない。", "explanation": "ここは〈目〉という器官の意味。かゆみや充血を感じる体の部位の話なので、道具を使わずに見ることを指す肉眼は合わない。"}, {"text": "肉眼を入れると、視界がはっきりする。", "explanation": "ここは〈コンタクトレンズ〉の意味。目に入れる器具の話なので、肉眼は器具ではなく合わない。"}, {"text": "彼女の肉眼が、ずっとこちらに注がれていた。", "explanation": "ここは〈視線〉の意味。目の向きを表す話なので、見ること自体を指す肉眼は注がれるものではなく合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52599, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肉眼", "is_correct": true, "explanation": "道具を使わず目で見ることなので、肉眼が入る。"}, {"text": "聴覚", "is_correct": false, "explanation": "音を聞く感覚で、見えることとは結びつかない。"}, {"text": "嗅覚", "is_correct": false, "explanation": "においを感じる感覚で、見えることには合わない。"}, {"text": "触覚", "is_correct": false, "explanation": "触れて感じる感覚で、見えることには合わない。"}], "explanations": {"肉眼": "道具を使わず目で見ることなので、肉眼が入る。", "聴覚": "音を聞く感覚で、見えることとは結びつかない。", "嗅覚": "においを感じる感覚で、見えることには合わない。", "触覚": "触れて感じる感覚で、見えることには合わない。"}, "sentence_index": 6, "correct_answer": "肉眼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "犬は肉眼が鋭くて、遠くの足音も聞き分けられる。", "explanation": "ここは〈聴覚〉の意味。音を聞き分ける力の話なので、見ることを指す肉眼は合わない。"}, {"text": "肉眼がはがれて、視野の一部が欠けてしまった。", "explanation": "ここは〈網膜〉の意味。目の内側の組織の話なので、見る行為を指す肉眼は組織ではなく合わない。"}, {"text": "肉眼をさすと、目の乾きが和らぐ。", "explanation": "ここは〈目薬〉の意味。目に液を差す話なので、肉眼は差せるものではなく合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52599, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜空の星は、肉眼を見えるが、望遠鏡のほうがよく見える。", "corrected_sentence": "夜空の星は、肉眼で見えるが、望遠鏡のほうがよく見える。", "error_description": "見える手段は『肉眼で』で示す。『肉眼を見える』は『を』が誤りで、肉眼を対象にしてしまう。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52599, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕方の空に、一番星が肉眼でかすかに聞こえた。", "corrected_sentence": "夕方の空に、一番星が肉眼でかすかに見えた。", "error_description": "『肉眼で』は目で見ることを表すので、続く動詞は『見えた』。『聞こえた』は音を耳で感じる動詞で、肉眼とは合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52600, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "『肉眼』は見る手段を表すので、手段を示す『で』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『肉眼を』とすると目的語になり、『は見えない』とつながらない。"}, {"text": "と", "is_correct": false, "explanation": "『肉眼と』は並列や相手を示すが、ここでは文が成り立たない。"}, {"text": "も", "is_correct": false, "explanation": "『肉眼も』の後に『は』が続き、助詞が重なって文が崩れる。"}], "correct_answer": "で", "explanations": {"で": "『肉眼』は見る手段を表すので、手段を示す『で』が正しい。", "を": "『肉眼を』とすると目的語になり、『は見えない』とつながらない。", "と": "『肉眼と』は並列や相手を示すが、ここでは文が成り立たない。", "も": "『肉眼も』の後に『は』が続き、助詞が重なって文が崩れる。"}, "error_tags": {"を": "目的語", "と": "並列", "も": "助詞の重なり"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52600, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "『肉眼で』は同じ色かどうかを見る手段を示すので、『で』が正しい。"}, {"text": "の", "is_correct": false, "explanation": "『肉眼の』と続けると修飾になり、『は同じ色に見えても』とつながらない。"}, {"text": "を", "is_correct": false, "explanation": "『肉眼を』は目的語になり、『見えても』と続かない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、見るという動作には合わない。"}], "correct_answer": "で", "explanations": {"で": "『肉眼で』は同じ色かどうかを見る手段を示すので、『で』が正しい。", "の": "『肉眼の』と続けると修飾になり、『は同じ色に見えても』とつながらない。", "を": "『肉眼を』は目的語になり、『見えても』と続かない。", "へ": "方向を示すが、見るという動作には合わない。"}, "error_tags": {"の": "連体修飾", "を": "目的語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52600, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "めがねや道具を使わずに、自分の目で直接見ること。", "primary_collocate": null, "pronunciation": "にくがん", "ipa": "ɲikɯɡaɴ", "syllable_count": 4, "sentences": [{"text": "まず、現場や鑑識ラボにおいて、肉眼では捉えられぬ潜在指紋を、シアノアクリレート法や光学的手法といったアプローチにより顕在化させる。", "target_word": "肉眼", "complexity_tier": "T4", "furigana": "まず、現場[げんば]や鑑識[かんしき]ラボにおいて、肉眼[にくがん]では捉[とら]えられぬ潜在[せんざい]指紋[しもん]を、シアノアクリレート法[ほう]や光学的[こうがくてき]手法[しゅほう]といったアプローチにより顕在化[けんざいか]させる。", "sentence_source": "mined"}, {"text": "肉眼では見えない小さな星も、望遠鏡を使えば見つかる。", "target_word": "肉眼", "complexity_tier": "T3", "furigana": "肉眼[にくがん]では見[み]えない小[ちい]さな星[ほし]も、望遠鏡[ぼうえんきょう]を使[つか]えば見[み]つかる。", "sentence_source": "generated"}, {"text": "細菌は小さすぎて、肉眼で見ることができない。", "target_word": "肉眼", "complexity_tier": "T3", "furigana": "細菌[さいきん]は小[ちい]さすぎて、肉眼[にくがん]で見[み]ることができない。", "sentence_source": "generated"}, {"text": "この彗星は、空が暗ければ肉眼でも確認できる。", "target_word": "肉眼", "complexity_tier": "T3", "furigana": "この彗星[すいせい]は、空[そら]が暗[くら]ければ肉眼[にくがん]でも確認[かくにん]できる。", "sentence_source": "generated"}, {"text": "肉眼で見ただけでは、ひび割れの深さまではわからない。", "target_word": "肉眼", "complexity_tier": "T3", "furigana": "肉眼[にくがん]で見[み]ただけでは、ひび割[わ]れの深[ふか]さまではわからない。", "sentence_source": "generated"}, {"text": "医者は傷の状態をまず肉眼で調べ、そのあと機械で検査した。", "target_word": "肉眼", "complexity_tier": "T3", "furigana": "医者[いしゃ]は傷[きず]の状態[じょうたい]をまず肉眼[にくがん]で調[しら]べ、そのあと機械[きかい]で検査[けんさ]した。", "sentence_source": "generated"}, {"text": "月のクレーターは、双眼鏡がなくても肉眼でうっすらと見える。", "target_word": "肉眼", "complexity_tier": "T3", "furigana": "月[つき]のクレーターは、双眼鏡[そうがんきょう]がなくても肉眼[にくがん]でうっすらと見[み]える。", "sentence_source": "generated"}, {"text": "肉眼では同じ色に見えても、機械で測るとわずかに違っている。", "target_word": "肉眼", "complexity_tier": "T3", "furigana": "肉眼[にくがん]では同[おな]じ色[いろ]に見[み]えても、機械[きかい]で測[はか]るとわずかに違[ちが]っている。", "sentence_source": "generated"}, {"text": "山の上からは、肉眼で遠くの海まで見渡せた。", "target_word": "肉眼", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]からは、肉眼[にくがん]で遠[とお]くの海[うみ]まで見渡[みわた]せた。", "sentence_source": "generated"}, {"text": "肉眼で見つけにくい汚れは、特別なライトを当てると浮かび上がる。", "target_word": "肉眼", "complexity_tier": "T4", "furigana": "肉眼[にくがん]で見[み]つけにくい汚[よご]れは、特別[とくべつ]なライトを当[あ]てると浮[う]かび上[あ]がる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "肉眼", "label": "基本形"}], "register": "neutral written", "sense_fingerprint": "顕微鏡や望遠鏡などの道具を使わない、人間の目そのもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T4: contains vocabulary far above tier T4: シアノアクリレート (Zipf 1.04)','sentence 3 above tier T4: contains vocabulary far above tier T4: 暗けれ (Zipf 1.11)']::text[], 'c159ce9d-4761-4f07-94d2-f261ff2177aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52600, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肉眼", "is_correct": true, "explanation": "道具を使わず目で見る場面なので、肉眼が入る。"}, {"text": "時間", "is_correct": false, "explanation": "指紋を捉える手段ではなく、この文には入らない。"}, {"text": "地図", "is_correct": false, "explanation": "指紋を見るための道具ではなく、文に合わない。"}, {"text": "音声", "is_correct": false, "explanation": "指紋を見る手段ではなく、この文には合わない。"}], "explanations": {"肉眼": "道具を使わず目で見る場面なので、肉眼が入る。", "時間": "指紋を捉える手段ではなく、この文には入らない。", "地図": "指紋を見るための道具ではなく、文に合わない。", "音声": "指紋を見る手段ではなく、この文には合わない。"}, "sentence_index": 0, "correct_answer": "肉眼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "肉眼をかけると、遠くの文字がはっきり見える。", "explanation": "ここは〈眼鏡〉の意味。顔にかけて使う道具の話なので、道具を使わずに見ることを指す肉眼は身につけられず合わない。"}, {"text": "肉眼が落ちて、遠くの看板が読みにくくなった。", "explanation": "ここは〈視力〉の意味。目の働きの強さを表す話なので、道具を使わない見方を指す肉眼は合わない。"}, {"text": "肉眼を覗くと、細菌が動いているのが見える。", "explanation": "ここは〈顕微鏡〉の意味。レンズを覗いて拡大する話なので、拡大しない肉眼は覗くものではなく合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52600, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肉眼", "is_correct": true, "explanation": "双眼鏡を使わず、目で見える範囲を表すので肉眼が入る。"}, {"text": "聴力", "is_correct": false, "explanation": "音を聞く力で、見えることとは結びつかない。"}, {"text": "嗅覚", "is_correct": false, "explanation": "においを感じる働きで、見えることには合わない。"}, {"text": "触覚", "is_correct": false, "explanation": "触れて感じる働きで、見えることには合わない。"}], "explanations": {"肉眼": "双眼鏡を使わず、目で見える範囲を表すので肉眼が入る。", "聴力": "音を聞く力で、見えることとは結びつかない。", "嗅覚": "においを感じる働きで、見えることには合わない。", "触覚": "触れて感じる働きで、見えることには合わない。"}, "sentence_index": 6, "correct_answer": "肉眼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "肉眼をつけると、会話が聞き取りやすくなる。", "explanation": "ここは〈補聴器〉の意味。耳に付ける機器の話なので、目で見ることを指す肉眼は付けるものではなく合わない。"}, {"text": "肉眼をさすと、目の乾きが和らぐ。", "explanation": "ここは〈目薬〉の意味。目に液を差す話なので、見る働きそのものを指す肉眼は差せず合わない。"}, {"text": "肉眼が狭くなって、横から近づく車が見えにくい。", "explanation": "ここは〈視野〉の意味。見える範囲の話なので、見る方法を指す肉眼は範囲を表さず合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52600, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜空の星は、肉眼にで見ることができる。", "corrected_sentence": "夜空の星は、肉眼で見ることができる。", "error_description": "『に』と『で』が重なっていて不自然。手段は『で』だけで示すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52600, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今夜は空が澄んでいて、肉眼で天の川が見えられる。", "corrected_sentence": "今夜は空が澄んでいて、肉眼で天の川が見える。", "error_description": "『見える』自体に可能の意味が含まれるため、『見えられる』は可能が重なって不自然。正しくは『見える』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48324637-c903-42e9-bbd3-39bdcf8e70ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52601, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「指紋は人によって違う」と話題を立てる「は」。ここで正しい"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「指紋を人によって違う」は文が成り立たない"}, {"text": "と", "is_correct": false, "explanation": "並列を示すが、「指紋と人によって違う」は述語とつながらず不自然"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すため、「指紋へ人によって違う」は意味が通らない"}], "correct_answer": "は", "explanations": {"は": "「指紋は人によって違う」と話題を立てる「は」。ここで正しい", "を": "目的語を示すが、「指紋を人によって違う」は文が成り立たない", "と": "並列を示すが、「指紋と人によって違う」は述語とつながらず不自然", "へ": "方向を示すため、「指紋へ人によって違う」は意味が通らない"}, "error_tags": {"を": "目的語", "と": "並列・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52601, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「指紋は同じではない」と主題を示す「は」。ここで正しい"}, {"text": "を", "is_correct": false, "explanation": "「指紋を同じではない」は文が成り立たない"}, {"text": "に", "is_correct": false, "explanation": "「指紋に同じではない」は不自然で、述語とつながらない"}, {"text": "へ", "is_correct": false, "explanation": "「指紋へ同じではない」は方向の意味になり、ここでは合わない"}], "correct_answer": "は", "explanations": {"は": "「指紋は同じではない」と主題を示す「は」。ここで正しい", "を": "「指紋を同じではない」は文が成り立たない", "に": "「指紋に同じではない」は不自然で、述語とつながらない", "へ": "「指紋へ同じではない」は方向の意味になり、ここでは合わない"}, "error_tags": {"を": "目的語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52601, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ゆびのさきにある、せんの もよう。ひとりひとり ちがう。", "primary_collocate": null, "pronunciation": "しもん", "ipa": "ɕimoɴ", "syllable_count": 3, "sentences": [{"text": "指紋は、指の先にある細い線の模様です。", "target_word": "指紋", "complexity_tier": "T2", "furigana": "指紋[しもん]は、指[ゆび]の先[さき]にある細[ほそ]い線[せん]の模様[もよう]です。", "sentence_source": "generated"}, {"text": "指紋は人によってみんな違います。", "target_word": "指紋", "complexity_tier": "T2", "furigana": "指紋[しもん]は人[ひと]によってみんな違[ちが]います。", "sentence_source": "generated"}, {"text": "ドアに指紋がついていたので、ふきました。", "target_word": "指紋", "complexity_tier": "T2", "furigana": "ドアに指紋[しもん]がついていたので、ふきました。", "sentence_source": "generated"}, {"text": "警察は指紋を調べて、犯人を見つけました。", "target_word": "指紋", "complexity_tier": "T2", "furigana": "警察[けいさつ]は指紋[しもん]を調[しら]べて、犯人[はんにん]を見[み]つけました。", "sentence_source": "generated"}, {"text": "弟の指紋が、窓ガラスにたくさん残っています。", "target_word": "指紋", "complexity_tier": "T2", "furigana": "弟[おとうと]の指紋[しもん]が、窓[まど]ガラスにたくさん残[のこ]っています。", "sentence_source": "generated"}, {"text": "新しい携帯電話は、指紋でロックが開きます。", "target_word": "指紋", "complexity_tier": "T2", "furigana": "新[あたら]しい携帯[けいたい]電話[でんわ]は、指紋[しもん]でロックが開[あ]きます。", "sentence_source": "generated"}, {"text": "虫めがねで見ると、指紋の線がよく分かります。", "target_word": "指紋", "complexity_tier": "T2", "furigana": "虫[むし]めがねで見[み]ると、指紋[しもん]の線[せん]がよく分[わ]かります。", "sentence_source": "generated"}, {"text": "双子でも、指紋は同じではありません。", "target_word": "指紋", "complexity_tier": "T2", "furigana": "双子[ふたご]でも、指紋[しもん]は同[おな]じではありません。", "sentence_source": "generated"}, {"text": "会社の入口で、指紋を登録しました。", "target_word": "指紋", "complexity_tier": "T2", "furigana": "会社[かいしゃ]の入口[いりぐち]で、指紋[しもん]を登録[とうろく]しました。", "sentence_source": "generated"}, {"text": "黒い机は、指紋が目立ちます。", "target_word": "指紋", "complexity_tier": "T2", "furigana": "黒[くろ]い机[つくえ]は、指紋[しもん]が目立[めだ]ちます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "指紋", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "指先にある線の模様で、人によって違うもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: 虫めがね (Zipf 1.44)']::text[], '866b1129-2e8c-4bbb-8e31-7d683a7aed2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52601, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指輪", "is_correct": false, "explanation": "指輪は装飾品で、指先にある線の模様ではない"}, {"text": "指紋", "is_correct": true, "explanation": "指の先にある細い線の模様。ここに合う"}, {"text": "手袋", "is_correct": false, "explanation": "手袋は指にはめる道具で、線の模様を持つものではない"}, {"text": "霧", "is_correct": false, "explanation": "霧は空気中の水滴で、指の先にあるものとは言えない"}], "explanations": {"指輪": "指輪は装飾品で、指先にある線の模様ではない", "指紋": "指の先にある細い線の模様。ここに合う", "手袋": "手袋は指にはめる道具で、線の模様を持つものではない", "霧": "霧は空気中の水滴で、指の先にあるものとは言えない"}, "sentence_index": 0, "correct_answer": "指紋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雪の上に指紋が続いていたので、犯人の歩いた道がわかった", "explanation": "ここは〈足跡〉の意味。雪の上に続く跡は足跡と言い、指紋は指の模様なので合わない"}, {"text": "電話の声で、指紋を確かめて本人だとわかった", "explanation": "ここは〈声紋〉の意味。声の模様で本人を確かめる。指紋は指の模様なので、声では使わない"}, {"text": "転んで指紋を痛めたので、しばらくピアノが弾けない", "explanation": "ここは〈指先〉の意味。けがをするのは指先で、指紋は指の表面の模様なので合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52601, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "砂糖", "is_correct": false, "explanation": "砂糖は線の模様を持たず、虫めがねで見る線の対象にならない"}, {"text": "寒さ", "is_correct": false, "explanation": "寒さは気温の感覚で、線の模様とは言えない"}, {"text": "味", "is_correct": false, "explanation": "味は感覚で、線の模様として見るものではない"}, {"text": "指紋", "is_correct": true, "explanation": "虫めがねで見ると分かる細かい線の模様。ここに合う"}], "explanations": {"砂糖": "砂糖は線の模様を持たず、虫めがねで見る線の対象にならない", "寒さ": "寒さは気温の感覚で、線の模様とは言えない", "味": "味は感覚で、線の模様として見るものではない", "指紋": "虫めがねで見ると分かる細かい線の模様。ここに合う"}, "sentence_index": 6, "correct_answer": "指紋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "砂浜に大人の手のひらを押しつけた指紋が、くっきり残っていた", "explanation": "ここは〈手形〉（手のひら全体の跡）の意味。手のひら全体の跡は手形と言い、指紋は指先の模様なので合わない"}, {"text": "ドアを開けるため、指紋をまわして解除した", "explanation": "ここは〈鍵〉の意味。まわして開けるのは鍵で、指紋は指先の模様なので合わない"}, {"text": "火事のあと、焼けた指紋がのこっていた", "explanation": "ここは〈痕跡〉の意味。火事のあとに残る跡を指す。指紋は指の模様なので焼けた跡には使わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52601, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ガラスに指紋を残った", "corrected_sentence": "ガラスに指紋が残った", "error_description": "「残る」は主語に「が」をとる。「指紋を残った」は助詞の誤りで、正しくは「指紋が残った」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52601, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ドアノブに指紋をついていたので、ふきました", "corrected_sentence": "ドアノブに指紋がついていたので、ふきました", "error_description": "「ついている」は主語に「が」をとる。「指紋をついていた」は助詞の誤りで、正しくは「指紋がついていた」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
