INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52602, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「コップに付いた指紋を浮かび上がらせた」の「を」。目的語を示し正しい"}, {"text": "に", "is_correct": false, "explanation": "「指紋に浮かび上がらせた」は目的語にならず不自然"}, {"text": "が", "is_correct": false, "explanation": "「指紋が浮かび上がらせた」は主語と述語が合わない"}, {"text": "へ", "is_correct": false, "explanation": "「指紋へ浮かび上がらせた」は方向の意味になり、目的語として成り立たない"}], "correct_answer": "を", "explanations": {"を": "「コップに付いた指紋を浮かび上がらせた」の「を」。目的語を示し正しい", "に": "「指紋に浮かび上がらせた」は目的語にならず不自然", "が": "「指紋が浮かび上がらせた」は主語と述語が合わない", "へ": "「指紋へ浮かび上がらせた」は方向の意味になり、目的語として成り立たない"}, "error_tags": {"に": "位置・相手", "が": "主語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52602, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "指の腹にある凹凸の模様。個人を識別するために使われることが多い。", "primary_collocate": null, "pronunciation": "しもん", "ipa": "ɕimoɴ", "syllable_count": 3, "sentences": [{"text": "まず、現場や鑑識ラボにおいて、肉眼では見えない指紋を、シアノアクリレート法や光学的手法といったアプローチにより浮かび上がらせる。", "target_word": "指紋", "complexity_tier": "T5", "furigana": "まず、現場[げんば]や鑑識[かんしき]ラボにおいて、肉眼[にくがん]では見[み]えない指紋[しもん]を、シアノアクリレート法[ほう]や光学的[こうがくてき]手法[しゅほう]といったアプローチにより浮[う]かび上[あ]がらせる。", "sentence_source": "generated"}, {"text": "真実を解き明かすための静謐かつ論理的なプロセス、それこそが指紋分析の真髄と言えよう。", "target_word": "指紋", "complexity_tier": "T5", "furigana": "真実[しんじつ]を解[と]き明[あ]かすための静謐[せいひつ]かつ論理的[ろんりてき]なプロセス、それこそが指紋[しもん]分析[ぶんせき]の真髄[しんずい]と言[い]えよう。", "sentence_source": "mined"}, {"text": "犯人は手袋をしていなかったため、ドアノブから指紋が見つかった。", "target_word": "指紋", "complexity_tier": "T3", "furigana": "犯人[はんにん]は手袋[てぶくろ]をしていなかったため、ドアノブから指紋[しもん]が見[み]つかった。", "sentence_source": "generated"}, {"text": "警察は現場に残された指紋を照合して、容疑者を特定した。", "target_word": "指紋", "complexity_tier": "T3", "furigana": "警察[けいさつ]は現場[げんば]に残[のこ]された指紋[しもん]を照合[しょうごう]して、容疑者[ようぎしゃ]を特定[とくてい]した。", "sentence_source": "generated"}, {"text": "最近のスマートフォンは、指紋で画面のロックを解除できる。", "target_word": "指紋", "complexity_tier": "T3", "furigana": "最近[さいきん]のスマートフォンは、指紋[しもん]で画面[がめん]のロックを解除[かいじょ]できる。", "sentence_source": "generated"}, {"text": "指紋は一人ひとり異なるので、本人確認に使われている。", "target_word": "指紋", "complexity_tier": "T3", "furigana": "指紋[しもん]は一人[ひとり]ひとり異[こと]なるので、本人[ほんにん]確認[かくにん]に使[つか]われている。", "sentence_source": "generated"}, {"text": "空港の入国審査では、両手の指紋を登録する必要がある。", "target_word": "指紋", "complexity_tier": "T3", "furigana": "空港[くうこう]の入国[にゅうこく]審査[しんさ]では、両手[りょうて]の指紋[しもん]を登録[とうろく]する必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "鑑識課員は、コップに付いた指紋を粉末で浮かび上がらせた。", "target_word": "指紋", "complexity_tier": "T3", "furigana": "鑑識[かんしき]課員[かいん]は、コップに付[つ]いた指紋[しもん]を粉末[ふんまつ]で浮[う]かび上[あ]がらせた。", "sentence_source": "generated"}, {"text": "洗ったばかりなのに、ガラスのコップに指紋が残っていて気になった。", "target_word": "指紋", "complexity_tier": "T3", "furigana": "洗[あら]ったばかりなのに、ガラスのコップに指紋[しもん]が残[のこ]っていて気[き]になった。", "sentence_source": "generated"}, {"text": "手の荒れがひどいと、指紋が薄くなって認証に失敗することがある。", "target_word": "指紋", "complexity_tier": "T3", "furigana": "手[て]の荒[あ]れがひどいと、指紋[しもん]が薄[うす]くなって認証[にんしょう]に失敗[しっぱい]することがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "指紋", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "指先の凹凸の模様で、個人識別や鑑識、認証に使われるもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: シアノアクリレート (Zipf 1.04)','sentence 7 above tier T3: contains vocabulary far above tier T3: 課員 (Zipf 1.98)']::text[], '866b1129-2e8c-4bbb-8e31-7d683a7aed2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52602, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指輪", "is_correct": false, "explanation": "指輪は装飾品で、肉眼では見えない跡を浮かび上がらせる対象ではない"}, {"text": "指紋", "is_correct": true, "explanation": "肉眼では見えない指の跡で、浮かび上がらせる対象として合う"}, {"text": "手袋", "is_correct": false, "explanation": "手袋は道具で、跡を浮かび上がらせるものではない"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気の状態で、現場で浮かび上がらせる対象ではない"}], "explanations": {"指輪": "指輪は装飾品で、肉眼では見えない跡を浮かび上がらせる対象ではない", "指紋": "肉眼では見えない指の跡で、浮かび上がらせる対象として合う", "手袋": "手袋は道具で、跡を浮かび上がらせるものではない", "湿度": "湿度は空気の状態で、現場で浮かび上がらせる対象ではない"}, "sentence_index": 0, "correct_answer": "指紋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雪の上に残った指紋をたどって、犯人の逃げた道を追いかけた", "explanation": "ここは〈足跡〉の意味。雪の上に残る跡は足跡と言い、指紋は指先の模様なので合わない"}, {"text": "マイクに向かって話すと、機械が本人の指紋を声から照合して本人確認をする", "explanation": "ここは〈声紋〉の意味。声の周波数の模様で本人を識別する。指紋は指の模様なので声の照合には使わない"}, {"text": "転んで指紋を切ってしまったので、しばらく絆創膏をはっている", "explanation": "ここは〈指先〉の意味。けがをするのは指先の部分で、指紋は指先の表面の模様なので部位としては言わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52602, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "虹彩", "is_correct": false, "explanation": "虹彩は目の模様で、両手の登録には合わない"}, {"text": "爪", "is_correct": false, "explanation": "爪は手の部位で、登録の対象にはならない"}, {"text": "傷跡", "is_correct": false, "explanation": "傷跡は皮膚の傷で、入国審査で登録する対象ではない"}, {"text": "指紋", "is_correct": true, "explanation": "入国審査で登録する指の模様。ここに合う"}], "explanations": {"虹彩": "虹彩は目の模様で、両手の登録には合わない", "爪": "爪は手の部位で、登録の対象にはならない", "傷跡": "傷跡は皮膚の傷で、入国審査で登録する対象ではない", "指紋": "入国審査で登録する指の模様。ここに合う"}, "sentence_index": 6, "correct_answer": "指紋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "砂浜に大人の手のひらを押しつけた指紋が、くっきり残っていた", "explanation": "ここは〈手形〉（手のひら全体の跡）の意味。手のひら全体の跡は手形と言い、指紋は指先の模様なので合わない"}, {"text": "火事のあとの現場には、焼け焦げた指紋がいくつも残っていた", "explanation": "ここは〈痕跡〉の意味。火事などの後に残る跡を指す。指紋は指の模様なので、焼けた跡には使わない"}, {"text": "ドアを開けるため、指紋を回して解除した", "explanation": "ここは〈鍵〉の意味。回して開けるのは鍵で、指紋は指先の模様なので合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52602, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ガラスのコップに指紋を残っていた", "corrected_sentence": "ガラスのコップに指紋が残っていた", "error_description": "「残る」は自動詞で、主語には「が」を使う。「指紋を残っていた」は助詞の誤りで、正しくは「指紋が残っていた」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
