INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52603, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "光についての学問。", "primary_collocate": null, "pronunciation": "こうがく", "ipa": "koːɡaku", "syllable_count": 4, "sentences": [{"text": "光学は、光について学ぶ学問です。", "target_word": "光学", "complexity_tier": "T2", "furigana": "光学[こうがく]は、光[ひかり]について学[まな]ぶ学問[がくもん]です。", "sentence_source": "generated"}, {"text": "兄は大学で光学を勉強しています。", "target_word": "光学", "complexity_tier": "T2", "furigana": "兄[あに]は大学[だいがく]で光学[こうがく]を勉強[べんきょう]しています。", "sentence_source": "generated"}, {"text": "光学の本に、虹のできかたがのっていました。", "target_word": "光学", "complexity_tier": "T2", "furigana": "光学[こうがく]の本[ほん]に、虹[にじ]のできかたがのっていました。", "sentence_source": "generated"}, {"text": "光学を学ぶと、めがねのしくみが分かります。", "target_word": "光学", "complexity_tier": "T2", "furigana": "光学[こうがく]を学[まな]ぶと、めがねのしくみが分[わ]かります。", "sentence_source": "generated"}, {"text": "先生は光学が専門で、レンズの話をしてくれました。", "target_word": "光学", "complexity_tier": "T2", "furigana": "先生[せんせい]は光学[こうがく]が専門[せんもん]で、レンズの話[はなし]をしてくれました。", "sentence_source": "generated"}, {"text": "光学の実験で、鏡に光を当てました。", "target_word": "光学", "complexity_tier": "T2", "furigana": "光学[こうがく]の実験[じっけん]で、鏡[かがみ]に光[ひかり]を当[あ]てました。", "sentence_source": "generated"}, {"text": "光学では、光がまがる理由も勉強します。", "target_word": "光学", "complexity_tier": "T2", "furigana": "光学[こうがく]では、光[ひかり]がまがる理由[りゆう]も勉強[べんきょう]します。", "sentence_source": "generated"}, {"text": "図書館で光学の入門書を借りました。", "target_word": "光学", "complexity_tier": "T2", "furigana": "図書館[としょかん]で光学[こうがく]の入門書[にゅうもんしょ]を借[か]りました。", "sentence_source": "generated"}, {"text": "光学に興味があって、理科の授業が楽しみです。", "target_word": "光学", "complexity_tier": "T2", "furigana": "光学[こうがく]に興味[きょうみ]があって、理科[りか]の授業[じゅぎょう]が楽[たの]しみです。", "sentence_source": "generated"}, {"text": "光学の研究者は、光の性質を調べています。", "target_word": "光学", "complexity_tier": "T2", "furigana": "光学[こうがく]の研究者[けんきゅうしゃ]は、光[ひかり]の性質[せいしつ]を調[しら]べています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "光学", "label": "基本形"}, {"form": "光学的", "label": "的形"}], "register": "neutral", "sense_fingerprint": "光について調べる学問", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: まがる (Zipf 1.49)']::text[], '866b1129-2e8c-4bbb-8e31-7d683a7aed2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52603, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鏡", "is_correct": false, "explanation": "鏡は道具で、光について学ぶ学問ではない"}, {"text": "光学", "is_correct": true, "explanation": "光について学ぶ学問。主語として定義に合う"}, {"text": "めがね", "is_correct": false, "explanation": "めがねは道具で、学問ではない"}, {"text": "虹", "is_correct": false, "explanation": "虹は光の現象で、学問ではない"}], "explanations": {"鏡": "鏡は道具で、光について学ぶ学問ではない", "光学": "光について学ぶ学問。主語として定義に合う", "めがね": "めがねは道具で、学問ではない", "虹": "虹は光の現象で、学問ではない"}, "sentence_index": 0, "correct_answer": "光学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重い物を持ち上げる仕組みを知るには、光学の知識が役に立つ", "explanation": "ここは〈力学〉の意味。重い物を持ち上げる仕組みは力の働きを扱う力学で、光についての学問である光学とは合わない"}, {"text": "この布は光学が美しく、高く売れた", "explanation": "ここは〈光沢〉（表面の輝き）の意味。布の輝きは光沢と言い、光学は学問なので合わない"}, {"text": "植物は光学で養分を作り、大きく育つ", "explanation": "ここは〈光合成〉の意味。植物が光から養分を作る働きで、学問の光学とは合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52603, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "料理", "is_correct": false, "explanation": "料理の授業では、光がまがる理由は学ばない"}, {"text": "光学", "is_correct": true, "explanation": "光の性質を扱う学問で、光がまがる理由を学ぶ授業に合う"}, {"text": "書道", "is_correct": false, "explanation": "書道では、光がまがる理由は学ばない"}, {"text": "剣道", "is_correct": false, "explanation": "剣道では、光がまがる理由は学ばない"}], "explanations": {"料理": "料理の授業では、光がまがる理由は学ばない", "光学": "光の性質を扱う学問で、光がまがる理由を学ぶ授業に合う", "書道": "書道では、光がまがる理由は学ばない", "剣道": "剣道では、光がまがる理由は学ばない"}, "sentence_index": 6, "correct_answer": "光学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "光学の研究者は、病気の原因を調べています", "explanation": "ここは〈医学〉の意味。病気の原因を調べるのは医学で、光の性質を扱う光学とは合わない"}, {"text": "光学では、コンサートホールの音の響き方を調べます", "explanation": "ここは〈音響学〉の意味。音の響きを扱う学問で、光の性質を扱う光学とは合わない"}, {"text": "光学の研究者は、岩の成り立ちを調べています", "explanation": "ここは〈地質学〉の意味。岩の成り立ちは地質学で扱うもので、光学とは合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
