INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52604, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "光の性質や、光を使った技術・機器についての学問分野。", "primary_collocate": null, "pronunciation": "こうがく", "ipa": "koːɡaku", "syllable_count": 4, "sentences": [{"text": "光学は、光の性質や光を使った機器を研究する学問分野です。", "target_word": "光学", "complexity_tier": "T3", "furigana": "光学[こうがく]は、光[ひかり]の性質[せいしつ]や光[ひかり]を使[つか]った機器[きき]を研究[けんきゅう]する学問分野[がくもんぶんや]です。", "sentence_source": "generated"}, {"text": "大学で光学を専攻し、カメラのレンズ設計を学んだ。", "target_word": "光学", "complexity_tier": "T3", "furigana": "大学[だいがく]で光学[こうがく]を専攻[せんこう]し、カメラのレンズ設計[せっけい]を学[まな]んだ。", "sentence_source": "generated"}, {"text": "光学の研究が進み、より小さな顕微鏡が作られるようになった。", "target_word": "光学", "complexity_tier": "T3", "furigana": "光学[こうがく]の研究[けんきゅう]が進[すす]み、より小[ちい]さな顕微鏡[けんびきょう]が作[つく]られるようになった。", "sentence_source": "generated"}, {"text": "光学の基礎として、まず光の屈折や反射を理解しなければならない。", "target_word": "光学", "complexity_tier": "T3", "furigana": "光学[こうがく]の基礎[きそ]として、まず光[ひかり]の屈折[くっせつ]や反射[はんしゃ]を理解[りかい]しなければならない。", "sentence_source": "generated"}, {"text": "彼女は光学の専門家で、望遠鏡の精度を高める研究をしている。", "target_word": "光学", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は光学[こうがく]の専門家[せんもんか]で、望遠鏡[ぼうえんきょう]の精度[せいど]を高[たか]める研究[けんきゅう]をしている。", "sentence_source": "generated"}, {"text": "光学の発展によって、遠くの星まで観測できるようになった。", "target_word": "光学", "complexity_tier": "T3", "furigana": "光学[こうがく]の発展[はってん]によって、遠[とお]くの星[ほし]まで観測[かんそく]できるようになった。", "sentence_source": "generated"}, {"text": "光学の授業では、レンズを使った実験を行った。", "target_word": "光学", "complexity_tier": "T3", "furigana": "光学[こうがく]の授業[じゅぎょう]では、レンズを使[つか]った実験[じっけん]を行[おこな]った。", "sentence_source": "generated"}, {"text": "医療の現場では、光学の技術が内視鏡に生かされている。", "target_word": "光学", "complexity_tier": "T3", "furigana": "医療[いりょう]の現場[げんば]では、光学[こうがく]の技術[ぎじゅつ]が内視鏡[ないしきょう]に生[い]かされている。", "sentence_source": "generated"}, {"text": "光学を学べば、虹ができる仕組みも説明できる。", "target_word": "光学", "complexity_tier": "T3", "furigana": "光学[こうがく]を学[まな]べば、虹[にじ]ができる仕組[しく]みも説明[せつめい]できる。", "sentence_source": "generated"}, {"text": "光学の分野では、レーザーの研究が盛んに行われている。", "target_word": "光学", "complexity_tier": "T3", "furigana": "光学[こうがく]の分野[ぶんや]では、レーザーの研究[けんきゅう]が盛[さか]んに行[おこな]われている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "光学", "label": "基本形"}, {"form": "光学的", "label": "的形"}], "register": "formal", "sense_fingerprint": "光の性質やレンズ・レーザーなどの技術を扱う学問分野", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866b1129-2e8c-4bbb-8e31-7d683a7aed2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52604, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放課後", "is_correct": false, "explanation": "時間を表す語で、学問分野の名前にはならない"}, {"text": "光学", "is_correct": true, "explanation": "光の性質や機器を扱う学問分野の名前として成り立つ"}, {"text": "鉄道", "is_correct": false, "explanation": "交通機関の名前で、学問分野ではない"}, {"text": "海面", "is_correct": false, "explanation": "水面の位置を表す語で、学問分野ではない"}], "explanations": {"放課後": "時間を表す語で、学問分野の名前にはならない", "光学": "光の性質や機器を扱う学問分野の名前として成り立つ", "鉄道": "交通機関の名前で、学問分野ではない", "海面": "水面の位置を表す語で、学問分野ではない"}, "sentence_index": 0, "correct_answer": "光学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地層の年代を調べる研究は、光学の分野で行われる", "explanation": "ここは〈地質学〉の意味。地層の年代を調べるのは地質学で、光の性質を扱う光学とは合わない"}, {"text": "この布は光学がきれいで、高く売れた", "explanation": "ここは〈光沢〉（表面の輝き）の意味。布の輝きは光沢と言い、光学は学問なので合わない"}, {"text": "ブレーキの仕組みを理解するには、光学の知識が必要だ", "explanation": "ここは〈力学〉の意味。ブレーキの仕組みは力の働きを扱う力学で、光の学問である光学とは合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52604, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "料理", "is_correct": false, "explanation": "料理の授業では、レンズを使った実験は行わない"}, {"text": "光学", "is_correct": true, "explanation": "光やレンズを扱う授業。レンズを使った実験の授業に合う"}, {"text": "書道", "is_correct": false, "explanation": "書道の授業では、レンズを使った実験は行わない"}, {"text": "柔道", "is_correct": false, "explanation": "柔道の授業と、レンズを使った実験は結びつかない"}], "explanations": {"料理": "料理の授業では、レンズを使った実験は行わない", "光学": "光やレンズを扱う授業。レンズを使った実験の授業に合う", "書道": "書道の授業では、レンズを使った実験は行わない", "柔道": "柔道の授業と、レンズを使った実験は結びつかない"}, "sentence_index": 6, "correct_answer": "光学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "光学の分野では、新しい薬の研究が盛んに行われている", "explanation": "ここは〈医学〉の意味。新しい薬の研究は医学の分野で、光学の分野とは言えないので合わない"}, {"text": "植物は光学によって養分を作り、大きく育つ", "explanation": "ここは〈光合成〉の意味。植物が光から養分を作る働きで、学問の光学とは合わない"}, {"text": "光学の分野では、橋の強度を調べる研究が盛んに行われている", "explanation": "ここは〈工学〉の意味。橋の強度など建造物の研究は工学で扱うので、光学とは合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52604, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は大学で光学に専攻していた", "corrected_sentence": "彼は大学で光学を専攻していた", "error_description": "「専攻する」は目的語に「を」をとる。「光学に専攻」は助詞の誤りで、正しくは「光学を専攻」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52604, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "光学が学ぶと、レンズの仕組みがわかります", "corrected_sentence": "光学を学ぶと、レンズの仕組みがわかります", "error_description": "「学ぶ」の目的語は「を」で示す。「光学が学ぶ」は「光学」を主語にできないので、助詞の誤り。正しくは「光学を学ぶ」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52605, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「入っています」の主語を示す「が」で、文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「入る」は目的語を取らない自動詞なので、「を」は誤り。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所・手段を示し、入っているものの主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列・引用を示し、入る主体を示せない。"}], "correct_answer": "が", "explanations": {"が": "「入っています」の主語を示す「が」で、文が成り立つ。", "を": "「入る」は目的語を取らない自動詞なので、「を」は誤り。", "で": "「で」は場所・手段を示し、入っているものの主語にはならない。", "と": "「と」は並列・引用を示し、入る主体を示せない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
