INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52605, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものをくっつけるための、かたいのりのようなものです。", "primary_collocate": null, "pronunciation": "しあのあくりれーと", "ipa": "ɕianoakuɾireːto", "syllable_count": 9, "sentences": [{"text": "シアノアクリレートは、ものをくっつけるための強いのりです。", "target_word": "シアノアクリレート", "complexity_tier": "T2", "furigana": "シアノアクリレートは、ものをくっつけるための強[つよ]いのりです。", "sentence_source": "generated"}, {"text": "瞬間接着剤には、シアノアクリレートが入っています。", "target_word": "シアノアクリレート", "complexity_tier": "T2", "furigana": "瞬間[しゅんかん]接着剤[せっちゃくざい]には、シアノアクリレートが入[はい]っています。", "sentence_source": "generated"}, {"text": "シアノアクリレートは、空気にふれるとすぐにかたまります。", "target_word": "シアノアクリレート", "complexity_tier": "T2", "furigana": "シアノアクリレートは、空気[くうき]にふれるとすぐにかたまります。", "sentence_source": "generated"}, {"text": "こわれたカップを、シアノアクリレートでくっつけました。", "target_word": "シアノアクリレート", "complexity_tier": "T2", "furigana": "こわれたカップを、シアノアクリレートでくっつけました。", "sentence_source": "generated"}, {"text": "シアノアクリレートが手につくと、指がはなれなくなります。", "target_word": "シアノアクリレート", "complexity_tier": "T2", "furigana": "シアノアクリレートが手[て]につくと、指[ゆび]がはなれなくなります。", "sentence_source": "generated"}, {"text": "シアノアクリレートを使ったあとは、ふたをしっかり閉めました。", "target_word": "シアノアクリレート", "complexity_tier": "T3", "furigana": "シアノアクリレート[しあのあくりれーと]を使[つか]ったあとは、ふたをしっかり閉[し]めました。", "sentence_source": "generated"}, {"text": "先生はシアノアクリレートの安全な使い方を教えてくれました。", "target_word": "シアノアクリレート", "complexity_tier": "T2", "furigana": "先生[せんせい]はシアノアクリレートの安全[あんぜん]な使[つか]い方[かた]を教[おし]えてくれました。", "sentence_source": "generated"}, {"text": "シアノアクリレートは、紙や木にもよくつきます。", "target_word": "シアノアクリレート", "complexity_tier": "T2", "furigana": "シアノアクリレートは、紙[かみ]や木[き]にもよくつきます。", "sentence_source": "generated"}, {"text": "切れたひもを、シアノアクリレートでつなぎました。", "target_word": "シアノアクリレート", "complexity_tier": "T2", "furigana": "切[き]れたひもを、シアノアクリレートでつなぎました。", "sentence_source": "generated"}, {"text": "シアノアクリレートで貼ったものは、一度かたまるとはがしにくいです。", "target_word": "シアノアクリレート", "complexity_tier": "T3", "furigana": "シアノアクリレート[しあのあくりれーと]で貼[は]ったものは、一度[いちど]かたまるとはがしにくいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "シアノアクリレート", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ものをくっつける、すぐにかたまる強いのり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866b1129-2e8c-4bbb-8e31-7d683a7aed2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52605, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "シアノアクリレート", "is_correct": true, "explanation": "ものをくっつける強いのりの名前として成り立つ。"}, {"text": "湿度", "is_correct": false, "explanation": "気象の数値で、のりの説明文の主語にならない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さで、のりとしての説明にならない。"}, {"text": "気温", "is_correct": false, "explanation": "気象の数値で、のりの説明文の主語にならない。"}], "explanations": {"シアノアクリレート": "ものをくっつける強いのりの名前として成り立つ。", "湿度": "気象の数値で、のりの説明文の主語にならない。", "体重": "体の重さで、のりとしての説明にならない。", "気温": "気象の数値で、のりの説明文の主語にならない。"}, "sentence_index": 0, "correct_answer": "シアノアクリレート"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "黄ばんだシャツを、シアノアクリレートで白くした。", "explanation": "ここは〈漂白剤〉の用途。シアノアクリレートは色を落とす働きがなく、くっつけるための接着剤。"}, {"text": "壁にシアノアクリレートを塗って、部屋を明るい色にした。", "explanation": "ここは〈塗料〉の用途。シアノアクリレートは色を付けるものではなく、接着に使う。"}, {"text": "熱くなったエンジンに、シアノアクリレートを流して温度を下げた。", "explanation": "ここは〈冷却剤〉の役割。シアノアクリレートは熱を取る働きがなく、温度は下がらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52605, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "シアノアクリレート", "is_correct": true, "explanation": "接着剤として安全な使い方を教える対象になる。"}, {"text": "指紋", "is_correct": false, "explanation": "人の皮膚の模様で、使い方を教える対象にならない。"}, {"text": "皮膚", "is_correct": false, "explanation": "体の一部で、道具の使い方の対象にならない。"}, {"text": "雨量", "is_correct": false, "explanation": "降水量で、使い方を教える対象にならない。"}], "explanations": {"シアノアクリレート": "接着剤として安全な使い方を教える対象になる。", "指紋": "人の皮膚の模様で、使い方を教える対象にならない。", "皮膚": "体の一部で、道具の使い方の対象にならない。", "雨量": "降水量で、使い方を教える対象にならない。"}, "sentence_index": 6, "correct_answer": "シアノアクリレート"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "虫が出やすい場所に、シアノアクリレートを置いておく。", "explanation": "ここは〈殺虫剤〉の役割。シアノアクリレートは虫を殺す働きがなく、接着に使う。"}, {"text": "髪型を崩さないように、シアノアクリレートを軽くかける。", "explanation": "ここは〈ヘアスプレー〉の用途。シアノアクリレートは髪を整える働きがなく、くっつける接着剤。"}, {"text": "ガラスの表面を、シアノアクリレートで磨いて傷を消した。", "explanation": "ここは〈研磨剤〉の役割。シアノアクリレートは表面を削る働きがなく、傷を消す役目はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52605, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "シアノアクリレートを、プラスチックどうしを強くくっつけるのに向いています。", "corrected_sentence": "シアノアクリレートは、プラスチックどうしを強くくっつけるのに向いています。", "error_description": "「向いています」の主語は「は」で示す。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52605, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "シアノアクリレートが子どもの手の届かない所に置いてください。", "corrected_sentence": "シアノアクリレートを子どもの手の届かない所に置いてください。", "error_description": "「置く」は目的語を「を」で示す。「が」は主語の印で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
