INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52606, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「入っている」の主語を示す「が」で、文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「入る」は目的語を取らない自動詞なので、「を」は誤り。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列・引用を示し、入っているものの主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所・手段を示し、入っているものの主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「入っている」の主語を示す「が」で、文が成り立つ。", "を": "「入る」は目的語を取らない自動詞なので、「を」は誤り。", "と": "「と」は並列・引用を示し、入っているものの主語にはならない。", "で": "「で」は場所・手段を示し、入っているものの主語にはならない。"}, "error_tags": {"を": "目的語", "と": "並列・引用", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52606, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "瞬間接着剤の主成分で、空気中の水分と反応して急速に硬化する合成樹脂。指紋の検出などにも利用される。", "primary_collocate": null, "pronunciation": "しあのあくりれーと", "ipa": "ɕianoakuɾireːto", "syllable_count": 9, "sentences": [{"text": "現場の指紋を調べるとき、鑑識はシアノアクリレートを使うことがある。", "target_word": "シアノアクリレート", "complexity_tier": "T3", "furigana": "現場[げんば]の指紋[しもん]を調[しら]べるとき、鑑識[かんしき]はシアノアクリレートを使[つか]うことがある。", "sentence_source": "generated"}, {"text": "瞬間接着剤の主成分はシアノアクリレートで、空気中の水分に触れると固まる。", "target_word": "シアノアクリレート", "complexity_tier": "T3", "furigana": "瞬間[しゅんかん]接着剤[せっちゃくざい]の主成分[しゅせいぶん]はシアノアクリレートで、空気中[くうきちゅう]の水分[すいぶん]に触[ふ]れると固[かた]まる。", "sentence_source": "generated"}, {"text": "シアノアクリレートは水分と反応して急速に硬化するため、使うときは手早く作業する必要がある。", "target_word": "シアノアクリレート", "complexity_tier": "T3", "furigana": "シアノアクリレートは水分[すいぶん]と反応[はんのう]して急速[きゅうそく]に硬化[こうか]するため、使[つか]うときは手早[てばや]く作業[さぎょう]する必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "鑑識では、シアノアクリレートの蒸気を使って指紋を白く浮かび上がらせる。", "target_word": "シアノアクリレート", "complexity_tier": "T3", "furigana": "鑑識[かんしき]では、シアノアクリレートの蒸気[じょうき]を使[つか]って指紋[しもん]を白[しろ]く浮[う]かび上[あ]がらせる。", "sentence_source": "generated"}, {"text": "シアノアクリレートが指に付くと、皮膚がくっついてしまうので注意が必要だ。", "target_word": "シアノアクリレート", "complexity_tier": "T3", "furigana": "シアノアクリレートが指[ゆび]に付[つ]くと、皮膚[ひふ]がくっついてしまうので注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "研究者は、シアノアクリレートを医療用の接着剤に応用する方法を調べている。", "target_word": "シアノアクリレート", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、シアノアクリレートを医療用[いりょうよう]の接着剤[せっちゃくざい]に応用[おうよう]する方法[ほうほう]を調[しら]べている。", "sentence_source": "generated"}, {"text": "湿度が高い日は、シアノアクリレートの硬化が早まる。", "target_word": "シアノアクリレート", "complexity_tier": "T3", "furigana": "湿度[しつど]が高[たか]い日[ひ]は、シアノアクリレートの硬化[こうか]が早[はや]まる。", "sentence_source": "generated"}, {"text": "このチューブにはシアノアクリレートが入っているので、使用後は必ず蓋を閉めてください。", "target_word": "シアノアクリレート", "complexity_tier": "T3", "furigana": "このチューブにはシアノアクリレートが入[はい]っているので、使用後[しようご]は必[かなら]ず蓋[ふた]を閉[し]めてください。", "sentence_source": "generated"}, {"text": "シアノアクリレートは接着力が強い反面、衝撃にはもろいという弱点がある。", "target_word": "シアノアクリレート", "complexity_tier": "T3", "furigana": "シアノアクリレートは接着力[せっちゃくりょく]が強[つよ]い反面[はんめん]、衝撃[しょうげき]にはもろいという弱点[じゃくてん]がある。", "sentence_source": "generated"}, {"text": "実験室では、シアノアクリレートを加熱して気化させ、容器の中の指紋を調べた。", "target_word": "シアノアクリレート", "complexity_tier": "T3", "furigana": "実験室[じっけんしつ]では、シアノアクリレートを加熱[かねつ]して気化[きか]させ、容器[ようき]の中[なか]の指紋[しもん]を調[しら]べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "シアノアクリレート", "label": "基本形"}], "register": "technical", "sense_fingerprint": "瞬間接着剤の主成分で、水分に反応して急速に硬化し、指紋検出にも使われる合成樹脂", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866b1129-2e8c-4bbb-8e31-7d683a7aed2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52606, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "シアノアクリレート", "is_correct": true, "explanation": "指紋検出に使う化合物で、文の目的語として成り立つ"}, {"text": "湿度", "is_correct": false, "explanation": "気象の数値で、鑑識が使う物質にならない"}, {"text": "気温", "is_correct": false, "explanation": "気象の数値で、鑑識が使う物質にならない"}, {"text": "気圧", "is_correct": false, "explanation": "大気の圧力で、鑑識が使う物質にならない"}], "explanations": {"シアノアクリレート": "指紋検出に使う化合物で、文の目的語として成り立つ", "湿度": "気象の数値で、鑑識が使う物質にならない", "気温": "気象の数値で、鑑識が使う物質にならない", "気圧": "大気の圧力で、鑑識が使う物質にならない"}, "sentence_index": 0, "correct_answer": "シアノアクリレート"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鑑識では、シアノアクリレートを指紋の上に振りかけ、浮かび上がった紋様を写真に撮った。", "explanation": "ここは〈アルミニウム粉末〉の使い方。粉を振りかけて指紋を見せる方法で、シアノアクリレートは粉ではなく蒸気として使うので合わない。"}, {"text": "使う直前に、シアノアクリレートの主剤と硬化剤を一対一で混ぜ、三十分ほど待つ。", "explanation": "ここは〈エポキシ樹脂〉の使い方。二液を混ぜて固めるもので、シアノアクリレートは一液で混ぜる必要がなく、水分で固まる。"}, {"text": "湿気を防ぐため、シアノアクリレートの小袋を箱に入れておく。", "explanation": "ここは〈乾燥剤〉の役割。シアノアクリレートは水分と反応して固まるもので、湿気を吸い取る働きはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52606, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "シアノアクリレート", "is_correct": true, "explanation": "水分と反応して硬化する物質で、硬化が早まる対象になる。"}, {"text": "体重", "is_correct": false, "explanation": "人や動物の重さで、硬化の対象にならない。"}, {"text": "雨量", "is_correct": false, "explanation": "降った雨の量で、硬化の対象にならない。"}, {"text": "指紋", "is_correct": false, "explanation": "皮膚の模様で、接着剤の硬化とは関係しない。"}], "explanations": {"シアノアクリレート": "水分と反応して硬化する物質で、硬化が早まる対象になる。", "体重": "人や動物の重さで、硬化の対象にならない。", "雨量": "降った雨の量で、硬化の対象にならない。", "指紋": "皮膚の模様で、接着剤の硬化とは関係しない。"}, "sentence_index": 6, "correct_answer": "シアノアクリレート"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "油で汚れた調理台は、シアノアクリレートでこすると汚れが落ちる。", "explanation": "ここは〈洗剤〉の役割。シアノアクリレートは接着剤で、油汚れを落とす働きはない。"}, {"text": "畑にシアノアクリレートをまくと、作物が早く大きく育つ。", "explanation": "ここは〈肥料〉の役割。シアノアクリレートは作物の栄養にならず、育てるために使う物質でもない。"}, {"text": "靴箱の嫌なにおいを、シアノアクリレートで消した。", "explanation": "ここは〈脱臭剤〉の役割。シアノアクリレートは臭いを消す働きがなく、くっつける接着剤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52606, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "シアノアクリレートを、空気中の水分に触れると急速に固まる。", "corrected_sentence": "シアノアクリレートは、空気中の水分に触れると急速に固まる。", "error_description": "「固まる」の主語は「は」で示す。「を」は目的語の印で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52606, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "シアノアクリレートを食べるときは、換気の良い場所で作業してください。", "corrected_sentence": "シアノアクリレートを使うときは、換気の良い場所で作業してください。", "error_description": "「シアノアクリレートを」に続く動詞は「使う」が正しい。「食べる」は誤った組み合わせ。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52607, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を表す「が」。「配列が〜なっている」で文が成立する。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表すので、「なっている」の主語には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は連体修飾で、主語の位置を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、なっている状態の主語には使えない。"}], "correct_answer": "が", "explanations": {"が": "主語を表す「が」。「配列が〜なっている」で文が成立する。", "を": "「を」は目的語を表すので、「なっている」の主語には合わない。", "の": "「の」は連体修飾で、主語の位置を表せない。", "へ": "「へ」は方向を表すので、なっている状態の主語には使えない。"}, "error_tags": {"を": "対象", "の": "連体", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
