INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52607, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものがならんでいるじゅんばんや、そのならびかた。", "primary_collocate": null, "pronunciation": "はいれつ", "ipa": "haiɾetsɯ", "syllable_count": 4, "sentences": [{"text": "教室の机の配列を変えました。", "target_word": "配列", "complexity_tier": "T3", "furigana": "教室(きょうしつ)の机(つくえ)の配列(はいれつ)を変(か)えました。", "sentence_source": "generated"}, {"text": "本の配列が、背の高さ順になっています。", "target_word": "配列", "complexity_tier": "T3", "furigana": "本(ほん)の配列(はいれつ)が、背(せ)の高(たか)さ順(じゅん)になっています。", "sentence_source": "generated"}, {"text": "花の配列がきれいで、庭が明るく見えます。", "target_word": "配列", "complexity_tier": "T3", "furigana": "花(はな)の配列(はいれつ)がきれいで、庭(にわ)が明(あか)るく見(み)えます。", "sentence_source": "generated"}, {"text": "店では、お菓子の配列を毎週変えます。", "target_word": "配列", "complexity_tier": "T3", "furigana": "店(みせ)では、お菓子(かし)の配列(はいれつ)を毎週(まいしゅう)変(か)えます。", "sentence_source": "generated"}, {"text": "積み木の配列を間違えて、形が崩れました。", "target_word": "配列", "complexity_tier": "T3", "furigana": "積(つ)み木(き)の配列(はいれつ)を間違(まちが)えて、形(かたち)が崩(くず)れました。", "sentence_source": "generated"}, {"text": "この表は、名前の配列が五十音順です。", "target_word": "配列", "complexity_tier": "T3", "furigana": "この表(ひょう)は、名前(なまえ)の配列(はいれつ)が五十音順(ごじゅうおんじゅん)です。", "sentence_source": "generated"}, {"text": "席の配列が変わって、友だちと離れた席になってしまいました。", "target_word": "配列", "complexity_tier": "T3", "furigana": "席(せき)の配列(はいれつ)が変(か)わって、友(とも)だちと離(はな)れた席(せき)になってしまいました。", "sentence_source": "generated"}, {"text": "靴箱の靴の配列は、学年ごとに決まっています。", "target_word": "配列", "complexity_tier": "T3", "furigana": "靴箱(くつばこ)の靴(くつ)の配列(はいれつ)は、学年(がくねん)ごとに決(き)まっています。", "sentence_source": "generated"}, {"text": "駐車場の車の配列がそろっていて、気持ちがいいです。", "target_word": "配列", "complexity_tier": "T3", "furigana": "駐車場(ちゅうしゃじょう)の車(くるま)の配列(はいれつ)がそろっていて、気持(きも)ちがいいです。", "sentence_source": "generated"}, {"text": "配列を見れば、どこに何があるか分かります。", "target_word": "配列", "complexity_tier": "T3", "furigana": "配列(はいれつ)を見(み)れば、どこに何(なに)があるか分(わ)かります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "配列", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ものが並んでいる順番や並び方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3b14ba-f350-4b70-835c-74054ef8b390') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52607, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "配列", "is_correct": true, "explanation": "教室の机の並び方を変えたという文脈に合う。"}, {"text": "味", "is_correct": false, "explanation": "机の味を変えるという文脈は成立せず、不自然。"}, {"text": "香り", "is_correct": false, "explanation": "机の香りを変えるという文脈は成立せず、意味が通らない。"}, {"text": "音色", "is_correct": false, "explanation": "机の音色を変えるという文脈は成立せず、不自然。"}], "explanations": {"配列": "教室の机の並び方を変えたという文脈に合う。", "味": "机の味を変えるという文脈は成立せず、不自然。", "香り": "机の香りを変えるという文脈は成立せず、意味が通らない。", "音色": "机の音色を変えるという文脈は成立せず、不自然。"}, "sentence_index": 0, "correct_answer": "配列"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新人を営業所に配列した。", "explanation": "〈配置〉の意味。人を職場に割り当てる意味で、物の並び方を表す配列とは違う。"}, {"text": "生徒が校庭で配列した。", "explanation": "〈整列〉の意味。人が一列に並ぶ動作には整列を使い、配列は物の並べ方に使う。"}, {"text": "毎週、食料の配列があった。", "explanation": "〈配給〉の意味。食料などを配る行為なので、並び方を表す配列では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52607, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "配列", "is_correct": true, "explanation": "席の並び方が変わって友だちと離れたという文脈に合う。"}, {"text": "音量", "is_correct": false, "explanation": "席の音量が変わるという文脈は成立せず、意味が通らない。"}, {"text": "匂い", "is_correct": false, "explanation": "席の匂いが変わって友だちと離れたという文脈にはならない。"}, {"text": "寿命", "is_correct": false, "explanation": "席の寿命が変わるという文脈は成立せず、不自然。"}], "explanations": {"配列": "席の並び方が変わって友だちと離れたという文脈に合う。", "音量": "席の音量が変わるという文脈は成立せず、意味が通らない。", "匂い": "席の匂いが変わって友だちと離れたという文脈にはならない。", "寿命": "席の寿命が変わるという文脈は成立せず、不自然。"}, "sentence_index": 6, "correct_answer": "配列"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "配列を守って、並んでください。", "explanation": "〈順番〉の意味。人が並ぶ順序には順番を使い、配列は物の並び方に使う。"}, {"text": "来月の利益を、社員に配列した。", "explanation": "〈分配〉の意味。利益を分けて配る意味で、並べるという意味の配列では合わない。"}, {"text": "ニュースを毎朝配列している。", "explanation": "〈配信〉の意味。ニュースを届ける意味で、並べるという意味の配列では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52607, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "引き出しの中の文房具の配列が、使う順に直した。", "corrected_sentence": "引き出しの中の文房具の配列を、使う順に直した。", "error_description": "誤: 「が」／正: 「を」。「直す」の対象は「を」で示す。「が」では配列が主語になり、直す人の文脈に合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52607, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "服の配列と、色の順にそろえた。", "corrected_sentence": "服の配列を、色の順にそろえた。", "error_description": "誤: 「と」／正: 「を」。「そろえる」の対象は「を」で示す。「と」は並列を表し、対象の表し方が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52608, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「配列を変える」の対象を表す「を」で、文が通る。"}, {"text": "が", "is_correct": false, "explanation": "「配列が変えた」では配列が主語になり、変えた人の文脈に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を表すので、変える対象には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は連体修飾で、変える動作の対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「配列を変える」の対象を表す「を」で、文が通る。", "が": "「配列が変えた」では配列が主語になり、変えた人の文脈に合わない。", "と": "「と」は並列を表すので、変える対象には合わない。", "の": "「の」は連体修飾で、変える動作の対象を表せない。"}, "error_tags": {"が": "主語", "と": "並列", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52608, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「配列が違えば」の主語を表す「が」。文が自然に通る。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表すので、「違う」の主語には合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や帰着点を表し、違うという状態の主語には使えない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を表すので、主語の位置には合わない。"}], "correct_answer": "が", "explanations": {"が": "「配列が違えば」の主語を表す「が」。文が自然に通る。", "を": "「を」は目的語を表すので、「違う」の主語には合わない。", "に": "「に」は相手や帰着点を表し、違うという状態の主語には使えない。", "で": "「で」は手段を表すので、主語の位置には合わない。"}, "error_tags": {"を": "対象", "に": "相手・帰着点", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52608, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が一定の順序で並んでいること。また、その並び方や順序。", "primary_collocate": null, "pronunciation": "はいれつ", "ipa": "haiɾetsɯ", "syllable_count": 4, "sentences": [{"text": "次いで、分岐や終点といった特徴点の配列を精密に分析する。", "target_word": "配列", "complexity_tier": "T4", "furigana": "次(つ)いで、分岐(ぶんき)や終点(しゅうてん)といった特徴点(とくちょうてん)の配列(はいれつ)を精密(せいみつ)に分析(ぶんせき)する。", "sentence_source": "mined"}, {"text": "本棚の本の配列を、五十音順に変えた。", "target_word": "配列", "complexity_tier": "T3", "furigana": "本棚(ほんだな)の本(ほん)の配列(はいれつ)を、五十音順(ごじゅうおんじゅん)に変(か)えた。", "sentence_source": "generated"}, {"text": "店内の商品の配列が変わって、目的の物を探しにくくなった。", "target_word": "配列", "complexity_tier": "T3", "furigana": "店内(てんない)の商品(しょうひん)の配列(はいれつ)が変(か)わって、目的(もくてき)の物(もの)を探(さが)しにくくなった。", "sentence_source": "generated"}, {"text": "この庭は、木の配列が美しく計算されている。", "target_word": "配列", "complexity_tier": "T3", "furigana": "この庭(にわ)は、木(き)の配列(はいれつ)が美(うつく)しく計算(けいさん)されている。", "sentence_source": "generated"}, {"text": "机の配列を変えたら、教室が広く見えた。", "target_word": "配列", "complexity_tier": "T3", "furigana": "机(つくえ)の配列(はいれつ)を変(か)えたら、教室(きょうしつ)が広(ひろ)く見(み)えた。", "sentence_source": "generated"}, {"text": "展示品の配列には、時代の流れを示す意図がある。", "target_word": "配列", "complexity_tier": "T4", "furigana": "展示品(てんじひん)の配列(はいれつ)には、時代(じだい)の流(なが)れを示(しめ)す意図(いと)がある。", "sentence_source": "generated"}, {"text": "駅前のビルの配列は、地図で見ると規則的だ。", "target_word": "配列", "complexity_tier": "T3", "furigana": "駅前(えきまえ)のビルの配列(はいれつ)は、地図(ちず)で見(み)ると規則的(きそくてき)だ。", "sentence_source": "generated"}, {"text": "文字の配列が違えば、同じ文字でも別の言葉になる。", "target_word": "配列", "complexity_tier": "T3", "furigana": "文字(もじ)の配列(はいれつ)が違(ちが)えば、同(おな)じ文字(もじ)でも別(べつ)の言葉(ことば)になる。", "sentence_source": "generated"}, {"text": "資料の配列が乱れていて、必要な頁を探すのに時間がかかった。", "target_word": "配列", "complexity_tier": "T4", "furigana": "資料(しりょう)の配列(はいれつ)が乱(みだ)れていて、必要(ひつよう)な頁(ページ)を探(さが)すのに時間(じかん)がかかった。", "sentence_source": "generated"}, {"text": "研究者は、原子の配列によって物の性質が変わることを確かめた。", "target_word": "配列", "complexity_tier": "T4", "furigana": "研究者(けんきゅうしゃ)は、原子(げんし)の配列(はいれつ)によって物(もの)の性質(せいしつ)が変(か)わることを確(たし)かめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "配列", "label": "基本形"}], "register": "formal", "sense_fingerprint": "物が決まった順序で並ぶこと、またその並びの順序", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3b14ba-f350-4b70-835c-74054ef8b390') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52608, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "配列", "is_correct": true, "explanation": "特徴点の並び方を精密に分析するという文脈に合う。"}, {"text": "気温", "is_correct": false, "explanation": "特徴点の気温を精密に分析するという内容は成立しない。"}, {"text": "表情", "is_correct": false, "explanation": "特徴点の表情は分析の対象として成立せず、文脈に合わない。"}, {"text": "音色", "is_correct": false, "explanation": "特徴点の音色を分析するという文脈にはならず、不自然。"}], "explanations": {"配列": "特徴点の並び方を精密に分析するという文脈に合う。", "気温": "特徴点の気温を精密に分析するという内容は成立しない。", "表情": "特徴点の表情は分析の対象として成立せず、文脈に合わない。", "音色": "特徴点の音色を分析するという文脈にはならず、不自然。"}, "sentence_index": 0, "correct_answer": "配列"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今朝、郵便物を各家に配列した。", "explanation": "〈配達〉の意味。郵便物を家に届ける意味で、並べるという意味の配列では合わない。"}, {"text": "今朝、食料の配列が始まった。", "explanation": "〈配給〉の意味。食料などを人に配る行為なので、並び方の配列とは意味が違う。"}, {"text": "作業員を持ち場に配列した。", "explanation": "〈配置〉の意味。人を持ち場に割り当てる意味で、物の並び方を表す配列では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52608, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "配列", "is_correct": true, "explanation": "ビルの並び方が規則的だという文脈に合う。"}, {"text": "音量", "is_correct": false, "explanation": "ビルの音量を地図で見て規則的と言う文脈は成立しない。"}, {"text": "匂い", "is_correct": false, "explanation": "匂いは地図で見て規則的かを判断するものではなく、文脈に合わない。"}, {"text": "感触", "is_correct": false, "explanation": "感触は地図で見て規則的かどうかという話にならず、不自然。"}], "explanations": {"配列": "ビルの並び方が規則的だという文脈に合う。", "音量": "ビルの音量を地図で見て規則的と言う文脈は成立しない。", "匂い": "匂いは地図で見て規則的かを判断するものではなく、文脈に合わない。", "感触": "感触は地図で見て規則的かどうかという話にならず、不自然。"}, "sentence_index": 6, "correct_answer": "配列"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "生徒たちは、朝礼のために体育館で配列した。", "explanation": "〈整列〉の意味。人が一列に並ぶ動作には整列を使い、物の並び方を表す配列では合わない。"}, {"text": "新人を営業部に配列した。", "explanation": "〈配属〉の意味。人を部署に割り当てる意味で、並び方を表す配列とは違う。"}, {"text": "動画を毎日配列している。", "explanation": "〈配信〉の意味。動画などを届ける意味で、並べるという意味の配列では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52608, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "棚の本の配列に見直して、探しやすくした。", "corrected_sentence": "棚の本の配列を見直して、探しやすくした。", "error_description": "誤: 「に」／正: 「を」。「見直す」の対象は「を」で示す。「配列に見直す」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52608, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ファイルの配列を乱れていて、探しにくかった。", "corrected_sentence": "ファイルの配列が乱れていて、探しにくかった。", "error_description": "誤: 「を」／正: 「が」。「乱れる」は主語に「が」を取る。「を」では目的語になり、文が成立しない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52609, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "降りる場所を示す「で」で、「終点で、全員が降りました」と続くので正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、降りる場所を表す位置には入らないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列を示す「と」で、降りる場所の意味にはならないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、「終点の」では文が続かないので合わない。"}], "correct_answer": "で", "explanations": {"で": "降りる場所を示す「で」で、「終点で、全員が降りました」と続くので正しい。", "が": "主語を示す助詞で、降りる場所を表す位置には入らないので合わない。", "と": "並列を示す「と」で、降りる場所の意味にはならないので合わない。", "の": "連体修飾の「の」で、「終点の」では文が続かないので合わない。"}, "error_tags": {"が": "主語の格助詞", "と": "並列の助詞", "の": "連体修飾の助詞"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "始点", "is_correct": true, "explanation": "道や線が始まる地点で、終点の対義語。"}, {"text": "中間", "is_correct": false, "explanation": "道や線の途中を指し、始まりの地点ではないので対にならない。"}, {"text": "頂上", "is_correct": false, "explanation": "山などの一番高い所を指し、終わりの地点を表さないので対にならない。"}, {"text": "入口", "is_correct": false, "explanation": "入るところを指し、対義語の関係にないので合わない。"}], "correct_answer": "始点", "explanations": {"始点": "道や線が始まる地点で、終点の対義語。", "中間": "道や線の途中を指し、始まりの地点ではないので対にならない。", "頂上": "山などの一番高い所を指し、終わりの地点を表さないので対にならない。", "入口": "入るところを指し、対義語の関係にないので合わない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52609, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "存在する場所を示す「に」で、「終点に、古いお寺がある」と続くので正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞で、存在する場所は表せないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞で、「終点の」では文が続かないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」で、存在する場所を示す語としては合わない。"}], "correct_answer": "に", "explanations": {"に": "存在する場所を示す「に」で、「終点に、古いお寺がある」と続くので正しい。", "を": "目的語を示す助詞で、存在する場所は表せないので合わない。", "の": "連体修飾の助詞で、「終点の」では文が続かないので合わない。", "へ": "方向を示す「へ」で、存在する場所を示す語としては合わない。"}, "error_tags": {"を": "目的語の格助詞", "の": "連体修飾の助詞", "へ": "方向の助詞"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "始点", "is_correct": true, "explanation": "道や線が始まる地点で、終点の対義語。"}, {"text": "車両", "is_correct": false, "explanation": "乗り物そのものを指し、終点の対義語の関係にないので合わない。"}, {"text": "乗車", "is_correct": false, "explanation": "乗り物に乗ることを指し、地点を表す語ではないので対にならない。"}, {"text": "停留所", "is_correct": false, "explanation": "乗客が乗り降りする停止地点を指すが、始まりと終わりの対義関係にはないので合わない。"}], "correct_answer": "始点", "explanations": {"始点": "道や線が始まる地点で、終点の対義語。", "車両": "乗り物そのものを指し、終点の対義語の関係にないので合わない。", "乗車": "乗り物に乗ることを指し、地点を表す語ではないので対にならない。", "停留所": "乗客が乗り降りする停止地点を指すが、始まりと終わりの対義関係にはないので合わない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52609, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "道や線がそこで終わる場所のことです。", "primary_collocate": null, "pronunciation": "しゅうてん", "ipa": "ɕɯːteɴ", "syllable_count": 4, "sentences": [{"text": "電車は終点に着きました。", "target_word": "終点", "complexity_tier": "T3", "furigana": "電車(でんしゃ)は終点(しゅうてん)に着(つ)きました。", "sentence_source": "generated"}, {"text": "バスの終点で、全員が降りました。", "target_word": "終点", "complexity_tier": "T3", "furigana": "バスの終点(しゅうてん)で、全員(ぜんいん)が降(お)りました。", "sentence_source": "generated"}, {"text": "この道の終点には、小さな公園があります。", "target_word": "終点", "complexity_tier": "T3", "furigana": "この道(みち)の終点(しゅうてん)には、小(ちい)さな公園(こうえん)があります。", "sentence_source": "generated"}, {"text": "線の終点に、赤い丸をかいてください。", "target_word": "終点", "complexity_tier": "T3", "furigana": "線(せん)の終点(しゅうてん)に、赤(あか)い丸(まる)をかいてください。", "sentence_source": "generated"}, {"text": "終点まで乗るので、切符を買い足しました。", "target_word": "終点", "complexity_tier": "T3", "furigana": "終点(しゅうてん)まで乗(の)るので、切符(きっぷ)を買(か)い足(た)しました。", "sentence_source": "generated"}, {"text": "県道の終点は、駅前の広場です。", "target_word": "終点", "complexity_tier": "T3", "furigana": "県道(けんどう)の終点(しゅうてん)は、駅前(えきまえ)の広場(ひろば)です。", "sentence_source": "generated"}, {"text": "駅員さんが、ここが終点だと教えてくれました。", "target_word": "終点", "complexity_tier": "T3", "furigana": "駅員(えきいん)さんが、ここが終点(しゅうてん)だと教(おし)えてくれました。", "sentence_source": "generated"}, {"text": "長い坂の終点に、古いお寺があります。", "target_word": "終点", "complexity_tier": "T3", "furigana": "長(なが)い坂(さか)の終点(しゅうてん)に、古(ふる)いお寺(てら)があります。", "sentence_source": "generated"}, {"text": "地図で、この線路の終点を探しました。", "target_word": "終点", "complexity_tier": "T3", "furigana": "地図(ちず)で、この線路(せんろ)の終点(しゅうてん)を探(さが)しました。", "sentence_source": "generated"}, {"text": "眠ってしまって、終点まで行きました。", "target_word": "終点", "complexity_tier": "T3", "furigana": "眠(ねむ)ってしまって、終点(しゅうてん)まで行(い)きました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "終点", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "道や線路などがそこで終わる場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3b14ba-f350-4b70-835c-74054ef8b390') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52609, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "終点", "is_correct": true, "explanation": "到着する地点を表すので、「終点に着きました」として文に合う。"}, {"text": "運賃", "is_correct": false, "explanation": "乗車にかかる料金のことで、電車が着く場所にはならないので合わない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のことで、電車が着く場所ではないので合わない。"}, {"text": "発車", "is_correct": false, "explanation": "車両が出発することで、到着する地点を表さないので合わない。"}], "explanations": {"終点": "到着する地点を表すので、「終点に着きました」として文に合う。", "運賃": "乗車にかかる料金のことで、電車が着く場所にはならないので合わない。", "天気": "空模様のことで、電車が着く場所ではないので合わない。", "発車": "車両が出発することで、到着する地点を表さないので合わない。"}, "sentence_index": 0, "correct_answer": "終点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "線の終点は、両端のちょうど真ん中だ。", "explanation": "ここは〈中間点〉の意味。両端の真ん中は中間点と言い、終点は線の端の一つを指すので合わない。"}, {"text": "川の終点は、山の中の小さな泉だ。", "explanation": "ここは〈始点〉の意味。流れの源は始点と言い、終点は流れが行き着く先を指すので合わない。"}, {"text": "我慢の終点に、もう達してしまった。", "explanation": "ここは〈限界〉の意味。これ以上は耐えられない境は限界と言い、終点は道や線の到着地点を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52609, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "終点", "is_correct": true, "explanation": "「ここが〜だ」で目的地を示す語で、文に合う。"}, {"text": "予算", "is_correct": false, "explanation": "使える金額のことで、場所を表さないので合わない。"}, {"text": "車両", "is_correct": false, "explanation": "乗り物そのものを指し、「ここが〜だ」とは言えないので合わない。"}, {"text": "規則", "is_correct": false, "explanation": "決まりのことで、場所を表さないので合わない。"}], "explanations": {"終点": "「ここが〜だ」で目的地を示す語で、文に合う。", "予算": "使える金額のことで、場所を表さないので合わない。", "車両": "乗り物そのものを指し、「ここが〜だ」とは言えないので合わない。", "規則": "決まりのことで、場所を表さないので合わない。"}, "sentence_index": 6, "correct_answer": "終点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家の終点に、大きな柱が立っている。", "explanation": "ここは〈中心〉の意味。家の真ん中は中心と言い、終点は道や線の到着地点を指すので合わない。"}, {"text": "門の終点で、切符を見せた。", "explanation": "ここは〈入口〉の意味。入るところは入口と言い、終点は到着する地点を指すので合わない。"}, {"text": "家の終点で、靴をそろえた。", "explanation": "ここは〈玄関〉の意味。家の出入り口は玄関と言い、終点は道や線の到着地点を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52609, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜遅く、列車は終点を到着しました。", "corrected_sentence": "夜遅く、列車は終点に到着しました。", "error_description": "「到着する」は到着先を「に」で示すので、「終点を到着する」は誤り。正しくは「終点に到着する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
