INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52610, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "到着点を示す格助詞「に」で、「終点に着く」と続くので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「着く」は目的語を取らないので、「終点を着く」とはならない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、到着地点を表す位置には入らない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞で、「終点の着く」では文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "到着点を示す格助詞「に」で、「終点に着く」と続くので正しい。", "を": "「着く」は目的語を取らないので、「終点を着く」とはならない。", "が": "主語を示す助詞で、到着地点を表す位置には入らない。", "の": "連体修飾の助詞で、「終点の着く」では文が成り立たない。"}, "error_tags": {"を": "目的語の格助詞", "が": "主語の格助詞", "の": "連体修飾の助詞"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "始点", "is_correct": true, "explanation": "道や線が始まる地点で、終点の対義語。"}, {"text": "途中", "is_correct": false, "explanation": "道の中ほどを指し、始まりでも終わりでもないので対にならない。"}, {"text": "中心", "is_correct": false, "explanation": "中央の位置を指し、終点と対をなす関係ではないので合わない。"}, {"text": "頂点", "is_correct": false, "explanation": "山や図形の頂上を指し、終わりの地点を表さないので対にならない。"}], "correct_answer": "始点", "explanations": {"始点": "道や線が始まる地点で、終点の対義語。", "途中": "道の中ほどを指し、始まりでも終わりでもないので対にならない。", "中心": "中央の位置を指し、終点と対をなす関係ではないので合わない。", "頂点": "山や図形の頂上を指し、終わりの地点を表さないので対にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52610, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "場所を示す「で」で、「終点では」と続くので正しい。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、「終点の」の後に文が続かないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」で、場所を示す文脈が成り立たないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」で、待っている場所を示す語としては合わない。"}], "correct_answer": "で", "explanations": {"で": "場所を示す「で」で、「終点では」と続くので正しい。", "の": "連体修飾の「の」で、「終点の」の後に文が続かないので合わない。", "より": "比較の「より」で、場所を示す文脈が成り立たないので合わない。", "へ": "方向を示す「へ」で、待っている場所を示す語としては合わない。"}, "error_tags": {"より": "比較の助詞", "へ": "方向の助詞", "の": "連体修飾の助詞"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "始点", "is_correct": true, "explanation": "道や線が始まる地点で、終点の対義語。"}, {"text": "出口", "is_correct": false, "explanation": "外へ出る通り道を指し、始点の反対の意味にはならないので合わない。"}, {"text": "中央", "is_correct": false, "explanation": "真ん中の位置を指し、終点と対義語の関係にないので合わない。"}, {"text": "表面", "is_correct": false, "explanation": "物の外側の面を指し、対義語の関係にないので合わない。"}], "correct_answer": "始点", "explanations": {"始点": "道や線が始まる地点で、終点の対義語。", "出口": "外へ出る通り道を指し、始点の反対の意味にはならないので合わない。", "中央": "真ん中の位置を指し、終点と対義語の関係にないので合わない。", "表面": "物の外側の面を指し、対義語の関係にないので合わない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52610, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "道や線、物事の流れが終わる地点。終わり。", "primary_collocate": null, "pronunciation": "しゅうてん", "ipa": "ɕɯːteɴ", "syllable_count": 4, "sentences": [{"text": "次いで、分岐や終点といった特徴点の配列を精密に分析する。", "target_word": "終点", "complexity_tier": "T4", "furigana": "次(つ)いで、分岐(ぶんき)や終点(しゅうてん)といった特徴点(とくちょうてん)の配列(はいれつ)を精密(せいみつ)に分析(ぶんせき)する。", "sentence_source": "mined"}, {"text": "バスは終点に着いたので、乗客は全員降りた。", "target_word": "終点", "complexity_tier": "T3", "furigana": "バスは終点(しゅうてん)に着(つ)いたので、乗客(じょうきゃく)は全員(ぜんいん)降(お)りた。", "sentence_source": "generated"}, {"text": "この電車の終点は、海の近くの小さな駅だ。", "target_word": "終点", "complexity_tier": "T3", "furigana": "この電車(でんしゃ)の終点(しゅうてん)は、海(うみ)の近(ちか)くの小(ちい)さな駅(えき)だ。", "sentence_source": "generated"}, {"text": "寝過ごして、終点まで行ってしまった。", "target_word": "終点", "complexity_tier": "T3", "furigana": "寝過(ねす)ごして、終点(しゅうてん)まで行(い)ってしまった。", "sentence_source": "generated"}, {"text": "川の終点は、広い海につながっている。", "target_word": "終点", "complexity_tier": "T3", "furigana": "川(かわ)の終点(しゅうてん)は、広(ひろ)い海(うみ)につながっている。", "sentence_source": "generated"}, {"text": "登山道の終点には、小さな山小屋がある。", "target_word": "終点", "complexity_tier": "T3", "furigana": "登山道(とざんどう)の終点(しゅうてん)には、小(ちい)さな山小屋(やまごや)がある。", "sentence_source": "generated"}, {"text": "始点から終点まで、まっすぐな線を引いた。", "target_word": "終点", "complexity_tier": "T3", "furigana": "始点(してん)から終点(しゅうてん)まで、まっすぐな線(せん)を引(ひ)いた。", "sentence_source": "generated"}, {"text": "マラソンの終点では、大勢の人が選手を待っていた。", "target_word": "終点", "complexity_tier": "T3", "furigana": "マラソンの終点(しゅうてん)では、大勢(おおぜい)の人(ひと)が選手(せんしゅ)を待(ま)っていた。", "sentence_source": "generated"}, {"text": "長い旅の終点に、故郷の町が見えてきた。", "target_word": "終点", "complexity_tier": "T3", "furigana": "長(なが)い旅(たび)の終点(しゅうてん)に、故郷(こきょう)の町(まち)が見(み)えてきた。", "sentence_source": "generated"}, {"text": "次の駅が終点なので、降りる準備をした。", "target_word": "終点", "complexity_tier": "T3", "furigana": "次(つぎ)の駅(えき)が終点(しゅうてん)なので、降(お)りる準備(じゅんび)をした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "終点", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "道・線・路線・流れが終わる地点。始点の反対", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3b14ba-f350-4b70-835c-74054ef8b390') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52610, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "終点", "is_correct": true, "explanation": "「分岐」と並ぶ特徴点として、道や線の終わりの地点を表すので文に合う。"}, {"text": "運賃", "is_correct": false, "explanation": "乗車にかかる料金のことで、特徴点の例にはならないので合わない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を指し、分岐と並べて特徴点とは言えないので合わない。"}, {"text": "発車", "is_correct": false, "explanation": "車両が出発することで、地点を表す名詞ではないので合わない。"}], "explanations": {"終点": "「分岐」と並ぶ特徴点として、道や線の終わりの地点を表すので文に合う。", "運賃": "乗車にかかる料金のことで、特徴点の例にはならないので合わない。", "天気": "空模様を指し、分岐と並べて特徴点とは言えないので合わない。", "発車": "車両が出発することで、地点を表す名詞ではないので合わない。"}, "sentence_index": 0, "correct_answer": "終点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "マラソンの終点は、コースのちょうど半分の地点だ。", "explanation": "ここは〈中間点〉の意味。コースの真ん中は中間点と言い、終点は道の終わりを指すので合わない。"}, {"text": "通帳の終点を確認した。", "explanation": "ここは〈残高〉の意味。お金の残りの額は残高と言い、終点は道や線の到着地点を指すので合わない。"}, {"text": "この電車の終点は、朝いちばん最初に出る駅だ。", "explanation": "ここは〈始発〉の意味。最初に出る駅は始発と言い、終点は最後に着く地点を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52610, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "終点", "is_correct": true, "explanation": "「始点から」と対になり、線の到達点を表すので文に合う。"}, {"text": "出発", "is_correct": false, "explanation": "出発する動作を指し、線の到達点を表す位置には入らないので合わない。"}, {"text": "車両", "is_correct": false, "explanation": "乗り物そのものを指し、地点を表さないので合わない。"}, {"text": "運行", "is_correct": false, "explanation": "乗り物を走らせることを指し、場所を表さないので合わない。"}], "explanations": {"終点": "「始点から」と対になり、線の到達点を表すので文に合う。", "出発": "出発する動作を指し、線の到達点を表す位置には入らないので合わない。", "車両": "乗り物そのものを指し、地点を表さないので合わない。", "運行": "乗り物を走らせることを指し、場所を表さないので合わない。"}, "sentence_index": 6, "correct_answer": "終点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "体力の終点に達して、そこで倒れた。", "explanation": "ここは〈限界〉の意味。体力が尽きる所は限界と言い、終点は道や線の到着地点を指すので合わない。"}, {"text": "国の終点を越えて、隣の国へ入った。", "explanation": "ここは〈境界〉の意味。国と国のさかいは境界と言い、終点は道や線の到着地点を指すので合わない。"}, {"text": "改札の終点で、切符を見せた。", "explanation": "ここは〈入口〉の意味。人が入るところは入口と言い、終点は到着する地点を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52610, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜遅く、タクシーは終点を着いた。", "corrected_sentence": "夜遅く、タクシーは終点に着いた。", "error_description": "「着く」は到着先を「に」で示すので、「終点を着いた」は誤り。正しくは「終点に着いた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52610, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "次の停車駅が終点だので、乗客は降りる準備をした。", "corrected_sentence": "次の停車駅が終点なので、乗客は降りる準備をした。", "error_description": "名詞に付く断定の形は「なので」で、「だので」は誤り。正しくは「終点なので」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52611, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「を」は「見た」の目的語で、犯行を見たという動作の対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「犯行が」では主語になり、「見た」の対象が欠けて文が崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、「見た」の対象を示せず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「犯行に」では対象を表すが、「見る」は「を」を取るため不自然。"}], "correct_answer": "を", "explanations": {"を": "「を」は「見た」の目的語で、犯行を見たという動作の対象を示す。", "が": "「犯行が」では主語になり、「見た」の対象が欠けて文が崩れる。", "へ": "「へ」は方向を表すが、「見た」の対象を示せず、文が成り立たない。", "に": "「犯行に」では対象を表すが、「見る」は「を」を取るため不自然。"}, "error_tags": {"が": "主格", "へ": "方向", "に": "位置・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52611, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「は」は「犯行」を話題として示し、後半の「被害は大きかった」と対比させる。"}, {"text": "を", "is_correct": false, "explanation": "「犯行を」では目的語になるが、「終わった」と噛み合わず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「犯行へ」は方向を示すが、「終わった」の主語として意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「犯行より」は比較になり、文の主題として成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「は」は「犯行」を話題として示し、後半の「被害は大きかった」と対比させる。", "を": "「犯行を」では目的語になるが、「終わった」と噛み合わず文が成り立たない。", "へ": "「犯行へ」は方向を示すが、「終わった」の主語として意味が通らない。", "より": "「犯行より」は比較になり、文の主題として成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52611, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "わるいことをすること。", "primary_collocate": null, "pronunciation": "はんこう", "ipa": "haŋkoː", "syllable_count": 4, "sentences": [{"text": "昨日の夜、店で犯行があったので、警察が来ました。", "target_word": "犯行", "complexity_tier": "T2", "furigana": "昨日[きのう]の夜[よる]、店[みせ]で犯行[はんこう]があったので、警察[けいさつ]が来[き]ました。", "sentence_source": "generated"}, {"text": "犯行を見た人は、すぐに警察に電話してください。", "target_word": "犯行", "complexity_tier": "T2", "furigana": "犯行[はんこう]を見[み]た人[ひと]は、すぐに警察[けいさつ]に電話[でんわ]してください。", "sentence_source": "generated"}, {"text": "彼は自分の犯行を、母に正直に話した。", "target_word": "犯行", "complexity_tier": "T2", "furigana": "彼[かれ]は自分[じぶん]の犯行[はんこう]を、母[はは]に正直[しょうじき]に話[はな]した。", "sentence_source": "generated"}, {"text": "犯行がわかったあとで、犯人はとても後悔した。", "target_word": "犯行", "complexity_tier": "T2", "furigana": "犯行[はんこう]がわかったあとで、犯人[はんにん]はとても後悔[こうかい]した。", "sentence_source": "generated"}, {"text": "カメラのおかげで、犯行の様子がはっきり見えた。", "target_word": "犯行", "complexity_tier": "T2", "furigana": "カメラのおかげで、犯行[はんこう]の様子[ようす]がはっきり見[み]えた。", "sentence_source": "generated"}, {"text": "この犯行は一人でやったのではなく、三人で計画した。", "target_word": "犯行", "complexity_tier": "T3", "furigana": "この犯行[はんこう]は一人[ひとり]でやったのではなく、三人[さんにん]で計画[けいかく]した。", "sentence_source": "generated"}, {"text": "犯行の理由を聞かれても、男は何も答えなかった。", "target_word": "犯行", "complexity_tier": "T3", "furigana": "犯行[はんこう]の理由[りゆう]を聞[き]かれても、男[おとこ]は何[なに]も答[こた]えなかった。", "sentence_source": "generated"}, {"text": "犯行は短い時間で終わったが、被害は大きかった。", "target_word": "犯行", "complexity_tier": "T3", "furigana": "犯行[はんこう]は短[みじか]い時間[じかん]で終[お]わったが、被害[ひがい]は大[おお]きかった。", "sentence_source": "generated"}, {"text": "子どもの犯行だと分かって、町の人は驚いた。", "target_word": "犯行", "complexity_tier": "T2", "furigana": "子[こ]どもの犯行[はんこう]だと分[わ]かって、町[まち]の人[ひと]は驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "警察は、犯行に使われた車を探している。", "target_word": "犯行", "complexity_tier": "T2", "furigana": "警察[けいさつ]は、犯行[はんこう]に使[つか]われた車[くるま]を探[さが]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "犯行", "label": "基本形"}, {"form": "犯行の", "label": "連体格"}, {"form": "犯行を", "label": "目的格"}], "register": "neutral", "sense_fingerprint": "犯行:悪いことをすること(やさしい説明・日常の事件の文脈)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61cb1192-68a7-491c-85b3-7aecd2d4e55a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52611, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "犯行", "is_correct": true, "explanation": "「犯行」は悪いことをすること。ここでは店で起きた悪い出来事を指し、文の意味に合う。"}, {"text": "天候", "is_correct": false, "explanation": "「天候」は空模様や気象の状態。店で起きた出来事としては意味が通らない。"}, {"text": "食卓", "is_correct": false, "explanation": "「食卓」は食事をする台。店で起きた出来事の名前としては合わない。"}, {"text": "給料", "is_correct": false, "explanation": "「給料」は働いて受け取る金銭。店で起きたことを表すには合わない。"}], "explanations": {"犯行": "「犯行」は悪いことをすること。ここでは店で起きた悪い出来事を指し、文の意味に合う。", "天候": "「天候」は空模様や気象の状態。店で起きた出来事としては意味が通らない。", "食卓": "「食卓」は食事をする台。店で起きた出来事の名前としては合わない。", "給料": "「給料」は働いて受け取る金銭。店で起きたことを表すには合わない。"}, "sentence_index": 0, "correct_answer": "犯行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母の料理を手伝って、野菜を切る犯行をした。", "explanation": "ここは〈手伝い〉の意味。犯行は悪いことをすることで、人を助ける行いには使わない。"}, {"text": "毎日ピアノを練習する犯行を続けている。", "explanation": "ここは〈練習〉の意味。犯行は悪いことを指し、努力して身につける行為には使わない。"}, {"text": "料理に工夫を加えて、家族に褒められる犯行をした。", "explanation": "ここは〈工夫〉の意味。犯行は悪いことの意味で、ほめられる工夫には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52611, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "犯行", "is_correct": true, "explanation": "「犯行」は悪いことをすること。ここでは理由を聞かれた悪い行いを指し、文に合う。"}, {"text": "旅程", "is_correct": false, "explanation": "「旅程」は旅行の予定。理由を聞かれた対象としては意味が通らない。"}, {"text": "通帳", "is_correct": false, "explanation": "「通帳」は預金の記録を書く冊子。理由の対象として不自然で、文脈に合わない。"}, {"text": "献立", "is_correct": false, "explanation": "「献立」は料理の予定表。理由を聞かれる対象としては合わない。"}], "explanations": {"犯行": "「犯行」は悪いことをすること。ここでは理由を聞かれた悪い行いを指し、文に合う。", "旅程": "「旅程」は旅行の予定。理由を聞かれた対象としては意味が通らない。", "通帳": "「通帳」は預金の記録を書く冊子。理由の対象として不自然で、文脈に合わない。", "献立": "「献立」は料理の予定表。理由を聞かれる対象としては合わない。"}, "sentence_index": 6, "correct_answer": "犯行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨の日でも、近所の道を掃除する犯行を続けている。", "explanation": "ここは〈掃除〉の意味。犯行は悪いことで、町をきれいにする行いには使えない。"}, {"text": "母の誕生日に、手作りケーキを焼く犯行をした。", "explanation": "ここは〈製菓〉の意味。犯行は悪いことで、ケーキを焼く行為には使わない。"}, {"text": "先生から、テストで満点を取った犯行をほめられた。", "explanation": "ここは〈成績〉の意味。犯行は悪いことで、よい成績には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52611, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日の夜、駅で犯行をあったので、警察が来ました。", "corrected_sentence": "昨日の夜、駅で犯行があったので、警察が来ました。", "error_description": "「ある」の主語は「犯行」で、「犯行が」と格助詞「が」を使う。「を」では目的語になり、「あった」と噛み合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
