INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52612, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「の」は「犯行」と後の「あと」をつなぎ、犯行の後であることを示す。"}, {"text": "を", "is_correct": false, "explanation": "「犯行を」では目的語になるが、「あと」とつながらず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「犯行へ」は方向を示すが、ここでは時間の関係を表す「あと」と合わない。"}, {"text": "より", "is_correct": false, "explanation": "「犯行より」は比較になり、時間の順序を示す「あと」と合わない。"}], "correct_answer": "の", "explanations": {"の": "「の」は「犯行」と後の「あと」をつなぎ、犯行の後であることを示す。", "を": "「犯行を」では目的語になるが、「あと」とつながらず文が成り立たない。", "へ": "「犯行へ」は方向を示すが、ここでは時間の関係を表す「あと」と合わない。", "より": "「犯行より」は比較になり、時間の順序を示す「あと」と合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52612, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "法律に違反する行為。犯罪行為。", "primary_collocate": null, "pronunciation": "はんこう", "ipa": "haŋkoː", "syllable_count": 4, "sentences": [{"text": "犯行の客観的裏付けという目的のため、この緻密な照合作業を経て、初めて不可謬な身元特定が達成されるのである。", "target_word": "犯行", "complexity_tier": "T5", "furigana": "犯行[はんこう]の客観的[きゃっかんてき]裏付[うらづ]けという目的[もくてき]のため、この緻密[ちみつ]な照合[しょうごう]作業[さぎょう]を経[へ]て、初[はじ]めて不可謬[ふかびゅう]な身元[みもと]特定[とくてい]が達成[たっせい]されるのである。", "sentence_source": "mined"}, {"text": "警察は防犯カメラの映像から、犯行の時刻を特定した。", "target_word": "犯行", "complexity_tier": "T3", "furigana": "警察[けいさつ]は防犯[ぼうはん]カメラの映像[えいぞう]から、犯行[はんこう]の時刻[じこく]を特定[とくてい]した。", "sentence_source": "generated"}, {"text": "男は取り調べで、犯行を全面的に認めた。", "target_word": "犯行", "complexity_tier": "T3", "furigana": "男[おとこ]は取[と]り調[しら]べで、犯行[はんこう]を全面的[ぜんめんてき]に認[みと]めた。", "sentence_source": "generated"}, {"text": "犯行が行われた場所には、犯人の足跡が残っていた。", "target_word": "犯行", "complexity_tier": "T3", "furigana": "犯行[はんこう]が行[おこな]われた場所[ばしょ]には、犯人[はんにん]の足跡[あしあと]が残[のこ]っていた。", "sentence_source": "generated"}, {"text": "証拠が見つかったので、容疑者は犯行を否定できなくなった。", "target_word": "犯行", "complexity_tier": "T4", "furigana": "証拠[しょうこ]が見[み]つかったので、容疑者[ようぎしゃ]は犯行[はんこう]を否定[ひてい]できなくなった。", "sentence_source": "generated"}, {"text": "犯行の動機が分からず、捜査は難航している。", "target_word": "犯行", "complexity_tier": "T4", "furigana": "犯行[はんこう]の動機[どうき]が分[わ]からず、捜査[そうさ]は難航[なんこう]している。", "sentence_source": "generated"}, {"text": "彼女は犯行を目撃したと、裁判で証言した。", "target_word": "犯行", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は犯行[はんこう]を目撃[もくげき]したと、裁判[さいばん]で証言[しょうげん]した。", "sentence_source": "generated"}, {"text": "犯人は犯行のあと、すぐに町から姿を消した。", "target_word": "犯行", "complexity_tier": "T3", "furigana": "犯人[はんにん]は犯行[はんこう]のあと、すぐに町[まち]から姿[すがた]を消[け]した。", "sentence_source": "generated"}, {"text": "この事件は、計画的な犯行だと考えられている。", "target_word": "犯行", "complexity_tier": "T3", "furigana": "この事件[じけん]は、計画的[けいかくてき]な犯行[はんこう]だと考[かんが]えられている。", "sentence_source": "generated"}, {"text": "少年は反省して、自分の犯行を深く後悔している。", "target_word": "犯行", "complexity_tier": "T3", "furigana": "少年[しょうねん]は反省[はんせい]して、自分[じぶん]の犯行[はんこう]を深[ふか]く後悔[こうかい]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "犯行", "label": "基本形"}, {"form": "犯行の", "label": "連体格"}, {"form": "犯行を", "label": "目的格"}], "register": "formal", "sense_fingerprint": "犯行:法律に違反する犯罪行為(事件・捜査の文脈)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61cb1192-68a7-491c-85b3-7aecd2d4e55a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52612, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "犯行", "is_correct": true, "explanation": "「犯行」は法律に違反する犯罪行為のこと。ここでは裏付けの対象となる犯罪行為を指し、文の意味に合う。"}, {"text": "献立", "is_correct": false, "explanation": "「献立」は料理の予定表。犯罪行為の客観的裏付けという文脈には合わない。"}, {"text": "天候", "is_correct": false, "explanation": "「天候」は空模様や気象の状態。犯罪の客観的裏付けには当てはまらない。"}, {"text": "給料", "is_correct": false, "explanation": "「給料」は労働の対価として受け取る金銭。ここでは意味が通らない。"}], "explanations": {"犯行": "「犯行」は法律に違反する犯罪行為のこと。ここでは裏付けの対象となる犯罪行為を指し、文の意味に合う。", "献立": "「献立」は料理の予定表。犯罪行為の客観的裏付けという文脈には合わない。", "天候": "「天候」は空模様や気象の状態。犯罪の客観的裏付けには当てはまらない。", "給料": "「給料」は労働の対価として受け取る金銭。ここでは意味が通らない。"}, "sentence_index": 0, "correct_answer": "犯行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その犯行は、昨夜逮捕された男性だった。", "explanation": "ここは〈犯人〉の意味。犯行は行為を指す語で、人を指しては使わない。"}, {"text": "彼は道に倒れた老人を助け、その犯行を称えられた。", "explanation": "ここは〈善行〉の意味。犯行は法律に違反する行為なので、称賛される行いには使えない。"}, {"text": "サッカーの試合で、彼は犯行を取られて退場した。", "explanation": "ここは〈反則〉の意味。スポーツの違反には反則を使い、犯行は犯罪行為に限られる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52612, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "犯行", "is_correct": true, "explanation": "「犯行」は犯罪行為のこと。ここでは目撃した犯罪の出来事を指し、証言の対象として合う。"}, {"text": "旅程", "is_correct": false, "explanation": "「旅程」は旅行の予定。犯罪を目撃したという文脈には合わない。"}, {"text": "食卓", "is_correct": false, "explanation": "「食卓」は食事をする台や場所。目撃の対象としては意味が通らない。"}, {"text": "通帳", "is_correct": false, "explanation": "「通帳」は預金の記録を書く冊子。目撃の対象として不自然で、文脈に合わない。"}], "explanations": {"犯行": "「犯行」は犯罪行為のこと。ここでは目撃した犯罪の出来事を指し、証言の対象として合う。", "旅程": "「旅程」は旅行の予定。犯罪を目撃したという文脈には合わない。", "食卓": "「食卓」は食事をする台や場所。目撃の対象としては意味が通らない。", "通帳": "「通帳」は預金の記録を書く冊子。目撃の対象として不自然で、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "犯行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は大きな犯行を立て、社長から表彰された。", "explanation": "ここは〈手柄〉の意味。犯行は犯罪行為を指し、手柄を立てる意味では使えない。"}, {"text": "彼女は努力の犯行を証明するため、資料を集めた。", "explanation": "ここは〈成果〉の意味。犯行は犯罪行為で、努力の結果には使えない。"}, {"text": "この会社は画期的な犯行を生み出した。", "explanation": "ここは〈発明〉の意味。犯行は犯罪行為を指し、新しい技術や製品には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52612, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察は防犯カメラの映像から、犯行を時間を割り出した。", "corrected_sentence": "警察は防犯カメラの映像から、犯行の時間を割り出した。", "error_description": "目的語の「を」が二つ重なっている。「犯行の時間」と「の」で結ぶ。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52612, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は犯行に認めて、警察に自首した。", "corrected_sentence": "彼は犯行を認めて、警察に自首した。", "error_description": "「認める」は「を」で対象を示すので、「犯行を認める」とする。「犯行に」では「認める」の対象が示されず不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52613, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「を」は「照合する」の対象を示し、レシートを突き合わせることを表す。"}, {"text": "の", "is_correct": false, "explanation": "「の」では「照合する」の目的語にならず、動詞の形が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、照合の対象を示せず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「レシートへ照合する」は方向を示すが、照合の対象を直接示せない。"}], "correct_answer": "を", "explanations": {"を": "「を」は「照合する」の対象を示し、レシートを突き合わせることを表す。", "の": "「の」では「照合する」の目的語にならず、動詞の形が成り立たない。", "より": "「より」は比較を表し、照合の対象を示せず文が成り立たない。", "へ": "「レシートへ照合する」は方向を示すが、照合の対象を直接示せない。"}, "error_tags": {"の": "連体", "より": "比較", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52613, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「の」は「照合」と後の「結果」をつなぎ、照合という行為の結果であることを示す。"}, {"text": "を", "is_correct": false, "explanation": "「照合を結果」では目的語になるが、「結果」と結びつかず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「照合で結果」は手段になり、「結果」との関係が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「照合より結果」は比較になり、文の流れに合わない。"}], "correct_answer": "の", "explanations": {"の": "「の」は「照合」と後の「結果」をつなぎ、照合という行為の結果であることを示す。", "を": "「照合を結果」では目的語になるが、「結果」と結びつかず不自然。", "で": "「照合で結果」は手段になり、「結果」との関係が成り立たない。", "より": "「照合より結果」は比較になり、文の流れに合わない。"}, "error_tags": {"を": "目的語", "で": "手段", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52613, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "二つのものをくらべて、同じところやちがうところを調べること。", "primary_collocate": null, "pronunciation": "しょうごう", "ipa": "ɕoːɡoː", "syllable_count": 4, "sentences": [{"text": "先生は、答えと正解を照合して、点数をつけた。", "target_word": "照合", "complexity_tier": "T2", "furigana": "先生[せんせい]は、答[こた]えと正解[せいかい]を照合[しょうごう]して、点数[てんすう]をつけた。", "sentence_source": "generated"}, {"text": "買ったものとレシートを照合すると、お金が足りなかった。", "target_word": "照合", "complexity_tier": "T2", "furigana": "買[か]ったものとレシートを照合[しょうごう]すると、お金[かね]が足[た]りなかった。", "sentence_source": "generated"}, {"text": "名簿と照合して、来た人の名前に印をつけた。", "target_word": "照合", "complexity_tier": "T2", "furigana": "名簿[めいぼ]と照合[しょうごう]して、来[き]た人[ひと]の名前[なまえ]に印[しるし]をつけた。", "sentence_source": "generated"}, {"text": "二つの地図を照合すれば、道のちがいがわかる。", "target_word": "照合", "complexity_tier": "T2", "furigana": "二[ふた]つの地図[ちず]を照合[しょうごう]すれば、道[みち]のちがいがわかる。", "sentence_source": "generated"}, {"text": "受付で名前を照合してもらってから、中に入った。", "target_word": "照合", "complexity_tier": "T2", "furigana": "受付[うけつけ]で名前[なまえ]を照合[しょうごう]してもらってから、中[なか]に入[はい]った。", "sentence_source": "generated"}, {"text": "荷物の数をリストと照合したが、全部そろっていた。", "target_word": "照合", "complexity_tier": "T2", "furigana": "荷物[にもつ]の数[かず]をリストと照合[しょうごう]したが、全部[ぜんぶ]そろっていた。", "sentence_source": "generated"}, {"text": "写真を見本と照合して、同じかどうかを調べた。", "target_word": "照合", "complexity_tier": "T2", "furigana": "写真[しゃしん]を見本[みほん]と照合[しょうごう]して、同[おな]じかどうかを調[しら]べた。", "sentence_source": "generated"}, {"text": "照合の結果、二つの文章はほとんど同じだった。", "target_word": "照合", "complexity_tier": "T3", "furigana": "照合[しょうごう]の結果[けっか]、二[ふた]つの文章[ぶんしょう]はほとんど同[おな]じだった。", "sentence_source": "generated"}, {"text": "手紙の字を本人の字と照合してみたが、ちがう人が書いたようだ。", "target_word": "照合", "complexity_tier": "T3", "furigana": "手紙[てがみ]の字[じ]を本人[ほんにん]の字[じ]と照合[しょうごう]してみたが、ちがう人[ひと]が書[か]いたようだ。", "sentence_source": "generated"}, {"text": "彼女は、帳簿の数字をレシートと照合する仕事をしている。", "target_word": "照合", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は、帳簿[ちょうぼ]の数字[すうじ]をレシートと照合[しょうごう]する仕事[しごと]をしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "照合", "label": "基本形"}, {"form": "照合する", "label": "サ変動詞"}, {"form": "照合した", "label": "過去形"}, {"form": "照合して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "照合:二つをくらべて同じ・ちがうを調べる(日常のやさしい確認)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61cb1192-68a7-491c-85b3-7aecd2d4e55a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52613, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "照合", "is_correct": true, "explanation": "「照合」は二つをくらべて同じところを調べること。答えと正解を調べる動作として合う。"}, {"text": "食卓", "is_correct": false, "explanation": "「食卓」は食事をする台。答えと正解を対象にする動作としては合わない。"}, {"text": "天候", "is_correct": false, "explanation": "「天候」は空模様や気象の状態。答えと正解の確認には意味が通らない。"}, {"text": "旅程", "is_correct": false, "explanation": "「旅程」は旅行の予定。答えと正解を対象にする動作としては合わない。"}], "explanations": {"照合": "「照合」は二つをくらべて同じところを調べること。答えと正解を調べる動作として合う。", "食卓": "「食卓」は食事をする台。答えと正解を対象にする動作としては合わない。", "天候": "「天候」は空模様や気象の状態。答えと正解の確認には意味が通らない。", "旅程": "「旅程」は旅行の予定。答えと正解を対象にする動作としては合わない。"}, "sentence_index": 0, "correct_answer": "照合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭に花を照合して、きれいに植えた。", "explanation": "ここは〈植える〉の意味。照合はくらべて確かめることで、植物を植える意味はない。"}, {"text": "朝、部屋に差す照合がまぶしくて目が覚めた。", "explanation": "ここは〈日差し〉の意味。照合は比べて確かめる行為で、光が差す意味はない。"}, {"text": "玄関を照合して、ほうきで掃除した。", "explanation": "ここは〈掃除〉の意味。照合は比べて確かめることで、きれいにする意味は含まない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52613, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "照合", "is_correct": true, "explanation": "「照合」は二つをくらべて同じところを調べること。写真と見本を比べる動作として合う。"}, {"text": "給料", "is_correct": false, "explanation": "「給料」は働いて受け取る金銭。写真と見本を比べる動作には合わない。"}, {"text": "出張", "is_correct": false, "explanation": "「出張」は仕事で別の場所へ行くこと。写真と見本を対象にする動作としては合わない。"}, {"text": "献立", "is_correct": false, "explanation": "「献立」は料理の予定表。写真と見本を比べる動作としては意味が通らない。"}], "explanations": {"照合": "「照合」は二つをくらべて同じところを調べること。写真と見本を比べる動作として合う。", "給料": "「給料」は働いて受け取る金銭。写真と見本を比べる動作には合わない。", "出張": "「出張」は仕事で別の場所へ行くこと。写真と見本を対象にする動作としては合わない。", "献立": "「献立」は料理の予定表。写真と見本を比べる動作としては意味が通らない。"}, "sentence_index": 6, "correct_answer": "照合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店の照合が古くて、遠くからは見えなかった。", "explanation": "ここは〈看板〉の意味。照合は比べて確かめる行為で、店の表示板の意味はない。"}, {"text": "玄関の照合が壊れて、ドアが閉まらない。", "explanation": "ここは〈錠〉の意味。照合は比べて確かめる行為で、ドアの鍵の意味はない。"}, {"text": "家族で夕食を照合して、おいしく食べた。", "explanation": "ここは〈食べる〉の意味。照合は比べて確かめる行為で、食事をする意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52613, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つの地図を照合しければ、道のちがいはすぐわかる。", "corrected_sentence": "二つの地図を照合すれば、道のちがいはすぐわかる。", "error_description": "「照合する」の仮定形は「照合すれば」。「照合しければ」は形容詞の活用を誤っている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52613, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その店員は帳簿の数字をレシートと照合しる仕事をしている。", "corrected_sentence": "その店員は帳簿の数字をレシートと照合する仕事をしている。", "error_description": "「照合する」は連体形も「照合する」。「照合しる」は活用を誤っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52614, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「を」は「照合する」の対象を示し、名前を突き合わせることを表す。"}, {"text": "が", "is_correct": false, "explanation": "「名前が照合した」では主語になり、突き合わせる行為の主体が名前になって不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「名前へ照合した」は方向を示すが、照合は対象を直接取るので不自然。"}, {"text": "より", "is_correct": false, "explanation": "「名前より照合した」は比較になり、照合の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「を」は「照合する」の対象を示し、名前を突き合わせることを表す。", "が": "「名前が照合した」では主語になり、突き合わせる行為の主体が名前になって不自然。", "へ": "「名前へ照合した」は方向を示すが、照合は対象を直接取るので不自然。", "より": "「名前より照合した」は比較になり、照合の対象を示せない。"}, "error_tags": {"が": "主格", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52614, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「を」は「照合した」の対象を示し、請求書と納品書を突き合わせることを表す。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、照合の対象を示せず文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、動詞「照合した」につながらず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、照合の対象を示せず不自然。"}], "correct_answer": "を", "explanations": {"を": "「を」は「照合した」の対象を示し、請求書と納品書を突き合わせることを表す。", "より": "「より」は比較を表し、照合の対象を示せず文が成り立たない。", "の": "「の」は名詞をつなぐ助詞で、動詞「照合した」につながらず不自然。", "へ": "「へ」は方向を表し、照合の対象を示せず不自然。"}, "error_tags": {"より": "比較", "の": "連体", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52614, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "二つのものを比較し、一致しているかどうかを確かめること。特に、違いや類似点を詳しく調べること。", "primary_collocate": null, "pronunciation": "しょうごう", "ipa": "ɕoːɡoː", "syllable_count": 4, "sentences": [{"text": "犯行の客観的裏付けという目的のため、この緻密な照合作業を経て、初めて不可謬な身元特定が達成されるのである。", "target_word": "照合", "complexity_tier": "T5", "furigana": "犯行[はんこう]の客観的[きゃっかんてき]裏付[うらづ]けという目的[もくてき]のため、この緻密[ちみつ]な照合[しょうごう]作業[さぎょう]を経[へ]て、初[はじ]めて不可謬[ふかびゅう]な身元[みもと]特定[とくてい]が達成[たっせい]されるのである。", "sentence_source": "mined"}, {"text": "受付で、申込書の名前と身分証の名前を照合した。", "target_word": "照合", "complexity_tier": "T3", "furigana": "受付[うけつけ]で、申込書[もうしこみしょ]の名前[なまえ]と身分証[みぶんしょう]の名前[なまえ]を照合[しょうごう]した。", "sentence_source": "generated"}, {"text": "指紋を照合した結果、容疑者のものと一致した。", "target_word": "照合", "complexity_tier": "T3", "furigana": "指紋[しもん]を照合[しょうごう]した結果[けっか]、容疑者[ようぎしゃ]のものと一致[いっち]した。", "sentence_source": "generated"}, {"text": "データを照合すると、二つの帳簿に違いが見つかった。", "target_word": "照合", "complexity_tier": "T3", "furigana": "データを照合[しょうごう]すると、二[ふた]つの帳簿[ちょうぼ]に違[ちが]いが見[み]つかった。", "sentence_source": "generated"}, {"text": "銀行では、署名を登録された見本と照合してから手続きを進める。", "target_word": "照合", "complexity_tier": "T4", "furigana": "銀行[ぎんこう]では、署名[しょめい]を登録[とうろく]された見本[みほん]と照合[しょうごう]してから手続[てつづ]きを進[すす]める。", "sentence_source": "generated"}, {"text": "DNAの照合には数日かかるため、結果はまだ出ていない。", "target_word": "照合", "complexity_tier": "T3", "furigana": "DNAの照合[しょうごう]には数日[すうじつ]かかるため、結果[けっか]はまだ出[で]ていない。", "sentence_source": "generated"}, {"text": "入館の際は顔写真と本人を照合するので、マスクを外してください。", "target_word": "照合", "complexity_tier": "T4", "furigana": "入館[にゅうかん]の際[さい]は顔写真[かおじゃしん]と本人[ほんにん]を照合[しょうごう]するので、マスクを外[はず]してください。", "sentence_source": "generated"}, {"text": "請求書と納品書を照合したところ、数量が合わなかった。", "target_word": "照合", "complexity_tier": "T4", "furigana": "請求書[せいきゅうしょ]と納品書[のうひんしょ]を照合[しょうごう]したところ、数量[すうりょう]が合[あ]わなかった。", "sentence_source": "generated"}, {"text": "原本との照合が済むまで、コピーは正式な書類として使えない。", "target_word": "照合", "complexity_tier": "T4", "furigana": "原本[げんぽん]との照合[しょうごう]が済[す]むまで、コピーは正式[せいしき]な書類[しょるい]として使[つか]えない。", "sentence_source": "generated"}, {"text": "システムはパスワードを照合して、正しい利用者かどうかを確認する。", "target_word": "照合", "complexity_tier": "T3", "furigana": "システムはパスワードを照合[しょうごう]して、正[ただ]しい利用者[りようしゃ]かどうかを確認[かくにん]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "照合", "label": "基本形"}, {"form": "照合する", "label": "サ変動詞"}, {"form": "照合した", "label": "過去形"}, {"form": "照合して", "label": "て形"}], "register": "formal", "sense_fingerprint": "照合:二つを突き合わせ一致を確かめる(書類・指紋・データの確認)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61cb1192-68a7-491c-85b3-7aecd2d4e55a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52614, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "照合", "is_correct": true, "explanation": "「照合」は二つを突き合わせて一致を確かめること。ここでは作業の内容として文に合う。"}, {"text": "献立", "is_correct": false, "explanation": "「献立」は料理の予定表。緻密な作業の名前としては意味が通らない。"}, {"text": "天候", "is_correct": false, "explanation": "「天候」は空模様や気象の状態。作業を修飾する語としては合わない。"}, {"text": "出張", "is_correct": false, "explanation": "「出張」は仕事で別の場所へ行くこと。緻密な作業の名前としては合わない。"}], "explanations": {"照合": "「照合」は二つを突き合わせて一致を確かめること。ここでは作業の内容として文に合う。", "献立": "「献立」は料理の予定表。緻密な作業の名前としては意味が通らない。", "天候": "「天候」は空模様や気象の状態。作業を修飾する語としては合わない。", "出張": "「出張」は仕事で別の場所へ行くこと。緻密な作業の名前としては合わない。"}, "sentence_index": 0, "correct_answer": "照合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "英語の文章を照合してもらったら、すぐに意味が分かった。", "explanation": "ここは〈翻訳〉の意味。照合は突き合わせて一致を確かめる行為で、言葉を訳す意味はない。"}, {"text": "店の照合を明るくして、雰囲気を良くした。", "explanation": "ここは〈照明〉の意味。照合は比べて確かめる行為で、明かりの意味はない。"}, {"text": "カメラで照合して、景色を撮影した。", "explanation": "ここは〈撮影〉の意味。照合は比べて確かめる行為で、写真を撮る意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52614, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "照合", "is_correct": true, "explanation": "「照合」は顔写真と本人を突き合わせて確かめること。入館の確認という文脈に合う。"}, {"text": "旅程", "is_correct": false, "explanation": "「旅程」は旅行の予定。顔写真と本人を対象にする動詞としては合わない。"}, {"text": "給料", "is_correct": false, "explanation": "「給料」は働いて受け取る金銭。顔写真と本人の確認には意味が通らない。"}, {"text": "通帳", "is_correct": false, "explanation": "「通帳」は預金の記録を書く冊子。本人確認の動作としては合わない。"}], "explanations": {"照合": "「照合」は顔写真と本人を突き合わせて確かめること。入館の確認という文脈に合う。", "旅程": "「旅程」は旅行の予定。顔写真と本人を対象にする動詞としては合わない。", "給料": "「給料」は働いて受け取る金銭。顔写真と本人の確認には意味が通らない。", "通帳": "「通帳」は預金の記録を書く冊子。本人確認の動作としては合わない。"}, "sentence_index": 6, "correct_answer": "照合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "野菜を照合して、おいしいスープを作った。", "explanation": "ここは〈料理〉の意味。照合は突き合わせて確かめる行為で、食材を調理する意味はない。"}, {"text": "弓の名人は的に矢を照合した。", "explanation": "ここは〈狙う〉の意味。照合は比べて確かめる行為で、的をねらう意味はない。"}, {"text": "トラックの荷台に荷物を照合した。", "explanation": "ここは〈積む〉の意味。照合は比べて確かめる行為で、荷物を載せる意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52614, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "照合を結果、二つのデータは一致した。", "corrected_sentence": "照合の結果、二つのデータは一致した。", "error_description": "「照合の結果」と「の」で結ぶ。「照合を」では目的語になり、「結果」と続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52614, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "写しを原本と照合で、内容の正しさを確かめた。", "corrected_sentence": "写しを原本と照合して、内容の正しさを確かめた。", "error_description": "「照合」は動詞なので、続けるには「照合して」とする。「照合で」は「で」が続く形になり、文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c920fe7-56d2-4f9c-b4b0-0cbfbf550b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
